define('FAMILY_TREE_PLUGIN_URL', plugin_dir_url(__FILE__));

/**
 * ИСПРАВЛЕНО (PHP 8): безопасная обёртка над sanitize_text_field().
 * sanitize_text_field() объявлена с типом параметра `string`. Если значение
 * из $_POST/$_GET/$_REQUEST окажется массивом (что легко подделать в запросе,
 * например nonce[]=1), прямой вызов sanitize_text_field($value) приводит
 * к неперехваченной фатальной ошибке TypeError. Эта функция гарантированно
 * возвращает строку в любом случае.
 */
if (!function_exists('family_tree_sanitize_str')) {
    function family_tree_sanitize_str($value) {
        if (!is_scalar($value)) {
            return '';
        }
        return sanitize_text_field(wp_unslash((string) $value));
    }
}
if (!function_exists('family_tree_get_placeholder')) {
    function family_tree_get_placeholder($gender) {
        $is_female = ($gender === 'female');
        $option = $is_female ? get_option('family_tree_female_placeholder', '') : get_option('family_tree_male_placeholder', '');
        if (!empty($option)) {
            return $option;
        }
        return FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-' . ($is_female ? 'woman' : 'man') . '.svg';
    }
}
if (!function_exists('ft_privacy_visibility')) {
    /**
     * Уровень доступа к данным родословной для текущего посетителя.
     *
     * @return string 'full'   — видит всё без маскировки (администратор, разрешённые
     *                           пользователи при «Приватном древе», авторизованные
     *                           при опции «Скрыть от незарегистрированных»);
     *                 'masked' — видит древо/страницы, но с маскировкой полей и заглушкой
     *                           для скрытых персон (анонимный посетитель в публичном режиме);
     *                 'blocked'— не видит ничего, отображается текст-заглушка.
     */
    function ft_privacy_visibility() {
        if ((int) get_option('family_tree_private_tree', 0)) {
            $uid = get_current_user_id();
            if (current_user_can('manage_options')) {
                return 'full';
            }
            if ($uid) {
                $allowed = array_map('intval', (array) get_option('family_tree_allowed_viewers', array()));
                if (in_array($uid, $allowed, true)) {
                    return 'full';
                }
            }
            return 'blocked';
        }
        if ((int) get_option('family_tree_hide_from_unregistered', 0)) {
            return is_user_logged_in() ? 'full' : 'blocked';
        }
        if (current_user_can('manage_options')) {
            return 'full';
        }
        return 'masked';
    }
}
if (!function_exists('ft_hidden_fields')) {
    /**
     * Список полей, скрываемых на публике (пустой, если у пользователя полный доступ).
     * Возможные ключи: dates, years, name_parts, photo, places.
     */
    function ft_hidden_fields() {
        if (ft_privacy_visibility() === 'full') {
            return array();
        }
        $hide = (array) get_option('family_tree_hide_fields', array());
        return array_values(array_filter(array_map('sanitize_key', $hide)));
    }
}
if (!function_exists('ft_hide_field')) {
    function ft_hide_field($key) {
        return in_array($key, ft_hidden_fields(), true);
    }
}
if (!function_exists('ft_privacy_stub_text')) {
    function ft_privacy_stub_text() {
        $text = get_option('family_tree_private_stub_text', '');
        if ('' === trim((string) $text)) {
            $text = __('Администратор закрыл древо от просмотра неавторизованными пользователями.', 'genius-family-tree');
        }
        return $text;
    }
}
if (!function_exists('ft_privacy_hidden_label')) {
    function ft_privacy_hidden_label() {
        return __('Скрыто администратором', 'genius-family-tree');
    }
}
if (!function_exists('ft_unpublished_label')) {
    /**
     * Заглушка для членов семьи, чья запись не опубликована (черновик, ожидает
     * проверки, отложенная публикация). Персональная страница такой записи
     * посетителю недоступна, поэтому в древе вместо карточки персоны
     * показываем заглушку.
     *
     * @return string
     */
    function ft_unpublished_label() {
        return __('Неизвестно', 'genius-family-tree');
    }
}
if (!function_exists('ft_person_is_private')) {
    /**
     * Скрыта ли персона от текущего посетителя (персональный флаг приватности
     * или принадлежность к приватной группе). Для «полного» доступа всегда false.
     */
    function ft_person_is_private($person_id) {
        if (!(int) $person_id) {
            return false;
        }
        if (ft_privacy_visibility() === 'full') {
            return false;
        }
        if (get_post_meta($person_id, '_family_member_private', true)) {
            return true;
        }
        $group_id = (int) get_post_meta($person_id, '_family_member_group_id', true);
        if ($group_id && get_post_meta($group_id, '_family_group_private', true)) {
            return true;
        }
        return false;
    }
}
if (!function_exists('ft_person_display_name')) {
    /**
     * Имя персоны для публичного показа: при скрытии отчества/фамилии
     * остаётся только имя. $default — имя, уже известное вызывающему коду.
     */
    function ft_person_display_name($person_id, $default = '') {
        $name = ('' !== (string) $default) ? $default : get_the_title($person_id);
        $person_id = (int) $person_id;
        if ($person_id && ft_privacy_visibility() !== 'full' && ft_hide_field('name_parts')) {
            $first = get_post_meta($person_id, '_family_member_first_name', true);
            if ('' !== trim((string) $first)) {
                return $first;
            }
        }
        return $name;
    }
}
if (!function_exists('ft_privacy_render_blocked')) {
    /**
     * HTML-заглушка для полностью закрытого доступа (приватное древо / скрытие
     * от незарегистрированных). Знакомая обёртка контента темы межстраничных шаблонов.
     */
    function ft_privacy_render_blocked() {
        return '<div class="family-tree-privacy-blocked"><h2>' . esc_html__('Доступ ограничен', 'genius-family-tree') . '</h2><p>' . esc_html(ft_privacy_stub_text()) . '</p></div>';
    }
}
if (!function_exists('ft_privacy_render_person_hidden')) {
    function ft_privacy_render_person_hidden() {
        return '<div class="family-tree-privacy-person"><h1>' . esc_html__('Персона скрыта администратором', 'genius-family-tree') . '</h1></div>';
    }
}
if (!function_exists('family_tree_font_size_value')) {
    function family_tree_font_size_value($option_name, $default) {
        $value = (int) get_option($option_name, 0);
        if ($value <= 0) {
            return $default;
        }
        return $value;
    }
}
if (!function_exists('ft_lighten_color')) {
    function ft_lighten_color($hex, $percent = 85) {
        $hex = ltrim($hex, '#');
        if (strlen($hex) === 3) {
            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
        }
        $r = hexdec(substr($hex, 0, 2));
        $g = hexdec(substr($hex, 2, 2));
        $b = hexdec(substr($hex, 4, 2));
        $r = round($r + (255 - $r) * $percent / 100);
        $g = round($g + (255 - $g) * $percent / 100);
        $b = round($b + (255 - $b) * $percent / 100);
        return sprintf('#%02x%02x%02x', $r, $g, $b);
    }
}
// === Хелперы для именованных фотоальбомов ===
/**
 * Ключ post-meta для альбомов/папок раздела семейного архива.
 * Раздел «photoalbums» хранит данные в legacy-ключе _family_member_albums,
 * остальные разделы — в _family_member_albums_{section}.
 *
 * @param string $section ключ раздела (photoalbums|documents|video|tree|custom id).
 * @return string
 */
if (!function_exists('ft_archive_section_meta_key')) {
    function ft_archive_section_meta_key($section = 'photoalbums') {
        $section = sanitize_key($section);
        if ('' === $section || 'photoalbums' === $section) {
            return '_family_member_albums';
        }
        return '_family_member_albums_' . $section;
    }
}
