if (!function_exists('ft_get_albums')) {
    function ft_get_albums($post_id, $section = 'photoalbums') {
        $post_id = (int) $post_id;
        if (!$post_id) {
            return array();
        }
        $meta_key = ft_archive_section_meta_key($section);
        $albums = get_post_meta($post_id, $meta_key, true);
        if (is_array($albums)) {
            return ft_normalize_albums($albums);
        }
        // Миграция: старый формат _family_member_photos → один альбом (только для photoalbums)
        if ('photoalbums' === sanitize_key($section)) {
            $legacy_photos = get_post_meta($post_id, '_family_member_photos', true);
            if (is_array($legacy_photos) && !empty($legacy_photos)) {
                $legacy_photos = array_values(array_filter(array_map('intval', $legacy_photos)));
                $albums = array(array(
                    'name'   => 'Фотоальбом',
                    'photos' => $legacy_photos,
                ));
                update_post_meta($post_id, $meta_key, $albums);
                return ft_normalize_albums($albums);
            }
        }
        return array();
    }
}
if (!function_exists('ft_normalize_albums')) {
    function ft_normalize_albums($albums) {
        if (!is_array($albums)) {
            return array();
        }
        foreach ($albums as &$album) {
            if (!is_array($album)) {
                $album = array('name' => '', 'photos' => array());
            }
            if (empty($album['name'])) {
                $album['name'] = 'Альбом';
            }
            if (!isset($album['photos']) || !is_array($album['photos'])) {
                $album['photos'] = array();
            }
            if (empty($album['cover'])) {
                $album['cover'] = 0;
            }
            $album['cover'] = (int) $album['cover'];
            if (!isset($album['description'])) {
                $album['description'] = '';
            }
            $album['description'] = (string) $album['description'];
        }
        unset($album);
        return array_values($albums);
    }
}
if (!function_exists('ft_save_albums')) {
    function ft_save_albums($post_id, $albums, $section = 'photoalbums') {
        update_post_meta((int) $post_id, ft_archive_section_meta_key($section), $albums);
    }
}
if (!function_exists('ft_add_album')) {
    function ft_add_album($post_id, $name = '', $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        if (empty($name)) {
            $n = count($albums) + 1;
            $name = 'Альбом ' . $n;
            while (in_array($name, array_column($albums, 'name'), true)) {
                $n++;
                $name = 'Альбом ' . $n;
            }
        }
        $albums[] = array('name' => $name, 'photos' => array());
        ft_save_albums($post_id, $albums, $section);
        return count($albums) - 1;
    }
}
if (!function_exists('ft_rename_album')) {
    function ft_rename_album($post_id, $album_index, $new_name, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $album_index = (int) $album_index;
        if (isset($albums[$album_index])) {
            $albums[$album_index]['name'] = sanitize_text_field($new_name);
            ft_save_albums($post_id, $albums, $section);
            return true;
        }
        return false;
    }
}
if (!function_exists('ft_delete_album')) {
    function ft_delete_album($post_id, $album_index, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $album_index = (int) $album_index;
        if (isset($albums[$album_index])) {
            array_splice($albums, $album_index, 1);
            ft_save_albums($post_id, $albums, $section);
            return true;
        }
        return false;
    }
}
if (!function_exists('ft_add_photos_to_album')) {
    function ft_add_photos_to_album($post_id, $album_index, $photo_ids, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $album_index = (int) $album_index;
        if (!isset($albums[$album_index])) {
            return 0;
        }
        $added = 0;
        foreach ($photo_ids as $photo_id) {
            $photo_id = (int) $photo_id;
            if (!$photo_id) {
                continue;
            }
            $attachment = get_post($photo_id);
            if (!$attachment || $attachment->post_type !== 'attachment') {
                continue;
            }
            if (!in_array($photo_id, $albums[$album_index]['photos'], true)) {
                $albums[$album_index]['photos'][] = $photo_id;
                $added++;
            }
        }
        ft_save_albums($post_id, $albums, $section);
        return $added;
    }
}
if (!function_exists('ft_remove_photo_from_album')) {
    function ft_remove_photo_from_album($post_id, $album_index, $photo_id, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $album_index = (int) $album_index;
        $photo_id = (int) $photo_id;
        if (!isset($albums[$album_index])) {
            return false;
        }
        $albums[$album_index]['photos'] = array_values(
            array_diff($albums[$album_index]['photos'], array($photo_id))
        );
        ft_save_albums($post_id, $albums, $section);
        return true;
    }
}
if (!function_exists('ft_reorder_album_photos')) {
    function ft_reorder_album_photos($post_id, $album_index, $photo_ids, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $album_index = (int) $album_index;
        if (!isset($albums[$album_index])) {
            return false;
        }
        $current = array_values(array_map('intval', $albums[$album_index]['photos']));
        $allowed = array_flip($current);
        $new_order = array();
        foreach ($photo_ids as $photo_id) {
            $photo_id = (int) $photo_id;
            if ($photo_id && isset($allowed[$photo_id])) {
                $new_order[] = $photo_id;
            }
        }
        foreach ($current as $photo_id) {
            if (!in_array($photo_id, $new_order, true)) {
                $new_order[] = $photo_id;
            }
        }
        $albums[$album_index]['photos'] = $new_order;
        ft_save_albums($post_id, $albums, $section);
        return true;
    }
}
if (!function_exists('ft_reorder_albums')) {
    function ft_reorder_albums($post_id, $album_order, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $indexes = (array) $album_order;
        $indexes = array_values(array_unique(array_map('intval', $indexes)));
        $count = count($albums);
        $reordered = array();
        foreach ($indexes as $idx) {
            if ($idx >= 0 && $idx < $count && isset($albums[$idx]) && !isset($reordered[$idx])) {
                $reordered[$idx] = $albums[$idx];
            }
        }
        foreach ($albums as $idx => $album) {
            if (!isset($reordered[$idx])) {
                $reordered[$idx] = $album;
            }
        }
        $reordered = array_values($reordered);
        if ($reordered == $albums) {
            return true;
        }
        ft_save_albums($post_id, $reordered, $section);
        return true;
    }
}
if (!function_exists('ft_update_album_meta')) {
    function ft_update_album_meta($post_id, $album_index, $cover, $description = '', $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        $album_index = (int) $album_index;
        if (!isset($albums[$album_index])) {
            return false;
        }
        $cover = (int) $cover;
        if ($cover && get_post_type($cover) !== 'attachment') {
            $cover = 0;
        }
        $albums[$album_index]['cover'] = $cover;
        $albums[$album_index]['description'] = sanitize_textarea_field($description);
        ft_save_albums($post_id, $albums, $section);
        return true;
    }
}
if (!function_exists('ft_get_album_photo_count')) {
    function ft_get_album_photo_count($post_id, $album_index = null, $section = 'photoalbums') {
        $albums = ft_get_albums($post_id, $section);
        if ($album_index !== null && isset($albums[(int) $album_index])) {
            return count($albums[(int) $album_index]['photos']);
        }
        $total = 0;
        foreach ($albums as $album) {
            $total += count($album['photos']);
        }
        return $total;
    }
}
if (!function_exists('ft_get_all_albums_photo_count')) {
    function ft_get_all_albums_photo_count($post_id, $section = 'photoalbums') {
        return ft_get_album_photo_count($post_id, null, $section);
    }
}
/**
 * Склонение слова «альбом» для переданного количества.
 * Примеры: 1 альбом, 2-4 альбома, 5-20 альбомов.
 */
if (!function_exists('ft_album_count_label')) {
    function ft_album_count_label($count) {
        $count = (int) $count;
        $abs = abs($count) % 100;
        $last = $abs % 10;
        if ($last === 1 && $abs !== 11) {
            $word = __('альбом', 'genius-family-tree');
        } elseif ($last >= 2 && $last <= 4 && ($abs < 12 || $abs > 14)) {
            $word = __('альбома', 'genius-family-tree');
        } else {
            $word = __('альбомов', 'genius-family-tree');
        }
        return $count . ' ' . $word;
    }
}
/**
 * Русское склонение существительного по количеству.
 * @param int    $count число.
 * @param string $one   форма для 1 (альбом/папка).
 * @param string $few   форма для 2-4 (альбома/папки).
 * @param string $many  форма для 5+ (альбомов/папок).
 */
if (!function_exists('ft_ru_plural')) {
    function ft_ru_plural($count, $one, $few, $many) {
        $count = absint($count);
        $abs = abs($count) % 100;
        $last = $abs % 10;
        if ($last === 1 && $abs !== 11) {
            $word = $one;
        } elseif ($last >= 2 && $last <= 4 && ($abs < 12 || $abs > 14)) {
            $word = $few;
        } else {
            $word = $many;
        }
        return $count . ' ' . $word;
    }
}
/**
 * Счётная подпись для раздела семейного архива: «2 папки, 5 документов».
 * Слова зависят от раздела (альбомы/папки/источники/адресаты и фото/документы/сканы).
 *
 * @param string $section ID раздела.
 * @param int    $folders количество папок/альбомов.
 * @param int    $files   количество элементов (фото/документов/сканов).
 */
if (!function_exists('ft_archive_section_counts_label')) {
    function ft_archive_section_counts_label($section, $folders, $files) {
        $section = sanitize_key($section);
        $words = array(
            'photoalbums' => array(
                __('альбом', 'genius-family-tree'),
                __('альбома', 'genius-family-tree'),
                __('альбомов', 'genius-family-tree'),
                __('фотография', 'genius-family-tree'),
                __('фотографии', 'genius-family-tree'),
                __('фотографий', 'genius-family-tree'),
            ),
            'documents' => array(
                __('папка', 'genius-family-tree'),
                __('папки', 'genius-family-tree'),
                __('папок', 'genius-family-tree'),
                __('документ', 'genius-family-tree'),
                __('документа', 'genius-family-tree'),
                __('документов', 'genius-family-tree'),
            ),
            'video' => array(
                __('источник', 'genius-family-tree'),
                __('источника', 'genius-family-tree'),
                __('источников', 'genius-family-tree'),
                __('скан', 'genius-family-tree'),
                __('скана', 'genius-family-tree'),
                __('сканов', 'genius-family-tree'),
            ),
            'tree' => array(
                __('адресат', 'genius-family-tree'),
                __('адресата', 'genius-family-tree'),
                __('адресатов', 'genius-family-tree'),
                __('письмо', 'genius-family-tree'),
                __('письма', 'genius-family-tree'),
                __('писем', 'genius-family-tree'),
            ),
        );
        if (empty($words[$section])) {
            $section = 'photoalbums';
        }
        $w = $words[$section];
        return ft_ru_plural($folders, $w[0], $w[1], $w[2]) . ', ' . ft_ru_plural($files, $w[3], $w[4], $w[5]);
    }
}
/**
 * Склонение названия элемента раздела для количества: «3 документа», «1 скан».
 * Кастомные разделы считаются как фотоальбомы («файл»).
 *
 * @param string $section ключ раздела.
 * @param int    $count   количество.
 * @return string
 */
if (!function_exists('ft_archive_item_name')) {
    function ft_archive_item_name($section, $count) {
        $section = sanitize_key($section);
        $words = array(
            'photoalbums' => array(__('фото', 'genius-family-tree'), __('фото', 'genius-family-tree'), __('фото', 'genius-family-tree')),
            'documents'   => array(__('документ', 'genius-family-tree'), __('документа', 'genius-family-tree'), __('документов', 'genius-family-tree')),
            'video'       => array(__('скан', 'genius-family-tree'), __('скана', 'genius-family-tree'), __('сканов', 'genius-family-tree')),
            'tree'        => array(__('письмо', 'genius-family-tree'), __('письма', 'genius-family-tree'), __('писем', 'genius-family-tree')),
        );
        $f = isset($words[$section]) ? $words[$section] : array(__('файл', 'genius-family-tree'), __('файла', 'genius-family-tree'), __('файлов', 'genius-family-tree'));
        return ft_ru_plural($count, $f[0], $f[1], $f[2]);
    }
}
