/**
 * Текущие настройки таба «Алфавитный указатель» семейного архива
 * (сохранённые + значения по умолчанию).
 *
 * @return array массив настроек.
 */
if (!function_exists('ft_get_archive_catalog_settings')) {
    function ft_get_archive_catalog_settings($force = false) {
        static $cache = null;
        if (null !== $cache && !$force) {
            return $cache;
        }
        $defaults = ft_get_archive_catalog_defaults();
        $saved = get_option('family_tree_archive_catalog_settings', array());
        if (!is_array($saved)) {
            $saved = array();
        }
        $cache = array_merge($defaults, $saved);
        return $cache;
    }
}
/**
 * Иконка кнопки «Сбросить» — единая для всех контролов (как у «Ширина контейнера»).
 */
function ft_reset_icon_svg() {
    return '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" focusable="false"><path d="M12.9 3.1A6 6 0 1 0 14 8h-1.5A4.5 4.5 0 1 1 8 3.5c1.2 0 2.3.5 3.1 1.2L9 7h6V1z"/></svg>';
}
/**
 * Единый контрол фона (стиль «как у Kadence», собственные классы ft-*):
 * тип Классический/Градиент, цвет с палитрой и прозрачностью, изображение
 * (медиатека/URL), градиент (тип Линейный/Радиальный, угол в градусах).
 *
 * Параметры ($args):
 *  - id:            базовый id (уникальный префикс) контрола
 *  - label:         подпись
 *  - help:          пояснение (components-base-control__help)
 *  - color_name:    name поля цвета
 *  - color_value:   текущий цвет
 *  - color_default: цвет по умолчанию (кнопка Сбросить)
 *  - type_name:     name поля типа (classic|gradient)
 *  - type_value:    текущий тип
 *  - grad_name:     name поля градиента (строка CSS, пустая — берётся из type_name+angle)
 *  - grad_value:    текущий CSS-градиент
 *  - gtype_name:    name поля типа градиента (linear|radial)
 *  - gtype_value:   текущий тип градиента
 *  - angle_name:    name поля угла (градусы)
 *  - angle_value:   текущий угол
 *  - image_name:    name поля изображения ('' — блок изображения скрыт)
 *  - image_value:   текущий URL изображения
 *  - defaults:      массив ['type'=>..,'grad'=>..,'gtype'=>..,'angle'=>..,'image'=>..] для сброса
 */
function ft_render_bg_control($args) {
    $args = wp_parse_args($args, array(
        'id'            => 'ft-bg',
        'label'         => '',
        'help'          => '',
        'color_name'    => '',
        'color_id'      => '',
        'color_value'   => '',
        'color_default' => '',
        // Подсказка в пустом поле. Здесь и по умолчанию значение не
        // отправляется: placeholder браузером в POST не попадает.
        'color_placeholder' => '',
        'show_reset'    => true,
        'type_name'     => '',
        'type_value'    => 'classic',
        'grad_name'     => '',
        'grad_value'    => '',
        'gtype_name'    => '',
        'gtype_value'   => 'linear',
        'angle_name'    => '',
        'angle_value'   => 180,
        'image_name'    => '',
        'image_value'   => '',
        'defaults'      => array(),
        'show_type'     => true,
    ));
    $id       = sanitize_html_class($args['id']);
    $type     = ('gradient' === $args['type_value']) ? 'gradient' : 'classic';
    $gtype    = ('radial' === $args['gtype_value']) ? 'radial' : 'linear';
    $angle    = max(-360, min(360, intval($args['angle_value'])));
    $def      = wp_parse_args((array) $args['defaults'], array('type' => 'classic', 'grad' => '', 'gtype' => 'linear', 'angle' => 180, 'image' => ''));
    $show_img = $args['image_name'] !== '';
    $show_type = !empty($args['show_type']);
    $out = '<div class="ft-bg-control' . ($show_type ? '' : ' ft-bg-control--no-type') . '" id="' . esc_attr($id) . '-ctrl" data-ft-bg-control>';
    // Тип: Классический / Градиент
    $out .= '<input type="hidden" name="' . esc_attr($args['type_name']) . '" class="ft-bg-type-input" value="' . esc_attr($type) . '" data-ft-bg-def="' . esc_attr($def['type']) . '" />';
    if ($show_type) {
        $out .= '<div class="ft-bg-type-tabs" role="group">';
        $out .= '<button type="button" class="ft-bg-type-tab' . ('classic' === $type ? ' is-active' : '') . '" data-ft-bg-type="classic">' . esc_html__('Классический', 'genius-family-tree') . '</button>';
        $out .= '<button type="button" class="ft-bg-type-tab' . ('gradient' === $type ? ' is-active' : '') . '" data-ft-bg-type="gradient">' . esc_html__('Градиент', 'genius-family-tree') . '</button>';
        $out .= '</div>';
    }
    // Панель «Классический»
    $out .= '<div class="ft-bg-pane ft-bg-pane-classic"' . ('classic' === $type ? '' : ' style="display:none;"') . '>';
    // Цвет
    $out .= '<div class="ft-bg-color-row">';
    $out .= '<span class="ft-bg-swatch" role="button" tabindex="0" title="' . esc_attr__('Открыть палитру', 'genius-family-tree') . '"></span>';
    $out .= '<input type="text" name="' . esc_attr($args['color_name']) . '"' . ('' !== $args['color_id'] ? ' id="' . esc_attr($args['color_id']) . '"' : '') . ' class="ft-bg-color-input small-text" value="' . esc_attr($args['color_value']) . '" data-default-color="' . esc_attr($args['color_default']) . '" placeholder="' . esc_attr('' !== $args['color_placeholder'] ? $args['color_placeholder'] : __('прозрачный', 'genius-family-tree')) . '" />';
    if (!empty($args['show_reset'])) {
        $out .= '<button type="button" class="ft-bg-reset" title="' . esc_attr__('Сбросить', 'genius-family-tree') . '">' . ft_reset_icon_svg() . '<span class="screen-reader-text">' . esc_html__('Сбросить', 'genius-family-tree') . '</span></button>';
    }
    $out .= '</div>'; // .ft-bg-color-row
    // Изображение
    if ($show_img) {
        $out .= '<div class="ft-bg-image-row">';
        $out .= '<input type="hidden" name="' . esc_attr($args['image_name']) . '" class="ft-bg-image-url" value="' . esc_attr($args['image_value']) . '" data-ft-bg-def="' . esc_attr($def['image']) . '" />';
        $out .= '<div class="ft-bg-image-buttons">';
        $out .= '<button type="button" class="button ft-bg-image-open">' . esc_html__('Выбрать изображение', 'genius-family-tree') . '</button>';
        $out .= '<button type="button" class="button ft-bg-image-urlmode">' . esc_html__('Вставить из URL', 'genius-family-tree') . '</button>';
        $out .= '</div>';
        $out .= '<div class="ft-bg-image-urlrow"' . (empty($args['image_value']) ? ' style="display:none;"' : '') . '><input type="url" class="regular-text ft-bg-image-urlinput" value="' . esc_attr($args['image_value']) . '" placeholder="https://..." /><button type="button" class="button ft-bg-image-urlok">' . esc_html__('ОК', 'genius-family-tree') . '</button></div>';
        $out .= '<button type="button" class="button-link ft-bg-image-remove"' . (empty($args['image_value']) ? ' style="display:none;"' : '') . '>' . esc_html__('Удалить', 'genius-family-tree') . '</button>';
        $out .= '<div class="ft-bg-image-preview"' . (empty($args['image_value']) ? ' style="display:none;"' : '') . '><img src="' . esc_url($args['image_value']) . '" alt="" /></div>';
        $out .= '</div>';
    }
    $out .= '</div>'; // .ft-bg-pane-classic
    // Панель «Градиент»
    if ($show_type) {
        $out .= '<div class="ft-bg-pane ft-bg-pane-gradient"' . ('gradient' === $type ? '' : ' style="display:none;"') . '>';
    $out .= '<input type="hidden" name="' . esc_attr($args['grad_name']) . '" class="ft-bg-grad-input" value="' . esc_attr($args['grad_value']) . '" data-ft-bg-def="' . esc_attr($def['grad']) . '" />';
    $out .= '<div class="ft-bg-grad-bar">';
    $out .= '</div>';
    // Ряд настроек градиента: лейбл поля ВСЕГДА над инпутом (колонка),
    // «Сбросить» — последним элементом этого же ряда, без своей строки.
    $out .= '<div class="ft-bg-grad-controls">';
    $out .= '<div class="ft-bg-grad-field">';
    $out .= '<span class="components-base-control__label ft-phs-caption ft-bg-grad-label">' . esc_html__('Тип', 'genius-family-tree') . '</span>';
    $out .= '<select class="ft-bg-grad-type" name="' . esc_attr($args['gtype_name']) . '" data-ft-bg-def="' . esc_attr($def['gtype']) . '">';
    $out .= '<option value="linear"' . selected($gtype, 'linear', false) . '>' . esc_html__('Линейный', 'genius-family-tree') . '</option>';
    $out .= '<option value="radial"' . selected($gtype, 'radial', false) . '>' . esc_html__('Радиальный', 'genius-family-tree') . '</option>';
    $out .= '</select>';
    $out .= '</div>';
    $out .= '<div class="ft-bg-grad-field">';
    $out .= '<span class="components-base-control__label ft-phs-caption ft-bg-grad-label">' . esc_html__('Угол', 'genius-family-tree') . '</span>';
    $out .= '<div class="ft-bg-grad-angle-row">';
    $out .= '<div class="ft-bg-grad-angle-circle" role="slider" aria-label="' . esc_attr__('Угол градиента', 'genius-family-tree') . '" tabindex="0" aria-valuemin="-360" aria-valuemax="360" aria-valuenow="' . esc_attr($angle) . '">';
    $out .= '<div class="ft-bg-grad-angle-circle-indicator-wrapper" style="transform: rotate(' . esc_attr($angle) . 'deg);"><div class="ft-bg-grad-angle-circle-indicator"></div></div>';
    $out .= '</div>';
    $out .= '<input type="number" class="ft-bg-grad-angle" name="' . esc_attr($args['angle_name']) . '" min="-360" max="360" step="1" value="' . esc_attr($angle) . '" data-ft-bg-def="' . esc_attr($def['angle']) . '" />';
    $out .= '<span class="ft-bg-grad-deg">°</span>';
    $out .= '</div>';
    $out .= '</div>';
    $out .= '<button type="button" class="ft-bg-grad-reset" title="' . esc_attr__('Сбросить', 'genius-family-tree') . '">' . ft_reset_icon_svg() . '<span class="screen-reader-text">' . esc_html__('Сбросить', 'genius-family-tree') . '</span></button>';
    $out .= '</div>'; // .ft-bg-grad-controls
    $out .= '</div>'; // .ft-bg-pane-gradient
    }
    // Общая палитра контрола (классический цвет и стопы градиента).
    // Вынесена на уровень контрола, чтобы открываться и из панели «Градиент».
    $out .= '<div class="ft-bg-popover" role="dialog" aria-label="' . esc_attr__('Палитра цвета', 'genius-family-tree') . '">';
    $out .= '<div class="ft-bg-sv"><div class="ft-bg-sv-bg"></div><span class="ft-bg-sv-thumb"></span></div>';
    $out .= '<div class="ft-bg-hue"><span class="ft-bg-hue-thumb"></span></div>';
    $out .= '<div class="ft-bg-alpha-row"><label>' . esc_html__('Прозрачность', 'genius-family-tree') . '</label><input type="range" class="ft-bg-alpha" min="0" max="100" value="100" /><span class="ft-bg-alpha-value">100%</span></div>';
    $out .= '<div class="ft-bg-channel-row">';
    $out .= '<span class="ft-bg-channel ft-bg-channel-hex">HEX<input type="text" class="ft-bg-hex" maxlength="7" /></span>';
    $out .= '<span class="ft-bg-channel">R<input type="number" class="ft-bg-rgb ft-bg-r" min="0" max="255" /></span>';
    $out .= '<span class="ft-bg-channel">G<input type="number" class="ft-bg-rgb ft-bg-g" min="0" max="255" /></span>';
    $out .= '<span class="ft-bg-channel">B<input type="number" class="ft-bg-rgb ft-bg-b" min="0" max="255" /></span>';
    $out .= '<span class="ft-bg-channel">A<input type="number" class="ft-bg-a" min="0" max="1" step="0.01" /></span>';
    $out .= '</div>';
    $out .= '<div class="ft-bg-quick">';
    $ft_quick = array('#000000', '#abb8c3', '#ffffff', '#f78da7', '#cf2e2e', '#ff6900', '#fcb900', '#7bdcba', '#00d084', '#8ed1fc', '#0693e3', '#9b51e0');
    foreach ($ft_quick as $ft_q) {
        $out .= '<button type="button" class="ft-bg-quick-swatch" style="background:' . esc_attr($ft_q) . ';" data-color="' . esc_attr($ft_q) . '" title="' . esc_attr($ft_q) . '"></button>';
    }
    $out .= '</div>';
    $out .= '<button type="button" class="button-link ft-bg-remove-stop" style="display:none;">' . esc_html__('Удалить точку', 'genius-family-tree') . '</button>';
    $out .= '</div>'; // .ft-bg-popover
    if ($args['help'] !== '') {
        $out .= '<p class="components-base-control__help">' . esc_html($args['help']) . '</p>';
    }
    $out .= '</div>'; // .ft-bg-control
    return $out;
}
/**
 * Устройства для адаптивных настроек: ключ => подпись + иконка dashicons.
 * Порядок важен: он же используется при выводе @media.
 */
function ft_device_list() {
    return array(
        'desktop' => array(
            'label' => __('Десктоп', 'genius-family-tree'),
            'icon'  => 'desktop',
        ),
        'tablet' => array(
            'label' => __('Планшет', 'genius-family-tree'),
            'icon'  => 'tablet',
        ),
        'mobile' => array(
            'label' => __('Мобильные', 'genius-family-tree'),
            'icon'  => 'smartphone',
        ),
    );
}
/**
 * Media-запрос устройства. Для десктопа возвращает '' — базовые правила
 * выводятся без обёртки @media.
 */
function ft_device_media($device) {
    if ('tablet' === $device) {
        return 'max-width: 1024px';
    }
    if ('mobile' === $device) {
        return 'max-width: 767px';
    }
    return '';
}
/**
 * Схема настроек шапки персоны: блок => (состояние) => ключ => значение по
 * умолчанию. Пустое значение = «не задано» (наследовать/дефолт).
 *
 * «title» состояний не имеет. «button» имеет normal/hover, где hover
 * наследует normal при незаполненных значениях.
 */
function ft_phs_schema() {
    $button = array(
        'bg_type'          => 'classic',
        'bg_color'         => '',
        'bg_gradient'      => '',
        'bg_gradient_type' => 'linear',
        'bg_angle'         => 180,
        'text_color'       => '',
        'font_family'      => '',
        'font_size'        => 0,
        'font_weight'      => 0,
        'border_width'     => '',
        'border_style'     => '',
        'border_color'     => '',
    );
    return array(
        'title'  => array(
            'color'       => '',
            'font_family' => '',
            'font_size'   => 0,
            'font_weight' => 0,
            'text_align'  => '',
        ),
        'button'  => array(
            'normal' => $button,
            'hover'  => $button,
        ),
        // Габариты кнопки: одни на оба состояния, поэтому отдельный блок без
        // состояний (ft_phs_normalize читает его напрямую из $raw[$dev]['box']).
        'box'    => array(
            'margin'  => '',
            'padding' => '',
            'radius'  => '',
            'align'   => '',
        ),
    );
}
/**
 * Схема настроек кнопок ленты альбомов — ссылок .ft-photo-page__nav-link
 * в шапке блока фотографий.
 *
 * Устроена как кнопка «Показать в древе» в настройках шапки персоны: устройство
 * -> состояние (Обычный / При наведении) -> значения, плюс общие габариты
 * (отступы и скругление) в «box». Выравнивания по горизонтали здесь нет
 * намеренно: кнопка стоит в flex-строке рядом с заголовком, её положение
 * задаёт сама строка.
 *
 * @return array
 */
function ft_album_navlink_schema() {
    $phs = ft_phs_schema();
    return array(
        'box'    => array(
            'margin'  => '',
            'padding' => '',
            'radius'  => '',
        ),
        'button' => $phs['button'],
    );
}
/**
 * Настройки кнопок ленты альбомов, приведённые к схеме: пустое значение =
 * «не задано» (наследование Десктопа или дефолт темы).
 *
 * @param mixed $raw значение опции family_tree_album_settings['navlink']
 * @return array
 */
function ft_album_navlink_normalized($raw) {
    $raw = is_array($raw) ? $raw : array();
    $out = ft_phs_normalize($raw, ft_album_navlink_schema(), 'button');
    // Какая вкладка «Обычный / При наведении» открыта — не часть схемы, но без
    // неё выбор сбрасывался бы на «Обычный» после каждого сохранения. Так же,
    // как в ft_get_person_header_settings().
    foreach (array_keys(ft_device_list()) as $dev) {
        $st = isset($raw[$dev]['button_state']) ? $raw[$dev]['button_state'] : 'normal';
        $out[$dev]['button_state'] = ('hover' === $st) ? 'hover' : 'normal';
    }
    return $out;
}
/**
 * Чекбокс линии под заголовком + её цвет и толщина.
 *
 * Разметка и поведение те же, что у чекбоксов «Добавить подчёркивание» /
 * «Добавить разделители» в сайдбаре персоны: чекбокс показывает или прячет свой
 * ряд, а при снятии галочки поля чистятся, чтобы выключенная опция ничего не
 * переносила с собой. Различается только то, как вычисляется «включено»:
 * у Десктопа снятая галочка — это «выключено», у Планшета и Мобильных — «не
 * задано», то есть решение Десктопа.
 *
 * @param array $args см. ft_render_separator_control() ниже по коду вызова
 * @return string
 */
function ft_render_separator_control($args) {
    $args = wp_parse_args($args, array(
        'toggle'        => '',
        'color'         => '',
        'width'         => 0,
        'desk_color'    => '',
        'desk_width'    => 0,
        'is_desk'       => true,
        'name_prefix'   => '',
        'id_prefix'     => '',
        'suffix'        => '',
        'toggle_label'  => __('Добавить разделитель', 'genius-family-tree'),
        'color_label'   => __('Цвет разделителя', 'genius-family-tree'),
        'width_label'   => __('Толщина разделителя', 'genius-family-tree'),
        'color_default' => '#e5e5e5',
    ));
    $is_on = $args['is_desk'] ? ('0' !== (string) $args['toggle']) : ('1' === (string) $args['toggle']);
    $sfx   = $args['suffix'];
    // Незаданное поле показываем серым значением Десктопа (см. блок заголовка
    // ленты): placeholder браузером в POST не отправляется.
    $pick  = function ($own, $desk) use ($args) {
        $raw = trim((string) $own);
        if ($args['is_desk'] || ('' !== $raw && '0' !== $raw)) {
            return '';
        }
        return trim((string) $desk);
    };
    $out  = '<div class="ft-phs-checkbox-block">';
    $out .= '<label class="ft-phs-checkbox-label">';
    $out .= '<input type="checkbox" class="ft-phs-checkbox" name="' . esc_attr($args['name_prefix'] . '_separator' . $sfx) . '" id="' . esc_attr($args['id_prefix'] . '-separator') . '" value="1" ' . checked($is_on, true, false) . ' data-ft-phs-underline-toggle /> ';
    $out .= esc_html($args['toggle_label']);
    $out .= '</label>';
    if (! $args['is_desk']) {
        $out .= '<p class="components-base-control__help">' . esc_html($is_on
            ? __('Задано своё значение для этого устройства.', 'genius-family-tree')
            : __('Наследуется с Десктопа.', 'genius-family-tree')) . '</p>';
    }
    $out .= '<div class="ft-phs-row ft-phs-underline-settings' . ($is_on ? ' is-on' : '') . '" data-ft-phs-underline-settings>';
    $out .= ft_render_phs_cell(
        $args['color_label'],
        ft_render_color_field($args['name_prefix'] . '_separator_color' . $sfx, $args['id_prefix'] . '-separator-color', $args['color'], $args['color_default'], $pick($args['color'], $args['desk_color'])),
        'ft-phs-cell--color'
    );
    $out .= ft_render_phs_cell(
        $args['width_label'],
        ft_render_size_field($args['name_prefix'] . '_separator_width' . $sfx, $args['id_prefix'] . '-separator-width', $args['width'], $pick($args['width'], $args['desk_width'])),
        'ft-phs-cell--size'
    );
    $out .= '</div>';
    $out .= '</div>';
    return $out;
}
/**
 * CSS кнопок ленты альбомов для одного устройства.
 *
 * Селектор ограничен шапкой блока: тот же класс .ft-photo-page__nav-link стоит
 * на странице альбома и в сайдбаре персоны, там у ссылок свои настройки.
 *
 * @param array  $s   нормализованные настройки по ft_album_navlink_schema()
 * @param string $dev устройство: desktop | tablet | mobile
 * @return string
 */
function ft_album_navlink_device_css($s, $dev) {
    $selectors = array(
        '.family-member-photo-album__header .ft-photo-page__nav-link',
        '.family-member-photo-album__subheader .ft-photo-page__nav-link',
    );
    $sel = implode(', ', $selectors);
    $hover_selectors = array();
    foreach ($selectors as $selector) {
        $hover_selectors[] = $selector . ':hover';
        $hover_selectors[] = $selector . ':focus';
    }
    $n   = isset($s[$dev]['button']['normal']) ? $s[$dev]['button']['normal'] : array();
    $h   = isset($s[$dev]['button']['hover']) ? $s[$dev]['button']['hover'] : array();
    $box = isset($s[$dev]['box']) && is_array($s[$dev]['box']) ? $s[$dev]['box'] : array();
    $css = '';

    // Обычное состояние.
    $decl = '';
    if (isset($n['bg_type']) && 'gradient' === $n['bg_type'] && '' !== $n['bg_gradient']) {
        $decl .= ' background: ' . esc_html($n['bg_gradient']) . ' !important;';
    } elseif ('' !== $n['bg_color']) {
        $decl .= ' background: ' . esc_html($n['bg_color']) . ' !important; border-color: ' . esc_html($n['bg_color']) . ' !important;';
    }
    if ('' !== $n['text_color']) {
        $decl .= ' color: ' . esc_html($n['text_color']) . ' !important;';
    }
    if ('' !== $n['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($n['font_family']) . '\', serif !important;';
    }
    if ((int) $n['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $n['font_size'] . 'px !important;';
    }
    if ((int) $n['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $n['font_weight'] . ' !important;';
    }
    $decl .= ft_phs_border_css($n, false);
    // Габариты одни на оба состояния, поэтому только здесь: :hover наследует
    // их от обычного правила.
    if ('' !== $box['margin']) {
        $decl .= ' margin: ' . esc_html($box['margin']) . ' !important;';
    }
    if ('' !== $box['padding']) {
        $decl .= ' padding: ' . esc_html($box['padding']) . ' !important;';
    }
    if ('' !== $box['radius']) {
        $decl .= ' border-radius: ' . esc_html($box['radius']) . ' !important;';
    }
    if ('' !== $decl) {
        $css .= $sel . ' {' . $decl . ' }';
    }

    // При наведении: незаданные значения наследуют обычное состояние.
    $hdecl = '';
    if (isset($h['bg_type']) && 'gradient' === $h['bg_type'] && '' !== $h['bg_gradient']) {
        $hdecl .= ' background: ' . esc_html($h['bg_gradient']) . ' !important;';
    } elseif ('' !== $h['bg_color']) {
        $hdecl .= ' background: ' . esc_html($h['bg_color']) . ' !important; border-color: ' . esc_html($h['bg_color']) . ' !important;';
    } elseif ('' !== $n['bg_color'] || (isset($n['bg_type']) && 'gradient' === $n['bg_type'] && '' !== $n['bg_gradient'])) {
        // Фон задан только в обычном состоянии — слегка затемняем при наведении.
        $hdecl .= ' filter: brightness(0.9);';
    }
    if ('' !== $h['text_color']) {
        $hdecl .= ' color: ' . esc_html($h['text_color']) . ' !important;';
    }
    if ('' !== $h['font_family']) {
        $hdecl .= ' font-family: \'' . esc_attr($h['font_family']) . '\', serif !important;';
    }
    if ((int) $h['font_size'] > 0) {
        $hdecl .= ' font-size: ' . (int) $h['font_size'] . 'px !important;';
    }
    if ((int) $h['font_weight'] > 0) {
        $hdecl .= ' font-weight: ' . (int) $h['font_weight'] . ' !important;';
    }
    $hdecl .= ft_phs_border_css($h, true);
    if ('' !== $hdecl) {
        $css .= implode(', ', $hover_selectors) . ' {' . $hdecl . ' }';
    }

    return $css;
}
/**
 * Раздел «Кнопки» ленты альбомов: оформление ссылок
 * .ft-photo-page__nav-link («Все альбомы →») в шапке блока фотографий.
 *
 * Разметка повторяет раздел «Кнопка «Показать в древе»» из настроек шапки
 * персоны: табы устройств, затем габариты кнопки (отступы и скругление — одни
 * на оба состояния) и табы «Обычный / При наведении», где у каждого состояния
 * свой фон, текст и граница. Выравнивания по горизонтали здесь нет: кнопка
 * стоит в flex-строке заголовка, и её положение задаёт сама строка.
 *
 * @param array  $s              настройки по ft_album_navlink_schema()
 * @param array  $ft_fonts        системные гарнитуры
 * @param array  $ft_google_fonts Google Fonts
 * @param string $active          устройство, открытое по умолчанию
 * @return string
 */
function ft_render_album_navlink_buttons($s, $ft_fonts, $ft_google_fonts, $active = 'desktop') {
    $group = 'album-navlink';
    $name  = 'family_tree_album_navlink[';
    $out   = ft_render_device_tabs($group, $active);
    $out  .= '<div class="ft-device-frame" data-ft-device-frame="' . esc_attr($group) . '">';
    foreach (ft_device_list() as $dev => $meta) {
        $is_desk    = ('desktop' === $dev);
        $bx         = isset($s[$dev]['box']) && is_array($s[$dev]['box']) ? $s[$dev]['box'] : array('margin' => '', 'padding' => '', 'radius' => '');
        $bd_box     = isset($s['desktop']['box']) && is_array($s['desktop']['box']) ? $s['desktop']['box'] : array();
        $active_tab = isset($s[$dev]['button_state']) ? $s[$dev]['button_state'] : 'normal';
        // «Не задано» — это и пустая строка, и 0: у размеров и толщины
        // невыбранное значение приходит как 0.
        $is_set     = function ($v) {
            $raw = trim((string) $v);
            return ('' !== $raw && '0' !== $raw);
        };
        $pick       = function ($own, $desk) use ($is_desk, $is_set) {
            if ($is_desk || $is_set($own)) { return ''; }
            return trim((string) $desk);
        };
        // Для кнопки цепочка длиннее: своё значение -> своё «Обычный» ->
        // значение Десктопа в этом же состоянии -> «Обычный» Десктопа.
        $pick_btn   = function ($own, $own_norm, $desk, $desk_norm) use ($is_desk, $is_set) {
            if ($is_desk || $is_set($own)) { return ''; }
            foreach (array($own_norm, $desk, $desk_norm) as $cand) {
                if ($is_set($cand)) { return trim((string) $cand); }
            }
            return '';
        };
        $out .= '<div class="ft-device-panel" data-ft-device-panel="' . esc_attr($dev) . '"' . ($dev === $active ? '' : ' style="display:none;"') . '>';
        $out .= '<div class="ft-phs-block">';
        $out .= '<div class="ft-measure-row ft-phs-boxrow">';
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-album-navlink-' . $dev . '-margin',
            'name'         => $name . $dev . '][box][margin]',
            'value'        => $bx['margin'],
            'placeholder'  => $pick($bx['margin'], isset($bd_box['margin']) ? $bd_box['margin'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Внешние отступы', 'genius-family-tree'),
            'help'         => esc_html__('Внешние отступы (margin) кнопок ленты альбомов. Кнопка с цепочкой позволяет задать каждую сторону отдельно.', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-album-navlink-' . $dev . '-padding',
            'name'         => $name . $dev . '][box][padding]',
            'value'        => $bx['padding'],
            'placeholder'  => $pick($bx['padding'], isset($bd_box['padding']) ? $bd_box['padding'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Внутренние отступы', 'genius-family-tree'),
            'help'         => esc_html__('Внутренние отступы (padding) кнопок ленты альбомов. Кнопка с цепочкой позволяет задать каждую сторону отдельно.', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'          => 'ft-album-navlink-' . $dev . '-radius',
            'name'        => $name . $dev . '][box][radius]',
            'value'       => $bx['radius'],
            'placeholder' => $pick($bx['radius'], isset($bd_box['radius']) ? $bd_box['radius'] : ''),
            'default'     => '0px',
            'label'       => esc_html__('Скругление углов', 'genius-family-tree'),
            'help'        => esc_html__('Радиус скругления углов кнопок ленты альбомов: 0, 4px, 20px, 50% и т.п.', 'genius-family-tree'),
        ));
        $out .= '</div>';

        $out .= '<div class="ft-state-cell" data-state="' . esc_attr($active_tab) . '">';
        $out .= '<div class="ft-layout-tabs ft-state-tabs" data-state-group="' . esc_attr($group . '-' . $dev) . '-btn">';
        $out .= '<label class="ft-layout-tab"><input type="radio" name="' . $name . $dev . '][button_state]" value="normal" ' . checked($active_tab, 'normal', false) . ' /><span>' . esc_html__('Обычный', 'genius-family-tree') . '</span></label>';
        $out .= '<label class="ft-layout-tab"><input type="radio" name="' . $name . $dev . '][button_state]" value="hover" ' . checked($active_tab, 'hover', false) . ' /><span>' . esc_html__('При наведении', 'genius-family-tree') . '</span></label>';
        $out .= '</div>';

        foreach (array('normal', 'hover') as $state) {
            $b           = isset($s[$dev]['button'][$state]) ? $s[$dev]['button'][$state] : array();
            $b_norm      = isset($s[$dev]['button']['normal']) ? $s[$dev]['button']['normal'] : array();
            $b_desk      = isset($s['desktop']['button'][$state]) ? $s['desktop']['button'][$state] : array();
            $b_desk_norm = isset($s['desktop']['button']['normal']) ? $s['desktop']['button']['normal'] : array();
            $sfx         = 'ft-album-navlink-' . $dev . '-' . $state;
            $is_hover    = ('hover' === $state);
            $out .= '<div class="ft-state-group" data-state-group="' . esc_attr($group . '-' . $dev) . '-btn" data-group-state="' . esc_attr($state) . '">';

            // Блок 1. Цвет фона кнопки — Классический / Градиент.
            $out .= '<span class="components-base-control__label ft-phs-sublabel">' . esc_html__('Цвет фона кнопки', 'genius-family-tree') . '</span>';
            $out .= ft_render_bg_control(array(
                'id'            => $sfx . '-bg',
                'color_name'    => $name . $dev . '][button][' . $state . '][bg_color]',
                'color_value'   => $b['bg_color'],
                'color_default' => '#ffffff',
                'color_placeholder' => $pick_btn($b['bg_color'], $b_norm['bg_color'], $b_desk['bg_color'], $b_desk_norm['bg_color']),
                'type_name'     => $name . $dev . '][button][' . $state . '][bg_type]',
                'type_value'    => $b['bg_type'],
                'grad_name'     => $name . $dev . '][button][' . $state . '][bg_gradient]',
                'grad_value'    => $b['bg_gradient'],
                'gtype_name'    => $name . $dev . '][button][' . $state . '][bg_gradient_type]',
                'gtype_value'   => $b['bg_gradient_type'],
                'angle_name'    => $name . $dev . '][button][' . $state . '][bg_angle]',
                'angle_value'   => $b['bg_angle'],
                'help'          => $is_hover
                    ? __('Пусто — используется фон из состояния «Обычный».', 'genius-family-tree')
                    : __('Классический цвет или градиент.', 'genius-family-tree'),
            ));

            // Блок 2. Текст — тот же ряд, что и у заголовка.
            $out .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Текст', 'genius-family-tree') . '</span>';
            $out .= '<div class="ft-phs-row">';
            $out .= ft_render_phs_cell(
                __('Цвет', 'genius-family-tree'),
                ft_render_color_field($name . $dev . '][button][' . $state . '][text_color]', $sfx . '-color', $b['text_color'], '#1d2327', $pick_btn($b['text_color'], $b_norm['text_color'], $b_desk['text_color'], $b_desk_norm['text_color'])),
                'ft-phs-cell--color'
            );
            $out .= ft_render_phs_cell(
                __('Шрифт', 'genius-family-tree'),
                ft_render_font_select($name . $dev . '][button][' . $state . '][font_family]', $sfx . '-font', $b['font_family'], $ft_fonts, $ft_google_fonts, $pick_btn($b['font_family'], $b_norm['font_family'], $b_desk['font_family'], $b_desk_norm['font_family']))
            );
            $out .= ft_render_phs_cell(
                __('Размер', 'genius-family-tree'),
                ft_render_size_field($name . $dev . '][button][' . $state . '][font_size]', $sfx . '-size', $b['font_size'], $pick_btn($b['font_size'], $b_norm['font_size'], $b_desk['font_size'], $b_desk_norm['font_size'])),
                'ft-phs-cell--size'
            );
            $out .= ft_render_phs_cell(
                __('Толщина', 'genius-family-tree'),
                ft_render_weight_select($name . $dev . '][button][' . $state . '][font_weight]', $sfx . '-weight', $b['font_family'], $b['font_weight'], $sfx . '-font', $pick_btn($b['font_weight'], $b_norm['font_weight'], $b_desk['font_weight'], $b_desk_norm['font_weight']))
            );
            // Сбрасываем только поля этого ряда: фон кнопки — соседний блок со
            // своим сбросом, сюда не подмешиваем.
            $out .= ft_render_phs_reset_cell('#' . $sfx . '-color, #' . $sfx . '-font, #' . $sfx . '-size, #' . $sfx . '-weight');
            $out .= '</div>';
            $out .= '<p class="components-base-control__help">' . ($is_hover
                ? esc_html__('Пустые поля наследуют состояние «Обычный».', 'genius-family-tree')
                : esc_html__('Фон, цвет текста, гарнитура, размер и толщина кнопки в состоянии «Обычный».', 'genius-family-tree')) . '</p>';

            // Блок 3. Граница — одна толщина, один стиль и один цвет на всё
            // состояние, как у кнопки «Показать в древе».
            $out .= '<div class="ft-phs-statebox">';
            $out .= ft_render_corner_control(array(
                'id'            => $sfx . '-border',
                'name'          => $name . $dev . '][button][' . $state . '][border_width]',
                'value'         => $b['border_width'],
                'placeholder'   => $pick_btn($b['border_width'], $b_norm['border_width'], $b_desk['border_width'], $b_desk_norm['border_width']),
                'default'       => '1px',
                'max'           => 50,
                'units'         => array('px', 'em', 'rem'),
                'label'         => esc_html__('Граница', 'genius-family-tree'),
                'help'          => $is_hover
                    ? esc_html__('Пусто — наследует границу состояния «Обычный».', 'genius-family-tree')
                    : esc_html__('Рамка вокруг кнопки. Кнопка с цепочкой позволяет задать толщину каждой стороны отдельно.', 'genius-family-tree'),
                'link_title'    => esc_html__('Связанные стороны', 'genius-family-tree'),
                'corner_icons'  => array('↑', '→', '↓', '←'),
                'style_name'    => $name . $dev . '][button][' . $state . '][border_style]',
                'style_value'   => $b['border_style'],
                'style_placeholder' => $pick_btn($b['border_style'], $b_norm['border_style'], $b_desk['border_style'], $b_desk_norm['border_style']),
                'style_default' => 'solid',
                'style_options' => array(
                    'solid'  => __('Сплошная', 'genius-family-tree'),
                    'dashed' => __('Пунктирная (dashed)', 'genius-family-tree'),
                    'dotted' => __('Точечная (dotted)', 'genius-family-tree'),
                    'double' => __('Двойная (double)', 'genius-family-tree'),
                ),
                'color_name'    => $name . $dev . '][button][' . $state . '][border_color]',
                'color_value'   => $b['border_color'],
                'color_placeholder' => $pick_btn($b['border_color'], $b_norm['border_color'], $b_desk['border_color'], $b_desk_norm['border_color']),
                'color_default' => '',
                'color_id'      => $sfx . '-border-color',
                'show_range'    => false,
            ));
            $out .= '</div>';

            $out .= '</div>';
        }
        $out .= '</div>';

        $out .= '<p class="components-base-control__help">' . esc_html__('Оформление ссылок ленты альбомов («Все альбомы →») для этого устройства: фон, текст и граница отдельно для обычного состояния и при наведении, отступы и скругление — одни на оба состояния.', 'genius-family-tree') . '</p>';
        $out .= '</div>';
        $out .= '</div>';
    }
    $out .= '</div>';
    return $out;
}
/**
 * Допустимые значения выравнивания по горизонтали. Пусто = не задано
 * (наследовать Десктоп / дефолт темы).
 */
function ft_phs_align_values() {
    return array('left', 'center', 'right');
}
/**
 * Схема адаптивных настроек сайдбара персоны.
 *
 * Устроена так же, как у шапки (ft_phs_schema): «heading» и «text» — по
 * одному набору полей на устройство, «link» — с состояниями Обычный /
 * При наведении, «link_box» — общие для состояний (выравнивание, отступы
 * и скругление). Подчёркивание, фон, текст и граница — свои у каждого
 * состояния, поэтому «Обычный» и «При наведении» настраиваются независимо.
 */
function ft_pms_schema() {
    $link = array(
        'bg_type'          => 'classic',
        'bg_color'         => '',
        'bg_gradient'      => '',
        'bg_gradient_type' => 'linear',
        'bg_angle'         => 180,
        'color'            => '',
        'font_family'      => '',
        'font_size'        => 0,
        'font_weight'      => 0,
        // Подчёркивание своё у каждого состояния: ссылка может быть
        // подчёркнута в покое и не подчёркнута при наведении (и наоборот).
        // Пусто = не задано (Десктоп — как в теме, остальные наследуют).
        'underline'        => '',
        'border_width'     => '',
        'border_style'     => '',
        'border_color'     => '',
    );
    $text = array(
        'color'       => '',
        'font_family' => '',
        'font_size'   => 0,
        'font_weight' => 0,
        'text_align'  => '',
    );
    // Заголовки: плюс отступы и подчёркивание (опционально).
    $heading = $text + array(
        'margin'          => '',
        'padding'         => '',
        'underline'       => '',
        'underline_color' => '',
        'underline_width' => 0,
    );
    // Текст: плюс разделители таблицы (опционально).
    $text_sep = $text + array(
        'separator'       => '',
        'separator_color' => '',
        'separator_width' => 0,
    );
    // Портрет (аватар сайдбара): пропорции картинки, выравнивание, отступы
    // и граница — всё по одному устройству.
    $portrait = array(
        'shape'        => '',
        'align'        => '',
        'margin'       => '',
        'padding'      => '',
        'border_width' => '',
        'border_style' => '',
        'border_color' => '',
    );
    // Подпись: фон (как у ссылки), отступы, скругление и граница.
    $signature = array(
        'bg_type'          => 'classic',
        'bg_color'         => '',
        'bg_gradient'      => '',
        'bg_gradient_type' => 'linear',
        'bg_angle'         => 180,
        'margin'           => '',
        'padding'          => '',
        'radius'           => '',
        'border_width'     => '',
        'border_style'     => '',
        'border_color'     => '',
    );
    return array(
        'heading'   => $heading,
        'text'      => $text_sep,
        'link'      => array(
            'normal' => $link,
            'hover'  => $link,
        ),
        // Габариты ссылок и выравнивание — одно на оба состояния, поэтому
        // отдельный блок без состояний (ft_phs_normalize читает его из
        // $raw[$dev]['link_box']). Внутри табов остаётся только граница,
        // которая у каждого состояния своя.
        'link_box'  => array(
            'align'   => '',
            'margin'  => '',
            'padding' => '',
            'radius'  => '',
        ),
        'portrait'  => $portrait,
        'signature' => $signature,
    );
}
/**
 * Перенос старых плоских опций сайдбара в новую адаптивную структуру.
 *
 * До появления табов устройств настройки сайдбара и цвет ссылок лежали в
 * отдельных опциях без привязки к устройству. Здесь они становятся значением
 * Десктопа, чтобы у сайтов ничего не пропало. Остальные устройства остаются
 * пустыми и наследуют Десктоп, как и задумано.
 *
 * @return array структура по ft_pms_schema()
 */
function ft_pms_legacy_to_schema() {
    $out = ft_phs_normalize(array(), ft_pms_schema(), 'link');
    $map = array(
        'color'       => 'family_tree_person_sidebar_heading_color',
        'font_family' => 'family_tree_person_sidebar_heading_font_family',
        'font_size'   => 'family_tree_person_sidebar_heading_font_size',
        'font_weight' => 'family_tree_person_sidebar_heading_font_weight',
    );
    foreach ($map as $key => $opt) {
        $out['desktop']['heading'][$key] = get_option($opt, '');
    }
    $map = array(
        'color'       => 'family_tree_person_sidebar_text_color',
        'font_family' => 'family_tree_person_sidebar_text_font_family',
        'font_size'   => 'family_tree_person_sidebar_text_font_size',
        'font_weight' => 'family_tree_person_sidebar_text_font_weight',
    );
    foreach ($map as $key => $opt) {
        $out['desktop']['text'][$key] = get_option($opt, '');
    }
    // Старый цвет ссылок был один на все состояния: переносим в «Обычный»,
    // а «При наведении» оставляем пустым и наследуемым.
    $out['desktop']['link']['normal']['color'] = get_option('family_tree_person_link', '');
    return $out;
}
/**
 * Чтение адаптивных настроек сайдбара с одноразовым переносом старых опций.
 *
 * @return array структура по ft_pms_schema()
 */
function ft_get_person_sidebar_settings() {
    $raw = get_option('family_tree_person_sidebar_settings', array());
    if (!is_array($raw) || empty($raw)) {
        $raw = ft_pms_legacy_to_schema();
        // Пишем только в админке: на фронтенде опция не должна меняться при чтении.
        if (is_admin()) {
            update_option('family_tree_person_sidebar_settings', $raw);
        }
    }
    $out = ft_phs_normalize($raw, ft_pms_schema(), 'link');
    // Габариты ссылок переехали из состояний в общий блок link_box: переносим
    // уже сохранённые значения, чтобы у сайтов с настройками до переноса
    // отступы и скругление не потерялись.
    foreach (array_keys(ft_device_list()) as $dev) {
        foreach (array('margin', 'padding', 'radius') as $key) {
            if ('' === trim((string) $out[$dev]['link_box'][$key])) {
                foreach (array('normal', 'hover') as $state) {
                    $old = isset($raw[$dev]['link'][$state][$key]) ? trim((string) $raw[$dev]['link'][$state][$key]) : '';
                    if ('' !== $old) {
                        $out[$dev]['link_box'][$key] = $old;
                        break;
                    }
                }
            }
        }
    }
    // Какая вкладка «Обычный / При наведении» открыта — помним между
    // сохранениями, чтобы не сбрасывать выбор при перезагрузке страницы.
    foreach (array_keys(ft_device_list()) as $dev) {
        $st = isset($raw[$dev]['link_state']) ? $raw[$dev]['link_state'] : 'normal';
        $out[$dev]['link_state'] = ('hover' === $st) ? 'hover' : 'normal';
    }
    return $out;
}
/**
 * Есть ли в настройках сайдбара хоть одно непустое значение. Если все пусто,
 * CSS не выводим и оформление остаётся дефолтным.
 */
function ft_pms_is_empty($s) {
    if (!is_array($s)) {
        return true;
    }
    foreach ($s as $dev => $blocks) {
        if (!is_array($blocks)) {
            continue;
        }
        foreach ($blocks as $block => $states) {
            if ('link_state' === $block || !is_array($states)) {
                continue;
            }
            $rows = ('link' === $block) ? $states : array($states);
            foreach ($rows as $row) {
                if (!is_array($row)) {
                    continue;
                }
                foreach ($row as $key => $val) {
                    // Технические поля фона всегда заполнены дефолтами и выбором
                    // ничего не меняют: без исключения фона настройки никогда не
                    // считались бы пустыми.
                    if (in_array($key, array('bg_type', 'bg_gradient_type', 'bg_angle'), true)) {
                        continue;
                    }
                    // Явное включение/выключение подчёркивания или разделителей —
                    // тоже настройка: без CSS-правила линии не убрать/добавить.
                    if (in_array($key, array('underline', 'separator'), true)
                        && ('0' === (string) $val || '1' === (string) $val)) {
                        return false;
                    }
                    if (is_array($val) || is_object($val)) {
                        return false;
                    }
                    $val = trim((string) $val);
                    if ('' !== $val && '0' !== $val) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}
/**
 * Приводит произвольный массив к схеме ft_phs_schema(), отбрасывая лишние
 * ключи и подставляя значения по умолчанию.
 *
 * $schema и $state_block позволяют переиспользовать нормализацию для других
 * адаптивных секций: состояния (Обычный / При наведении) хранятся только у
 * блока, имя которого передано в $state_block.
 */
function ft_phs_normalize($raw, $schema = null, $state_block = 'button') {
    $schema = (null === $schema) ? ft_phs_schema() : $schema;
    $out    = array();
    foreach (array_keys(ft_device_list()) as $dev) {
        $out[$dev] = array();
        foreach ($schema as $block => $def) {
            // У <title> полей нет - состояния хранятся под ключом ''.
            $states = ($state_block === $block) ? $def : array('' => $def);
            foreach ($states as $state => $fields) {
                $src = array();
                if (isset($raw[$dev][$block]) && is_array($raw[$dev][$block])) {
                    $src = $raw[$dev][$block];
                    if ('' !== $state) {
                        $src = isset($src[$state]) && is_array($src[$state]) ? $src[$state] : array();
                    }
                }
                $row = array();
                foreach ($fields as $key => $default) {
                    $val = isset($src[$key]) ? $src[$key] : $default;
                    // Массив или объект вместо строки - мусор в опции, а не
                    // значение: подставляем дефолт, иначе он всплывёт в esc_html.
                    if (is_array($val) || is_object($val)) {
                        $val = $default;
                    }
                    $row[$key] = $val;
                }
                if ('' === $state) {
                    $out[$dev][$block] = $row;
                } else {
                    $out[$dev][$block][$state] = $row;
                }
            }
        }
    }
    return $out;
}
/**
 * Перенос старых плоских опций в новый групповой формат (устройство «десктоп»).
 * Вызывается один раз, пока family_tree_person_header_settings пуст, чтобы
 * значения, настроенные до появления адаптивных табов, не потерялись.
 */
function ft_phs_legacy_to_schema() {
    $out = ft_phs_normalize(array());
    $map = array(
        'desktop' => array(
            'title'  => array(
                'color'       => 'family_tree_person_header_title_color',
                'font_family' => 'family_tree_person_header_font_family',
                'font_size'   => 'family_tree_person_header_font_size',
                'font_weight' => 'family_tree_person_header_font_weight',
            ),
            'button' => array(
                'bg_color'    => 'family_tree_person_tree_button',
                'text_color'  => 'family_tree_person_tree_button_text_color',
                'font_family' => 'family_tree_person_tree_button_font_family',
                'font_size'   => 'family_tree_person_tree_button_font_size',
                'font_weight' => 'family_tree_person_tree_button_font_weight',
            ),
        ),
        'tablet'  => array(
            'title' => array('font_size' => 'family_tree_person_header_font_size_tablet'),
        ),
        'mobile'  => array(
            'title' => array('font_size' => 'family_tree_person_header_font_size_mobile'),
        ),
    );
    foreach ($map as $dev => $blocks) {
        foreach ($blocks as $block => $keys) {
            $state = ('button' === $block) ? 'normal' : '';
            foreach ($keys as $key => $opt) {
                $val = get_option($opt, '');
                if (null === $val || '' === $val || 0 === $val) {
                    continue;
                }
                if ('' === $state) {
                    $out[$dev][$block][$key] = $val;
                } else {
                    $out[$dev][$block][$state][$key] = $val;
                }
            }
        }
    }
    return $out;
}
/**
 * Настройки шапки персоны по устройствам. Пока групповая опция не заполнена,
 * значения собираются из старых плоских опций (см. ft_phs_legacy_to_schema).
 */
function ft_get_person_header_settings() {
    $raw = get_option('family_tree_person_header_settings', array());
    if (!is_array($raw) || empty($raw)) {
        $raw = ft_phs_legacy_to_schema();
        // Пишем только в админке: на фронтенде опция не должна меняться при чтении.
        if (is_admin()) {
            update_option('family_tree_person_header_settings', $raw);
        }
    }
    $out = ft_phs_normalize($raw);
    // Какая вкладка «Обычный / При наведении» открыта у кнопки — помним между
    // сохранениями, чтобы не сбрасывать выбор при перезагрузке страницы.
    foreach (array_keys(ft_device_list()) as $dev) {
        $st = isset($raw[$dev]['button_state']) ? $raw[$dev]['button_state'] : 'normal';
        $out[$dev]['button_state'] = ('hover' === $st) ? 'hover' : 'normal';
    }
    return $out;
}
/**
 * Является ли CSS-значение нулём во всех своих частях: «0», «0px», «0px 0px».
 * Используется миграцией, чтобы отличить запись, сделанную старым багом
 * (пустой контрол при загрузке страницы становился «0px»), от осознанного
 * значения пользователя.
 */
function ft_css_value_is_zero($value) {
    $raw = trim(strtolower((string) $value));
    if ('' === $raw) {
        return false;
    }
    $numbers = preg_replace('/[^0-9.\-]+/', ' ', $raw);
    $parts = preg_split('/\s+/', trim($numbers), -1, PREG_SPLIT_NO_EMPTY);
    if (empty($parts)) {
        return false;
    }
    foreach ($parts as $n) {
        if (abs((float) $n) > 0.000001) {
            return false;
        }
    }
    return true;
}
/**
 * Разовая чистка настроек шапки.
 *
 * Старый баг: ftMeasInit при загрузке страницы прогонял числовые поля
 * (показывающие 0 у пустого контрола) через ftMeasRefresh, и скрытое поле
 * .ft-measure-value получало «0px» без участия пользователя. При сохранении
 * это значение уходило в опцию как явное, и Планшет/Мобильные начинали
 * перебивать значения Десктопа нулями вместо наследования.
 *
 * Здесь такие значения в Планшете и Мобильных заменяются на пустые, и
 * наследование от Десктопа восстанавливается. Значения Десктопа не трогаем,
 * осознанные ненулевые значения не трогаем.
 */
function family_tree_migrate_measure_zeroes() {
    if (get_option('family_tree_measure_zero_migrated')) {
        return;
    }
    $raw = get_option('family_tree_person_header_settings', array());
    if (is_array($raw) && !empty($raw)) {
        $changed = false;
        foreach (array('tablet', 'mobile') as $dev) {
            if (!isset($raw[$dev]) || !is_array($raw[$dev])) {
                continue;
            }
            foreach (array('margin', 'padding', 'radius') as $key) {
                if (isset($raw[$dev]['box'][$key]) && ft_css_value_is_zero($raw[$dev]['box'][$key])) {
                    $raw[$dev]['box'][$key] = '';
                    $changed = true;
                }
            }
            foreach (array('normal', 'hover') as $state) {
                if (isset($raw[$dev]['button'][$state]['border_width'])
                    && ft_css_value_is_zero($raw[$dev]['button'][$state]['border_width'])) {
                    $raw[$dev]['button'][$state]['border_width'] = '';
                    $changed = true;
                }
            }
        }
        if ($changed) {
            update_option('family_tree_person_header_settings', $raw);
        }
    }
    update_option('family_tree_measure_zero_migrated', 1);
}
add_action('admin_init', 'family_tree_migrate_measure_zeroes');
/**
 * Табы устройств в стиле Kadence: группа кнопок с иконками.
 */
function ft_render_device_tabs($group, $active = 'desktop') {
    $out = '<div role="group" class="components-button-group ft-device-options" aria-label="' . esc_attr__('Устройство', 'genius-family-tree') . '">';
    foreach (ft_device_list() as $key => $dev) {
        $is_active = ($key === $active);
        $classes   = array('components-button', 'components-button-group__item', 'ft-device-btn', 'ft-device-btn--' . $key);
        if ($is_active) {
            $classes[] = 'is-active';
        }
        $out .= '<button type="button" aria-pressed="' . ($is_active ? 'true' : 'false') . '" class="' . esc_attr(implode(' ', $classes)) . '" data-ft-device="' . esc_attr($key) . '" data-ft-device-group="' . esc_attr($group) . '" title="' . esc_attr($dev['label']) . '">';
        $out .= '<span class="dashicons dashicons-' . esc_attr($dev['icon']) . '"></span>';
        // Подпись видимая, а не только для скринридера: «Десктоп / Планшет /
        // Мобильные» должны читаться прямо на кнопке.
        $out .= '<span class="ft-device-btn__label">' . esc_html($dev['label']) . '</span>';
        $out .= '</button>';
    }
    $out .= '</div>';
    return $out;
}
/**
 * Select с гарнитурой (без лейбла — лейбл рисует ячейка ряда).
 */
function ft_render_font_select($name, $id, $value, $ft_fonts, $ft_google_fonts, $placeholder = '') {
    $out  = '<select name="' . esc_attr($name) . '" id="' . esc_attr($id) . '">';
    if ('' !== $placeholder) {
        $out .= '<option value="" selected>' . esc_html($placeholder) . '</option>';
    } else {
        $out .= '<option value="">' . esc_html__('По умолчанию', 'genius-family-tree') . '</option>';
    }
    $out .= '<optgroup label="' . esc_attr__('Системные', 'genius-family-tree') . '">';
    foreach ($ft_fonts as $ft_fv => $ft_fl) {
        $out .= '<option value="' . esc_attr($ft_fv) . '" ' . selected($value, $ft_fv, false) . '>' . esc_html($ft_fl) . '</option>';
    }
    $out .= '</optgroup>';
    $out .= '<optgroup label="' . esc_attr__('Google Fonts', 'genius-family-tree') . '">';
    foreach ($ft_google_fonts as $ft_fv => $ft_fl) {
        $out .= '<option value="' . esc_attr($ft_fv) . '" ' . selected($value, $ft_fv, false) . '>' . esc_html($ft_fl) . '</option>';
    }
    $out .= '</optgroup>';
    $out .= '</select>';
    return $out;
}
/**
 * Select с толщиной. Набор весов зависит от гарнитуры, поэтому класс
 * ft-font-weight-select + data-font-select на гарнитуру.
 */
function ft_render_weight_select($name, $id, $font_value, $weight_value, $font_id, $placeholder = '') {
    return '<select name="' . esc_attr($name) . '" id="' . esc_attr($id) . '" class="ft-font-weight-select" data-font-select="#' . esc_attr($font_id) . '">'
        . Family_Tree_Plugin::render_font_weight_options($font_value, $weight_value, $placeholder)
        . '</select>';
}
/**
 * Select «Подчёркивание» для ссылок.
 *
 * Три состояния, а не два: '' — не задано (Десктоп берёт вид темы, остальные
 * устройства наследуют Десктоп), '0' — явно нет, '1' — явно подчёркнуто.
 * Разделение нужно, чтобы состояния «Обычный» и «При наведении» не зависели
 * друг от друга: иначе «нет» при наведении не отличить от «наследую обычное».
 *
 * @param string $name       имя поля
 * @param string $id         id поля
 * @param string $value      текущее значение: '', '0' или '1'
 * @param string $inherited  значение Десктопа для подписи у планшета/мобильных
 * @param bool   $show_inherit_note  показывать ли вариант наследования
 * @return string
 */
function ft_render_phs_underline_select($name, $id, $value = '', $inherited = '', $show_inherit_note = false) {
    $value = ('0' === (string) $value || '1' === (string) $value) ? (string) $value : '';
    $out = '<select name="' . esc_attr($name) . '" id="' . esc_attr($id) . '" class="ft-phs-underline-select">';
    if ($show_inherit_note) {
        $label = ('1' === (string) $inherited)
            ? __('Как на Десктопе — подчёркнуто', 'genius-family-tree')
            : (('0' === (string) $inherited)
                ? __('Как на Десктопе — без подчёркивания', 'genius-family-tree')
                : __('Как на Десктопе — как в теме', 'genius-family-tree'));
        $out .= '<option value=""' . selected('', $value, false) . '>' . esc_html($label) . '</option>';
    }
    $out .= '<option value="0"' . selected('0', $value, false) . '>' . esc_html__('Нет', 'genius-family-tree') . '</option>';
    $out .= '<option value="1"' . selected('1', $value, false) . '>' . esc_html__('Подчёркнутый', 'genius-family-tree') . '</option>';
    $out .= '</select>';
    return $out;
}
/**
 * Подчёркивание ссылок для устройства и состояния в виде '' | '0' | '1'.
 *
 * Пусто в настройках значит «не задано». На Десктопе это не то же самое,
 * что «Нет»: десктоп — база для планшета и мобильных, поэтому там пустое
 * значение превращается в явное '0'. Иначе выбор «Нет» в панели не
 * соответствовал бы картинке и подчёркивание темы просочилось бы при
 * наведении.
 *
 * @param array  $s     нормализованные настройки по ft_pms_schema()
 * @param string $dev   устройство: desktop | tablet | mobile
 * @param string $state normal | hover
 * @return string
 */
function ft_pms_link_underline($s, $dev, $state) {
    $v = isset($s[$dev]['link'][$state]['underline']) ? (string) $s[$dev]['link'][$state]['underline'] : '';
    if ('' === $v && 'desktop' === $dev) {
        $v = '0';
    }
    return ('0' === $v || '1' === $v) ? $v : '';
}
/**
 * Ячейка ряда настроек: лейбл сверху, поле снизу.
 * $html — уже готовый контрол.
 */
function ft_render_phs_cell($caption, $html, $mod = '') {
    return '<div class="ft-phs-cell' . ('' !== $mod ? ' ' . $mod : '') . '">'
        . '<span class="components-base-control__label ft-phs-caption">' . esc_html($caption) . '</span>'
        . $html
        . '</div>';
}
/**
 * Собирает CSS-правило устройства: оборачивает в @media, если нужно.
 */
function ft_wrap_media($media, $css) {
    if ('' === trim($css)) {
        return '';
    }
    if ('' === $media) {
        return $css;
    }
    return '@media (' . $media . ') { ' . $css . ' }';
}
/**
 * Задано ли хотя бы одно значение в настройках шапки. Если нет — CSS можно
 * не выводить вовсе, и стили темы останутся в силе.
 */
function ft_phs_is_empty($s) {
    foreach ($s as $dev => $blocks) {
        if (!is_array($blocks)) {
            continue;
        }
        foreach ($blocks as $block => $states) {
            if ('button_state' === $block || !is_array($states)) {
                continue;
            }
            $rows = ('button' === $block) ? $states : array($states);
            foreach ($rows as $row) {
                if (!is_array($row)) {
                    continue;
                }
                foreach ($row as $key => $val) {
                    if (in_array($key, array('bg_type', 'bg_gradient_type', 'bg_angle'), true)) {
                        continue; // Служебные значения с дефолтами, сами по себе не настройка.
                    }
                    // Сравниваем строками: (int)'#fff' === 0, и цвет сошёлся бы
                    // за «не заполнено».
                    $val = trim((string) $val);
                    if ('' !== $val && '0' !== $val) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}
/**
 * CSS шапки персоны для одного устройства.
 *
 * Незаданное значение ничего не выводит — тогда стиль берётся из темы. В
 * состоянии «При наведении» пустые поля наследуют «Обычный».
 */
function ft_person_header_device_css($s, $dev) {
    $t = $s[$dev]['title'];
    $n = $s[$dev]['button']['normal'];
    $h = $s[$dev]['button']['hover'];
    $css = '';

    // Заголовок.
    $decl = '';
    if ('' !== $t['color']) {
        $decl .= ' color: ' . esc_html($t['color']) . ' !important;';
    }
    if ('' !== $t['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($t['font_family']) . '\', serif !important;';
    }
    if ((int) $t['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $t['font_size'] . 'px !important;';
    }
    if ((int) $t['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $t['font_weight'] . ' !important;';
    }
    // Выравнивание по горизонтали. В схеме пусто = не задано (наследование).
    if (!empty($t['text_align']) && in_array($t['text_align'], ft_phs_align_values(), true)) {
        $decl .= ' text-align: ' . $t['text_align'] . ' !important;';
    }
    if ('' !== $decl) {
        $css .= '.family-member-header h1 {' . $decl . ' }';
    }

    // Кнопка «Показать в древе» — обычное состояние.
    $decl = '';
    if ('gradient' === $n['bg_type'] && '' !== $n['bg_gradient']) {
        $decl .= ' background: ' . esc_html($n['bg_gradient']) . ' !important;';
    } elseif ('' !== $n['bg_color']) {
        $decl .= ' background: ' . esc_html($n['bg_color']) . ' !important; border-color: ' . esc_html($n['bg_color']) . ' !important;';
    }
    if ('' !== $n['text_color']) {
        $decl .= ' color: ' . esc_html($n['text_color']) . ' !important;';
    }
    if ('' !== $n['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($n['font_family']) . '\', serif !important;';
    }
    if ((int) $n['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $n['font_size'] . 'px !important;';
    }
    if ((int) $n['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $n['font_weight'] . ' !important;';
    }
    // Рамка кнопки (толщина/стиль/цвет).
    $decl .= ft_phs_border_css($n, false);
    // Габариты кнопки — одни на оба состояния, поэтому только в базовом
    // правиле: :hover унаследует их от него.
    $box = isset($s[$dev]['box']) && is_array($s[$dev]['box']) ? $s[$dev]['box'] : array();
    if (!empty($box['margin'])) {
        $decl .= ' margin: ' . esc_html($box['margin']) . ' !important;';
    }
    if (!empty($box['padding'])) {
        $decl .= ' padding: ' . esc_html($box['padding']) . ' !important;';
    }
    if (!empty($box['radius'])) {
        $decl .= ' border-radius: ' . esc_html($box['radius']) . ' !important;';
    }
    // Выравнивание кнопки по горизонтали. Шапка — flex-колонка, поэтому
    // поперечная ось это горизонталь, и положение задаёт align-self.
    if (!empty($box['align']) && in_array($box['align'], ft_phs_align_values(), true)) {
        $self = array('left' => 'flex-start', 'center' => 'center', 'right' => 'flex-end');
        $decl .= ' align-self: ' . $self[$box['align']] . ' !important;';
    }
    if ('' !== $decl) {
        $css .= '.family-member-header .button {' . $decl . ' }';
    }

    // Кнопка при наведении: unset наследует обычное состояние.
    $hdecl = '';
    if ('gradient' === $h['bg_type'] && '' !== $h['bg_gradient']) {
        $hdecl .= ' background: ' . esc_html($h['bg_gradient']) . ' !important;';
    } elseif ('' !== $h['bg_color']) {
        $hdecl .= ' background: ' . esc_html($h['bg_color']) . ' !important; border-color: ' . esc_html($h['bg_color']) . ' !important;';
    } elseif ('' !== $n['bg_color'] || ('gradient' === $n['bg_type'] && '' !== $n['bg_gradient'])) {
        // Фон задан только в обычном состоянии — слегка затемняем при наведении.
        $hdecl .= ' filter: brightness(0.9);';
    }
    if ('' !== $h['text_color']) {
        $hdecl .= ' color: ' . esc_html($h['text_color']) . ' !important;';
    }
    if ('' !== $h['font_family']) {
        $hdecl .= ' font-family: \'' . esc_attr($h['font_family']) . '\', serif !important;';
    }
    if ((int) $h['font_size'] > 0) {
        $hdecl .= ' font-size: ' . (int) $h['font_size'] . 'px !important;';
    }
    if ((int) $h['font_weight'] > 0) {
        $hdecl .= ' font-weight: ' . (int) $h['font_weight'] . ' !important;';
    }
    $hdecl .= ft_phs_border_css($h, true);
    if ('' !== $hdecl) {
        $css .= '.family-member-header .button:hover {' . $hdecl . ' }';
    }

    return $css;
}
/**
 * CSS блока сайдбара для одного устройства.
 *
 * Устройство передаётся явно, поэтому на Планшете и Мобильных блок выводится
 * внутри media-запроса и перекрывает Десктоп. Пустое поле = не задано, то есть
 * значение остаётся у десктопного блока или у дефолта темы.
 *
 * Блоки «Заголовки», «Текст» и «Ссылки» независимы: цвет текста сайдбара не
 * должен перебивать собственные цвета заголовков и ссылок, поэтому обычный
 * текст адресуется точным селектором, а заголовки и ссылки - своими.
 *
 * @param array  $s   нормализованные настройки по ft_pms_schema()
 * @param string $dev устройство: desktop | tablet | mobile
 * @return string
 */
function ft_person_sidebar_device_css($s, $dev) {
    $h  = $s[$dev]['heading'];
    $t  = $s[$dev]['text'];
    $n  = $s[$dev]['link']['normal'];
    $hv = $s[$dev]['link']['hover'];
    $lx = isset($s[$dev]['link_box']) && is_array($s[$dev]['link_box']) ? $s[$dev]['link_box'] : array();
    $css = '';

    // --- Заголовки: «Краткая информация», «Родители», «Дети» и т.д. ---
    $decl = '';
    if ('' !== $h['color']) {
        $decl .= ' color: ' . esc_html($h['color']) . ' !important;';
    }
    if ('' !== $h['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($h['font_family']) . '\', serif !important;';
    }
    if ((int) $h['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $h['font_size'] . 'px !important;';
    }
    if ((int) $h['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $h['font_weight'] . ' !important;';
    }
    if (!empty($h['text_align']) && in_array($h['text_align'], ft_phs_align_values(), true)) {
        $decl .= ' text-align: ' . $h['text_align'] . ' !important;';
    }
    if ('' !== trim((string) $h['margin'])) {
        $decl .= ' margin: ' . trim((string) $h['margin']) . ' !important;';
    }
    if ('' !== trim((string) $h['padding'])) {
        $decl .= ' padding: ' . trim((string) $h['padding']) . ' !important;';
    }
    // Подчёркивание задаём длинными свойствами: так «цвет»/«толщина» линии
    // наследуются от Десктопа, а выключение не задевает их.
    if ('1' === $h['underline']) {
        $decl .= ' border-bottom-style: solid !important;';
        if ((int) $h['underline_width'] > 0) {
            $decl .= ' border-bottom-width: ' . (int) $h['underline_width'] . 'px !important;';
        }
        if ('' !== $h['underline_color']) {
            $decl .= ' border-bottom-color: ' . esc_html($h['underline_color']) . ' !important;';
        }
    } elseif ('0' === $h['underline']) {
        $decl .= ' border-bottom-style: none !important;';
    }
    if ('' !== $decl) {
        $css .= '.family-member-sidebar h2 {' . $decl . ' }';
    }

    // --- Обычный текст сайдбара: таблицы, списки, подписи. ---
    $decl = '';
    if ('' !== $t['color']) {
        $decl .= ' color: ' . esc_html($t['color']) . ' !important;';
    }
    if ('' !== $t['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($t['font_family']) . '\', serif !important;';
    }
    if ((int) $t['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $t['font_size'] . 'px !important;';
    }
    if ((int) $t['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $t['font_weight'] . ' !important;';
    }
    $calign = '';
    if (!empty($t['text_align']) && in_array($t['text_align'], ft_phs_align_values(), true)) {
        $calign = $t['text_align'];
    }
    if ('' !== $decl) {
        $css .= '.family-member-sidebar { ' . ltrim($decl) . ' }';
    }
    // Выравнивание текста задаём самим текстовым элементам, а не контейнеру:
    // иначе оно наследовалось бы заголовкам (<h2>) и ссылкам.
    if ('' !== $calign) {
        $css .= '.family-member-sidebar td, .family-member-sidebar th, .family-member-sidebar li { text-align: ' . $calign . ' !important; }';
    }
    // text-align наследуется, поэтому выравнивание текста задевало бы и ссылки
    // внутри ячеек и списков. Ссылки выравнивает только свой раздел, поэтому
    // здесь явно возвращаем им их собственное значение.
    $lalign = '';
    if (!empty($lx['align']) && in_array($lx['align'], ft_phs_align_values(), true)) {
        $lalign = $lx['align'];
    } elseif ('desktop' !== $dev && !empty($s['desktop']['link_box']['align'])
        && in_array($s['desktop']['link_box']['align'], ft_phs_align_values(), true)) {
        $lalign = $s['desktop']['link_box']['align'];
    }
    if ('' !== $calign && '' === $lalign) {
        // Ссылкам нечего наследовать: раздел «Ссылки» своего выравнивания не
        // задал. Дефолт темы для ссылок сайдбара — по левому краю (как у
        // .family-member-table th/td), иначе они унаследуют выравнивание
        // блока «Текст».
        $css .= '.family-member-sidebar a { text-align: left !important; }';
    }
    // Разделители — длинными свойствами border-bottom на ячейках таблиц
    // сайдбара («Краткая информация», «Отец/Мать»).
    $tsep = '';
    if ('1' === $t['separator']) {
        $tsep .= ' border-bottom-style: solid !important;';
        if ((int) $t['separator_width'] > 0) {
            $tsep .= ' border-bottom-width: ' . (int) $t['separator_width'] . 'px !important;';
        }
        if ('' !== $t['separator_color']) {
            $tsep .= ' border-bottom-color: ' . esc_html($t['separator_color']) . ' !important;';
        }
    } elseif ('0' === $t['separator']) {
        $tsep .= ' border-bottom-style: none !important;';
    }
    if ('' !== $tsep) {
        $css .= '.family-member-sidebar .family-member-table th, .family-member-sidebar .family-member-table td {' . $tsep . ' }';
    }

    // --- Ссылки, состояние «Обычный». ---
    $link_sel = '.family-member-sidebar a';
    $decl = '';
    if ('gradient' === $n['bg_type'] && '' !== $n['bg_gradient']) {
        $decl .= ' background: ' . esc_html($n['bg_gradient']) . ' !important;';
    } elseif ('' !== $n['bg_color']) {
        $decl .= ' background: ' . esc_html($n['bg_color']) . ' !important;';
    }
    if ('' !== $n['color']) {
        $decl .= ' color: ' . esc_html($n['color']) . ' !important;';
    }
    if ('' !== $n['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($n['font_family']) . '\', serif !important;';
    }
    if ((int) $n['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $n['font_size'] . 'px !important;';
    }
    if ((int) $n['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $n['font_weight'] . ' !important;';
    }
    // Подчёркивание длинным свойством text-decoration-line: так «нет» не
    // задевает цвет и толщину линии, если их задаст тема.
    $n_ul = ft_pms_link_underline($s, $dev, 'normal');
    if ('1' === $n_ul) {
        $decl .= ' text-decoration-line: underline !important;';
    } elseif ('0' === $n_ul) {
        $decl .= ' text-decoration-line: none !important;';
    }
    // Габариты ссылок — одни на оба состояния, поэтому только в базовом
    // правиле: :hover унаследует их от него.
    if (!empty($lx['margin'])) {
        $decl .= ' margin: ' . esc_html($lx['margin']) . ' !important;';
    }
    if (!empty($lx['padding'])) {
        $decl .= ' padding: ' . esc_html($lx['padding']) . ' !important;';
    }
    if (!empty($lx['radius'])) {
        $decl .= ' border-radius: ' . esc_html($lx['radius']) . ' !important;';
    }
    $decl .= ft_phs_border_css($n, false);
    // Ссылка — блочный элемент (в статичном CSS у .family-member-sidebar a
    // display:block), поэтому выравнивание задаём самому <a>: оно не задевает
    // обычный текст ячеек и пунктов списка.
    if (!empty($lx['align']) && in_array($lx['align'], ft_phs_align_values(), true)) {
        $css .= '.family-member-sidebar a { text-align: ' . $lx['align'] . ' !important; }';
    }
    if ('' !== $decl) {
        $css .= $link_sel . ' {' . $decl . ' }';
    }

    // --- Ссылки, состояние «При наведении»: unset от десктопного значения. ---
    $hdecl = '';
    if ('gradient' === $hv['bg_type'] && '' !== $hv['bg_gradient']) {
        $hdecl .= ' background: ' . esc_html($hv['bg_gradient']) . ' !important;';
    } elseif ('' !== $hv['bg_color']) {
        $hdecl .= ' background: ' . esc_html($hv['bg_color']) . ' !important;';
    }
    if ('' !== $hv['color']) {
        $hdecl .= ' color: ' . esc_html($hv['color']) . ' !important;';
    }
    if ('' !== $hv['font_family']) {
        $hdecl .= ' font-family: \'' . esc_attr($hv['font_family']) . '\', serif !important;';
    }
    if ((int) $hv['font_size'] > 0) {
        $hdecl .= ' font-size: ' . (int) $hv['font_size'] . 'px !important;';
    }
    if ((int) $hv['font_weight'] > 0) {
        $hdecl .= ' font-weight: ' . (int) $hv['font_weight'] . ' !important;';
    }
    // Подчёркивание при наведении — своё значение: состояние может как
    // убрать подчёркивание, так и добавить его, независимо от «Обычного».
    $hv_ul = ft_pms_link_underline($s, $dev, 'hover');
    if ('1' === $hv_ul) {
        $hdecl .= ' text-decoration-line: underline !important;';
    } elseif ('0' === $hv_ul) {
        $hdecl .= ' text-decoration-line: none !important;';
    }
    $hdecl .= ft_phs_border_css($hv, true);
    if ('' !== $hdecl) {
        $css .= $link_sel . ':hover, ' . $link_sel . ':focus {' . $hdecl . ' }';
    }

    return $css;
}
/**
 * CSS портрета и подписи сайдбара — общий для всех устройств.
 *
 * У этих двух разделов нет табов устройств: в админке они стоят над панелью
 * табов и под ней, поэтому набор значений один. Поэтому и правила выводятся
 * один раз, без @media, иначе одинаковые объявления повторились бы трижды.
 * Источник — ветка «desktop»: именно она приходит из формы, остальные ветки
 * этого больше не читаются.
 *
 * @param array $s нормализованные настройки по ft_pms_schema()
 * @return string
 */
function ft_person_sidebar_image_css($s) {
    $pr = isset($s['desktop']['portrait']) && is_array($s['desktop']['portrait']) ? $s['desktop']['portrait'] : array();
    $sg = isset($s['desktop']['signature']) && is_array($s['desktop']['signature']) ? $s['desktop']['signature'] : array();
    $css = '';

    // --- Портрет (аватар сайдбара). ---
    $psel = '.family-member-sidebar .family-member-avatar img';
    $decl = '';
    if (!empty($pr['shape'])) {
        $pshape = $pr['shape'];
        // «Круг на всю ширину» и «Квадрат на всю ширину» отличаются от простых
        // «Круг»/«Квадрат» только снятием max-width темы: картинка занимает
        // всю ширину сайдбара. Форму задаёт пара aspect-ratio + border-radius.
        $pfull = in_array($pshape, array('full', 'full-square'), true);
        $decl .= ' width: 100% !important;';
        if ($pfull) {
            $decl .= ' max-width: none !important;';
        }
        $decl .= ' height: auto !important;';
        $decl .= ' aspect-ratio: 1 / 1 !important;';
        $decl .= ' border-radius: ' . (in_array($pshape, array('circle', 'full'), true) ? '50%' : '0') . ' !important;';
        $decl .= ' object-fit: cover !important;';
    }
    if (!empty($pr['margin'])) {
        $decl .= ' margin: ' . esc_html($pr['margin']) . ' !important;';
    }
    if (!empty($pr['padding'])) {
        $decl .= ' padding: ' . esc_html($pr['padding']) . ' !important;';
    }
    $decl .= ft_phs_border_css($pr, false);
    if (!empty($pr['align']) && in_array($pr['align'], ft_phs_align_values(), true)) {
        // <img> внутри контейнера остаётся строчным, поэтому положение
        // задаёт text-align контейнера, а не самой картинки.
        $css .= '.family-member-sidebar .family-member-avatar { text-align: ' . $pr['align'] . ' !important; }';
    }
    if ('' !== $decl) {
        $css .= $psel . ' {' . $decl . ' }';
    }

    // --- Подпись. ---
    $ssel = '.family-member-sidebar .family-member-signature__image';
    $decl = '';
    if (isset($sg['bg_type']) && 'gradient' === $sg['bg_type'] && !empty($sg['bg_gradient'])) {
        $decl .= ' background: ' . esc_html($sg['bg_gradient']) . ' !important;';
    } elseif (!empty($sg['bg_color'])) {
        $decl .= ' background: ' . esc_html($sg['bg_color']) . ' !important;';
    }
    if (!empty($sg['margin'])) {
        $decl .= ' margin: ' . esc_html($sg['margin']) . ' !important;';
    }
    if (!empty($sg['padding'])) {
        $decl .= ' padding: ' . esc_html($sg['padding']) . ' !important;';
    }
    if (!empty($sg['radius'])) {
        $decl .= ' border-radius: ' . esc_html($sg['radius']) . ' !important;';
    }
    $decl .= ft_phs_border_css($sg, false);
    if ('' !== $decl) {
        $css .= $ssel . ' {' . $decl . ' }';
    }

    return $css;
}
/**
 * CSS рамки кнопки по одному состоянию.
 *
 * Пустые поля не выводятся: тогда состояние наследует обычное (для hover) или
 * тему (для normal). Задавать можно любую часть — толщину, стиль или цвет, —
 * поэтому правило собирается из того, что реально заполнено. Иначе, например,
 * цвет без толщины молча терялся бы, и рамка выглядела бы несохранённой.
 */
function ft_phs_border_css($b, $hover) {
    $w = isset($b['border_width']) ? trim((string) $b['border_width']) : '';
    $s = isset($b['border_style']) ? trim((string) $b['border_style']) : '';
    $c = isset($b['border_color']) ? trim((string) $b['border_color']) : '';
    if ('' === $w && '' === $s && '' === $c) {
        return '';
    }
    $out = '';
    if ('' !== $w || 'double' === $s) {
        $out .= ' border-width: ' . esc_html(ft_border_width_css('' !== $w ? $w : '1px', '' !== $s ? $s : 'solid')) . ' !important;';
        if ('' === $s) {
            $s = 'solid';
        }
        $out .= ' border-style: ' . esc_html($s) . ' !important;';
    } elseif ('' !== $s) {
        $out .= ' border-style: ' . esc_html($s) . ' !important;';
    }
    if ('' !== $c) {
        $out .= ' border-color: ' . esc_html($c) . ' !important;';
    }
    return $out;
}
/**
 * Поле «цвет» в рядах адаптивных настроек (шапка персоны, «Настройки текста» карточек).
 *
 * Это НЕ отдельный инструмент: рендерится тот же контрол палитры, что и во всех
 * остальных местах настроек (ft_render_bg_control), поэтому поведение, вид и
 * поповер везде одинаковые. Отличия только в габаритах: без градиента, без
 * картинки и без собственной кнопки сброса — в этих рядах сброс уже есть
 * отдельной ячейкой справа.
 */
function ft_render_color_field($name, $id, $value, $default, $placeholder = '', $show_reset = false) {
    return ft_render_bg_control(array(
        'id'            => $id,
        'color_name'    => $name,
        'color_id'      => $id,
        'color_value'   => $value,
        'color_default' => $default,
        'color_placeholder' => $placeholder,
        'show_type'     => false,
        'show_reset'    => $show_reset,
    ));
}
/**
 * Поле «размер» в px. Пусто = наследовать тему.
 */
function ft_render_size_field($name, $id, $value, $placeholder = '') {
    return '<div class="ft-phs-size-row">'
        . '<input type="number" name="' . esc_attr($name) . '" id="' . esc_attr($id) . '" value="' . esc_attr(0 === (int) $value ? '' : (int) $value) . '" class="small-text" min="0" max="96" step="1" placeholder="' . esc_attr('' !== $placeholder ? $placeholder : '0') . '" />'
        . '<span class="ft-phs-unit">px</span>'
        . '</div>';
}
/**
 * Ячейка сброса: очищает все поля строки. $targets — CSS-селекторы через запятую.
 */
function ft_render_phs_reset_cell($targets, $color_placeholder = '') {
    // Пустая подпись-распорка: класс тот же, что у соседних названий блоков,
    // чтобы кнопка сброса вставала на одну линию с подписями ячеек ряда.
    $color_placeholder_attr = '' !== $color_placeholder
        ? ' data-ft-phs-reset-color-placeholder="' . esc_attr($color_placeholder) . '"'
        : '';
    return '<div class="ft-phs-cell ft-phs-cell--reset">'
        . '<span class="components-base-control__label ft-phs-caption">&nbsp;</span>'
        . '<button type="button" class="ft-phs-reset" data-ft-phs-reset="' . esc_attr($targets) . '"' . $color_placeholder_attr . ' title="' . esc_attr__('Сбросить', 'genius-family-tree') . '">' . ft_reset_icon_svg()         . '<span class="screen-reader-text">' . esc_html__('Сбросить', 'genius-family-tree') . '</span></button>'
        . '</div>';
}

/**
 * Тулбар «Выравнивание по горизонтали» (слева / по центру / справа).
 * Значение живёт в скрытом поле, кнопки только переключают aria-pressed.
 * Пустое значение = наследование Десктопа; повторный клик по активной
 * кнопке снимает выбор и возвращает наследование.
 *
 * @param string $name              имя скрытого поля
 * @param string $id                id для привязки
 * @param string $value             текущее значение (left|center|right|'')
 * @param string $inherited         значение Десктопа для подсказки
 * @param bool   $show_inherit_note печатать ли пояснение про наследование
 * @return string
 */
function ft_render_phs_align_control($name, $id, $value = '', $inherited = '', $show_inherit_note = false) {
    $value     = in_array($value, ft_phs_align_values(), true) ? $value : '';
    $inherited = in_array($inherited, ft_phs_align_values(), true) ? $inherited : '';
    $icons = array(
        'left'   => '<path d="M9 9v6h11V9H9zM4 20h1.5V4H4v16z"></path>',
        'center' => '<path d="M12.5 15v5H11v-5H4V9h7V4h1.5v5h7v6h-7Z"></path>',
        'right'  => '<path d="M4 15h11V9H4v6zM18.5 4v16H20V4h-1.5z"></path>',
    );
    $labels = array(
        'left'   => esc_html__('По левому краю', 'genius-family-tree'),
        'center' => esc_html__('По центру', 'genius-family-tree'),
        'right'  => esc_html__('По правому краю', 'genius-family-tree'),
    );
    $out  = '<div class="ft-align" data-ft-align="' . esc_attr($id) . '">';
    $out .= '<span class="components-base-control__label ft-phs-caption ft-align__caption">' . esc_html__('Выравнивание по горизонтали', 'genius-family-tree') . '</span>';
    $out .= '<div class="ft-align__toolbar">';
    foreach ($icons as $key => $path) {
        $classes = 'ft-align__btn' . ($value === $key ? ' is-pressed' : '');
        $out .= '<div class="ft-align__item">';
        $out .= '<button type="button" class="' . esc_attr($classes) . '"'
            . ' data-ft-align-btn="' . esc_attr($key) . '"'
            . ' aria-pressed="' . ($value === $key ? 'true' : 'false') . '"'
            . ' aria-label="' . esc_attr($labels[$key]) . '"'
            . ' title="' . esc_attr($labels[$key]) . '">';
        $out .= '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true" focusable="false">' . $path . '</svg>';
        $out .= '</button></div>';
    }
    $out .= '</div>';
    $out .= '<input type="hidden" class="ft-align__value" id="' . esc_attr($id) . '" name="' . esc_attr($name) . '" value="' . esc_attr($value) . '">';
    if ($show_inherit_note) {
        $own_text = esc_html__('Нажмите активную иконку ещё раз, чтобы вернуть наследование.', 'genius-family-tree');
        $inh_text = ('' !== $inherited)
            ? esc_html__('Сейчас наследуется от Десктопа: ', 'genius-family-tree') . $labels[$inherited]
            : esc_html__('Сейчас наследуется от Десктопа.', 'genius-family-tree');
        $out .= '<p class="components-base-control__help ft-align__help"'
            . ' data-ft-own-text="' . esc_attr($own_text) . '"'
            . ' data-ft-inherit-text="' . esc_attr($inh_text) . '">'
            . ('' !== $value ? $own_text : $inh_text)
            . '</p>';
    }
    $out .= '</div>';
    return $out;
}

/**
 * Чтение цвета текста карточки с откатом на старую общую опцию.
 *
 * До разделения на «Имена» / «Даты» цвет был один на весь текст карточки
 * (family_tree_text_color). Чтобы сайты не потеряли оформление, пока новые
 * опции ещё не записаны, берём старое значение.
 *
 * Важно: если новая опция существует, но пустая — значит пользователь
 * осознанно очистил поле, и возвращать старое значение нельзя.
 */
function ft_card_text_opt($new_key, $legacy_key, $default) {
    $value = get_option($new_key, null);
    if (null !== $value) {
        return trim((string) $value);
    }
    $legacy = trim((string) get_option($legacy_key, ''));
    return ('' !== $legacy) ? $legacy : $default;
}
/**
 * Объявления цвет/гарнитура/размер/толщина для одного состояния текста карточки.
 */
function ft_card_text_typography_css($row) {
    $decl = '';
    if ('' !== $row['color']) {
        $decl .= ' fill: ' . esc_html($row['color']) . ' !important;';
    }
    if ('' !== $row['font_family']) {
        $decl .= ' font-family: \'' . esc_attr($row['font_family']) . '\', sans-serif !important;';
    }
    if ((int) $row['font_size'] > 0) {
        $decl .= ' font-size: ' . (int) $row['font_size'] . 'px !important;';
    }
    if ((int) $row['font_weight'] > 0) {
        $decl .= ' font-weight: ' . (int) $row['font_weight'] . ' !important;';
    }
    return $decl;
}
/**
 * CSS-правила текста карточек: свой цвет и своя типографика для «Имён» и
 * «Дат», отдельно для обычного состояния и при наведении.
 *
 * Пустое значение в состоянии «При наведении» наследует обычное состояние,
 * поэтому выводим только явно заданные свойства.
 */
function ft_card_text_css($opts) {
    $css = '';
    foreach (array('name', 'date') as $block) {
        $sel = ('name' === $block)
            ? '.f3 svg.main_svg .card-body text tspan[font-size="12"]'
            : '.f3 svg.main_svg .card-body text tspan[font-size="10"]';

        $ndecl = ft_card_text_typography_css($opts[$block]['normal']);
        if ('' !== $ndecl) {
            $css .= $sel . ' {' . $ndecl . ' }';
        }
        $hdecl = ft_card_text_typography_css($opts[$block]['hover']);
        if ('' !== $hdecl) {
            $css .= '.f3 .card:hover ' . $sel . ' {' . $hdecl . ' }';
        }
    }
    return $css;
}
/**
 * Все настройки текста карточек в удобной структуре:
 * ['name'|'date']['normal'|'hover'] => color, font_family, font_size, font_weight.
 *
 * Обычное состояние читает существующие опции family_tree_*_font_*,
 * при наведении — новые с суффиксом _hover (пусто = наследовать обычное).
 */
function ft_get_card_text_settings() {
    $out = array();
    foreach (array('name', 'date') as $block) {
        $prefix = 'family_tree_' . $block . '_';
        $base   = 'family_tree_' . $block . '_font_';
        $out[$block] = array();
        foreach (array('normal', 'hover') as $state) {
            $suffix = ('hover' === $state) ? '_hover' : '';
            $out[$block][$state] = array(
                'color'       => ft_card_text_opt(
                    $prefix . 'text_color' . $suffix,
                    ('hover' === $state) ? 'family_tree_text_color_hover' : 'family_tree_text_color',
                    '#3b5560'
                ),
                'font_family' => get_option($base . 'family' . $suffix, ''),
                'font_size'   => ('hover' === $state)
                    ? (int) get_option($base . 'size' . $suffix, 0)
                    : family_tree_font_size_value($base . 'size', ('name' === $block) ? 12 : 10),
                'font_weight' => (int) get_option($base . 'weight' . $suffix, 0),
            );
        }
    }
    return $out;
}
/**
 * Секция «Настройки шапки» страницы персоны.
 *
 * Сверху — табы устройств (Kadence-стиль) в обрамлении, внутри каждого таба
 * один и тот же набор блоков: «Заголовок» (цвет/шрифт/размер/толщина) и
 * «Показать в древе» с табами Обычный / При наведении, где фон выбирается
 * между классическим цветом и градиентом.
 *
 * @param array  $s              настройки из ft_get_person_header_settings()
 * @param array  $ft_fonts        системные гарнитуры
 * @param array  $ft_google_fonts Google Fonts
 * @param string $active          устройство, открытое по умолчанию
 */
function ft_render_person_header_section($s, $ft_fonts, $ft_google_fonts, $active = 'desktop') {
    $group = 'person-header';
    $out   = ft_render_device_tabs($group, $active);
    $out  .= '<div class="ft-device-frame" data-ft-device-frame="' . esc_attr($group) . '">';
    foreach (ft_device_list() as $dev => $meta) {
        $t      = $s[$dev]['title'];
        $active_tab = isset($s[$dev]['button_state']) ? $s[$dev]['button_state'] : 'normal';
        $out .= '<div class="ft-device-panel" data-ft-device-panel="' . esc_attr($dev) . '"' . ($dev === $active ? '' : ' style="display:none;"') . '>';

        /* ---------- Заголовок ---------- */
        $t_sfx = 'ft-phs-' . $dev . '-title';
        // Планшет и Мобильные наследуют всё, что не задано явно, от Десктопа.
        // Показываем унаследованное значение серым в пустом поле: placeholder
        // браузером в POST не отправляется, поэтому переопределение остаётся
        // возможным, а при следующем сохранении значение снова не «прибивается».
        $is_desk  = ('desktop' === $dev);
        $sd       = $s['desktop']['title'];
        $bd_box   = isset($s['desktop']['box']) ? $s['desktop']['box'] : array();
        // «Не задано» — это и пустая строка, и 0: у размеров и толщины
        // невыбранное значение приходит как 0, а не как ''.
        $is_set   = function ($v) {
            $raw = trim((string) $v);
            return ('' !== $raw && '0' !== $raw);
        };
        $pick     = function ($own, $desk) use ($is_desk, $is_set) {
            if ($is_desk || $is_set($own)) { return ''; }
            return trim((string) $desk);
        };
        // Для кнопки цепочка длиннее: своё значение -> своё «Обычный» ->
        // значение Десктопа в этом же состоянии -> «Обычный» Десктопа.
        $pick_btn = function ($own, $own_norm, $desk, $desk_norm) use ($is_desk, $is_set) {
            if ($is_desk || $is_set($own)) { return ''; }
            foreach (array($own_norm, $desk, $desk_norm) as $cand) {
                if ($is_set($cand)) { return trim((string) $cand); }
            }
            return '';
        };
        $out .= '<div class="ft-phs-block">';
        $out .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Заголовок', 'genius-family-tree') . '</span>';
        $out .= '<div class="components-base-control">';
        $out .= ft_render_phs_align_control(
            'family_tree_phs[' . $dev . '][title][text_align]',
            $t_sfx . '-align',
            isset($t['text_align']) ? $t['text_align'] : '',
            isset($sd['text_align']) ? $sd['text_align'] : '',
            ! $is_desk
        );
        $out .= ($is_desk ? '' : '<p class="ft-phs-inherit-note">' . esc_html__('Пустые поля наследуют значения вкладки «Десктоп». Чтобы задать своё — заполните поле.', 'genius-family-tree') . '</p>');
        $out .= '<div class="ft-phs-row">';
        $out .= ft_render_phs_cell(
            __('Цвет', 'genius-family-tree'),
            ft_render_color_field('family_tree_phs[' . $dev . '][title][color]', $t_sfx . '-color', $t['color'], '#1d2327', $pick($t['color'], $sd['color'])),
            'ft-phs-cell--color'
        );
        $out .= ft_render_phs_cell(
            __('Шрифт', 'genius-family-tree'),
            ft_render_font_select('family_tree_phs[' . $dev . '][title][font_family]', $t_sfx . '-font', $t['font_family'], $ft_fonts, $ft_google_fonts, $pick($t['font_family'], $sd['font_family']))
        );
        $out .= ft_render_phs_cell(
            __('Размер', 'genius-family-tree'),
            ft_render_size_field('family_tree_phs[' . $dev . '][title][font_size]', $t_sfx . '-size', $t['font_size'], $pick($t['font_size'], $sd['font_size'])),
            'ft-phs-cell--size'
        );
        $out .= ft_render_phs_cell(
            __('Толщина', 'genius-family-tree'),
            ft_render_weight_select('family_tree_phs[' . $dev . '][title][font_weight]', $t_sfx . '-weight', $t['font_family'], $t['font_weight'], $t_sfx . '-font', $pick($t['font_weight'], $sd['font_weight']))
        );
        $out .= ft_render_phs_reset_cell('#' . $t_sfx . '-color, #' . $t_sfx . '-font, #' . $t_sfx . '-size, #' . $t_sfx . '-weight');
        $out .= '</div>';
        $out .= '<p class="components-base-control__help">' . esc_html__('Цвет, гарнитура, размер и толщина заголовка персоны (Имя, Фамилия) для этого устройства.', 'genius-family-tree') . '</p>';
        $out .= '</div>';
        $out .= '</div>';

        /* ---------- Кнопка «Показать в древе» ---------- */
        $out .= '<div class="ft-phs-block">';
        // Габариты кнопки — сразу под заголовком, ВЫШЕ табов «Обычный /
        // При наведении», и к состояниям не относятся: одни значения на всю
        // кнопку. Сами табы состояний настраивают только фон, текст и границу.
        $bx = isset($s[$dev]['box']) && is_array($s[$dev]['box']) ? $s[$dev]['box'] : array('margin' => '', 'padding' => '', 'radius' => '', 'align' => '');
        $out .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Кнопка «Показать в древе»', 'genius-family-tree') . '</span>';
        $out .= '<div class="components-base-control">';
        $out .= ft_render_phs_align_control(
            'family_tree_phs[' . $dev . '][box][align]',
            'ft-phs-' . $dev . '-btn-align',
            isset($bx['align']) ? $bx['align'] : '',
            isset($bd_box['align']) ? $bd_box['align'] : '',
            ! $is_desk
        );
        $out .= '</div>';
        $out .= '<div class="ft-measure-row ft-phs-boxrow">';
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-phs-' . $dev . '-btn-margin',
            'name'         => 'family_tree_phs[' . $dev . '][box][margin]',
            'value'        => $bx['margin'],
            'placeholder'  => $pick($bx['margin'], isset($bd_box['margin']) ? $bd_box['margin'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Внешние отступы', 'genius-family-tree'),
            'help'         => esc_html__('Внешние отступы (margin) кнопки «Показать в древе». Кнопка с цепочкой позволяет задать каждую сторону отдельно.', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-phs-' . $dev . '-btn-padding',
            'name'         => 'family_tree_phs[' . $dev . '][box][padding]',
            'value'        => $bx['padding'],
            'placeholder'  => $pick($bx['padding'], isset($bd_box['padding']) ? $bd_box['padding'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Внутренние отступы', 'genius-family-tree'),
            'help'         => esc_html__('Внутренние отступы (padding) кнопки «Показать в древе». Кнопка с цепочкой позволяет задать каждую сторону отдельно.', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'    => 'ft-phs-' . $dev . '-btn-radius',
            'name'  => 'family_tree_phs[' . $dev . '][box][radius]',
            'value' => $bx['radius'],
            'placeholder' => $pick($bx['radius'], isset($bd_box['radius']) ? $bd_box['radius'] : ''),
            'default' => '0px',
            'label' => esc_html__('Скругление углов', 'genius-family-tree'),
            'help'  => esc_html__('Радиус скругления углов кнопки «Показать в древе»: 0, 4px, 20px, 50% и т.п.', 'genius-family-tree'),
        ));
        $out .= '</div>';

        $out .= '<div class="ft-state-cell" data-state="' . esc_attr($active_tab) . '">';
        $out .= '<div class="ft-layout-tabs ft-state-tabs" data-state-group="' . esc_attr($group . '-' . $dev) . '-btn">';
        $out .= '<label class="ft-layout-tab"><input type="radio" name="family_tree_phs[' . $dev . '][button_state]" value="normal" ' . checked($active_tab, 'normal', false) . ' /><span>' . esc_html__('Обычный', 'genius-family-tree') . '</span></label>';
        $out .= '<label class="ft-layout-tab"><input type="radio" name="family_tree_phs[' . $dev . '][button_state]" value="hover" ' . checked($active_tab, 'hover', false) . ' /><span>' . esc_html__('При наведении', 'genius-family-tree') . '</span></label>';
        $out .= '</div>';

        foreach (array('normal', 'hover') as $state) {
            $b    = $s[$dev]['button'][$state];
            $sfx  = 'ft-phs-' . $dev . '-btn-' . $state;
            $is_hover = ('hover' === $state);
            $b_norm = $s[$dev]['button']['normal'];
            $b_desk = $s['desktop']['button'][$state];
            $b_desk_norm = $s['desktop']['button']['normal'];
            $out .= '<div class="ft-state-group" data-state-group="' . esc_attr($group . '-' . $dev) . '-btn" data-group-state="' . esc_attr($state) . '">';

            // Блок 1. Цвет фона кнопки — Классический / Градиент, как «Цвет фона
            // кнопок» в тулбаре. Сверху, отдельным блоком.
            $out .= '<span class="components-base-control__label ft-phs-sublabel">' . esc_html__('Цвет фона кнопки', 'genius-family-tree') . '</span>';
            $out .= ft_render_bg_control(array(
                'id'            => $sfx . '-bg',
                'color_name'    => 'family_tree_phs[' . $dev . '][button][' . $state . '][bg_color]',
                'color_value'   => $b['bg_color'],
                'color_default' => '#ff7744',
                'color_placeholder' => $pick_btn($b['bg_color'], $b_norm['bg_color'], $b_desk['bg_color'], $b_desk_norm['bg_color']),
                'type_name'     => 'family_tree_phs[' . $dev . '][button][' . $state . '][bg_type]',
                'type_value'    => $b['bg_type'],
                'grad_name'     => 'family_tree_phs[' . $dev . '][button][' . $state . '][bg_gradient]',
                'grad_value'    => $b['bg_gradient'],
                'gtype_name'    => 'family_tree_phs[' . $dev . '][button][' . $state . '][bg_gradient_type]',
                'gtype_value'   => $b['bg_gradient_type'],
                'angle_name'    => 'family_tree_phs[' . $dev . '][button][' . $state . '][bg_angle]',
                'angle_value'   => $b['bg_angle'],
                'help'          => $is_hover
                    ? __('Пусто — используется фон из состояния «Обычный».', 'genius-family-tree')
                    : __('Классический цвет или градиент. По умолчанию: #ff7744.', 'genius-family-tree'),
            ));

            // Блок 2. Текст — тот же ряд, что и у заголовка. Заголовок
            // раздела, в отличие от «Цвет фона кнопки» и «Границы»,
            // которые остаются названиями блоков.
            $out .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Текст', 'genius-family-tree') . '</span>';
            $out .= '<div class="ft-phs-row">';
            $out .= ft_render_phs_cell(
                __('Цвет', 'genius-family-tree'),
                ft_render_bg_control(array(
                    'id'            => $sfx . '-color',
                    'color_name'    => 'family_tree_phs[' . $dev . '][button][' . $state . '][text_color]',
                    'color_value'   => $b['text_color'],
                    'color_default' => '#ffffff',
                    'color_placeholder' => $pick_btn($b['text_color'], $b_norm['text_color'], $b_desk['text_color'], $b_desk_norm['text_color']),
                    'type_name'     => 'family_tree_phs[' . $dev . '][button][' . $state . '][text_color_type]',
                    'type_value'    => 'classic',
                    'grad_name'     => '',
                    'gtype_name'    => '',
                    'angle_name'    => '',
                    'angle_value'   => 180,
                    'show_type'     => false,
                    // Цвет стоит в ряду с шрифтом/размером/толщиной, где в конце
                    // уже есть кнопка сброса всего ряда — своя не нужна.
                    'show_reset'    => false,
                )),
                'ft-phs-cell--color'
            );
            $out .= ft_render_phs_cell(
                __('Шрифт', 'genius-family-tree'),
                ft_render_font_select('family_tree_phs[' . $dev . '][button][' . $state . '][font_family]', $sfx . '-font', $b['font_family'], $ft_fonts, $ft_google_fonts, $pick_btn($b['font_family'], $b_norm['font_family'], $b_desk['font_family'], $b_desk_norm['font_family']))
            );
            $out .= ft_render_phs_cell(
                __('Размер', 'genius-family-tree'),
                ft_render_size_field('family_tree_phs[' . $dev . '][button][' . $state . '][font_size]', $sfx . '-size', $b['font_size'], $pick_btn($b['font_size'], $b_norm['font_size'], $b_desk['font_size'], $b_desk_norm['font_size'])),
                'ft-phs-cell--size'
            );
            $out .= ft_render_phs_cell(
                __('Толщина', 'genius-family-tree'),
                ft_render_weight_select('family_tree_phs[' . $dev . '][button][' . $state . '][font_weight]', $sfx . '-weight', $b['font_family'], $b['font_weight'], $sfx . '-font', $pick_btn($b['font_weight'], $b_norm['font_weight'], $b_desk['font_weight'], $b_desk_norm['font_weight']))
            );
            // Сбрасываем только поля этого ряда (цвет текста, шрифт, размер,
            // толщину). Фон кнопки — соседний блок со своим сбросом, сюда не
            // подмешиваем.
            $out .= ft_render_phs_reset_cell('#' . $sfx . '-color-ctrl, #' . $sfx . '-font, #' . $sfx . '-size, #' . $sfx . '-weight');
            $out .= '</div>';

            $out .= '<p class="components-base-control__help">' . ($is_hover
                ? esc_html__('Пустые поля наследуют состояние «Обычный».', 'genius-family-tree')
                : esc_html__('Фон кнопки: классический цвет или градиент (по умолчанию #ff7744), цвет текста #ffffff.', 'genius-family-tree')) . '</p>';

            // Блок 3. Граница — тот же одиночный контрол, что в разделе
            // «Цвет блоков», но без разделения на стороны: одна толщина,
            // один стиль и один цвет на всё состояние.
            $out .= '<div class="ft-phs-statebox">';
            $out .= ft_render_corner_control(array(
                'id'            => $sfx . '-border',
                'name'          => 'family_tree_phs[' . $dev . '][button][' . $state . '][border_width]',
                'value'         => $b['border_width'],
                'placeholder'   => $pick_btn($b['border_width'], $b_norm['border_width'], $b_desk['border_width'], $b_desk_norm['border_width']),
                'default'       => '1px',
                'max'           => 50,
                'units'         => array('px', 'em', 'rem'),
                'label'         => esc_html__('Граница', 'genius-family-tree'),
                'help'          => $is_hover
                    ? esc_html__('Пусто — наследует границу состояния «Обычный».', 'genius-family-tree')
                    : esc_html__('Рамка вокруг кнопки. Кнопка с цепочкой позволяет задать толщину каждой стороны отдельно.', 'genius-family-tree'),
                'link_title'    => esc_html__('Связанные стороны', 'genius-family-tree'),
                'corner_icons'  => array('↑', '→', '↓', '←'),
                'style_name'    => 'family_tree_phs[' . $dev . '][button][' . $state . '][border_style]',
                'style_value'   => $b['border_style'],
                'style_placeholder' => $pick_btn($b['border_style'], $b_norm['border_style'], $b_desk['border_style'], $b_desk_norm['border_style']),
                'style_default' => 'solid',
                'style_options' => array(
                    'solid'  => __('Сплошная', 'genius-family-tree'),
                    'dashed' => __('Пунктирная (dashed)', 'genius-family-tree'),
                    'dotted' => __('Точечная (dotted)', 'genius-family-tree'),
                    'double' => __('Двойная (double)', 'genius-family-tree'),
                ),
                'color_name'    => 'family_tree_phs[' . $dev . '][button][' . $state . '][border_color]',
                'color_value'   => $b['border_color'],
                'color_placeholder' => $pick_btn($b['border_color'], $b_norm['border_color'], $b_desk['border_color'], $b_desk_norm['border_color']),
                'color_default' => '',
                'color_id'      => $sfx . '-border-color',
                'show_range'    => false,
            ));
            $out .= '</div>';

            $out .= '</div>';
        }
        $out .= '</div>';

        $out .= '<p class="components-base-control__help">' . esc_html__('Оформление кнопки «Показать в древе» для этого устройства. Отступы и скругление — одни на оба состояния. В состоянии «При наведении» пустые значения наследуют состояние «Обычный».', 'genius-family-tree') . '</p>';
        $out .= '</div>';
        $out .= '</div>';
    }
    $out .= '</div>';
    return $out;
}
/**
 * Блок «Заголовки» или «Текст» сайдбара: выравнивание по горизонтали и
 * один ряд с цветом, гарнитурой, размером, толщиной и сбросом.
 *
 * Разметка повторяет блок «Заголовок» из настроек шапки, чтобы обе секции
 * выглядели одинаково.
 *
 * @param array  $row          значения блока для текущего устройства
 * @param array  $desk         значения блока на Десктопе (для placeholder)
 * @param bool   $is_desk      текущее устройство — Десктоп
 * @param string $prefix       префикс id и имён полей
 * @param string $prefix_name  префикс name (может отличаться от префикса id)
 * @param string $label        заголовок блока
 * @param string $help         подпись под рядом
 * @param string $kind         'heading' или 'text' — набор дополнительных полей
 * @param array  $ft_fonts         системные гарнитуры
 * @param array  $ft_google_fonts   Google Fonts
 * @return string
 */
function ft_render_pms_text_block($row, $desk, $is_desk, $prefix, $prefix_name, $label, $help, $kind, $ft_fonts, $ft_google_fonts) {
    $out = '<div class="ft-phs-block">';
    $out .= '<span class="components-base-control__label ft-phs-heading">' . esc_html($label) . '</span>';
    $out .= '<div class="components-base-control">';
    $out .= ft_render_phs_align_control(
        $prefix_name . '[text_align]',
        $prefix . '-align',
        isset($row['text_align']) ? $row['text_align'] : '',
        isset($desk['text_align']) ? $desk['text_align'] : '',
        ! $is_desk
    );
    $out .= '<div class="ft-phs-row">';
    $out .= ft_render_phs_cell(
        __('Цвет', 'genius-family-tree'),
        ft_render_color_field($prefix_name . '[color]', $prefix . '-color', $row['color'], '#1d2327', ft_pms_pick($is_desk, $row['color'], $desk['color'])),
        'ft-phs-cell--color'
    );
    $out .= ft_render_phs_cell(
        __('Шрифт', 'genius-family-tree'),
        ft_render_font_select($prefix_name . '[font_family]', $prefix . '-font', $row['font_family'], $ft_fonts, $ft_google_fonts, ft_pms_pick($is_desk, $row['font_family'], $desk['font_family']))
    );
    $out .= ft_render_phs_cell(
        __('Размер', 'genius-family-tree'),
        ft_render_size_field($prefix_name . '[font_size]', $prefix . '-size', $row['font_size'], ft_pms_pick($is_desk, $row['font_size'], $desk['font_size'])),
        'ft-phs-cell--size'
    );
    $out .= ft_render_phs_cell(
        __('Толщина', 'genius-family-tree'),
        ft_render_weight_select($prefix_name . '[font_weight]', $prefix . '-weight', $row['font_family'], $row['font_weight'], $prefix . '-font', ft_pms_pick($is_desk, $row['font_weight'], $desk['font_weight']))
    );
    $out .= ft_render_phs_reset_cell('#' . $prefix . '-color, #' . $prefix . '-font, #' . $prefix . '-size, #' . $prefix . '-weight');
    $out .= '</div>';

    // Отступы заголовков — тот же measure-контрол, что у ссылок.
    if ('heading' === $kind) {
        $out .= '<div class="ft-measure-row ft-phs-boxrow">';
        $out .= ft_render_corner_control(array(
            'id'           => $prefix . '-margin',
            'name'         => $prefix_name . '[margin]',
            'value'        => isset($row['margin']) ? $row['margin'] : '',
            'placeholder'  => ft_pms_pick($is_desk, isset($row['margin']) ? $row['margin'] : '', isset($desk['margin']) ? $desk['margin'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => __('Внешние отступы', 'genius-family-tree'),
            'help'         => __('Внешние отступы (margin) вокруг заголовка.', 'genius-family-tree'),
            'link_title'   => __('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'           => $prefix . '-padding',
            'name'         => $prefix_name . '[padding]',
            'value'        => isset($row['padding']) ? $row['padding'] : '',
            'placeholder'  => ft_pms_pick($is_desk, isset($row['padding']) ? $row['padding'] : '', isset($desk['padding']) ? $desk['padding'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => __('Внутренние отступы', 'genius-family-tree'),
            'help'         => __('Внутренние отступы (padding) внутри заголовка.', 'genius-family-tree'),
            'link_title'   => __('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= '</div>';
    }

    // Подчёркивание заголовков / разделители текста: чекбокс + цвет/толщина.
    $tk      = ('heading' === $kind) ? 'underline' : 'separator';
    $toggle  = isset($row[$tk]) ? $row[$tk] : '';
    $t_color = isset($row[$tk . '_color']) ? $row[$tk . '_color'] : '';
    $t_width = isset($row[$tk . '_width']) ? $row[$tk . '_width'] : 0;
    $d_color = isset($desk[$tk . '_color']) ? $desk[$tk . '_color'] : '';
    $d_width = isset($desk[$tk . '_width']) ? $desk[$tk . '_width'] : 0;
    $is_on   = $is_desk ? ('0' !== $toggle) : ('1' === $toggle);
    if ('heading' === $kind) {
        $toggle_label = __('Добавить подчеркивание', 'genius-family-tree');
        $color_label  = __('Цвет линии', 'genius-family-tree');
        $width_label  = __('Толщина линии', 'genius-family-tree');
        $color_def    = '#e5e5e5';
    } else {
        $toggle_label = __('Добавить разделители', 'genius-family-tree');
        $color_label  = __('Цвет разделителя', 'genius-family-tree');
        $width_label  = __('Толщина разделителя', 'genius-family-tree');
        $color_def    = '#f0f0f1';
    }
    $out .= '<div class="ft-phs-checkbox-block">';
    $out .= '<label class="ft-phs-checkbox-label">';
    $out .= '<input type="checkbox" class="ft-phs-checkbox" name="' . esc_attr($prefix_name . '[' . $tk . ']') . '" id="' . esc_attr($prefix . '-' . $tk) . '" value="1" ' . checked($is_on, true, false) . ' data-ft-phs-underline-toggle /> ';
    $out .= esc_html($toggle_label);
    $out .= '</label>';
    if (! $is_desk) {
        $note = $is_on
            ? __('Задано своё значение для этого устройства.', 'genius-family-tree')
            : __('Наследуется с Десктопа.', 'genius-family-tree');
        $out .= '<p class="components-base-control__help">' . esc_html($note) . '</p>';
    }
    $out .= '<div class="ft-phs-row ft-phs-underline-settings' . ($is_on ? ' is-on' : '') . '" data-ft-phs-underline-settings>';
    $out .= ft_render_phs_cell(
        $color_label,
        ft_render_color_field($prefix_name . '[' . $tk . '_color]', $prefix . '-' . $tk . '-color', $t_color, $color_def, ft_pms_pick($is_desk, $t_color, $d_color)),
        'ft-phs-cell--color'
    );
    $out .= ft_render_phs_cell(
        $width_label,
        ft_render_size_field($prefix_name . '[' . $tk . '_width]', $prefix . '-' . $tk . '-width', $t_width, ft_pms_pick($is_desk, $t_width, $d_width)),
        'ft-phs-cell--size'
    );
    $out .= '</div>';
    $out .= '</div>';

    $out .= '<p class="components-base-control__help">' . esc_html($help) . '</p>';
    $out .= '</div>';
    $out .= '</div>';
    return $out;
}
/**
 * Значение для placeholder: на Десктопе подсказка не нужна, на остальных
 * устройствах показываем то, что придёт по наследованию.
 *
 * @param bool   $is_desk текущее устройство — Десктоп
 * @param mixed  $own     своё значение
 * @param mixed  $desk    значение Десктопа
 * @return string
 */
function ft_pms_pick($is_desk, $own, $desk) {
    if ($is_desk) {
        return '';
    }
    $own_raw = trim((string) $own);
    if ('' !== $own_raw && '0' !== $own_raw) {
        return '';
    }
    return trim((string) $desk);
}
/**
 * Раздел «Портрет» — вне табов устройств, поэтому один на все устройства.
 *
 * Набор значений общий, значит и подсказки «наследуется с Десктопа» не нужны:
 * полей с двумя источниками здесь нет. Ветка «desktop» в именах полей
 * остаётся — это же имя приходит в POST и лежит в опции, поэтому переезд
 * не ломает уже сохранённые настройки.
 *
 * @param array $pr настройки портрета из ветки «desktop»
 * @return string
 */
function ft_render_pms_portrait_block($pr) {
    $is_desk  = true;
    $pr_desk  = $pr;
    $pr_sfx   = 'ft-pms-portrait';
    $pr_nm    = 'family_tree_pms[desktop][portrait]';
    $shape    = isset($pr['shape']) ? $pr['shape'] : '';
    $out      = '<div class="ft-phs-block">';
    $out     .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Портрет', 'genius-family-tree') . '</span>';
    $out     .= '<div class="components-base-control">';
    $out     .= ft_render_phs_align_control(
        $pr_nm . '[align]',
        $pr_sfx . '-align',
        isset($pr['align']) ? $pr['align'] : '',
        '',
        false
    );
    $out     .= '</div>';
    // Пропорции: выбор одного варианта, а не набор размеров.
    $out     .= '<div class="ft-phs-row">';
    $out     .= ft_render_phs_cell(
        __('Форма', 'genius-family-tree'),
        '<select name="' . esc_attr($pr_nm . '[shape]') . '" id="' . esc_attr($pr_sfx . '-shape') . '">'
            . '<option value=""' . selected('', $shape, false) . '>' . esc_html__('Как в теме', 'genius-family-tree') . '</option>'
            . '<option value="square"' . selected('square', $shape, false) . '>' . esc_html__('Квадрат', 'genius-family-tree') . '</option>'
            . '<option value="circle"' . selected('circle', $shape, false) . '>' . esc_html__('Круг', 'genius-family-tree') . '</option>'
            . '<option value="full"' . selected('full', $shape, false) . '>' . esc_html__('Круг на всю ширину', 'genius-family-tree') . '</option>'
            . '<option value="full-square"' . selected('full-square', $shape, false) . '>' . esc_html__('Квадрат на всю ширину', 'genius-family-tree') . '</option>'
            . '</select>'
    );
    $out     .= '</div>';
    $out     .= '<p class="components-base-control__help">' . esc_html__('Пропорции картинки портрета: «Как в теме» оставляет вид темы (круг), остальные варианты задают форму принудительно. «На всю ширину» — картинка занимает всю ширину сайдбара без рамки и обрезается по кругу или квадрату.', 'genius-family-tree') . '</p>';
    $out     .= '<div class="ft-measure-row ft-phs-boxrow">';
    $out     .= ft_render_corner_control(array(
        'id'           => $pr_sfx . '-margin',
        'name'         => $pr_nm . '[margin]',
        'value'        => isset($pr['margin']) ? $pr['margin'] : '',
        'default'      => '0px',
        'max'          => 100,
        'units'        => array('px', 'em', 'rem', '%'),
        'label'        => esc_html__('Внешние отступы', 'genius-family-tree'),
        'help'         => esc_html__('Внешние отступы (margin) вокруг картинки портрета.', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
    ));
    $out     .= ft_render_corner_control(array(
        'id'           => $pr_sfx . '-padding',
        'name'         => $pr_nm . '[padding]',
        'value'        => isset($pr['padding']) ? $pr['padding'] : '',
        'default'      => '0px',
        'max'          => 100,
        'units'        => array('px', 'em', 'rem', '%'),
        'label'        => esc_html__('Внутренние отступы', 'genius-family-tree'),
        'help'         => esc_html__('Внутренние отступы (padding) внутри картинки портрета.', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
    ));
    // Граница — третьим блоком ТОЙ ЖЕ сетки, а не отдельным рядом: в
    // .ft-measure-row две колонки и gap 16px, поэтому «Внешние/Внутренние»
    // стоят в первом ряду, «Граница» — во втором, с тем же отступом и той же
    // шириной в ячейке. В .ft-phs-statebox она растягивалась на всю ширину и
    // выглядела иначе, чем соседи.
    $out     .= ft_render_corner_control(array(
        'id'           => $pr_sfx . '-border',
        'name'         => $pr_nm . '[border_width]',
        'value'        => isset($pr['border_width']) ? $pr['border_width'] : '',
        'default'      => '1px',
        'max'          => 50,
        'units'        => array('px', 'em', 'rem'),
        'label'        => esc_html__('Граница', 'genius-family-tree'),
        'help'         => esc_html__('Рамка вокруг картинки портрета.', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
        'style_name'   => $pr_nm . '[border_style]',
        'style_value'  => isset($pr['border_style']) ? $pr['border_style'] : '',
        'style_default' => 'solid',
        'style_options' => array(
            'solid'  => __('Сплошная', 'genius-family-tree'),
            'dashed' => __('Пунктирная (dashed)', 'genius-family-tree'),
            'dotted' => __('Точечная (dotted)', 'genius-family-tree'),
            'double' => __('Двойная (double)', 'genius-family-tree'),
        ),
        'color_name'   => $pr_nm . '[border_color]',
        'color_value'  => isset($pr['border_color']) ? $pr['border_color'] : '',
        'color_default' => '',
        'color_id'     => $pr_sfx . '-border-color',
        'show_range'   => false,
    ));
    $out     .= '</div>';
    $out     .= '<p class="components-base-control__help">' . esc_html__('Оформление портрета сайдбара. Настройки общие для всех устройств.', 'genius-family-tree') . '</p>';
    $out     .= '</div>';
    return $out;
}
/**
 * Раздел «Подпись» — вне табов устройств, поэтому один на все устройства.
 *
 * Устройство здесь не участвует: блок стоит под панелью табов, а значения
 * общие. Имена полей сохраняют ветку «desktop» — она приходит в POST и лежит
 * в опции, поэтому уже сохранённые настройки продолжают работать.
 *
 * @param array $sg настройки подписи из ветки «desktop»
 * @return string
 */
function ft_render_pms_signature_block($sg) {
    $is_desk = true;
    $sg_sfx  = 'ft-pms-signature';
    $sg_nm   = 'family_tree_pms[desktop][signature]';
    $out     = '<div class="ft-phs-block">';
    $out    .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Подпись', 'genius-family-tree') . '</span>';
    // Фон - как у самой ссылки, но <блок подписи>: настраивается один раз,
    // фон можно градиентом.
    $out    .= '<span class="components-base-control__label ft-phs-sublabel">' . esc_html__('Фон подписи', 'genius-family-tree') . '</span>';
    $out    .= ft_render_bg_control(array(
        'id'            => $sg_sfx . '-bg',
        'color_name'    => $sg_nm . '[bg_color]',
        'color_value'   => isset($sg['bg_color']) ? $sg['bg_color'] : '',
        'color_default' => '',
        'type_name'     => $sg_nm . '[bg_type]',
        'type_value'    => isset($sg['bg_type']) ? $sg['bg_type'] : 'classic',
        'grad_name'     => $sg_nm . '[bg_gradient]',
        'grad_value'    => isset($sg['bg_gradient']) ? $sg['bg_gradient'] : '',
        'gtype_name'    => $sg_nm . '[bg_gradient_type]',
        'gtype_value'   => isset($sg['bg_gradient_type']) ? $sg['bg_gradient_type'] : 'linear',
        'angle_name'    => $sg_nm . '[bg_angle]',
        'angle_value'   => isset($sg['bg_angle']) ? $sg['bg_angle'] : 180,
        'help'          => __('Цветной или градиентный фон. Текст - в разделе «Текст».', 'genius-family-tree'),
    ));
    $out    .= '<div class="ft-measure-row ft-phs-boxrow">';
    $out    .= ft_render_corner_control(array(
        'id'           => $sg_sfx . '-margin',
        'name'         => $sg_nm . '[margin]',
        'value'        => isset($sg['margin']) ? $sg['margin'] : '',
        'default'      => '0px',
        'max'          => 100,
        'units'        => array('px', 'em', 'rem', '%'),
        'label'        => esc_html__('Внешние отступы', 'genius-family-tree'),
        'help'         => esc_html__('Внешние отступы (margin) вокруг картинки подписи.', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
    ));
    $out    .= ft_render_corner_control(array(
        'id'           => $sg_sfx . '-padding',
        'name'         => $sg_nm . '[padding]',
        'value'        => isset($sg['padding']) ? $sg['padding'] : '',
        'default'      => '0px',
        'max'          => 100,
        'units'        => array('px', 'em', 'rem', '%'),
        'label'        => esc_html__('Внутренние отступы', 'genius-family-tree'),
        'help'         => esc_html__('Внутренние отступы (padding) внутри картинки подписи.', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
    ));
    $out    .= ft_render_corner_control(array(
        'id'           => $sg_sfx . '-radius',
        'name'         => $sg_nm . '[radius]',
        'value'        => isset($sg['radius']) ? $sg['radius'] : '',
        'default'      => '0px',
        'max'          => 100,
        'units'        => array('px', 'em', 'rem', '%'),
        'label'        => esc_html__('Скругление углов', 'genius-family-tree'),
        'help'         => esc_html__('Скругление углов фона подписи (border-radius).', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные углы', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
    ));
    // Граница - в тот же ряд, что и скругление: третья колонка второй строки
    // сетки, с тем же gap 16px и той же шириной в ячейке.
    $out    .= ft_render_corner_control(array(
        'id'           => $sg_sfx . '-border',
        'name'         => $sg_nm . '[border_width]',
        'value'        => isset($sg['border_width']) ? $sg['border_width'] : '',
        'default'      => '1px',
        'max'          => 50,
        'units'        => array('px', 'em', 'rem'),
        'label'        => esc_html__('Граница', 'genius-family-tree'),
        'help'         => esc_html__('Рамка вокруг картинки подписи.', 'genius-family-tree'),
        'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
        'corner_icons' => array('↑', '→', '↓', '←'),
        'style_name'   => $sg_nm . '[border_style]',
        'style_value'  => isset($sg['border_style']) ? $sg['border_style'] : '',
        'style_default' => 'solid',
        'style_options' => array(
            'solid'  => __('Сплошная', 'genius-family-tree'),
            'dashed' => __('Пунктирная (dashed)', 'genius-family-tree'),
            'dotted' => __('Точечная (dotted)', 'genius-family-tree'),
            'double' => __('Двойная (double)', 'genius-family-tree'),
        ),
        'color_name'   => $sg_nm . '[border_color]',
        'color_value'  => isset($sg['border_color']) ? $sg['border_color'] : '',
        'color_default' => '',
        'color_id'     => $sg_sfx . '-border-color',
        'show_range'   => false,
    ));
    $out    .= '</div>';
    $out    .= '<p class="components-base-control__help">' . esc_html__('Оформление картинки подписи (автографа). Настройки общие для всех устройств.', 'genius-family-tree') . '</p>';
    $out    .= '</div>';
    return $out;
}
/**
 * Раздел «Настройки сайдбара»: «Портрет» над табами устройств, «Подпись» под
 * ними, а между ними — блоки «Заголовки», «Текст» и «Ссылки». У ссылок,
 * кроме выравнивания, есть состояния «Обычный / При наведении».
 *
 * Портрет и подпись вынесены из табов, потому что табов у них нет: значения
 * общие для всех устройств (см. ft_render_pms_portrait_block()).
 *
 * @param array $s           нормализованные настройки по ft_pms_schema()
 * @param array $ft_fonts         системные гарнитуры
 * @param array $ft_google_fonts   Google Fonts
 * @param string $active      открытое устройство
 * @return string
 */
function ft_render_sidebar_section($s, $ft_fonts, $ft_google_fonts, $active = 'desktop') {
    $group = 'sidebar';

    /* ---------- Портрет: над табами устройств, табов у него нет ---------- */
    $out = ft_render_pms_portrait_block(isset($s['desktop']['portrait']) ? $s['desktop']['portrait'] : array());

    $out  .= ft_render_device_tabs($group, $active);
    $out  .= '<div class="ft-device-frame" data-ft-device-frame="' . esc_attr($group) . '">';
    foreach (ft_device_list() as $dev => $meta) {
        $is_desk    = ('desktop' === $dev);
        $h          = $s[$dev]['heading'];
        $t          = $s[$dev]['text'];
        $h_desk     = $s['desktop']['heading'];
        $t_desk     = $s['desktop']['text'];
        $lx         = $s[$dev]['link_box'];
        $lx_desk    = $s['desktop']['link_box'];
        $active_tab = isset($s[$dev]['link_state']) ? $s[$dev]['link_state'] : 'normal';

        $out .= '<div class="ft-device-panel" data-ft-device-panel="' . esc_attr($dev) . '"' . ($dev === $active ? '' : ' style="display:none;"') . '>';

        /* ---------- Заголовки ---------- */
        $out .= ft_render_pms_text_block(
            $h, $h_desk, $is_desk,
            'ft-pms-' . $dev . '-heading', 'family_tree_pms[' . $dev . '][heading]',
            __('Заголовки', 'genius-family-tree'),
            __('Цвет, гарнитура, размер, толщина и выравнивание заголовков сайдбара («Краткая информация», «Родители», «Дети») для этого устройства.', 'genius-family-tree'),
            'heading',
            $ft_fonts, $ft_google_fonts
        );

        /* ---------- Текст ---------- */
        $out .= ft_render_pms_text_block(
            $t, $t_desk, $is_desk,
            'ft-pms-' . $dev . '-text', 'family_tree_pms[' . $dev . '][text]',
            __('Текст', 'genius-family-tree'),
            __('Цвет, гарнитура, размер, толщина и выравнивание обычного текста сайдбара (таблицы, списки родственников) для этого устройства.', 'genius-family-tree'),
            'text',
            $ft_fonts, $ft_google_fonts
        );

        /* ---------- Ссылки ---------- */
        $out .= '<div class="ft-phs-block">';
        // Габариты ссылок — как у кнопки «Показать в древе»: одни значения на
        // всю ссылку, ВЫШЕ табов «Обычный / При наведении». Состояния внутри
        // настраивают только фон, текст и границу.
        $out .= '<span class="components-base-control__label ft-phs-heading">' . esc_html__('Ссылки', 'genius-family-tree') . '</span>';
        $out .= '<div class="components-base-control">';
        // Выравнивание одно на оба состояния, поэтому стоит до табов.
        $out .= ft_render_phs_align_control(
            'family_tree_pms[' . $dev . '][link_box][align]',
            'ft-pms-' . $dev . '-link-align',
            isset($lx['align']) ? $lx['align'] : '',
            isset($lx_desk['align']) ? $lx_desk['align'] : '',
            ! $is_desk
        );
        $out .= '</div>';
        $out .= '<div class="ft-measure-row ft-phs-boxrow">';
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-pms-' . $dev . '-link-margin',
            'name'         => 'family_tree_pms[' . $dev . '][link_box][margin]',
            'value'        => isset($lx['margin']) ? $lx['margin'] : '',
            'placeholder'  => ft_pms_pick($is_desk, isset($lx['margin']) ? $lx['margin'] : '', isset($lx_desk['margin']) ? $lx_desk['margin'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Внешние отступы', 'genius-family-tree'),
            'help'         => esc_html__('Внешние отступы (margin) вокруг ссылки.', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-pms-' . $dev . '-link-padding',
            'name'         => 'family_tree_pms[' . $dev . '][link_box][padding]',
            'value'        => isset($lx['padding']) ? $lx['padding'] : '',
            'placeholder'  => ft_pms_pick($is_desk, isset($lx['padding']) ? $lx['padding'] : '', isset($lx_desk['padding']) ? $lx_desk['padding'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Внутренние отступы', 'genius-family-tree'),
            'help'         => esc_html__('Внутренние отступы (padding) внутри ссылки. Работают вместе с фоном и скруглением.', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= ft_render_corner_control(array(
            'id'           => 'ft-pms-' . $dev . '-link-radius',
            'name'         => 'family_tree_pms[' . $dev . '][link_box][radius]',
            'value'        => isset($lx['radius']) ? $lx['radius'] : '',
            'placeholder'  => ft_pms_pick($is_desk, isset($lx['radius']) ? $lx['radius'] : '', isset($lx_desk['radius']) ? $lx_desk['radius'] : ''),
            'default'      => '0px',
            'max'          => 100,
            'units'        => array('px', 'em', 'rem', '%'),
            'label'        => esc_html__('Скругление углов', 'genius-family-tree'),
            'help'         => esc_html__('Скругление углов фона ссылки (border-radius).', 'genius-family-tree'),
            'link_title'   => esc_html__('Связанные углы', 'genius-family-tree'),
            'corner_icons' => array('↑', '→', '↓', '←'),
        ));
        $out .= '</div>';

        $out .= '<div class="ft-state-cell" data-state="' . esc_attr($active_tab) . '">';
        $out .= '<div class="ft-layout-tabs ft-state-tabs" data-state-group="' . esc_attr($group . '-' . $dev) . '-link">';
        $out .= '<label class="ft-layout-tab"><input type="radio" name="family_tree_pms[' . $dev . '][link_state]" value="normal" ' . checked($active_tab, 'normal', false) . ' /><span>' . esc_html__('Обычный', 'genius-family-tree') . '</span></label>';
        $out .= '<label class="ft-layout-tab"><input type="radio" name="family_tree_pms[' . $dev . '][link_state]" value="hover" ' . checked($active_tab, 'hover', false) . ' /><span>' . esc_html__('При наведении', 'genius-family-tree') . '</span></label>';
        $out .= '</div>';

        foreach (array('normal', 'hover') as $state) {
            $l           = $s[$dev]['link'][$state];
            $l_norm      = $s[$dev]['link']['normal'];
            $l_desk      = $s['desktop']['link'][$state];
            $l_desk_norm = $s['desktop']['link']['normal'];
            $sfx         = 'ft-pms-' . $dev . '-link-' . $state;
            $nm          = 'family_tree_pms[' . $dev . '][link][' . $state . ']';
            $is_hover    = ('hover' === $state);

            // Цепочка наследования ссылок: своё значение -> своё «Обычный» ->
            // значение Десктопа в этом же состоянии -> «Обычный» Десктопа.
            $pick = function ($own, $own_norm, $desk, $desk_norm) use ($is_desk) {
                if ($is_desk) {
                    return '';
                }
                foreach (array($own, $own_norm, $desk, $desk_norm) as $cand) {
                    $raw = trim((string) $cand);
                    if ('' !== $raw && '0' !== $raw) {
                        return $raw;
                    }
                }
                return '';
            };

            $out .= '<div class="ft-state-group" data-state-group="' . esc_attr($group . '-' . $dev) . '-link" data-group-state="' . esc_attr($state) . '">';

            // Цвет фона ссылки — тот же контрол, что «Цвет фона кнопки» в шапке.
            $out .= '<span class="components-base-control__label ft-phs-sublabel">' . esc_html__('Фон ссылки', 'genius-family-tree') . '</span>';
            $out .= ft_render_bg_control(array(
                'id'            => $sfx . '-bg',
                'color_name'    => $nm . '[bg_color]',
                'color_value'   => $l['bg_color'],
                'color_default' => '',
                'color_placeholder' => $pick($l['bg_color'], $l_norm['bg_color'], $l_desk['bg_color'], $l_desk_norm['bg_color']),
                'type_name'     => $nm . '[bg_type]',
                'type_value'    => $l['bg_type'],
                'grad_name'     => $nm . '[bg_gradient]',
                'grad_value'    => $l['bg_gradient'],
                'gtype_name'    => $nm . '[bg_gradient_type]',
                'gtype_value'   => $l['bg_gradient_type'],
                'angle_name'    => $nm . '[bg_angle]',
                'angle_value'   => $l['bg_angle'],
                'help'          => $is_hover
                    ? __('Пусто — используется фон из состояния «Обычный».', 'genius-family-tree')
                    : __('Классический цвет или градиент. Пусто — без фона, цвет ссылки темы.', 'genius-family-tree'),
            ));

            // Цвет, гарнитура, размер и толщина — в один ряд, как у заголовка.
            $out .= '<span class="components-base-control__label ft-phs-sublabel">' . esc_html__('Текст ссылки', 'genius-family-tree') . '</span>';
            $out .= '<div class="ft-phs-row">';
            $out .= ft_render_phs_cell(
                __('Цвет', 'genius-family-tree'),
                ft_render_bg_control(array(
                    'id'            => $sfx . '-color',
                    'color_name'    => $nm . '[color]',
                    'color_value'   => $l['color'],
                    'color_default' => '#ff7744',
                    'color_placeholder' => $pick($l['color'], $l_norm['color'], $l_desk['color'], $l_desk_norm['color']),
                    'type_name'     => $nm . '[color_type]',
                    'type_value'    => 'classic',
                    'grad_name'     => '',
                    'gtype_name'    => '',
                    'angle_name'    => '',
                    'angle_value'   => 180,
                    'show_type'     => false,
                    'show_reset'    => false,
                )),
                'ft-phs-cell--color'
            );
            $out .= ft_render_phs_cell(
                __('Шрифт', 'genius-family-tree'),
                ft_render_font_select($nm . '[font_family]', $sfx . '-font', $l['font_family'], $ft_fonts, $ft_google_fonts, $pick($l['font_family'], $l_norm['font_family'], $l_desk['font_family'], $l_desk_norm['font_family']))
            );
            $out .= ft_render_phs_cell(
                __('Размер', 'genius-family-tree'),
                ft_render_size_field($nm . '[font_size]', $sfx . '-size', $l['font_size'], $pick($l['font_size'], $l_norm['font_size'], $l_desk['font_size'], $l_desk_norm['font_size'])),
                'ft-phs-cell--size'
            );
            $out .= ft_render_phs_cell(
                __('Толщина', 'genius-family-tree'),
                ft_render_weight_select($nm . '[font_weight]', $sfx . '-weight', $l['font_family'], $l['font_weight'], $sfx . '-font', $pick($l['font_weight'], $l_norm['font_weight'], $l_desk['font_weight'], $l_desk_norm['font_weight']))
            );
            // Подчёркивание — свой select между «Толщиной» и сбросом строки.
            // Значение своё у каждого состояния: здесь не $pick, а только
            // подпись наследования от Десктопа.
            $out .= ft_render_phs_cell(
                __('Подчёркивание', 'genius-family-tree'),
                ft_render_phs_underline_select(
                    $nm . '[underline]',
                    $sfx . '-underline',
                    ft_pms_link_underline($s, $dev, $state),
                    ft_pms_link_underline($s, 'desktop', $state),
                    ! $is_desk
                )
            );
            // Цвет ссылки — это контрол фона (.ft-bg-control) с id обёртки
            // `-color-ctrl`: сам `<input>` id не имеет, поэтому в сбросе
            // указываем обёртку, иначе строка не очищалась бы.
            $out .= ft_render_phs_reset_cell('#' . $sfx . '-color-ctrl, #' . $sfx . '-font, #' . $sfx . '-size, #' . $sfx . '-weight, #' . $sfx . '-underline');
            $out .= '</div>';

            // Отступы и скругление вынесены выше табов (link_box), поэтому в
            // состоянии осталась только граница. Отдельным рядом, но с той же
            // шириной ячейки, что у соседей, и с отступом 16px от «Текста ссылки»
            // — оба задаёт CSS (ft-phs-statebox внутри .ft-state-group).
            $out .= '<div class="ft-phs-statebox">';
            $out .= ft_render_corner_control(array(
                'id'           => $sfx . '-border',
                'name'         => $nm . '[border_width]',
                'value'        => $l['border_width'],
                'placeholder'  => $pick($l['border_width'], $l_norm['border_width'], $l_desk['border_width'], $l_desk_norm['border_width']),
                'default'      => '1px',
                'max'          => 50,
                'units'        => array('px', 'em', 'rem'),
                'label'        => esc_html__('Граница', 'genius-family-tree'),
                'help'         => esc_html__('Рамка вокруг ссылки.', 'genius-family-tree'),
                'link_title'   => esc_html__('Связанные стороны', 'genius-family-tree'),
                'corner_icons' => array('↑', '→', '↓', '←'),
                'style_name'    => $nm . '[border_style]',
                'style_value'   => $l['border_style'],
                'style_placeholder' => $pick($l['border_style'], $l_norm['border_style'], $l_desk['border_style'], $l_desk_norm['border_style']),
                'style_default' => 'solid',
                'style_options' => array(
                    'solid'  => __('Сплошная', 'genius-family-tree'),
                    'dashed' => __('Пунктирная (dashed)', 'genius-family-tree'),
                    'dotted' => __('Точечная (dotted)', 'genius-family-tree'),
                    'double' => __('Двойная (double)', 'genius-family-tree'),
                ),
                'color_name'    => $nm . '[border_color]',
                'color_value'   => $l['border_color'],
                'color_placeholder' => $pick($l['border_color'], $l_norm['border_color'], $l_desk['border_color'], $l_desk_norm['border_color']),
                'color_default' => '',
                'color_id'      => $sfx . '-border-color',
                'show_range'    => false,
            ));
            $out .= '</div>';

            $out .= '</div>';
        }
        $out .= '</div>';

        $out .= '<p class="components-base-control__help">' . esc_html__('Оформление ссылок сайдбара для этого устройства. Отступы, скругление и выравнивание задаются один раз для обоих состояний. В состоянии «При наведении» пустые значения наследуют состояние «Обычный».', 'genius-family-tree') . '</p>';
        $out .= '</div>';

        $out .= '</div>';
    }
    $out .= '</div>';

    /* ---------- Подпись: под табами устройств, табов у неё нет ---------- */
    $out .= ft_render_pms_signature_block(isset($s['desktop']['signature']) ? $s['desktop']['signature'] : array());

    return $out;
}
/**
 * Парсит CSS-скругление (напр. "8px", "8px 0 4px 12px", "50%") в массив углов
 * [top, right, bottom, left] строк-значений. Связанное значение расширяется на все углы.
 */
function ft_radius_parts($value, $fallback = '0px') {
    $value = family_tree_sanitize_str($value);
    $value = trim($value);
    if ($value === '' || $value === 'auto') {
        $value = $fallback;
    }
    $parts = preg_split('/[\s,]+/', $value);
    $parts = array_filter(array_map('trim', $parts), function ($p) {
        return $p !== '';
    });
    $parts = array_values($parts);
    $fallback_unit = '';
    if (preg_match('/(px|em|rem|%|vh|vw)$/', $fallback, $mu)) {
        $fallback_unit = $mu[1];
    }
    $normalize = function ($p) use ($fallback_unit) {
        if (preg_match('/^\d+(\.\d+)?$/', $p)) {
            return $p . ($fallback_unit !== '' ? $fallback_unit : 'px');
        }
        return $p;
    };
    $parts = array_map($normalize, $parts);
    if (count($parts) === 1) {
        return array($parts[0], $parts[0], $parts[0], $parts[0]);
    }
    if (count($parts) === 2) {
        return array($parts[0], $parts[1], $parts[0], $parts[1]);
    }
    if (count($parts) === 3) {
        return array($parts[0], $parts[1], $parts[2], $parts[1]);
    }
    while (count($parts) < 4) {
        $parts[] = $parts[0];
    }
    return array_slice($parts, 0, 4);
}
/**
 * Список стилей рамки для ft_render_corner_control() — единый для всех блоков
 * «Граница», чтобы подписи не расходились между разделами настроек.
 */
function ft_border_style_options() {
    return array(
        'solid'  => __('Сплошная', 'genius-family-tree'),
        'dashed' => __('Пунктирная (dashed)', 'genius-family-tree'),
        'dotted' => __('Точечная (dotted)', 'genius-family-tree'),
        'double' => __('Двойная (double)', 'genius-family-tree'),
    );
}
/**
 * Единый блок «Граница»: толщина, стиль и цвет одним контролом
 * (ft_render_corner_control). Обёртка для старых разделов, где рамка была
 * собрана вручную из трёх полей.
 *
 * Параметры ($args) — те же, что у ft_render_corner_control, плюс обязательные
 * name / style_name / color_name: значения приходят в опции с теми же именами,
 * поэтому обработчики сохранения менять не нужно.
 */
function ft_render_border_control($args) {
    $args = (array) $args;
    $args['label'] = isset($args['label']) ? $args['label'] : '';
    if (!isset($args['style_options']) || empty($args['style_options'])) {
        $args['style_options'] = ft_border_style_options();
    }
    if (!isset($args['style_default']) || '' === $args['style_default']) {
        $args['style_default'] = 'solid';
    }
    $args['show_range'] = false;
    return ft_render_corner_control($args);
}
/**
 * Переиспользуемый measure-контрол «как у Kadence» (собственные классы ft-*):
 * скругление углов с 4 полями, кнопкой «Связанные», выбором единиц (px/em/rem/%),
 * range-слайдером для связанного режима и кнопкой сброса.
 *
 * Параметры ($args):
 *  - id:        уникальный префикс контрола
 *  - name:      name скрытого поля (значение: CSS-строка border-radius)
 *  - value:     текущее значение (CSS-строка, напр. "8px" или "8px 0 4px 12px")
 *  - default:   значение по умолчанию (для сброса), напр. "8px"
 *  - label:     подпись
 *  - help:      пояснение
 *  - units:     массив единиц, по умолчанию ['px','em','rem','%']
 *  - max:       максимум для range/инпутов (по умолчанию 100)
 */
function ft_render_corner_control($args) {
    $args = wp_parse_args($args, array(
        'id'      => 'ft-corner',
        'name'    => '',
        'value'   => '',
        'default' => '0px',
        'label'   => '',
        'help'    => '',
        'units'        => array('px', 'em', 'rem', '%'),
        'max'          => 100,
        'link_title'   => __('Связанные углы', 'genius-family-tree'),
        'corner_icons' => array('↖', '↗', '↘', '↙'),
        'style_name'     => '',
        'style_value'    => '',
        'style_default'  => '',
        'style_options'  => array(),
        'color_name'     => '',
        'color_value'    => '',
        'color_default'  => '',
        'show_type'     => true,
        'color_id'       => '',
        // Подсказки для пустых полей (значения наследуются от Десктопа).
        'placeholder'      => '',
        'color_placeholder' => '',
        'style_placeholder' => '',
        'show_range'     => true,
        'min'            => 0,
        'reset_to_defaults' => false,
        'reset_mode'     => '',
    ));
    $id    = sanitize_html_class($args['id']);
    $value = family_tree_sanitize_str($args['value']);
    $def   = $args['default'];
    $parts = ft_radius_parts($value, $def);
    $linked = (count(array_unique($parts)) === 1);
    $unit   = 'px';
    if (preg_match('/(px|em|rem|%|vh|vw)$/', $parts[0], $mu)) {
        $unit = $mu[1];
    }
    $units = array_values((array) $args['units']);
    $uopts = '';
    foreach ($units as $u) {
        if (!in_array($u, array('px', 'em', 'rem', '%', 'vh', 'vw'), true)) {
            continue;
        }
        $uopts .= '<option value="' . esc_attr($u) . '"' . selected($unit, $u, false) . '>' . esc_html($u) . '</option>';
    }
    $num = function ($p) {
        $n = rtrim(preg_replace('/[^0-9.-]/', '', (string) $p), '.');
        return $n === '' ? '' : $n;
    };
    $corner_labels = array(
        array('data-ft-corner="top"', isset($args['corner_icons'][0]) ? $args['corner_icons'][0] : '↖'),
        array('data-ft-corner="right"', isset($args['corner_icons'][1]) ? $args['corner_icons'][1] : '↗'),
        array('data-ft-corner="bottom"', isset($args['corner_icons'][2]) ? $args['corner_icons'][2] : '↘'),
        array('data-ft-corner="left"', isset($args['corner_icons'][3]) ? $args['corner_icons'][3] : '↙'),
    );
    $corners_html = '';
    $ph_num = $num($args['placeholder']);
    $ph_attr = ('' !== $ph_num) ? ' placeholder="' . esc_attr($ph_num) . '"' : '';
    for ($i = 0; $i < 4; $i++) {
        $corners_html .= '<div class="ft-measure__corner">';
        $corners_html .= '<span class="ft-measure__corner-ico">' . $corner_labels[$i][1] . '</span>';
        $corners_html .= '<input type="number" class="ft-measure__corner-input" ' . $corner_labels[$i][0] . ' min="' . esc_attr($args['min']) . '" max="' . esc_attr($args['max']) . '" value="' . esc_attr($num($parts[$i])) . '" step="1"' . $ph_attr . ' />';
        $corners_html .= '</div>';
    }
    $reset_mode = in_array($args['reset_mode'], array('defaults', 'inherit'), true) ? $args['reset_mode'] : '';
    $out = '<div class="ft-measure ft-measure--radius' . (($args['style_name'] !== '' || $args['color_name'] !== '') ? ' ft-measure--border' : '') . '" id="' . esc_attr($id) . '" data-ft-measure data-default="' . esc_attr($def) . '"' . ('' !== $reset_mode ? ' data-ft-reset-mode="' . esc_attr($reset_mode) . '"' : (!empty($args['reset_to_defaults']) ? ' data-ft-reset-to-defaults="1"' : '')) . ($linked ? ' data-linked="1"' : '') . '>';
    $out .= '<input type="hidden" name="' . esc_attr($args['name']) . '" class="ft-measure-value" value="' . esc_attr($value) . '" />';
    if ($args['label'] !== '') {
        $out .= '<span class="components-base-control__label">' . esc_html($args['label']) . '</span>';
    }
    $out .= '<div class="ft-measure__head">';
    $out .= '<button type="button" class="ft-measure__link" title="' . esc_attr($args['link_title']) . '"' . ($linked ? ' aria-pressed="true"' : '') . '><svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="M3.9 12c0-1.71 1.39-3.1 3.1-3.1h4V7H7c-2.76 0-5 2.24-5 5s2.24 5 5 5h4v-1.9H7c-1.71 0-3.1-1.39-3.1-3.1zM8 13h8v-2H8v2zm9-6h-4v1.9h4c1.71 0 3.1 1.39 3.1 3.1s-1.39 3.1-3.1 3.1h-4V17h4c2.76 0 5-2.24 5-5s-2.24-5-5-5z"/></svg></button>';
    if ($args['show_range']) {
        $out .= '<div class="ft-measure__range-wrap">';
        $out .= '<input type="range" class="ft-measure__range" min="' . esc_attr($args['min']) . '" max="' . esc_attr($args['max']) . '" value="' . esc_attr($num($parts[0])) . '" step="1" />';
        $out .= '</div>';
    }
    $out .= '<div class="ft-measure__single"' . ($linked ? '' : ' style="display:none;"') . '>';
    $out .= '<input type="number" class="ft-measure__single-input" min="' . esc_attr($args['min']) . '" max="' . esc_attr($args['max']) . '" value="' . esc_attr($num($parts[0])) . '" step="1"' . $ph_attr . ' />';
    $out .= '</div>';
    $out .= '<div class="ft-measure__units"><select class="ft-measure__unit">' . $uopts . '</select></div>';
    if ($args['style_name'] !== '') {
        $sopts = '';
        if ('' !== $args['style_placeholder'] && '' === (string) $args['style_value']) {
            $sopts .= '<option value="" selected>' . esc_html($args['style_placeholder']) . '</option>';
        }
        foreach ((array) $args['style_options'] as $sval => $slabel) {
            $sopts .= '<option value="' . esc_attr($sval) . '"' . selected((string) $args['style_value'], (string) $sval, false) . '>' . esc_html($slabel) . '</option>';
        }
        $out .= '<select class="ft-measure__style" name="' . esc_attr($args['style_name']) . '" data-default="' . esc_attr($args['style_default']) . '">' . $sopts . '</select>';
    }
    if ($args['color_name'] !== '') {
        $color_id = $args['color_id'] !== '' ? $args['color_id'] : ($id . '-color');
        $out .= ft_render_bg_control(array(
            'id'            => $color_id,
            'color_name'    => $args['color_name'],
            'color_value'   => $args['color_value'],
            'color_default' => $args['color_default'],
            'type_name'     => $color_id . '-type',
            'type_value'    => 'classic',
            'grad_name'     => $color_id . '-gradient',
            'grad_value'    => '',
            'gtype_name'    => $color_id . '-gradient-type',
            'gtype_value'   => 'linear',
            'angle_name'    => $color_id . '-angle',
            'angle_value'   => 180,
            'show_type'     => false,
            'label'         => '',
            'help'          => '',
            'color_placeholder' => $args['color_placeholder'],
        ));
    }
    $reset_title = ($args['style_name'] !== '' || $args['color_name'] !== '') ? __('Сбросить границу', 'genius-family-tree') : __('Сбросить', 'genius-family-tree');
    $out .= '<button type="button" class="ft-measure__reset" title="' . esc_attr($reset_title) . '">' . ft_reset_icon_svg() . '</button>';
    $out .= '</div>';
    $out .= '<div class="ft-measure__corners"' . ($linked ? ' style="display:none;"' : '') . '>' . $corners_html . '</div>';
    if ($args['help'] !== '') {
        $out .= '<p class="components-base-control__help">' . esc_html($args['help']) . '</p>';
    }
    $out .= '</div>';
    return $out;
}
/**
 * Measure-контрол одиночного размера (ширина/высота) со списком единиц
 * (например %, px, vw / % , px, vh) и кнопкой сброса. Тот же JS (data-ft-measure).
 *
 * Параметры ($args):
 *  - id:      уникальный префикс контрола
 *  - name:    name скрытого поля (значение: строка "100%", "60vh" и т.п.)
 *  - value:   текущее значение
 *  - default: значение по умолчанию (для сброса)
 *  - label:   подпись
 *  - help:    пояснение
 *  - units:   массив единиц (по умолчанию ['%','px','vw'] для ширины, ['%','px','vh'] для высоты)
 *  - max:     максимум для range (по умолчанию 100)
 *  - placeholder: серый текст в пустом поле — унаследованное значение Десктопа
 */
function ft_render_size_control($args) {
    $args = wp_parse_args($args, array(
        'id'      => 'ft-size',
        'name'    => '',
        'value'   => '',
        'default' => '100%',
        'label'   => '',
        'help'    => '',
        'units'   => array('%', 'px', 'vw'),
        'max'     => 100,
        'show_range_value' => false,
        // Пустое значение не заменяем значением по умолчанию: так вкладки
        // устройств наследуют Десктоп, а унаследованное значение показывается
        // серым в placeholder. keep_empty = false — одиночный контрол.
        'placeholder' => '',
        'keep_empty'  => false,
    ));
    $id    = sanitize_html_class($args['id']);
    $value = family_tree_sanitize_str($args['value']);
    if ($value === '' && !$args['keep_empty']) {
        $value = $args['default'];
    }
    $units = array_values((array) $args['units']);
    $unit  = 'px';
    if (preg_match('/(px|%|vh|vw|em|rem)$/', $value, $mu)) {
        $unit = $mu[1];
    } elseif (preg_match('/(px|%|vh|vw|em|rem)$/', (string) $args['placeholder'], $mp)) {
        $unit = $mp[1];
    }
    $num = preg_replace('/[^0-9.]/', '', $value);
    $ph  = preg_replace('/[^0-9.]/', '', (string) $args['placeholder']);
    $ph_attr = ('' !== $ph && '' === $num) ? ' placeholder="' . esc_attr($ph) . '"' : '';
    $uopts = '';
    foreach ($units as $u) {
        if (!in_array($u, array('px', '%', 'vh', 'vw', 'em', 'rem'), true)) {
            continue;
        }
        $uopts .= '<option value="' . esc_attr($u) . '"' . selected($unit, $u, false) . '>' . esc_html($u) . '</option>';
    }
    $class = 'ft-measure ft-measure--size' . (!empty($args['show_range_value']) ? ' ft-measure--range-value' : '');
    $out = '<div class="' . esc_attr($class) . '" id="' . esc_attr($id) . '" data-ft-measure data-mode="size" data-default="' . esc_attr($args['default']) . '">';
    $out .= '<input type="hidden" name="' . esc_attr($args['name']) . '" class="ft-measure-value" value="' . esc_attr($value) . '" />';
    if ($args['label'] !== '') {
        $out .= '<span class="components-base-control__label">' . esc_html($args['label']) . '</span>';
    }
    $out .= '<div class="ft-measure__head">';
    // Значения нет — ползунок показывать нечего, оставляем только поле с
    // унаследованным числом в placeholder.
    $out .= '<div class="ft-measure__range-wrap"' . ('' === $num ? ' style="display:none;"' : '') . '>';
    $out .= '<input type="range" class="ft-measure__range" min="0" max="' . esc_attr($args['max']) . '" value="' . esc_attr($num) . '" step="1" />';
    $out .= '</div>';
    $single_style = !empty($args['show_range_value']) ? '' : ('' === $num ? '' : ' style="display:none;"');
    $out .= '<div class="ft-measure__single"' . $single_style . '>';
    $out .= '<input type="number" class="ft-measure__single-input" min="0" max="' . esc_attr($args['max']) . '" value="' . esc_attr($num) . '" step="1"' . $ph_attr . ' />';
    $out .= '</div>';
    $out .= '<div class="ft-measure__units"><select class="ft-measure__unit">' . $uopts . '</select></div>';
    $out .= '<button type="button" class="ft-measure__reset" title="' . esc_attr__('Сбросить', 'genius-family-tree') . '">' . ft_reset_icon_svg() . '</button>';
    $out .= '</div>';
    if ($args['help'] !== '') {
        $out .= '<p class="components-base-control__help">' . esc_html($args['help']) . '</p>';
    }
    $out .= '</div>';
    return $out;
}
/**
 * Группа «box-model» контролов (ширина/высота, внешние и внутренние отступы,
 * скругление углов, граница) в табах устройств: Десктоп / Планшет / Мобильные.
 * Разметка, наследование и подписи — как в сайдбаре персон.
 *
 * Планшет и Мобильные наследуют Десктоп: собственное поле пустое, в него
 * показывается унаследованное число (placeholder браузером в POST не
 * уходит), у границы — стиль и цвет с пометкой, что они взяты с Десктопа.
 *
 * Имена полей: базовые для Десктопа, с суффиксами _tablet и _mobile — для
 * Планшета и Мобильных (у границы так же суффиксуются стиль и цвет).
 *
 * Параметры ($args):
 *  - group:  уникальное имя группы табов на странице
 *  - active: устройство, открытое по умолчанию
 *  - values: array( 'desktop' => array( 'margin' => '16px', 'border-style' => 'solid' ), … )
 *  - specs:  список контролов array( ключ => аргументы ft_render_corner_control
 *            либо ft_render_size_control, см. 'type' => 'size' )
 *  - panel_content: необязательный callback, добавляющий содержимое в панели устройств
 */
function ft_render_box_device_tabs($args) {
    $args = wp_parse_args($args, array(
        'group'  => 'box',
        'active' => 'desktop',
        'values' => array(),
        'specs'  => array(),
    ));
    $vals  = (array) $args['values'];
    $out   = ft_render_device_tabs($args['group'], $args['active']);
    $out  .= '<div class="ft-device-frame" data-ft-device-frame="' . esc_attr($args['group']) . '">';
    foreach (ft_device_list() as $dev => $meta) {
        $is_desk = ('desktop' === $dev);
        $sfx     = $is_desk ? '' : '_' . $dev;
        $idf     = $is_desk ? '' : '-' . $dev;
        $out    .= '<div class="ft-device-panel" data-ft-device-panel="' . esc_attr($dev) . '"' . ($is_desk ? '' : ' style="display:none;"') . '>';
        $out    .= '<div class="ft-measure-row">';
        foreach ((array) $args['specs'] as $key => $spec) {
            $own  = isset($vals[$dev][$key]) ? (string) $vals[$dev][$key] : '';
            $desk = isset($vals['desktop'][$key]) ? (string) $vals['desktop'][$key] : '';
            $c    = (array) $spec;
            $c['id']         = $spec['id'] . $idf;
            $c['name']       = $spec['name'] . $sfx;
            $c['value']      = $own;
            $c['keep_empty'] = !$is_desk;
            if (!empty($spec['style_name'])) {
                $c['style_name']  = $spec['style_name'] . $sfx;
                $c['style_value'] = isset($vals[$dev][$key . '-style']) ? (string) $vals[$dev][$key . '-style'] : '';
            }
            if (!empty($spec['color_name'])) {
                $c['color_name']  = $spec['color_name'] . $sfx;
                $c['color_value'] = isset($vals[$dev][$key . '-color']) ? (string) $vals[$dev][$key . '-color'] : '';
                if (!empty($spec['color_id'])) {
                    $c['color_id'] = $spec['color_id'] . $idf;
                }
            }
            if (!$is_desk) {
                if ('' === $own) {
                    if ('' !== $desk) {
                        $c['default'] = $desk;
                    }
                    $c['placeholder'] = $desk;
                }
                if (!empty($spec['style_name']) && '' === $c['style_value']) {
                    $c['style_placeholder'] = isset($vals['desktop'][$key . '-style'])
                        ? (string) $vals['desktop'][$key . '-style']
                        : (string) $spec['style_default'];
                }
                if (!empty($spec['color_name']) && '' === $c['color_value']) {
                    $c['color_placeholder'] = isset($vals['desktop'][$key . '-color'])
                        ? (string) $vals['desktop'][$key . '-color']
                        : '';
                }
            }
            $out .= (!empty($spec['type']) && 'size' === $spec['type'])
                ? ft_render_size_control($c)
                : ft_render_corner_control($c);
        }
        $out .= '</div>';
        if (!$is_desk) {
            $out .= '<p class="ft-phs-inherit-note">' . esc_html__('Пустое поле наследует значение с <Десктоп>. Чтобы задать своё — введите значение.', 'genius-family-tree') . '</p>';
        }
        if (isset($args['panel_content']) && is_callable($args['panel_content'])) {
            $out .= call_user_func($args['panel_content'], $dev);
        }
        $out .= '</div>';
    }
    $out .= '</div>';
    return $out;
}

/**
 * Настройки тени карточек альбомов для выбранного устройства.
 *
 * @param array  $settings настройки плагина
 * @param string $device   desktop / tablet / mobile
 */
function ft_render_album_display_shadow_controls($settings, $device) {
    $suffix = ('desktop' === $device) ? '' : '_' . $device;
    ob_start();
    ?>
    <div class="ft-album-shadow-device-controls">
        <?php $group = 'album-display-shadow-' . $device; ?>
        <div class="ft-state-cell" data-state="normal">
            <div class="ft-layout-tabs ft-state-tabs" data-state-group="<?php echo esc_attr($group); ?>">
                <label class="ft-layout-tab">
                    <input type="radio" name="<?php echo esc_attr($group); ?>-state" value="normal" checked />
                    <span><?php echo esc_html__('Обычный', 'genius-family-tree'); ?></span>
                </label>
                <label class="ft-layout-tab">
                    <input type="radio" name="<?php echo esc_attr($group); ?>-state" value="hover" />
                    <span><?php echo esc_html__('При наведении', 'genius-family-tree'); ?></span>
                </label>
            </div>
            <?php foreach (array('normal' => '', 'hover' => '_hover') as $state => $state_suffix):
                $shadow_key = ('normal' === $state) ? 'display_shadow' : 'display_hover_shadow';
                $checked = ('desktop' === $device)
                    ? !empty($settings[$shadow_key])
                    : (isset($settings[$shadow_key . $suffix]) ? !empty($settings[$shadow_key . $suffix]) : !empty($settings[$shadow_key]));
                $shadow_id = 'ft-album-display-shadow-' . $device . $state;
                ?>
                <div class="components-base-control ft-album-shadow-control">
                    <div class="ft-state-group" data-state-group="<?php echo esc_attr($group); ?>" data-group-state="<?php echo esc_attr($state); ?>">
                        <label>
                            <input type="checkbox" class="ft-album-shadow-toggle" name="<?php echo esc_attr('family_tree_album_' . $shadow_key . $suffix); ?>" id="<?php echo esc_attr($shadow_id); ?>" value="1" <?php checked($checked); ?> />
                            <?php echo esc_html__('Тень карточек', 'genius-family-tree'); ?>
                        </label>
                        <div class="ft-album-shadow-options" style="display:<?php echo $checked ? 'block' : 'none'; ?>;margin-top:12px;">
                            <div class="ft-phs-row ft-album-shadow-controls">
                                <?php
                                $shadow_fields = array(
                                    'color' => array(__('Цвет', 'genius-family-tree'), 'text', 'rgba(0, 0, 0, 0.12)'),
                                    'x' => array(__('Сдвиг X', 'genius-family-tree'), 'number', '0'),
                                    'y' => array(__('Сдвиг Y', 'genius-family-tree'), 'number', ('normal' === $state ? '4' : '6')),
                                    'blur' => array(__('Размытие', 'genius-family-tree'), 'number', ('normal' === $state ? '14' : '16')),
                                    'spread' => array(__('Распространение', 'genius-family-tree'), 'number', '0'),
                                );
                                foreach ($shadow_fields as $field_key => $field_meta):
                                    $setting = $shadow_key . '_' . $field_key;
                                    $value = isset($settings[$setting . $suffix]) ? $settings[$setting . $suffix] : $settings[$setting];
                                    $min = ('color' === $field_key) ? '' : ('spread' === $field_key ? '-100' : ('x' === $field_key || 'y' === $field_key ? '-200' : '0'));
                                    $max = ('color' === $field_key) ? '' : ('spread' === $field_key ? '100' : '200');
                                    $name = 'family_tree_album_' . $setting . $suffix;
                                    $input_id = $shadow_id . '-' . $field_key;
                                    ?>
                                    <?php if ('color' === $field_key): ?>
                                        <?php
                                        echo ft_render_phs_cell(
                                            $field_meta[0],
                                            ft_render_color_field($name, $input_id, $value, $field_meta[2]),
                                            'ft-phs-cell--color ft-album-shadow-field--color'
                                        );
                                        ?>
                                    <?php else: ?>
                                        <?php
                                        echo ft_render_phs_cell(
                                            $field_meta[0],
                                            '<input type="number" name="' . esc_attr($name) . '" id="' . esc_attr($input_id) . '" value="' . esc_attr($value) . '" data-ft-reset-value="' . esc_attr($field_meta[2]) . '" class="small-text" min="' . esc_attr($min) . '" max="' . esc_attr($max) . '" />',
                                            'ft-album-shadow-field'
                                        );
                                        ?>
                                    <?php endif; ?>
                                <?php endforeach; ?>
                                <?php
                                echo ft_render_phs_reset_cell(
                                    '#' . $shadow_id . '-color-ctrl, #' . $shadow_id . '-x, #' . $shadow_id . '-y, #' . $shadow_id . '-blur, #' . $shadow_id . '-spread'
                                );
                                ?>
                            </div>
                        </div>
                    </div>
                </div>
            <?php endforeach; ?>
        </div>
    </div>
    <?php
    return ob_get_clean();
}
/**
 * Значение параметра для устройства с откатом на Десктоп: пустое поле Планшета
 * или Мобильных наследует базовое значение.
 *
 * @param array  $values значения по устройствам
 * @param string $dev    desktop / tablet / mobile
 * @param string $key    ключ значения
 */
function ft_device_value($values, $dev, $key) {
    if (!empty($values[$dev][$key])) {
        return (string) $values[$dev][$key];
    }
    return isset($values['desktop'][$key]) ? (string) $values['desktop'][$key] : '';
}
/**
 * CSS для группы «box-model» с табами устройств: базовые правила для Десктопа
 * и @media-правила для Планшета (≤1024px) и Мобильных (≤767px) — если для них
 * есть собственные значения.
 *
 * @param string   $selector CSS-селектор блока
 * @param array    $values   значения по устройствам
 * @param callable $emit     функция( array $values, string $dev ): string —
 *                          декларации для устройства; $values содержит все
 *                          устройства, поэтому ft_device_value() наследует
 *                          пустые значения с Десктопа
 */
function ft_box_device_css($selector, $values, $emit) {
    $rules = '';
    foreach (array('desktop', 'tablet', 'mobile') as $dev) {
        if ('desktop' !== $dev && empty($values[$dev])) {
            continue;
        }
        $inner = trim((string) call_user_func($emit, (array) $values, $dev));
        if ('' === $inner) {
            continue;
        }
        if ('desktop' === $dev) {
            $rules .= $selector . ' { ' . $inner . ' }';
            continue;
        }
        $media = ft_device_media($dev);
        if ('' === $media) {
            $rules .= $selector . ' { ' . $inner . ' }';
        } else {
            $rules .= '@media (' . $media . ') { ' . $selector . ' { ' . $inner . ' } }';
        }
    }
    return $rules;
}
/**
 * CSS-значение для скругления: нормализует число в px и приводит 4 равных угла к одному.
 */
function ft_radius_css($value, $fallback = '0px') {
    $value = family_tree_sanitize_str($value);
    if ($value === '' || $value === 'auto') {
        return '';
    }
    $parts = ft_radius_parts($value, $fallback);
    while (count($parts) > 1 && end($parts) === $parts[0]) {
        array_pop($parts);
    }
    return implode(' ', $parts);
}
/**
 * Минимальная эффективная толщина для CSS double — не менее 3px, иначе
 * браузеры отображают двойную линию как сплошную.
 */
function ft_border_width_css($width, $style, $fallback = '1px') {
    $width = ft_radius_css($width, $fallback);
    if ('double' !== $style || '' === $width) {
        return $width;
    }
    $parts = ft_radius_parts($width, $fallback);
    $widths = array();
    foreach ($parts as $part) {
        $widths[] = 'max(3px, ' . $part . ')';
    }
    while (count($widths) > 1 && $widths[count($widths) - 1] === $widths[0]) {
        array_pop($widths);
    }
    return implode(' ', $widths);
}
/**
 * CSS-правила для алфавитного указателя семейного архива (единый шаблон archive-section.php).
 * Настройки применяются ко всем разделам сразу.
 *
 * @param array $s настройки (ft_get_archive_catalog_settings()).
 * @return string CSS-строкa (без <style>).
 */
if (!function_exists('ft_archive_catalog_css')) {
    function ft_archive_catalog_css($s = null) {
        if (null === $s || !is_array($s)) {
            $s = ft_get_archive_catalog_settings();
        }
        $css = '';

        // === Контейнер ===
        $ft_ac_bg_list = !empty($s['container_bg_list']) ? esc_html($s['container_bg_list']) : 'transparent';
        if ('gradient' === $s['container_bg_list_type'] && !empty($s['container_bg_list_gradient'])) {
            $css .= '.family-archive-catalog{background-image:' . esc_html($s['container_bg_list_gradient']) . '!important;background-color:' . $ft_ac_bg_list . '!important;}';
        } else {
            $css .= '.family-archive-catalog{background:' . $ft_ac_bg_list . '!important;}';
        }
        $ft_ac_bg_list_hover = !empty($s['container_bg_list_hover']) ? esc_html($s['container_bg_list_hover']) : 'transparent';
        if ('gradient' === $s['container_bg_list_hover_type'] && !empty($s['container_bg_list_hover_gradient'])) {
            $css .= '.family-archive-catalog:hover{background-image:' . esc_html($s['container_bg_list_hover_gradient']) . '!important;background-color:' . $ft_ac_bg_list_hover . '!important;}';
        } else {
            $css .= '.family-archive-catalog:hover{background:' . $ft_ac_bg_list_hover . '!important;}';
        }
        $ft_ac_bg_block = !empty($s['container_bg_block']) ? esc_html($s['container_bg_block']) : 'transparent';
        if ('gradient' === $s['container_bg_block_type'] && !empty($s['container_bg_block_gradient'])) {
            $css .= '.family-archive-catalog .ft-archive-letters,.family-archive-catalog .ft-archive-letter-block{background-image:' . esc_html($s['container_bg_block_gradient']) . '!important;background-color:' . $ft_ac_bg_block . '!important;}';
        } else {
            $css .= '.family-archive-catalog .ft-archive-letters,.family-archive-catalog .ft-archive-letter-block{background:' . $ft_ac_bg_block . '!important;}';
        }
        $ft_ac_bg_block_hover = !empty($s['container_bg_block_hover']) ? esc_html($s['container_bg_block_hover']) : 'transparent';
        if ('gradient' === $s['container_bg_block_hover_type'] && !empty($s['container_bg_block_hover_gradient'])) {
            $css .= '.family-archive-catalog .ft-archive-letters:hover,.family-archive-catalog .ft-archive-letter-block:hover{background-image:' . esc_html($s['container_bg_block_hover_gradient']) . '!important;background-color:' . $ft_ac_bg_block_hover . '!important;}';
        } else {
            $css .= '.family-archive-catalog .ft-archive-letters:hover,.family-archive-catalog .ft-archive-letter-block:hover{background:' . $ft_ac_bg_block_hover . '!important;}';
        }

        // === Контейнер: скругление, обводка, отступы ===
        if (!empty($s['container_radius']) || (!empty($s['container_border_width']) && !empty($s['container_border_color'])) || !empty($s['container_padding'])) {
            $css .= '.family-archive-catalog{';
            if (!empty($s['container_radius'])) {
                $css .= 'border-radius:' . ft_radius_css($s['container_radius'], '0px') . '!important;';
            }
            if (!empty($s['container_border_width']) && !empty($s['container_border_color'])) {
                $css .= 'border:' . esc_html(ft_border_width_css(absint($s['container_border_width']) . 'px', $s['container_border_style'])) . ' ' . esc_html($s['container_border_style']) . ' ' . esc_html($s['container_border_color']) . '!important;';
            }
            if (!empty($s['container_padding']) || '0' === (string) $s['container_padding']) {
