        if (!empty($s['container_border_color_hover'])) {
            $css .= '.family-archive-catalog:hover{border-color:' . esc_html($s['container_border_color_hover']) . '!important;}';
        }

        // === Блоки: скругление, обводка, отступы ===
        $ft_archive_block_sel = '.family-archive-catalog .ft-archive-letters,.family-archive-catalog .ft-archive-letter-block';
        if (!empty($s['block_radius']) || (!empty($s['block_border_width']) && !empty($s['block_border_color'])) || !empty($s['block_padding']) || '0' === (string) $s['block_padding']) {
