            }
            if (!empty($s['avatar_radius'])) {
                $css .= 'border-radius:' . ft_radius_css($s['avatar_radius'], '50%') . '!important;';
            }
            if (!empty($s['avatar_padding'])) {
                $css .= 'padding:' . esc_html(absint($s['avatar_padding'])) . 'px!important;';
            }
            $css .= '}';
            $css .= '.ft-archive-person-card .ft-avatar img{border-radius:inherit!important;}';
        }

        // === Карточка персоналии ===
        $ft_card_border = '';
        if (!empty($s['card_border_color'])) {
            $ft_card_style = in_array($s['card_border_style'], array('solid', 'dashed', 'dotted', 'double'), true) ? $s['card_border_style'] : 'solid';
            $ft_card_border = 'border-style:' . esc_html($ft_card_style) . '!important;';
            $ft_card_border .= 'border-width:' . esc_html(ft_border_width_css(intval($s['card_border_width']) . 'px', $ft_card_style)) . '!important;';
            $ft_card_border .= 'border-color:' . esc_html($s['card_border_color']) . '!important;';
        }
        if (!empty($s['card_bg']) || !empty($ft_card_border) || !empty($s['card_radius'])) {
            $css .= '.ft-archive-person-card{';
            if (!empty($s['card_bg'])) {
                $css .= 'background:' . esc_html($s['card_bg']) . '!important;';
            }
            if (!empty($ft_card_border)) {
                $css .= $ft_card_border;
            }
            if (!empty($s['card_radius']) && intval($s['card_radius']) >= 0) {
                $css .= 'border-radius:' . ft_radius_css($s['card_radius'], '8px') . '!important;';
            }
            $css .= '}';
        }
        if (!empty($s['card_bg_hover']) || !empty($s['card_border_color_hover'])) {
            $css .= '.ft-archive-person-card:hover{';
            if (!empty($s['card_bg_hover'])) {
                $css .= 'background:' . esc_html($s['card_bg_hover']) . '!important;';
            }
            if (!empty($s['card_border_color_hover'])) {
                $css .= 'border-color:' . esc_html($s['card_border_color_hover']) . '!important;';
            }
            $css .= '}';
        }
        return $css;
    }
}
if (!function_exists('ft_archive_catalog_layout_css')) {
    function ft_archive_catalog_layout_css($container_selector = '.family-archive-catalog', $blocks_selector = '') {
        $plugin = Family_Tree_Plugin::get_instance();
        if ('' === $blocks_selector) {
            $blocks_selector = $container_selector . ' .ft-archive-letters,' . $container_selector . ' .ft-archive-letter-block';
        }
        $container_values = $plugin->ft_get_box_devices(array(
            'margin' => 'family_tree_catalog_container_margin',
            'padding' => 'family_tree_catalog_container_padding',
            'radius' => 'family_tree_catalog_container_radius',
            'border-width' => 'family_tree_catalog_container_border_width',
            'border-style' => 'family_tree_catalog_container_border_style',
            'border-color' => 'family_tree_catalog_container_border_color',
        ));
        $blocks_values = $plugin->ft_get_box_devices(array(
            'margin' => 'family_tree_catalog_blocks_margin',
            'padding' => 'family_tree_catalog_blocks_padding',
            'radius' => 'family_tree_catalog_blocks_radius',
            'border-width' => 'family_tree_catalog_blocks_border_width',
            'border-style' => 'family_tree_catalog_blocks_border_style',
            'border-color' => 'family_tree_catalog_blocks_border_color',
        ));
        $css = '';
        $container_bg = get_option('family_tree_catalog_page_bg', '');
        $container_bg_type = get_option('family_tree_catalog_page_bg_type', 'classic');
        $container_bg_gradient = get_option('family_tree_catalog_page_bg_gradient', '');
        $container_bg_image = get_option('family_tree_catalog_page_bg_image', '');
        $container_bg_rules = '';
        if (!empty($container_bg_image)) {
            $container_bg_rules .= 'background-image:url("' . esc_url($container_bg_image) . '")!important;background-size:cover!important;background-position:center center!important;background-repeat:no-repeat!important;';
        }
        if ('gradient' === $container_bg_type && !empty($container_bg_gradient)) {
            $container_bg_rules .= 'background-image:' . esc_html($container_bg_gradient) . '!important;';
        }
        if (!empty($container_bg)) {
            $container_bg_rules .= 'background-color:' . esc_html($container_bg) . '!important;';
        }
        if ('' !== $container_bg_rules) {
            $css .= $container_selector . '{' . $container_bg_rules . '}';
        }
        $blocks_bg = get_option('family_tree_catalog_bg', '');
        $blocks_bg_type = get_option('family_tree_catalog_bg_type', 'classic');
        $blocks_bg_gradient = get_option('family_tree_catalog_bg_gradient', '');
        $blocks_bg_image = get_option('family_tree_catalog_bg_image', '');
        $blocks_bg_rules = '';
        if (!empty($blocks_bg_image)) {
            $blocks_bg_rules .= 'background-image:url("' . esc_url($blocks_bg_image) . '")!important;background-size:cover!important;background-position:center center!important;background-repeat:no-repeat!important;';
        }
        if ('gradient' === $blocks_bg_type && !empty($blocks_bg_gradient)) {
            $blocks_bg_rules .= 'background-image:' . esc_html($blocks_bg_gradient) . '!important;';
        }
        if (!empty($blocks_bg)) {
            $blocks_bg_rules .= 'background-color:' . esc_html($blocks_bg) . '!important;';
        }
        if ('' !== $blocks_bg_rules) {
            $css .= $blocks_selector . '{' . $blocks_bg_rules . '}';
        }
        $border_style = function ($value) {
            return in_array($value, array('solid', 'dashed', 'dotted', 'double'), true) ? $value : 'solid';
        };
        $has_border = function ($width, $color) {
            return !empty($width) && !empty($color);
        };
        foreach (array(
            $container_selector => $container_values,
            $blocks_selector => $blocks_values,
        ) as $selector => $values) {
            $css .= ft_box_device_css($selector, $values, function ($v, $dev) use ($border_style, $has_border) {
                $margin = ft_device_value($v, $dev, 'margin');
                $padding = ft_device_value($v, $dev, 'padding');
                $radius = ft_device_value($v, $dev, 'radius');
                $border_width = ft_device_value($v, $dev, 'border-width');
                $border_color = ft_device_value($v, $dev, 'border-color');
                if ('' === $margin && '' === $padding && '' === $radius && !$has_border($border_width, $border_color)) {
                    return '';
                }
                $rules = (!empty($padding) || !empty($border_width)) ? 'box-sizing:border-box;' : '';
                if (!empty($margin)) {
                    $rules .= 'margin:' . esc_attr(ft_radius_css($margin, '16px')) . '!important;';
                }
                if (!empty($padding)) {
                    $rules .= 'padding:' . esc_attr(ft_radius_css($padding, '16px')) . '!important;';
                }
                if (!empty($radius)) {
                    $rules .= 'border-radius:' . esc_attr(ft_radius_css($radius, '0px')) . '!important;';
                }
                if ($has_border($border_width, $border_color)) {
                    $rules .= 'border:' . esc_attr(ft_border_width_css($border_width, $border_style(ft_device_value($v, $dev, 'border-style')))) . ' ' . esc_attr($border_style(ft_device_value($v, $dev, 'border-style'))) . ' ' . esc_html($border_color) . '!important;';
                }
                return $rules;
            });
        }
        return $css;
    }
}
if (!function_exists('ft_catalog_alphabet_button_css')) {
    function ft_catalog_alphabet_button_css() {
        $css = '';
        $legacy_text_settings = array(
            'normal' => array(
                'color' => 'family_tree_catalog_letter_text_color',
            ),
            'active' => array(
                'color' => 'family_tree_catalog_letter_text_active',
            ),
            'hover' => array(
                'color' => 'family_tree_catalog_letter_text_active',
            ),
        );
        $states = array(
            'normal' => array(
                'selector' => '.family-tree-surname-catalog .alphabet-letter a',
                'text_selector' => '.family-tree-surname-catalog .alphabet-letter a,.family-tree-surname-catalog .alphabet-letter span',
                'bg' => 'family_tree_catalog_letter_bg_normal',
                'suffix' => 'normal',
            ),
            'active' => array(
                'selector' => '.family-tree-surname-catalog .alphabet-letter.active a',
                'text_selector' => '.family-tree-surname-catalog .alphabet-letter.active a',
                'bg' => 'family_tree_catalog_letter_bg',
                'suffix' => 'active',
            ),
            'hover' => array(
                'selector' => '.family-tree-surname-catalog .alphabet-letter.active a:hover',
                'text_selector' => '.family-tree-surname-catalog .alphabet-letter.active a:hover',
                'bg' => 'family_tree_catalog_letter_bg_hover',
                'suffix' => 'hover',
            ),
        );
        foreach ($states as $state => $config) {
            $color = get_option($config['bg'], '');
            $bg_type = get_option('family_tree_catalog_letter_bg_type_' . $config['suffix'], 'classic');
            $gradient = get_option('family_tree_catalog_letter_bg_gradient_' . $config['suffix'], '');
            $image = get_option('family_tree_catalog_letter_bg_image_' . $config['suffix'], '');
            $border_width = get_option('family_tree_catalog_letter_border_width_' . $state, '');
            $border_style = get_option('family_tree_catalog_letter_border_style_' . $state, '');
            $border_color = get_option('family_tree_catalog_letter_border_color_' . $state, '');
            $rules = '';
            if ('gradient' === $bg_type && !empty($gradient)) {
                $rules .= 'background-image:' . esc_html($gradient) . '!important;';
                $rules .= 'background-color:' . esc_html('' !== $color ? $color : 'transparent') . '!important;';
            } elseif (!empty($image)) {
                $rules .= 'background-image:url("' . esc_url($image) . '")!important;background-size:cover!important;background-position:center center!important;background-repeat:no-repeat!important;';
                if (!empty($color)) {
                    $rules .= 'background-color:' . esc_html($color) . '!important;';
                }
            } elseif (!empty($color)) {
                $rules .= 'background:' . esc_html($color) . '!important;';
            }
            if ('' !== (string) $border_width || '' !== (string) $border_color || '' !== (string) $border_style) {
                $border_style = in_array($border_style, array('solid', 'dashed', 'dotted', 'double'), true) ? $border_style : 'solid';
                if ('' !== (string) $border_width && '' !== (string) $border_color) {
                    $rules .= 'border:' . esc_html(ft_border_width_css($border_width, $border_style)) . ' ' . esc_html($border_style) . ' ' . esc_html($border_color) . '!important;';
                } else {
                    if ('' !== (string) $border_width) {
                        $rules .= 'border-width:' . esc_html(ft_border_width_css($border_width, $border_style)) . '!important;';
                    } elseif ('double' === $border_style) {
                        $rules .= 'border-width:3px!important;';
                    }
                    $rules .= 'border-style:' . esc_html($border_style) . '!important;';
                    if ('' !== (string) $border_color) {
                        $rules .= 'border-color:' . esc_html($border_color) . '!important;';
                    }
                }
            }
            $legacy_color = isset($legacy_text_settings[$state]['color']) ? get_option($legacy_text_settings[$state]['color'], '') : '';
            $text_color = get_option('family_tree_catalog_letter_text_color_' . $state, $legacy_color);
            $font_family = get_option('family_tree_catalog_letter_font_family_' . $state, get_option('family_tree_catalog_letter_font_family', ''));
            $font_size = get_option('family_tree_catalog_letter_font_size_' . $state, get_option('family_tree_catalog_letter_font_size', 0));
            $font_weight = get_option('family_tree_catalog_letter_font_weight_' . $state, get_option('family_tree_catalog_letter_font_weight', 0));
            $text_rules = '';
            if ('' !== (string) $text_color) {
                $text_rules .= 'color:' . esc_html($text_color) . '!important;';
            }
            if ('' !== (string) $font_family) {
                $text_rules .= 'font-family:\'' . esc_attr($font_family) . '\',serif!important;';
            }
            if ((int) $font_size > 0) {
                $text_rules .= 'font-size:' . (int) $font_size . 'px!important;';
            }
            if ((int) $font_weight > 0) {
                $text_rules .= 'font-weight:' . (int) $font_weight . '!important;';
            }
            if ('' !== $rules) {
                $css .= $config['selector'] . '{' . $rules . '}';
            }
            if ('' !== $text_rules) {
                $css .= $config['text_selector'] . '{' . $text_rules . '}';
            }
        }
        $plugin = Family_Tree_Plugin::get_instance();
        $values = $plugin->ft_get_box_devices(array(
            'gap' => 'family_tree_catalog_letter_gap',
            'padding' => 'family_tree_catalog_letter_padding',
            'radius' => 'family_tree_catalog_letter_radius',
        ));
        $css .= ft_box_device_css('.family-tree-surname-catalog .alphabet-list', $values, function ($v, $dev) {
            $gap = ft_device_value($v, $dev, 'gap');
            return !empty($gap) ? 'gap:' . esc_attr($gap) . '!important;' : '';
        });
        $css .= ft_box_device_css('.family-tree-surname-catalog .alphabet-letter a,.family-tree-surname-catalog .alphabet-letter span', $values, function ($v, $dev) {
            $padding = ft_device_value($v, $dev, 'padding');
            $radius = ft_device_value($v, $dev, 'radius');
            $rules = '';
            if (!empty($padding)) {
                $rules .= 'padding:' . esc_attr(ft_radius_css($padding, '10px')) . '!important;';
            }
            if (!empty($radius)) {
                $rules .= 'border-radius:' . esc_attr(ft_radius_css($radius, '6px')) . '!important;';
            }
            return $rules;
        });
        return $css;
    }
}
if (!function_exists('ft_render_catalog_text_settings')) {
    function ft_render_catalog_text_settings($fields, $fonts, $google_fonts, $help) {
        $out = '<div class="components-base-control"><div class="ft-phs-row">';
        $out .= ft_render_phs_cell(
            __('Цвет', 'genius-family-tree'),
            ft_render_color_field($fields['color_name'], $fields['color_id'], $fields['color'], '#1d2327'),
            'ft-phs-cell--color'
        );
        $out .= ft_render_phs_cell(
            __('Шрифт', 'genius-family-tree'),
            ft_render_font_select($fields['font_name'], $fields['font_id'], $fields['font'], $fonts, $google_fonts)
        );
        $out .= ft_render_phs_cell(
            __('Размер', 'genius-family-tree'),
            ft_render_size_field($fields['size_name'], $fields['size_id'], $fields['size']),
            'ft-phs-cell--size'
        );
        $out .= ft_render_phs_cell(
            __('Толщина', 'genius-family-tree'),
            ft_render_weight_select($fields['weight_name'], $fields['weight_id'], $fields['font'], $fields['weight'], $fields['font_id'])
        );
        $reset_selectors = '#' . $fields['color_id'] . ', #' . $fields['font_id'] . ', #' . $fields['size_id'] . ', #' . $fields['weight_id'];
        if (isset($fields['underline_name'], $fields['underline_id'], $fields['underline'])) {
            $out .= ft_render_phs_cell(
                __('Подчёркивание', 'genius-family-tree'),
                ft_render_phs_underline_select($fields['underline_name'], $fields['underline_id'], $fields['underline'])
            );
            $reset_selectors .= ', #' . $fields['underline_id'];
        }
        $out .= ft_render_phs_reset_cell($reset_selectors);
        $out .= '</div><p class="components-base-control__help">' . esc_html($help) . '</p></div>';
        return $out;
    }
}
