/**
 * Актуальные настройки страницы «Альбомы персоналий» (дефолты + сохранённые).
 *
 * @param bool $force Пропустить статический кэш и перечитать из БД.
 * @return array
 */
function ft_get_person_albums_settings($force = false) {
    static $cache = null;
    if (null === $cache || $force) {
        $defaults = ft_get_person_albums_defaults();
        $saved = get_option('family_tree_person_albums_settings', array());
        if (!is_array($saved)) {
            $saved = array();
        }
        $cache = array_merge($defaults, $saved);
    }
    return $cache;
}
