        'back_hover_border_style' => 'solid',
        'back_hover_border_color' => '',
        'back_hover_color' => '',
        // === Другие фотографии альбома (ft-photo-page__others) ===
        'thumbs_min_width' => 110,
        'thumbs_height' => 85,
        'thumbs_gap' => 10,
        'thumbs_radius' => 8,
        'thumbs_border_width' => 2,
        'thumbs_border_style' => 'solid',
        'thumbs_border_color' => 'transparent',
        'thumbs_active_border_width' => 2,
    'thumbs_active_border_style' => 'solid',
    'thumbs_active_border_color' => '#5b7745',
        'thumb_title_bg' => 'rgba(60, 73, 56, 0.85)',
        'thumb_title_color' => '#ffffff',
        'thumb_title_font_family' => '',
        'thumb_title_font_weight' => 0,
        'thumb_title_font_size' => 11,
        'thumb_title_padding_y' => 4,
        'thumb_title_padding_x' => 6,
    );
}
/**
 * Актуальные настройки страницы отдельной фотографии (дефолты + сохранённые).
 *
 * @param bool $force Пропустить статический кэш и перечитать из БД.
 * @return array
 */
function ft_get_photo_page_settings($force = false) {
    static $cache = null;
    if (null === $cache || $force) {
        $defaults = ft_get_photo_page_defaults();
        $saved = get_option('family_tree_photo_page_settings', array());
        if (!is_array($saved)) {
            $saved = array();
        }
        $cache = array_merge($defaults, $saved);
    }
    return $cache;
}
/**
 * CSS-стили страницы отдельной фотографии (контейнеры, фото, текст, «Кто на фото», кнопка «К папке», другие фото).
 *
 * @param array|null $s Настройки страницы отдельной фотографии.
 * @return string
 */
function ft_photo_page_css($s = null) {
    if (null === $s || !is_array($s)) {
        $s = ft_get_photo_page_settings();
    }
    $css = '';
    $ft_bs = function ($v) {
        return in_array($v, array('solid', 'dashed', 'dotted', 'double'), true) ? $v : 'solid';
    };
    $ft_font = function ($family) {
        return '' !== trim((string) $family) ? 'font-family:\'' . esc_html($family) . '\', serif!important;' : '';
    };

    // === Контейнеры (фото, текст, «Другие фотографии») ===
    $container_rule = '';
    if (intval($s['container_margin_top']) > 0) {
        $css .= '.ft-photo-page__body{margin-top:' . intval($s['container_margin_top']) . 'px!important;}';
    }
    if (intval($s['container_margin_bottom']) > 0) {
        $css .= '.ft-photo-page__others{margin-bottom:' . intval($s['container_margin_bottom']) . 'px!important;}';
    }
if (!empty($s['container_bg']) || ('gradient' === $s['container_bg_type'] && !empty($s['container_bg_gradient']))) {
        if ('gradient' === $s['container_bg_type'] && !empty($s['container_bg_gradient'])) {
            $container_rule .= 'background-image:' . esc_html($s['container_bg_gradient']) . '!important;background-color:' . ('' !== $s['container_bg'] ? esc_html($s['container_bg']) : 'transparent') . '!important;';
        } else {
            $container_rule .= 'background:' . esc_html($s['container_bg']) . '!important;';
        }
    }
    if (intval($s['container_radius']) > 0) {
$container_rule .= 'border-radius:' . ft_radius_css($s['container_radius'], '0px') . '!important;';
    }
    if (!empty($s['container_border_width']) || !empty($s['container_border_color'])) {
        $container_rule .= 'border:' . ft_border_width_css(max(1, intval($s['container_border_width'])) . 'px', $ft_bs($s['container_border_style'])) . ' ' . $ft_bs($s['container_border_style']) . ' ' . esc_html(!empty($s['container_border_color']) ? $s['container_border_color'] : '#dcdcde') . '!important;';
    }
    if ('' !== $s['container_padding'] && intval($s['container_padding']) > 0) {
        $container_rule .= 'padding:' . intval($s['container_padding']) . 'px!important;';
    }
    if ('' !== $container_rule) {
        $css .= '.ft-photo-page__media,.ft-photo-page__content,.ft-photo-page__others{' . $container_rule . '}';
    }

    // === Фотография (ft-photo-page__media) ===
    $media_rule = '';
    if ('10px' !== ft_radius_css($s['media_radius'], '10px')) {
        $media_rule .= 'border-radius:' . ft_radius_css($s['media_radius'], '10px') . '!important;';
    }
    if (!empty($s['media_border_width']) || !empty($s['media_border_color'])) {
        $media_rule .= 'border:' . ft_border_width_css(max(1, intval($s['media_border_width'])) . 'px', $ft_bs($s['media_border_style'])) . ' ' . $ft_bs($s['media_border_style']) . ' ' . esc_html(!empty($s['media_border_color']) ? $s['media_border_color'] : '#dcdcde') . '!important;';
    }
    if ('' !== $media_rule) {
        $css .= '.ft-photo-page__img-link{' . $media_rule . '}';
        $css .= '.ft-photo-page__img{border-radius:' . ft_radius_css($s['media_radius'], '10px') . '!important;}';
    }

    // === Текст (ft-photo-page__content) ===
    $text_rule = $ft_font($s['text_font_family']);
    if (!empty($s['text_color'])) {
        $text_rule .= 'color:' . esc_html($s['text_color']) . '!important;';
    }
    if (intval($s['text_font_size']) > 0) {
        $text_rule .= 'font-size:' . intval($s['text_font_size']) . 'px!important;';
    }
    if (intval($s['text_font_weight']) > 0) {
        $text_rule .= 'font-weight:' . intval($s['text_font_weight']) . '!important;';
    }
    if ('' !== $text_rule) {
        $css .= '.ft-photo-page__desc{' . $text_rule . '}';
    }
    // Метки «Дата съемки:», «Место съемки:», «Кто на фото:» — шрифт как у описания, но всегда жирные
    $label_rule = $ft_font($s['text_font_family']);
    if (!empty($s['text_color'])) {
        $label_rule .= 'color:' . esc_html($s['text_color']) . '!important;';
    }
    if (intval($s['text_font_size']) > 0) {
        $label_rule .= 'font-size:' . intval($s['text_font_size']) . 'px!important;';
    }
    if ('' !== $label_rule) {
        $css .= '.ft-photo-page__people-title,.ft-photo-page__meta-label{' . $label_rule . 'font-weight:600!important;}';
        $css .= '.ft-photo-page__meta-value{' . $label_rule . '}';
    }

    // === «Кто на фото»: кнопка персоналии ===
    $person_rule = '';
    if (!empty($s['person_bg']) && 'rgba(250, 245, 232, 0.7)' !== $s['person_bg']) {
        $person_rule .= 'background:' . esc_html($s['person_bg']) . '!important;';
    }
    if (!empty($s['person_color']) && '#3c4938' !== strtolower($s['person_color'])) {
        $person_rule .= 'color:' . esc_html($s['person_color']) . '!important;';
    }
    if ('20px' !== ft_radius_css($s['person_radius'], '20px')) {
        $person_rule .= 'border-radius:' . ft_radius_css($s['person_radius'], '20px') . '!important;';
    }
    if (!empty($s['person_border_width']) || !empty($s['person_border_color'])) {
        $person_rule .= 'border:' . ft_border_width_css(max(1, intval($s['person_border_width'])) . 'px', $ft_bs($s['person_border_style'])) . ' ' . $ft_bs($s['person_border_style']) . ' ' . esc_html(!empty($s['person_border_color']) ? $s['person_border_color'] : '#e5dcc3') . '!important;';
    }
    if (7 !== intval($s['person_padding_y']) || 14 !== intval($s['person_padding_x'])) {
        $person_rule .= 'padding:' . intval($s['person_padding_y']) . 'px ' . intval($s['person_padding_x']) . 'px!important;';
    }
    $person_rule .= $ft_font($s['person_font_family']);
    if (intval($s['person_font_weight']) > 0) {
        $person_rule .= 'font-weight:' . intval($s['person_font_weight']) . '!important;';
    }
    if (intval($s['person_font_size']) > 0 && 14 !== intval($s['person_font_size'])) {
        $person_rule .= 'font-size:' . intval($s['person_font_size']) . 'px!important;';
    }
    if ('' !== $person_rule) {
        $css .= '.ft-photo-page__person{' . $person_rule . '}';
    }
    $person_hover_rule = '';
    if (!empty($s['person_hover_bg']) && 'rgba(250, 245, 232, 1)' !== $s['person_hover_bg']) {
