    }
    if ('' !== $person_hover_rule) {
        $css .= '.ft-photo-page__person:hover{' . $person_hover_rule . '}';
    }

    // === «Кто на фото»: список персоналий ===
    if (8 !== intval($s['people_gap'])) {
