    }
    if (20 !== intval($s['person_num_size'])) {
        $person_num_rule .= 'width:' . intval($s['person_num_size']) . 'px;height:' . intval($s['person_num_size']) . 'px;';
    }
    if ('50%' !== ft_radius_css($s['person_num_radius'], '50%')) {
        $person_num_rule .= 'border-radius:' . ft_radius_css($s['person_num_radius'], '50%') . ';';
    }
    $person_num_rule .= $ft_font($s['person_num_font_family']);
    if (intval($s['person_num_font_weight']) > 0) {
        $person_num_rule .= 'font-weight:' . intval($s['person_num_font_weight']) . '!important;';
    }
    if (intval($s['person_num_font_size']) > 0 && 11 !== intval($s['person_num_font_size'])) {
        $person_num_rule .= 'font-size:' . intval($s['person_num_font_size']) . 'px!important;';
    }
    if ('' !== $person_num_rule) {
        $css .= '.ft-photo-page__person-num{' . $person_num_rule . '}';
    }

    // === «Кто на фото»: метка на фотографии ===
    $tag_rule = '';
    if (!empty($s['tag_bg']) && '#5b7745' !== strtolower($s['tag_bg'])) {
        $tag_rule .= 'background:' . esc_html($s['tag_bg']) . '!important;';
    }
    if (!empty($s['tag_color']) && '#ffffff' !== strtolower($s['tag_color'])) {
        $tag_rule .= 'color:' . esc_html($s['tag_color']) . '!important;';
    }
    $tag_size = intval($s['tag_size']);
    $tag_bw = intval($s['tag_border_width']);
    if ($tag_size > 0 && 28 !== $tag_size) {
        $half = round($tag_size / 2);
        $tag_rule .= 'width:' . $tag_size . 'px;height:' . $tag_size . 'px!important;margin:' . (-$half) . 'px 0 0 ' . (-$half) . 'px!important;';
        $tag_rule .= 'line-height:' . max(1, $tag_size - 2 * ($tag_bw > 0 ? $tag_bw : 2)) . 'px!important;';
    }
    if ('50%' !== ft_radius_css($s['tag_radius'], '50%')) {
        $tag_rule .= 'border-radius:' . ft_radius_css($s['tag_radius'], '50%') . ';';
    }
    if (2 !== $tag_bw || 'solid' !== $s['tag_border_style'] || (!empty($s['tag_border_color']) && '#ffffff' !== strtolower($s['tag_border_color']))) {
        if ($tag_bw > 0) {
            $tag_rule .= 'border:' . ft_border_width_css($tag_bw . 'px', $ft_bs($s['tag_border_style'])) . ' ' . $ft_bs($s['tag_border_style']) . ' ' . esc_html(!empty($s['tag_border_color']) ? $s['tag_border_color'] : '#ffffff') . '!important;';
        } else {
            $tag_rule .= 'border:0!important;';
        }
    }
    $tag_rule .= $ft_font($s['tag_font_family']);
    if (intval($s['tag_font_weight']) > 0) {
        $tag_rule .= 'font-weight:' . intval($s['tag_font_weight']) . '!important;';
    }
    if (intval($s['tag_font_size']) > 0 && 13 !== intval($s['tag_font_size'])) {
        $tag_rule .= 'font-size:' . intval($s['tag_font_size']) . 'px!important;';
    }
    if ('' !== $tag_rule) {
        $css .= '.ft-photo-tag{' . $tag_rule . '}';
    }

    // === Кнопка «К папке» ===
    if (!in_array($s['back_align'], array('left', 'center', 'right'), true)) {
        $s['back_align'] = 'left';
    }
    if (24 !== intval($s['back_margin_top'])) {
        $css .= '.ft-photo-page__back{margin-top:' . intval($s['back_margin_top']) . 'px;}';
    }
    if ('left' !== $s['back_align']) {
        $css .= '.ft-photo-page__back{text-align:' . esc_html($s['back_align']) . ';}';
    }
    $back_rule = '';
    if (!empty($s['back_bg'])) {
        $back_rule .= 'background:' . esc_html($s['back_bg']) . '!important;';
    }
    if (!empty($s['back_color'])) {
        $back_rule .= 'color:' . esc_html($s['back_color']) . '!important;';
    }
    if ('0px' !== ft_radius_css($s['back_radius'], '0px')) {
        $back_rule .= 'border-radius:' . ft_radius_css($s['back_radius'], '0px') . '!important;';
    }
    if (!empty($s['back_border_width']) || !empty($s['back_border_color'])) {
        $back_rule .= 'border:' . ft_border_width_css(max(1, intval($s['back_border_width'])) . 'px', $ft_bs($s['back_border_style'])) . ' ' . $ft_bs($s['back_border_style']) . ' ' . esc_html(!empty($s['back_border_color']) ? $s['back_border_color'] : '#dcdcde') . '!important;';
    }
    if (intval($s['back_padding_y']) > 0 || intval($s['back_padding_x']) > 0) {
        $back_rule .= 'padding:' . intval($s['back_padding_y']) . 'px ' . intval($s['back_padding_x']) . 'px!important;';
    }
    $back_rule .= $ft_font($s['back_font_family']);
    if (intval($s['back_font_weight']) > 0) {
        $back_rule .= 'font-weight:' . intval($s['back_font_weight']) . '!important;';
    }
    if (intval($s['back_font_size']) > 0) {
        $back_rule .= 'font-size:' . intval($s['back_font_size']) . 'px!important;';
    }
    if ('' !== $back_rule) {
        $css .= '.ft-photo-page__back-link{' . $back_rule . '}';
    }
    // === Кнопка «К папке»: при наведении ===
    $back_hover_rule = '';
    if (!empty($s['back_hover_bg'])) {
        $back_hover_rule .= 'background:' . esc_html($s['back_hover_bg']) . '!important;';
    }
    if (!empty($s['back_hover_color'])) {
        $back_hover_rule .= 'color:' . esc_html($s['back_hover_color']) . '!important;';
    }
    if (!empty($s['back_hover_border_width']) || !empty($s['back_hover_border_color'])) {
        $back_hover_rule .= 'border:' . ft_border_width_css(max(1, intval($s['back_hover_border_width'])) . 'px', $ft_bs($s['back_hover_border_style'])) . ' ' . $ft_bs($s['back_hover_border_style']) . ' ' . esc_html(!empty($s['back_hover_border_color']) ? $s['back_hover_border_color'] : '#dcdcde') . '!important;';
    }
    if ('' !== $back_hover_rule) {
        $css .= '.ft-photo-page__back-link:hover{' . $back_hover_rule . '}';
    }

    // === Другие фотографии альбома (ft-photo-page__others) ===
    if (110 !== intval($s['thumbs_min_width']) || 10 !== intval($s['thumbs_gap'])) {
        $css .= '.ft-photo-page__thumbs{';
        if (110 !== intval($s['thumbs_min_width'])) {
            $css .= 'grid-template-columns:repeat(auto-fill,minmax(' . intval($s['thumbs_min_width']) . 'px,1fr));';
        }
        if (10 !== intval($s['thumbs_gap'])) {
            $css .= 'gap:' . intval($s['thumbs_gap']) . 'px;';
        }
        $css .= '}';
    }
    if (85 !== intval($s['thumbs_height'])) {
        $css .= '.ft-photo-page__thumbs img{height:' . intval($s['thumbs_height']) . 'px!important;}';
    }
    $thumb_border = '';
    if ('8px' !== ft_radius_css($s['thumbs_radius'], '8px')) {
        $thumb_border .= 'border-radius:' . ft_radius_css($s['thumbs_radius'], '8px') . ';';
    }
    if (2 !== intval($s['thumbs_border_width']) || 'solid' !== $s['thumbs_border_style'] || 'transparent' !== $s['thumbs_border_color']) {
        $thumb_border .= 'border:' . ft_border_width_css(max(0, intval($s['thumbs_border_width'])) . 'px', $ft_bs($s['thumbs_border_style'])) . ' ' . $ft_bs($s['thumbs_border_style']) . ' ' . esc_html(!empty($s['thumbs_border_color']) ? $s['thumbs_border_color'] : 'transparent') . ';';
    }
    if ('' !== $thumb_border) {
        $css .= '.ft-photo-page__thumbs a{' . $thumb_border . '}';
    }
    if (2 !== intval($s['thumbs_active_border_width']) || 'solid' !== $s['thumbs_active_border_style'] || !empty($s['thumbs_active_border_color'])) {
        $css .= '.ft-photo-page__thumbs a.is-current{';
        if (2 !== intval($s['thumbs_active_border_width']) || 'double' === $ft_bs($s['thumbs_active_border_style'])) {
            $css .= 'border-width:' . esc_html(ft_border_width_css(intval($s['thumbs_active_border_width']) . 'px', $ft_bs($s['thumbs_active_border_style']))) . ';';
        }
        if ('solid' !== $s['thumbs_active_border_style']) {
            $css .= 'border-style:' . $ft_bs($s['thumbs_active_border_style']) . ';';
        }
        if (!empty($s['thumbs_active_border_color'])) {
            $css .= 'border-color:' . esc_html($s['thumbs_active_border_color']) . ';';
        }
        $css .= '}';
    }
    $tt_rule = '';
    if (!empty($s['thumb_title_bg']) && 'rgba(60, 73, 56, 0.85)' !== $s['thumb_title_bg']) {
        $tt_rule .= 'background:' . esc_html($s['thumb_title_bg']) . '!important;';
    }
    if (!empty($s['thumb_title_color']) && '#ffffff' !== $s['thumb_title_color']) {
        $tt_rule .= 'color:' . esc_html($s['thumb_title_color']) . '!important;';
    }
    $tt_rule .= $ft_font($s['thumb_title_font_family']);
    if (11 !== intval($s['thumb_title_font_size'])) {
        $tt_rule .= 'font-size:' . intval($s['thumb_title_font_size']) . 'px!important;';
    }
    if (intval($s['thumb_title_font_weight']) > 0) {
        $tt_rule .= 'font-weight:' . intval($s['thumb_title_font_weight']) . '!important;';
    }
    if (4 !== intval($s['thumb_title_padding_y']) || 6 !== intval($s['thumb_title_padding_x'])) {
        $tt_rule .= 'padding:' . intval($s['thumb_title_padding_y']) . 'px ' . intval($s['thumb_title_padding_x']) . 'px!important;';
    }
    if ('' !== $tt_rule) {
        $css .= '.ft-photo-page__thumb-title{' . $tt_rule . '}';
    }

    return $css;
}
/**
 * CSS-стили страницы «Альбомы персоналий» (шапка, табы альбомов, блок альбома).
 *
 * @param array|null $s Настройки страницы «Альбомы персоналий».
 * @return string
 */
function ft_person_albums_css($s = null) {
    if (null === $s || !is_array($s)) {
        $s = ft_get_person_albums_settings();
    }
    $css = '';
    // Базовые структурные правила (каркас шапки, свитчера альбомов)
    $css .= '.ft-albums-header__inner{display:flex;align-items:center;gap:20px;flex-wrap:wrap;}.ft-albums-header__avatar{width:84px;height:84px;border-radius:50%;object-fit:cover;flex-shrink:0;}.ft-albums-header__avatar--empty{width:84px;height:84px;border-radius:50%;background:#f0f0f1;display:flex;align-items:center;justify-content:center;font-size:34px;color:#999;flex-shrink:0;}.ft-albums-header__links{margin-top:10px;font-size:13px;}.ft-pa-header-btn{display:inline-block;}.ft-pa-header-sep{margin:0 6px;color:inherit;}.ft-album-switcher{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px;}.ft-album-tab{display:inline-flex;align-items:center;text-decoration:none;line-height:1;cursor:pointer;}.ft-album-tab .ft-album-tab-cover img{display:block;width:100%;height:100%;object-fit:cover;}';
    $ft_bs = function ($v) {
        return in_array($v, array('solid', 'dashed', 'dotted', 'double'), true) ? $v : 'solid';
    };
    $ft_font = function ($family) {
        return '' !== trim((string) $family) ? 'font-family:\'' . esc_html($family) . '\', serif!important;' : '';
    };
    $ft_font_size = function ($size) {
        return intval($size) > 0 ? 'font-size:' . intval($size) . 'px!important;' : '';
    };
    $ft_font_weight = function ($weight) {
        return intval($weight) > 0 ? 'font-weight:' . intval($weight) . '!important;' : '';
    };

    // === Контейнеры (единые для шапки и фотоальбома) ===
    $container_rule = 'margin-top:' . intval($s['container_margin_top']) . 'px;margin-bottom:' . intval($s['container_margin_bottom']) . 'px;';
    if (!empty($s['container_bg']) || ('gradient' === $s['container_bg_type'] && !empty($s['container_bg_gradient']))) {
        if ('gradient' === $s['container_bg_type'] && !empty($s['container_bg_gradient'])) {
            $container_rule .= 'background-image:' . esc_html($s['container_bg_gradient']) . '!important;background-color:' . ('' !== $s['container_bg'] ? esc_html($s['container_bg']) : 'transparent') . '!important;';
        } else {
            $container_rule .= 'background:' . esc_html($s['container_bg']) . '!important;';
        }
    } else {
        $container_rule .= 'background:transparent!important;';
    }
    $container_rule .= 'border-radius:' . ft_radius_css($s['container_radius'], '0px') . '!important;';
    if (!empty($s['container_border_width']) || !empty($s['container_border_color'])) {
        $container_rule .= 'border:' . ft_border_width_css(max(1, intval($s['container_border_width'])) . 'px', $ft_bs($s['container_border_style'])) . ' ' . $ft_bs($s['container_border_style']) . ' ' . esc_html(!empty($s['container_border_color']) ? $s['container_border_color'] : '#dcdcde') . '!important;';
