    // Соотношение сторон для сетки
    $ratio_map = array('4:3' => '4 / 3', '3:2' => '3 / 2', '16:9' => '16 / 9', '2:1' => '2 / 1', '3:1' => '3 / 1', '4:1' => '4 / 1', '3:4' => '3 / 4', '2:3' => '2 / 3', '1:1' => '1 / 1');
