    // Фотография: рамка и тень
    $img_rule = '';
    if (!empty($s['image_border_width']) || !empty($s['image_border_color'])) {
        $img_rule .= 'border:' . ft_border_width_css(max(1, intval($s['image_border_width'])) . 'px', $ft_bs($s['image_border_style'])) . ' ' . $ft_bs($s['image_border_style']) . ' ' . esc_html(!empty($s['image_border_color']) ? $s['image_border_color'] : '#dcdcde') . ';';
    }
    if (intval($s['image_shadow'])) {
