        $img_rule .= 'box-shadow:' . intval($s['shadow_offset_x']) . 'px ' . intval($s['shadow_offset_y']) . 'px ' . intval($s['shadow_blur']) . 'px ' . intval($s['shadow_spread']) . 'px ' . esc_html($sh_color) . ';';
    }
    if ('' !== $img_rule) {
        $css .= '.family-member-photo-album .family-member-photo-item{' . $img_rule . '}';
