    $img_hover_rule = '';
    if ('hover' === $s['image_border_state'] && !empty($s['image_border_color_hover'])) {
        $img_hover_rule .= 'border-color:' . esc_html($s['image_border_color_hover']) . '!important;';
    }
    if ('hover' === $s['image_shadow_state'] && intval($s['image_shadow_hover'])) {
        $sh_hov_color = !empty($s['shadow_color']) ? $s['shadow_color'] : 'rgba(0, 0, 0, 0.18)';
        $img_hover_rule .= 'box-shadow:' . intval($s['shadow_offset_x']) . 'px ' . intval($s['shadow_offset_y']) . 'px ' . intval($s['shadow_blur']) . 'px ' . intval($s['shadow_spread']) . 'px ' . esc_html($sh_hov_color) . '!important;';
    } elseif (intval($s['image_shadow'])) {
        $sh_norm_color = !empty($s['shadow_color']) ? $s['shadow_color'] : 'rgba(0, 0, 0, 0.18)';
        $img_hover_rule .= 'box-shadow:' . intval($s['shadow_offset_x']) . 'px ' . intval($s['shadow_offset_y']) . 'px ' . intval($s['shadow_blur']) . 'px ' . intval($s['shadow_spread']) . 'px ' . esc_html($sh_norm_color) . '!important;';
    } else {
