    $img_hover_rule .= 'transform:none!important;';
    $css .= '.family-member-photo-album .family-member-photo-item:hover{' . $img_hover_rule . '}';

    return $css;
}
/**
 * Статистика контента раздела семейного архива по всем персоналиям.
 *
 * @param string $section ID раздела.
 * @return array {
 *     int $members кол-во персон с содержимым,
 *     int $albums  всего папок/альбомов,
 *     int $files   всего элементов (фото/документов/сканов),
 *     array $rows  map post_id => ['albums'=>int,'files'=>int],
 * }
 */
if (!function_exists('ft_archive_section_stats')) {
    function ft_archive_section_stats($section = 'photoalbums') {
        static $cache = array();
        $section = sanitize_key($section);
        if (isset($cache[$section])) {
            return $cache[$section];
        }
        $members = get_posts(array(
            'post_type'      => 'family_member',
            'post_status'    => 'publish',
            'posts_per_page' => -1,
            'nopaging'       => true,
            'fields'         => 'ids',
            'no_found_rows'  => true,
        ));
        $rows = array();
        $total_albums = 0;
        $total_files  = 0;
        foreach ($members as $mid) {
            $albums = ft_get_albums($mid, $section);
            if (empty($albums)) {
                continue;
            }
            $files = 0;
            foreach ($albums as $a) {
                $files += count((array) $a['photos']);
            }
            $rows[$mid] = array('albums' => count($albums), 'files' => $files);
            $total_albums += count($albums);
            $total_files += $files;
        }
        $cache[$section] = array(
            'members' => count($rows),
            'albums'  => $total_albums,
            'files'   => $total_files,
            'rows'    => $rows,
        );
        return $cache[$section];
    }
}
/**
 * Дефолтные разделы семейного архива (кнопки главной страницы).
 *
 * @return array ключ раздела => настройки (title, description, image, enabled, coming_soon).
