/**
 * Возвращает разделы семейного архива (опция family_tree_archive_sections).
 * Порядок элементов массива = порядок отображения на сайте.
 */
if (!function_exists('ft_get_archive_sections')) {
    function ft_get_archive_sections() {
        $defaults = ft_get_archive_section_defaults();
        $saved = get_option('family_tree_archive_sections', array());
        if (!is_array($saved) || empty($saved)) {
            return $defaults;
        }
        $extra_defaults = array(
            'title'       => '',
            'description' => '',
            'image'       => 0,
            'enabled'     => true,
            'coming_soon' => true,
        );
        $sections = array();
        foreach ($saved as $id => $item) {
            $id = sanitize_key($id);
            if ('' === $id || !is_array($item)) {
                continue;
            }
            $base = isset($defaults[$id]) ? $defaults[$id] : $extra_defaults;
            $sections[$id] = wp_parse_args($item, $base);
        }
        // Миграция: старые названия разделов Пресса/Письма.
        $legacy_titles = array(
            'video' => array('Видео', 'Видеоархив'),
            'tree'  => array('Генеалогическое дерево', 'Дерево'),
        );
        foreach ($legacy_titles as $legacy_id => $legacy_old) {
            if (isset($sections[$legacy_id], $defaults[$legacy_id]) && in_array((string) $sections[$legacy_id]['title'], $legacy_old, true)) {
                $sections[$legacy_id]['title'] = $defaults[$legacy_id]['title'];
            }
        }
        foreach ($defaults as $id => $def) {
            if (!isset($sections[$id])) {
                $sections[$id] = $def;
            }
        }
        return $sections;
    }
}
/**
 * Сохраняет разделы семейного архива в опцию family_tree_archive_sections.
 */
if (!function_exists('ft_save_archive_sections')) {
    function ft_save_archive_sections($sections) {
        update_option('family_tree_archive_sections', $sections);
    }
}
/**
 * Дефолтная SVG-иконка раздела семейного архива.
 *
 * @param string $id ключ раздела (photoalbums|documents|video|tree).
 * @return string HTML иконки.
 */
if (!function_exists('ft_archive_section_default_icon')) {
    function ft_archive_section_default_icon($id) {
        $files = array(
            'photoalbums' => 'photoalbum.svg',
            'documents'   => 'documents.svg',
            'video'       => 'newspaper.svg',
            'tree'        => 'letter.svg',
        );
        $file = isset($files[$id]) ? $files[$id] : $files['photoalbums'];
        $path = FAMILY_TREE_PLUGIN_DIR . 'assets/images/' . $file;
        $cache = array();
        if (isset($GLOBALS['ft_archive_section_icons'][$file])) {
            return $GLOBALS['ft_archive_section_icons'][$file];
        }
        $svg = '';
        if (file_exists($path)) {
            $svg = file_get_contents($path);
            if (false !== $svg) {
                $svg = preg_replace('/^.*?<svg/Us', '<svg', $svg);
                $svg = preg_replace('/<\/svg>.*$/Uis', '</svg>', $svg);
                $svg = str_replace(array('<![CDATA[', ']]>'), '', $svg);
                $svg = preg_replace('/width="[^"]*"/', 'width="48"', $svg);
                $svg = preg_replace('/height="[^"]*"/', 'height="48"', $svg);
                $svg = str_replace('fill:black', 'fill:currentColor', $svg);
            } else {
                $svg = '';
            }
        }
        if ('' === trim($svg)) {
            $svg = '<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24"><path fill="currentColor" d="M4 5h16v14H4z"/></svg>';
        }
        $GLOBALS['ft_archive_section_icons'][$file] = $svg;
        return $svg;
    }
}
/**
 * HTML-иконки/изображения раздела. Если задано изображение — показываем его,
 * иначе дефолтную SVG-иконку.
 *
 * @param string $id
 * @param int $image_id attachment ID.
 * @return string
 */
if (!function_exists('ft_archive_section_icon_html')) {
    function ft_archive_section_icon_html($id, $image_id) {
        $image_id = intval($image_id);
        if ($image_id > 0) {
            $src = wp_get_attachment_image_src($image_id, 'large');
            if ($src && !empty($src[0])) {
                return '<img src="' . esc_url($src[0]) . '" width="48" height="48" alt="" style="width:48px;height:48px;object-fit:cover;border-radius:8px;" draggable="false" />';
            }
        }
        return ft_archive_section_default_icon($id);
    }
}
/**
 * Разделы семейного архива, выключенные для конкретной персоны
 * (тумблер в метабоксе на странице редактирования). Хранятся в мете
 * _family_member_disabled_sections (массив ключей разделов).
 *
 * @param int $person_id ID персоналии.
 * @return array
 */
if (!function_exists('ft_get_person_disabled_sections')) {
    function ft_get_person_disabled_sections($person_id) {
        $person_id = (int) $person_id;
        $disabled = get_post_meta($person_id, '_family_member_disabled_sections', true);
        if (!is_array($disabled)) {
            return array();
        }
        return array_values(array_unique(array_filter(array_map('sanitize_key', $disabled))));
    }
}
/**
 * Ключ post-meta режима отображения раздела персоны на сайте.
 * Раздел «photoalbums» хранит данные в legacy-ключе _family_member_album_display,
 * остальные разделы — в _family_member_album_display_{section}.
 *
 * @param string $section ключ раздела.
 * @return string
 */
if (!function_exists('ft_album_display_meta_key')) {
    function ft_album_display_meta_key($section = 'photoalbums') {
        $section = sanitize_key($section);
        if ('' === $section || 'photoalbums' === $section) {
            return '_family_member_album_display';
        }
        return '_family_member_album_display_' . $section;
    }
}
/**
 * Режим отображения фотоальбомов персоны на сайте.
 * Возвращает ['mode' => 'all'|'album_photos'|'album_covers'|'select_albums', 'albums' => array(slugs), 'album' => slug].
 */
if (!function_exists('ft_get_album_display')) {
    function ft_get_album_display($post_id, $section = 'photoalbums') {
        $post_id = (int) $post_id;
        $saved = get_post_meta($post_id, ft_album_display_meta_key($section), true);
        if (!is_array($saved)) {
            $saved = array();
        }
        $mode = isset($saved['mode']) ? $saved['mode'] : 'all';
        // Обратная совместимость: старый режим one_album → select_albums
        if ($mode === 'one_album') {
            $mode = 'select_albums';
        }
        if (!in_array($mode, array('all', 'album_photos', 'album_covers', 'select_albums'), true)) {
            $mode = 'all';
        }
        $album = isset($saved['album']) ? sanitize_title($saved['album']) : '';
        $albums = isset($saved['albums']) && is_array($saved['albums']) ? array_map('sanitize_title', $saved['albums']) : array();
        $albums = array_values(array_unique(array_filter($albums)));
        if ($mode === 'select_albums' && empty($albums) && $album !== '') {
            $albums = array($album);
        }
        if ($mode === 'album_photos' && $album === '' && !empty($albums)) {
            $album = $albums[0];
        }
        return array('mode' => $mode, 'album' => $album, 'albums' => $albums);
    }
}
