/**
/**
* Получает количество персоналий в группе
* ИСПРАВЛЕНО: раньше подсчёт шёл через get_posts()/WP_Query, что на этом
* сайте давало ненадёжный результат (см. аналогичный фикс в count_ungrouped_members()).
* Теперь используется прямой SQL-запрос через $wpdb, как и там.
*/
private function get_group_member_count($group_id) {
    global $wpdb;
    // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
    return (int) $wpdb->get_var($wpdb->prepare("
SELECT COUNT(DISTINCT p.ID)
FROM {$wpdb->posts} p
INNER JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id
WHERE p.post_type = 'family_member'
AND p.post_status NOT IN ('trash', 'auto-draft')
AND pm.meta_key = '_family_member_group_id'
AND pm.meta_value = %s
", (string) $group_id));
}
