/**
/**
* Отображает метабокс со списком персоналий группы.
* Используется WP_Query с posts_per_page => -1 и suppress_filters => true,
* чтобы гарантированно получить все записи и игнорировать
* сторонние фильтры, ограничивающие вывод.
* ИСПРАВЛЕНО: поиск раньше выполнялся через встроенный параметр WP_Query 's',
* который ищет не только по имени, но и по всему содержимому записи
* (post_content/post_excerpt) — из-за этого в результатах поиска "Яков"
* появлялись персоналии, у которых слово "Яков" просто где-то упоминается
* в тексте биографии, а не в имени. Теперь поиск ведётся только по полям
* имени/отчества/фамилии/девичьей фамилии и по заголовку записи.
*/
public function render_family_group_members_meta_box($post, $metabox) {
global $pagenow;
$group_id = $post->ID;
if (empty($group_id)) {
return;
}
// Получаем параметры из GET запроса
    // phpcs:ignore WordPress.Security.NonceVerification.Recommended
    $search_query = isset($_GET['s']) ? sanitize_text_field(wp_unslash($_GET['s'])) : '';
    // phpcs:ignore WordPress.Security.NonceVerification.Recommended
    $sort_order = isset($_GET['ft_group_sort']) ? sanitize_text_field(wp_unslash($_GET['ft_group_sort'])) : 'date_asc';

// Строим запрос с явными параметрами для получения ВСЕХ записей группы
// (без учёта поиска — поиск теперь применяется отдельно, ниже, по PHP-стороне
// только к полям имени, а не ко всему содержимому записи)
$query_args = array(
'post_type' => 'family_member',
'posts_per_page' => -1, // Получить все записи
'nopaging' => true,     // Отключить разбиение на страницы
        'ignore_sticky_posts' => 1, // Игнорировать закрепленные записи
        'post_status' => 'any',
        // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_query
        'meta_query' => array(
array(
'key' => '_family_member_group_id',
'value' => $group_id,
'compare' => '='
)
),
);

// Добавляем сортировку
switch ($sort_order) {
    case 'date_asc':
        // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
        $query_args['meta_key'] = '_family_member_birth_date';
        $query_args['orderby'] = 'meta_value_num';
        $query_args['order'] = 'ASC';
        break;
    case 'date_desc':
        // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
        $query_args['meta_key'] = '_family_member_birth_date';
        $query_args['orderby'] = 'meta_value_num';
        $query_args['order'] = 'DESC';
        break;
    case 'alpha_asc':
        $query_args['orderby'] = 'title';
        $query_args['order'] = 'ASC';
        break;
    case 'alpha_desc':
        $query_args['orderby'] = 'title';
        $query_args['order'] = 'DESC';
        break;
    default:
        // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
        $query_args['meta_key'] = '_family_member_birth_date';
        $query_args['orderby'] = 'meta_value_num';
        $query_args['order'] = 'ASC';
}

// Выполняем запрос — получаем ВСЕХ членов группы (это и есть надёжное
// "общее количество персоналий" группы, не зависящее от поиска)
$query = new WP_Query($query_args);
$all_group_members = $query->posts;
$total_group_count = count($all_group_members);

// ИСПРАВЛЕНО: поиск теперь фильтрует уже полученный список персоналий
// группы по именным полям (и заголовку), а не по всему содержимому записи.
// Порядок, заданный сортировкой выше, при этом сохраняется.
if (!empty($search_query)) {
$members = array_values(array_filter($all_group_members, function($member) use ($search_query) {
$haystacks = array(
$member->post_title,
get_post_meta($member->ID, '_family_member_first_name', true),
get_post_meta($member->ID, '_family_member_middle_name', true),
get_post_meta($member->ID, '_family_member_last_name', true),
get_post_meta($member->ID, '_family_member_maiden_name', true),
);
foreach ($haystacks as $haystack) {
if ($haystack !== '' && mb_stripos((string) $haystack, $search_query, 0, 'UTF-8') !== false) {
return true;
}
}
return false;
}));
} else {
$members = $all_group_members;
}
?>
<div class="ft-group-members-container">
<p class="ft-member-count" style="font-weight: 600; margin: 0 0 10px;">
<?php if (!empty($search_query)): ?>
<?php
printf(
/* translators: 1: найдено, 2: всего в группе */
esc_html__('Найдено: %1$d из %2$d персоналий в группе', 'genius-family-tree'),
count($members),
esc_html($total_group_count)
);
?>
<?php else: ?>
<?php
/* translators: %d: total number of persons in group */
printf(esc_html__('Всего в группе: %d персоналий', 'genius-family-tree'), esc_html($total_group_count)); ?>
<?php endif; ?>
</p>
<div class="tablenav top ft-controls-bar" id="ft-controls-bar">
<div class="alignleft actions">
<label class="screen-reader-text" for="ft-group-sort"><?php esc_html_e('Сортировка', 'genius-family-tree'); ?></label>
<select name="ft_group_sort" id="ft-group-sort">
<option value="date_asc" <?php selected($sort_order, 'date_asc'); ?>><?php esc_html_e('Дата рождения (старшие сначала)', 'genius-family-tree'); ?></option>
<option value="date_desc" <?php selected($sort_order, 'date_desc'); ?>><?php esc_html_e('Дата рождения (младшие сначала)', 'genius-family-tree'); ?></option>
<option value="alpha_asc" <?php selected($sort_order, 'alpha_asc'); ?>><?php esc_html_e('А-Я (А-Я)', 'genius-family-tree'); ?></option>
<option value="alpha_desc" <?php selected($sort_order, 'alpha_desc'); ?>><?php esc_html_e('Я-А (Я-А)', 'genius-family-tree'); ?></option>
