/**
* ИСПРАВЛЕНО: Надежный подсчет через $wpdb вместо get_posts
*/
    private function count_ungrouped_members() {
        global $wpdb;
        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
        return (int) $wpdb->get_var($wpdb->prepare("
            SELECT COUNT(DISTINCT p.ID)
            FROM {$wpdb->posts} p
            LEFT JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = %s
            LEFT JOIN {$wpdb->posts} g ON g.ID = pm.meta_value AND g.post_type = 'family_group' AND g.post_status != 'trash'
            WHERE p.post_type = 'family_member'
            AND p.post_status != 'trash'
            AND (pm.meta_value IS NULL OR pm.meta_value = '' OR pm.meta_value = '0' OR g.ID IS NULL)
        ", '_family_member_group_id'));
    }
