/**
* Страница миграции персоналий в группу по умолчанию
*/
public function migrate_members_page() {
$default_group_id = get_option('family_tree_default_group_id', 0);
if (!$default_group_id || !get_post($default_group_id)) {
?>
<div class="wrap">
<h1><?php esc_html_e('Миграция персоналий', 'genius-family-tree'); ?></h1>
<div class="notice notice-error">
<p><?php esc_html_e('Группа по умолчанию не найдена. Пожалуйста, активируйте плагин заново или создайте группу вручную.', 'genius-family-tree'); ?></p>
</div>
</div>
<?php
return;
}
$default_group = get_post($default_group_id);
// Обработка миграции
if (isset($_POST['migrate_members']) && check_admin_referer('family_tree_migrate_nonce')) {
$migrated = $this->migrate_ungrouped_members_to_default($default_group_id);
?>
<div class="wrap">
<div class="notice notice-success">
<p><?php printf(
    /* translators: %d: number of migrated persons */
    esc_html__('Успешно перенесено %d персоналий в группу «Без названия».', 'genius-family-tree'),
    esc_html($migrated)
); ?></p>
</div>
<p><a href="<?php echo esc_url(admin_url('edit.php?post_type=family_member')); ?>" class="button"><?php esc_html_e('Вернуться к списку персоналий', 'genius-family-tree'); ?></a></p>
</div>
<?php
return;
}
// Получаем количество персоналий без группы
$ungrouped_count = $this->count_ungrouped_members();
?>
<div class="wrap">
<h1><?php esc_html_e('Миграция персоналий', 'genius-family-tree'); ?></h1>
<?php if ($ungrouped_count > 0): ?>
<p><?php printf(
    /* translators: %d: number of ungrouped members */
    esc_html(
        /* translators: %d: number of ungrouped members */
        _n(
            'Найдена %d персоналия без семейной группы.',
            'Найдено %d персоналий без семейной группы.',
            $ungrouped_count,
            'genius-family-tree'
        )
    ),
    esc_html($ungrouped_count)
); ?></p>
<p><?php printf(
    /* translators: %s: group name */
    esc_html__('Эти персоналии будут перенесены в группу «%s». Вы сможете изменить название группы или перераспределить персоналий позже.', 'genius-family-tree'),
    '<strong>' . esc_html($default_group->post_title) . '</strong>'
); ?></p>
<form method="post" style="margin-top: 20px;">
<?php wp_nonce_field('family_tree_migrate_nonce'); ?>
<input type="submit" name="migrate_members" value="<?php esc_attr_e('Выполнить миграцию', 'genius-family-tree'); ?>" class="button button-primary button-hero">
<a href="<?php echo esc_url(admin_url('edit.php?post_type=family_member')); ?>" class="button button-secondary" style="margin-left: 10px;"><?php esc_html_e('Отмена', 'genius-family-tree'); ?></a>
</form>
<?php else: ?>
<div class="notice notice-success">
<p><?php esc_html_e('Все персоналии уже распределены по группам. Миграция не требуется.', 'genius-family-tree'); ?></p>
</div>
<p><a href="<?php echo esc_url(admin_url('edit.php?post_type=family_member')); ?>" class="button"><?php esc_html_e('Вернуться к списку персоналий', 'genius-family-tree'); ?></a></p>
<?php endif; ?>
</div>
<?php
}
/**
* ИСПРАВЛЕНО: Надежная миграция через прямой SQL + очистка кэша
*/
private function migrate_ungrouped_members_to_default($default_group_id) {
    global $wpdb;
    $default_group_id = intval($default_group_id);
    if (!$default_group_id) return 0;
    // Находим все ID персоналий без группы (NULL, '' или '0')
    // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
    $ids = $wpdb->get_col("
SELECT DISTINCT p.ID
FROM {$wpdb->posts} p
LEFT JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = '_family_member_group_id'
WHERE p.post_type = 'family_member'
AND p.post_status != 'trash'
            AND (pm.meta_value IS NULL OR pm.meta_value = '' OR pm.meta_value = '0')
            // phpcs:ignore WordPress.DB.PreparedSQLPlaceholders.UnnecessaryPrepare
            ");
if (empty($ids)) return 0;
$updated = 0;
foreach ($ids as $id) {
update_post_meta($id, '_family_member_group_id', $default_group_id);
wp_cache_delete($id, 'post_meta');
$updated++;
}
// Сбрасываем общий кэш запросов
wp_cache_flush();
return $updated;
}
public function register_settings() {
register_setting('family_tree_settings', 'family_tree_license_key', array('sanitize_callback' => 'sanitize_text_field'));
// Лицензионные опции INTENTIONALLY не регистрируются в Settings API:
// они должны меняться только кодом (validate_license / heartbeat / force_free),
// а не через options.php или произвольный POST.
register_setting('family_tree_settings', 'family_tree_bg_color', array('sanitize_callback' => array($this, 'sanitize_tree_color')));
register_setting('family_tree_settings', 'family_tree_bg_image', array('sanitize_callback' => 'esc_url_raw'));
    register_setting('family_tree_settings', 'family_tree_bg_type', array('sanitize_callback' => 'sanitize_text_field'));
    register_setting('family_tree_settings', 'family_tree_bg_gradient', array('sanitize_callback' => 'sanitize_text_field'));
    register_setting('family_tree_settings', 'family_tree_bg_gradient_type', array('sanitize_callback' => 'sanitize_text_field'));
    register_setting('family_tree_settings', 'family_tree_bg_angle', array('sanitize_callback' => 'intval'));
    register_setting('family_tree_settings', 'family_tree_person_bg', array('sanitize_callback' => array($this, 'sanitize_tree_color')));
    register_setting('family_tree_settings', 'family_tree_person_bg_type', array('sanitize_callback' => 'sanitize_text_field'));
    register_setting('family_tree_settings', 'family_tree_person_bg_gradient', array('sanitize_callback' => 'sanitize_text_field'));
    register_setting('family_tree_settings', 'family_tree_person_bg_gradient_type', array('sanitize_callback' => 'sanitize_text_field'));
    register_setting('family_tree_settings', 'family_tree_person_bg_angle', array('sanitize_callback' => 'intval'));
    register_setting('family_tree_settings', 'family_tree_person_bg_image', array('sanitize_callback' => 'esc_url_raw'));
    register_setting('family_tree_settings', 'family_tree_person_template', array('sanitize_callback' => array($this, 'sanitize_person_template'), 'default' => ''));
    register_setting('family_tree_settings', 'family_tree_person_container_margin', array('sanitize_callback' => array($this, 'sanitize_css_radius')));
