// Функция санитизации для лицензионных данных
public function sanitize_license_data($data) {
if (!is_array($data)) {
return array();
}
$sanitized = array();
foreach ($data as $key => $value) {
$safe_key = sanitize_text_field((string) $key);
// ИСПРАВЛЕНО (PHP 8): sanitize_text_field() требует строку. Если значение
// является массивом/bool/null (например, вложенные данные из ответа API),
// прямой вызов sanitize_text_field($value) приводил к фатальной ошибке TypeError.
if (is_array($value)) {
$sanitized[$safe_key] = $this->sanitize_license_data($value);
} elseif (is_bool($value) || is_null($value)) {
$sanitized[$safe_key] = $value;
} else {
$sanitized[$safe_key] = sanitize_text_field((string) $value);
}
}
return $sanitized;
}
/**
* Санитизация цвета фона древа. Допускает HEX (#rrggbb, #rgb) и rgba() с прозрачностью.
*/
public function sanitize_tree_color($value) {
$value = family_tree_sanitize_str($value);
$value = trim($value);
if (empty($value)) {
return '';
}
if (preg_match('/^#([A-Fa-f0-9]{3}|[A-Fa-f0-9]{4}|[A-Fa-f0-9]{6}|[A-Fa-f0-9]{8})$/', $value)) {
    return $value;
}
if (preg_match('/^rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(\s*,\s*(1(\.0+)?|0(\.\d+)?|\.\d+))?\s*\)$/i', $value)) {
    return $value;
}
return '';
}
/**
 * Санитизация адаптивных настроек шапки персоны (family_tree_phs из POST).
 * Пустое значение означает «не задано»: на выводе оно наследует состояние
 * «Обычный» (для hover) или дефолт темы.
 *
 * @param array $raw          необработанные данные формы
 * @param array $allowed_fonts разрешённые гарнитуры
 * @return array нормализованная структура по ft_phs_schema()
 */
public function sanitize_person_header_settings($raw, $allowed_fonts) {
    $out = ft_phs_normalize(array());
    if (!is_array($raw)) {
        return $out;
    }
    $allowed = is_array($allowed_fonts) ? $allowed_fonts : array();
    foreach (array_keys(ft_device_list()) as $dev) {
        if (isset($raw[$dev]['button_state']) && 'hover' === $raw[$dev]['button_state']) {
            $out[$dev]['button_state'] = 'hover';
        }
        if (!isset($raw[$dev]) || !is_array($raw[$dev])) {
            continue;
        }
        // Заголовок
        if (isset($raw[$dev]['title']) && is_array($raw[$dev]['title'])) {
            $t = $raw[$dev]['title'];
            $out[$dev]['title']['color'] = $this->sanitize_tree_color(isset($t['color']) ? $t['color'] : '');
            $out[$dev]['title']['font_size'] = isset($t['font_size']) ? max(0, min(96, intval($t['font_size']))) : 0;
            $font = isset($t['font_family']) ? family_tree_sanitize_str($t['font_family']) : '';
            $out[$dev]['title']['font_family'] = in_array($font, $allowed, true) ? $font : '';
            $weight = isset($t['font_weight']) ? intval($t['font_weight']) : 0;
            $out[$dev]['title']['font_weight'] = in_array($weight, self::get_font_weights($out[$dev]['title']['font_family']), true) ? $weight : 0;
            $talign = isset($t['text_align']) && !is_array($t['text_align']) && !is_object($t['text_align'])
                ? family_tree_sanitize_str($t['text_align']) : '';
            $out[$dev]['title']['text_align'] = in_array($talign, ft_phs_align_values(), true) ? $talign : '';
        }
        // Кнопка: normal / hover
        if (isset($raw[$dev]['button']) && is_array($raw[$dev]['button'])) {
            foreach (array('normal', 'hover') as $state) {
                if (!isset($raw[$dev]['button'][$state]) || !is_array($raw[$dev]['button'][$state])) {
                    continue;
                }
                $b = $raw[$dev]['button'][$state];
                $out[$dev]['button'][$state]['bg_color'] = $this->sanitize_tree_color(isset($b['bg_color']) ? $b['bg_color'] : '');
                $out[$dev]['button'][$state]['text_color'] = $this->sanitize_tree_color(isset($b['text_color']) ? $b['text_color'] : '');
                $out[$dev]['button'][$state]['bg_type'] = (isset($b['bg_type']) && 'gradient' === $b['bg_type']) ? 'gradient' : 'classic';
                $out[$dev]['button'][$state]['bg_gradient'] = isset($b['bg_gradient']) ? sanitize_text_field($b['bg_gradient']) : '';
                $out[$dev]['button'][$state]['bg_gradient_type'] = (isset($b['bg_gradient_type']) && 'radial' === $b['bg_gradient_type']) ? 'radial' : 'linear';
                $out[$dev]['button'][$state]['bg_angle'] = isset($b['bg_angle']) ? max(-360, min(360, intval($b['bg_angle']))) : 180;
                $out[$dev]['button'][$state]['font_size'] = isset($b['font_size']) ? max(0, min(96, intval($b['font_size']))) : 0;
                $bfont = isset($b['font_family']) ? family_tree_sanitize_str($b['font_family']) : '';
                $out[$dev]['button'][$state]['font_family'] = in_array($bfont, $allowed, true) ? $bfont : '';
                $bweight = isset($b['font_weight']) ? intval($b['font_weight']) : 0;
                $out[$dev]['button'][$state]['font_weight'] = in_array($bweight, self::get_font_weights($out[$dev]['button'][$state]['font_family']), true) ? $bweight : 0;
                $out[$dev]['button'][$state]['border_width'] = isset($b['border_width']) ? $this->sanitize_css_radius($b['border_width']) : '';
                $bstyle = isset($b['border_style']) ? family_tree_sanitize_str($b['border_style']) : '';
                $out[$dev]['button'][$state]['border_style'] = in_array($bstyle, array('solid', 'dashed', 'dotted', 'double'), true) ? $bstyle : '';
                $out[$dev]['button'][$state]['border_color'] = isset($b['border_color']) ? $this->sanitize_tree_color($b['border_color']) : '';
            }
        }
        // Габариты кнопки (отступы и скругление) — одни на оба состояния.
        if (isset($raw[$dev]['box']) && is_array($raw[$dev]['box'])) {
            $bx = $raw[$dev]['box'];
            foreach (array('margin', 'padding', 'radius') as $bkey) {
                $out[$dev]['box'][$bkey] = isset($bx[$bkey]) ? $this->sanitize_css_radius($bx[$bkey]) : '';
            }
            $balign = isset($bx['align']) && !is_array($bx['align']) && !is_object($bx['align'])
                ? family_tree_sanitize_str($bx['align']) : '';
            $out[$dev]['box']['align'] = in_array($balign, ft_phs_align_values(), true) ? $balign : '';
        }
    }
    return $out;
}
/**
 * Санитизация настроек кнопок ленты альбомов (family_tree_album_navlink из POST).
 *
 * Структура повторяет санитизацию кнопки «Показать в древе»: пустое значение
 * означает «не задано», то есть наследование состояния «Обычный» (для hover) или
 * дефолт темы. Выравнивания по горизонтали нет — у этой кнопки его нет и в
 * настройках.
 *
 * @param array $raw          необработанные данные формы
 * @param array $allowed_fonts разрешённые гарнитуры
 * @return array нормализованная структура по ft_album_navlink_schema()
 */
public function sanitize_album_navlink_settings($raw, $allowed_fonts) {
    $out = ft_album_navlink_normalized(array());
    if (!is_array($raw)) {
        return $out;
    }
    $allowed = is_array($allowed_fonts) ? $allowed_fonts : array();
    foreach (array_keys(ft_device_list()) as $dev) {
        // Какая вкладка «Обычный / При наведении» открыта — запоминаем и при
        // пустой форме, иначе выбор слетал бы после каждого сохранения.
        if (isset($raw[$dev]['button_state']) && 'hover' === $raw[$dev]['button_state']) {
            $out[$dev]['button_state'] = 'hover';
        }
        if (!isset($raw[$dev]) || !is_array($raw[$dev])) {
            continue;
        }
        if (isset($raw[$dev]['button']) && is_array($raw[$dev]['button'])) {
            foreach (array('normal', 'hover') as $state) {
                if (!isset($raw[$dev]['button'][$state]) || !is_array($raw[$dev]['button'][$state])) {
                    continue;
                }
                $b = $raw[$dev]['button'][$state];
                $out[$dev]['button'][$state]['bg_color'] = $this->sanitize_tree_color(isset($b['bg_color']) ? $b['bg_color'] : '');
                $out[$dev]['button'][$state]['text_color'] = $this->sanitize_tree_color(isset($b['text_color']) ? $b['text_color'] : '');
                $out[$dev]['button'][$state]['bg_type'] = (isset($b['bg_type']) && 'gradient' === $b['bg_type']) ? 'gradient' : 'classic';
                $out[$dev]['button'][$state]['bg_gradient'] = isset($b['bg_gradient']) ? sanitize_text_field($b['bg_gradient']) : '';
                $out[$dev]['button'][$state]['bg_gradient_type'] = (isset($b['bg_gradient_type']) && 'radial' === $b['bg_gradient_type']) ? 'radial' : 'linear';
                $out[$dev]['button'][$state]['bg_angle'] = isset($b['bg_angle']) ? max(-360, min(360, intval($b['bg_angle']))) : 180;
                $out[$dev]['button'][$state]['font_size'] = isset($b['font_size']) ? max(0, min(96, intval($b['font_size']))) : 0;
                $bfont = isset($b['font_family']) ? family_tree_sanitize_str($b['font_family']) : '';
                $out[$dev]['button'][$state]['font_family'] = in_array($bfont, $allowed, true) ? $bfont : '';
                $bweight = isset($b['font_weight']) ? intval($b['font_weight']) : 0;
                $out[$dev]['button'][$state]['font_weight'] = in_array($bweight, self::get_font_weights($out[$dev]['button'][$state]['font_family']), true) ? $bweight : 0;
                $out[$dev]['button'][$state]['border_width'] = isset($b['border_width']) ? $this->sanitize_css_radius($b['border_width']) : '';
                $bstyle = isset($b['border_style']) ? family_tree_sanitize_str($b['border_style']) : '';
                $out[$dev]['button'][$state]['border_style'] = in_array($bstyle, array('solid', 'dashed', 'dotted', 'double'), true) ? $bstyle : '';
                $out[$dev]['button'][$state]['border_color'] = $this->sanitize_tree_color(isset($b['border_color']) ? $b['border_color'] : '');
            }
        }
        // Габариты кнопки — одни на оба состояния.
        if (isset($raw[$dev]['box']) && is_array($raw[$dev]['box'])) {
            $bx = $raw[$dev]['box'];
            foreach (array('margin', 'padding', 'radius') as $bkey) {
                $out[$dev]['box'][$bkey] = isset($bx[$bkey]) ? $this->sanitize_css_radius($bx[$bkey]) : '';
            }
        }
    }
    return $out;
}
/**
 * Санитизация адаптивных настроек сайдбара (family_tree_pms из POST).
 * Структура повторяет настройки шапки: пустое значение = не задано, то есть
 * наследование Десктопа (для hover) или дефолта темы.
 *
 * @param array $raw          необработанные данные формы
 * @param array $allowed_fonts разрешённые гарнитуры
 * @return array нормализованная структура по ft_pms_schema()
 */
public function sanitize_person_sidebar_settings($raw, $allowed_fonts) {
    $out = ft_phs_normalize(array(), ft_pms_schema(), 'link');
    if (!is_array($raw)) {
        return $out;
    }
    $allowed = is_array($allowed_fonts) ? $allowed_fonts : array();
    $aligns  = ft_phs_align_values();
    foreach (array_keys(ft_device_list()) as $dev) {
        // Какая вкладка открыта — тоже часть структуры: без явного 'normal'
        // опция не сохраняла бы выбор и вкладка сбрасывалась бы.
        $out[$dev]['link_state'] = 'normal';
        if (isset($raw[$dev]['link_state']) && 'hover' === $raw[$dev]['link_state']) {
            $out[$dev]['link_state'] = 'hover';
        }
        if (!isset($raw[$dev]) || !is_array($raw[$dev])) {
            continue;
        }
        // Заголовки и Текст — одинаковые блоки.
        foreach (array('heading', 'text') as $block) {
            if (!isset($raw[$dev][$block]) || !is_array($raw[$dev][$block])) {
                continue;
            }
            $b = $raw[$dev][$block];
            $out[$dev][$block]['color'] = isset($b['color']) ? $this->sanitize_tree_color($b['color']) : '';
            $out[$dev][$block]['font_size'] = isset($b['font_size']) ? max(0, min(96, intval($b['font_size']))) : 0;
            $font = isset($b['font_family']) && !is_array($b['font_family']) ? family_tree_sanitize_str($b['font_family']) : '';
            $out[$dev][$block]['font_family'] = in_array($font, $allowed, true) ? $font : '';
            $weight = isset($b['font_weight']) ? intval($b['font_weight']) : 0;
            $out[$dev][$block]['font_weight'] = in_array($weight, self::get_font_weights($out[$dev][$block]['font_family']), true) ? $weight : 0;
            $al = isset($b['text_align']) && !is_array($b['text_align']) && !is_object($b['text_align'])
                ? family_tree_sanitize_str($b['text_align']) : '';
            $out[$dev][$block]['text_align'] = in_array($al, $aligns, true) ? $al : '';
            if ('heading' === $block) {
                // Отступы заголовка — те же measure-контролы, что у ссылок.
                foreach (array('margin', 'padding') as $mk) {
                    $out[$dev][$block][$mk] = (isset($b[$mk]) && !is_array($b[$mk]) && !is_object($b[$mk]))
                        ? $this->sanitize_css_radius($b[$mk]) : '';
                }
                // Чекбокс подчёркивания: на Десктопе отсутствие = выключено,
                // на других устройствах отсутствие = наследование Десктопа.
                $on = !empty($b['underline']);
                $out[$dev][$block]['underline'] = $on ? '1' : ('desktop' === $dev ? '0' : '');
                $out[$dev][$block]['underline_color'] = ($on && isset($b['underline_color']))
                    ? $this->sanitize_tree_color($b['underline_color']) : '';
                $out[$dev][$block]['underline_width'] = ($on && isset($b['underline_width']))
                    ? max(0, min(96, intval($b['underline_width']))) : 0;
            } else {
                // Чекбокс разделителей текста: та же логика наследования.
                $on = !empty($b['separator']);
                $out[$dev][$block]['separator'] = $on ? '1' : ('desktop' === $dev ? '0' : '');
                $out[$dev][$block]['separator_color'] = ($on && isset($b['separator_color']))
                    ? $this->sanitize_tree_color($b['separator_color']) : '';
                $out[$dev][$block]['separator_width'] = ($on && isset($b['separator_width']))
                    ? max(0, min(96, intval($b['separator_width']))) : 0;
            }
        }
        // Ссылки: состояния Обычный / При наведении.
        if (isset($raw[$dev]['link']) && is_array($raw[$dev]['link'])) {
            foreach (array('normal', 'hover') as $state) {
                if (!isset($raw[$dev]['link'][$state]) || !is_array($raw[$dev]['link'][$state])) {
                    continue;
                }
                $b = $raw[$dev]['link'][$state];
                $out[$dev]['link'][$state]['color'] = isset($b['color']) ? $this->sanitize_tree_color($b['color']) : '';
                $out[$dev]['link'][$state]['bg_color'] = isset($b['bg_color']) ? $this->sanitize_tree_color($b['bg_color']) : '';
                $out[$dev]['link'][$state]['bg_type'] = (isset($b['bg_type']) && 'gradient' === $b['bg_type']) ? 'gradient' : 'classic';
                $out[$dev]['link'][$state]['bg_gradient'] = isset($b['bg_gradient']) && !is_array($b['bg_gradient'])
                    ? sanitize_text_field($b['bg_gradient']) : '';
                $out[$dev]['link'][$state]['bg_gradient_type'] = (isset($b['bg_gradient_type']) && 'radial' === $b['bg_gradient_type']) ? 'radial' : 'linear';
                $out[$dev]['link'][$state]['bg_angle'] = isset($b['bg_angle']) ? max(-360, min(360, intval($b['bg_angle']))) : 180;
                $out[$dev]['link'][$state]['font_size'] = isset($b['font_size']) ? max(0, min(96, intval($b['font_size']))) : 0;
                $lfont = isset($b['font_family']) && !is_array($b['font_family']) ? family_tree_sanitize_str($b['font_family']) : '';
                $out[$dev]['link'][$state]['font_family'] = in_array($lfont, $allowed, true) ? $lfont : '';
                $lweight = isset($b['font_weight']) ? intval($b['font_weight']) : 0;
                $out[$dev]['link'][$state]['font_weight'] = in_array($lweight, self::get_font_weights($out[$dev]['link'][$state]['font_family']), true) ? $lweight : 0;
// Граница — своя у каждого состояния. Отступы и скругление
                // уехали в общий link_box (см. ниже), здесь их больше нет.
                // Массив или объект вместо строки отбрасываем, иначе
                // family_tree_sanitize_str() превратит его в строку «Array».
                // Подчёркивание: '' — не задано, '0' — нет, '1' — подчёркнуто.
                $ul = isset($b['underline']) && !is_array($b['underline']) ? (string) $b['underline'] : '';
                $out[$dev]['link'][$state]['underline'] = ('0' === $ul || '1' === $ul) ? $ul : '';
                $out[$dev]['link'][$state]['border_width'] = (isset($b['border_width']) && !is_array($b['border_width']) && !is_object($b['border_width']))
                    ? $this->sanitize_css_radius($b['border_width']) : '';
                $lstyle = isset($b['border_style']) && !is_array($b['border_style']) ? family_tree_sanitize_str($b['border_style']) : '';
                $out[$dev]['link'][$state]['border_style'] = in_array($lstyle, array('solid', 'dashed', 'dotted', 'double'), true) ? $lstyle : '';
                $out[$dev]['link'][$state]['border_color'] = isset($b['border_color']) ? $this->sanitize_tree_color($b['border_color']) : '';
            }
        }
        // Габариты и выравнивание ссылок — одни на оба состояния.
        if (isset($raw[$dev]['link_box']) && is_array($raw[$dev]['link_box'])) {
            $lbox = $raw[$dev]['link_box'];
            foreach (array('margin', 'padding', 'radius') as $bkey) {
                $out[$dev]['link_box'][$bkey] = (isset($lbox[$bkey]) && !is_array($lbox[$bkey]) && !is_object($lbox[$bkey]))
                    ? $this->sanitize_css_radius($lbox[$bkey]) : '';
            }
            $lal = isset($lbox['align']) && !is_array($lbox['align']) && !is_object($lbox['align'])
                ? family_tree_sanitize_str($lbox['align']) : '';
            $out[$dev]['link_box']['align'] = in_array($lal, $aligns, true) ? $lal : '';
        }
        // Перенос сохранённых ранее габаритов из состояний в link_box: форма
        // их больше не присылает, поэтому подхватываем из raw, иначе значения
        // сайтов, настроенных до переноса, потерялись бы при первом сохранении.
        foreach (array('margin', 'padding', 'radius') as $bkey) {
            if ('' !== trim((string) $out[$dev]['link_box'][$bkey])) {
                continue;
            }
            foreach (array('normal', 'hover') as $state) {
                $old = isset($raw[$dev]['link'][$state][$bkey]) && !is_array($raw[$dev]['link'][$state][$bkey]) && !is_object($raw[$dev]['link'][$state][$bkey])
                    ? $this->sanitize_css_radius($raw[$dev]['link'][$state][$bkey]) : '';
                if ('' !== $old) {
                    $out[$dev]['link_box'][$bkey] = $old;
                    break;
                }
            }
        }
        // Портрет и подпись — общие для всех устройств, поэтому sanitize берёт
        // их только из ветки «desktop» (именно её присылает форма). Ветки
        // Планшета и Мобильных в разметке больше нет, и их значения не
        // перезаписываются: старые per-device настройки остаются в опции
        // нетронутыми на случай возврата раздела в табы.
        if ('desktop' === $dev) {
            // Портрет: пропорции картинки, выравнивание, отступы, граница.
            if (isset($raw[$dev]['portrait']) && is_array($raw[$dev]['portrait'])) {
                $pr = $raw[$dev]['portrait'];
                $shape = isset($pr['shape']) && !is_array($pr['shape']) && !is_object($pr['shape'])
                    ? family_tree_sanitize_str($pr['shape']) : '';
                $out[$dev]['portrait']['shape'] = in_array($shape, array('square', 'circle', 'full', 'full-square'), true) ? $shape : '';
                $pal = isset($pr['align']) && !is_array($pr['align']) && !is_object($pr['align'])
                    ? family_tree_sanitize_str($pr['align']) : '';
                $out[$dev]['portrait']['align'] = in_array($pal, $aligns, true) ? $pal : '';
                foreach (array('margin', 'padding', 'border_width') as $bkey) {
                    $out[$dev]['portrait'][$bkey] = (isset($pr[$bkey]) && !is_array($pr[$bkey]) && !is_object($pr[$bkey]))
                        ? $this->sanitize_css_radius($pr[$bkey]) : '';
                }
                $pstyle = isset($pr['border_style']) && !is_array($pr['border_style']) ? family_tree_sanitize_str($pr['border_style']) : '';
                $out[$dev]['portrait']['border_style'] = in_array($pstyle, array('solid', 'dashed', 'dotted', 'double'), true) ? $pstyle : '';
                $out[$dev]['portrait']['border_color'] = isset($pr['border_color']) ? $this->sanitize_tree_color($pr['border_color']) : '';
            }
            // Подпись: фон, отступы, скругление, граница.
            if (isset($raw[$dev]['signature']) && is_array($raw[$dev]['signature'])) {
                $sg = $raw[$dev]['signature'];
                $out[$dev]['signature']['bg_color'] = isset($sg['bg_color']) ? $this->sanitize_tree_color($sg['bg_color']) : '';
                $out[$dev]['signature']['bg_type'] = (isset($sg['bg_type']) && 'gradient' === $sg['bg_type']) ? 'gradient' : 'classic';
                $out[$dev]['signature']['bg_gradient'] = isset($sg['bg_gradient']) && !is_array($sg['bg_gradient'])
                    ? sanitize_text_field($sg['bg_gradient']) : '';
                $out[$dev]['signature']['bg_gradient_type'] = (isset($sg['bg_gradient_type']) && 'radial' === $sg['bg_gradient_type']) ? 'radial' : 'linear';
                $out[$dev]['signature']['bg_angle'] = isset($sg['bg_angle']) ? max(-360, min(360, intval($sg['bg_angle']))) : 180;
                foreach (array('margin', 'padding', 'radius', 'border_width') as $bkey) {
                    $out[$dev]['signature'][$bkey] = (isset($sg[$bkey]) && !is_array($sg[$bkey]) && !is_object($sg[$bkey]))
                        ? $this->sanitize_css_radius($sg[$bkey]) : '';
                }
                $sstyle = isset($sg['border_style']) && !is_array($sg['border_style']) ? family_tree_sanitize_str($sg['border_style']) : '';
                $out[$dev]['signature']['border_style'] = in_array($sstyle, array('solid', 'dashed', 'dotted', 'double'), true) ? $sstyle : '';
                $out[$dev]['signature']['border_color'] = isset($sg['border_color']) ? $this->sanitize_tree_color($sg['border_color']) : '';
            }
        }
    }
    return $out;
}
/**
* Санитизация CSS-размера поля древа (ширина/высота/скругление).
* Допускает число с единицами px, %, vh, vw, em, rem, pt, cm, mm, in или ключевое слово auto.
*/
public function sanitize_css_size($value) {
$value = family_tree_sanitize_str($value);
$value = strtolower(trim($value));
if (empty($value)) {
return '';
}
if ($value === 'auto') {
return 'auto';
}
if (preg_match('/^\d+(\.\d+)?(px|%|vh|vw|em|rem|pt|cm|mm|in)?$/', $value)) {
    return $value;
}
    return '';
}
/**
 * Шаблоны темы, доступные для страницы персоны.
 *
 * Учитываются оба механизма WordPress:
 * — классические PHP-шаблоны тем (get_page_templates, файлы *.php);
 * — блочные шаблоны FSE (get_block_templates, файлы *.html).
 *
 * Ключ возвращаемого массива самодостаточен: "php:<slug>" либо "block:<slug>".
 * Так классические и блочные шаблоны с одинаковым slug не конфликтуют, а
 * сохранённая опция однозначно говорит, какой механизм применять.
 *
 * @return array<string,array{slug:string,title:string,source:string,file:string}>
 */
public function get_person_page_templates() {
    $templates = array();

    // Служебные slug'и, которые нельзя применять к произвольному типу записи.
    $reserved = array('default', 'index', 'page', 'single', '404', 'blank');

    // 1. Классические PHP-шаблоны темы.
    //    ВАЖНО 1: берём метод темы, а не глобальную get_page_templates().
    //    WP_Theme::get_page_templates() отдаёт array( файл => название ),
    //    а глобальная функция делает array_flip — там ключом становится
    //    НАЗВАНИЕ шаблона. Название обычно на русском, и sanitize_key()
    //    вычищал его в пустую строку, из-за чего список всегда был пуст.
    //
    //    ВАЖНО 2: ядро регистрирует шаблон без заголовка
    //    "Template Post Type:" только для page и post, поэтому запрос
    //    исключительно по family_member всегда возвращает пусто. Спрашиваем
    //    и family_member, и page — получаем ровно тот набор, который виден
    //    при редактировании страниц.
    $classic = array();
    if (function_exists('wp_get_theme')) {
        $theme_obj = wp_get_theme();
        if (is_object($theme_obj) && method_exists($theme_obj, 'get_page_templates')) {
            foreach (array('family_member', 'page') as $ft_ctype) {
                $found = $theme_obj->get_page_templates(null, $ft_ctype);
                if (!is_array($found)) {
                    continue;
                }
                foreach ($found as $file => $title) {
                    $file = (string) $file;
                    if ('' === $file || isset($classic[$file])) {
                        continue;
                    }
                    $classic[$file] = (string) $title;
                }
            }
        }
    }
    if (is_array($classic)) {
        foreach ($classic as $file => $title) {
            $slug = sanitize_key( preg_replace('/\.php$/i', '', basename((string) $file)) );
            if ('' === $slug || in_array($slug, $reserved, true)) {
                continue;
            }
            $templates['php:' . $slug] = array(
                'slug'   => $slug,
                'title'  => ('' !== (string) $title) ? (string) $title : $slug,
                'source' => 'php',
                'file'   => (string) $file,
            );
        }
    }

    // 2. Блочные шаблоны FSE.
    //    Редактор WordPress берёт их через
    //    get_block_templates( array( 'post_type' => ... ), 'wp_template' )
    //    (см. WP_REST_Templates_Controller::get_items()).
    //    Запрашиваем и family_member, и page: так в список попадают ровно те
    //    шаблоны, которые видны при редактировании обычных страниц.
    if (function_exists('get_block_templates')) {
        $seen = array();
        foreach (array('family_member', 'page') as $ft_ptype) {
            $block = get_block_templates(array('post_type' => $ft_ptype), 'wp_template');
            if (!is_array($block)) {
                continue;
            }
            foreach ($block as $tpl) {
                if (!is_object($tpl)) {
                    continue;
                }
                // Слаг блочного шаблона берём как есть: он уже нормализован
                // ядром и может быть кириллическим («внутренний»).
                // sanitize_key() вычистил бы его в пустую строку, и шаблон
                // отбросился бы как «без названия».
                $slug = isset($tpl->slug) ? trim((string) $tpl->slug) : '';
                if ('' === $slug || in_array($slug, $reserved, true)) {
                    continue;
                }
                if (in_array($slug, $seen, true)) {
                    continue;
                }
                $seen[] = $slug;
                $title = (isset($tpl->title) && '' !== (string) $tpl->title) ? (string) $tpl->title : $slug;
                $theme = (isset($tpl->theme) && '' !== (string) $tpl->theme) ? (string) $tpl->theme : '';
                $templates['block:' . $slug] = array(
                    'slug'   => $slug,
                    'title'  => $title,
                    'source' => 'block',
                    'file'   => ('' !== $theme ? $theme . '/' : '') . $slug . '.html',
                );
            }
        }
    }

    return $templates;
}
/**
 * Санитизация выбранного шаблона страницы персоны.
 * Принимает только ключ вида "php:<slug>" или "block:<slug>",
 * реально присутствующий в списке шаблонов темы.
 * @param mixed $value Значение из POST.
 * @return string
 */
public function sanitize_person_template($value) {
    $value = trim(family_tree_sanitize_str($value));
    if ('' === $value) {
        return '';
    }
    if (!preg_match('/^(?:php|block):[\p{L}\p{N}_\-]+$/u', $value)) {
        return '';
    }
    $templates = $this->get_person_page_templates();
    return isset($templates[$value]) ? $value : '';
}
/**
 * Диагностика источников шаблонов темы.
 *
 * Вызывается только когда список шаблонов пуст, чтобы не гадать, какой
 * именно механизм темы ничего не вернул.
 *
 * @return string
 */
public function get_person_templates_diagnostics() {
    $out = array();

    $theme_name = '';
    if (function_exists('wp_get_theme')) {
        $t = wp_get_theme();
        if (is_object($t)) {
            $theme_name = (string) $t->get('Name');
        }
    }
    $is_block = (function_exists('wp_is_block_theme') && wp_is_block_theme()) ? 'блочная FSE' : 'обычная';
    $out[] = 'Тема: ' . ($theme_name !== '' ? $theme_name : '?') . ' [' . $is_block . ']';
    $out[] = 'WordPress: ' . get_bloginfo('version');

    if (function_exists('wp_get_theme')) {
        $theme_obj = wp_get_theme();
        foreach (array('family_member', 'page') as $ft_ctype) {
            $found = (is_object($theme_obj) && method_exists($theme_obj, 'get_page_templates'))
                ? $theme_obj->get_page_templates(null, $ft_ctype) : array();
            $names = array();
            foreach ((array) $found as $f => $t) {
                $names[] = $f . ' => ' . $t;
            }
            $out[] = 'PHP-шаблоны «' . $ft_ctype . '»: ' . count((array) $found)
                . ($names ? ' [' . implode('; ', $names) . ']' : '');
        }
    }

    if (function_exists('get_block_templates')) {
        foreach (array('family_member', 'page') as $ft_ptype) {
            $b = get_block_templates(array('post_type' => $ft_ptype), 'wp_template');
            $names = array();
            foreach ((array) $b as $tpl) {
                if (is_object($tpl) && isset($tpl->slug)) {
                    $names[] = $tpl->slug;
                }
            }
            $out[] = 'Блочные «' . $ft_ptype . '»: ' . count((array) $b)
                . ($names ? ' [' . implode(', ', $names) . ']' : '');
        }
    } else {
        $out[] = 'get_block_templates(): функция недоступна';
    }

    return implode(' ;; ', $out);
}
/**
 * Санитизация CSS-скругления углов (border-radius).
 * Допускает от 1 до 4 значений: 8, 8px, 50%, 8px 0 4px 12px и т.п.
 * Числа без единиц принимаются как px.
 */
public function sanitize_css_radius($value) {
    $value = family_tree_sanitize_str($value);
    $value = strtolower(trim(preg_replace('/\s+/', ' ', $value)));
    if (empty($value)) {
        return '';
    }
    if ($value === 'auto') {
        return 'auto';
    }
    $parts = explode(' ', $value);
    if (count($parts) > 4) {
        return '';
    }
    $unit_re = '(px|%|vh|vw|em|rem|pt|cm|mm|in)?';
    $clean = array();
    foreach ($parts as $part) {
        if (!preg_match('/^\d+(\.\d+)?' . $unit_re . '$/', $part)) {
            return '';
        }
        $clean[] = $part;
    }
    return implode(' ', $clean);
}
/**
 * Суффиксы устройств для «box-model» параметров: пустой — Десктоп.
 *
 * @return array суффикс => устройство
 */
public static function ft_box_device_suffixes() {
    return array('' => 'desktop', '_tablet' => 'tablet', '_mobile' => 'mobile');
}
/**
 * Значения «box-model» параметра по устройствам из POST. Пустое поле Планшета
 * или Мобильных остаётся пустым — оно наследует значение с Десктопа.
 *
 * @param string $base базовое имя параметра (без суффикса устройства)
 * @param string $mode radius | size | style | color
 * @return array desktop / tablet / mobile => значение
 */
public function ft_post_box_device($base, $mode = 'radius') {
    $out = array();
    foreach (self::ft_box_device_suffixes() as $sfx => $dev) {
        $key = $base . $sfx;
        $raw = isset($_POST[$key]) ? wp_unslash($_POST[$key]) : '';
        $raw = is_scalar($raw) ? trim((string) $raw) : '';
        if ('radius' === $mode) {
            $out[$dev] = $this->sanitize_css_radius($raw);
        } elseif ('size' === $mode) {
            $out[$dev] = $this->sanitize_css_size($raw);
        } elseif ('color' === $mode) {
            $out[$dev] = $this->sanitize_tree_color($raw);
        } else {
            $out[$dev] = family_tree_sanitize_str($raw);
        }
    }
    return $out;
}
/**
 * Проверяет стиль границы по устройствам: неизвестное значение у Десктопа
 * заменяем на «сплошная», у Планшета и Мобильных — пустое поле, то есть
 * наследование с Десктопа.
 *
 * @param array $styles значения по устройствам
 * @return array значения по устройствам
 */
public function ft_box_device_style($styles) {
    $out = array();
    foreach ((array) $styles as $dev => $raw) {
        if (in_array($raw, array('solid', 'dashed', 'dotted', 'double'), true)) {
            $out[$dev] = $raw;
        } else {
            $out[$dev] = ('desktop' === $dev) ? 'solid' : '';
        }
    }
    return $out;
}
/**
 * Значения «box-model» параметров по устройствам. $map задаёт ключ значения и
 * базовое имя опции: у Планшета и Мобильных к имени добавляются суффиксы
 * _tablet и _mobile.
 *
 * @param array $map ключ => базовое имя опции
 * @return array desktop / tablet / mobile => ключ => значение
 */
public function ft_get_box_devices($map) {
    $out = array();
    foreach (self::ft_box_device_suffixes() as $sfx => $dev) {
        foreach ((array) $map as $key => $base) {
            $out[$dev][$key] = ('desktop' === $dev)
                ? (string) get_option($base, '')
                : (string) get_option($base . $sfx, '');
        }
    }
    return $out;
}
/**
 * Есть ли собственные значения Планшета или Мобильных.
 *
 * @param array $values значения по устройствам
 */
public static function ft_has_device_values($values) {
    foreach (array('tablet', 'mobile') as $dev) {
        if (empty($values[$dev])) {
            continue;
        }
        foreach ((array) $values[$dev] as $value) {
            if ('' !== trim((string) $value)) {
                return true;
            }
        }
    }
    return false;
}
/**
 * Сохраняет значения «box-model» параметра по устройствам: базовое имя — для
 * Десктопа, суффиксы _tablet и _mobile — для Планшета и Мобильных.
 *
 * @param string $base  базовое имя параметра
 * @param string $mode  radius | size | style | color
 * @return array значения по устройствам
 */
public function ft_save_box_device($base, $mode = 'radius') {
    $vals = $this->ft_post_box_device($base, $mode);
    foreach (self::ft_box_device_suffixes() as $sfx => $dev) {
        update_option($base . $sfx, $vals[$dev]);
    }
    return $vals;
}
/**
 * Значения «box-model» параметра по устройствам из опций. Устройства без
 * собственного значения наследуют Десктоп (ft_device_value()).
 *
 * @param string $base       базовое имя параметра
 * @param string $desk_value значение Десктопа, если опции ещё нет
 * @return array desktop / tablet / mobile => значение
 */
public function ft_get_box_device($base, $desk_value = '') {
    $out = array();
    foreach (self::ft_box_device_suffixes() as $sfx => $dev) {
        $out[$dev] = ('desktop' === $dev)
            ? $desk_value
            : (string) get_option($base . $sfx, '');
    }
    return $out;
}
/**
* Санитизация размеров карточек (ширина/высота в пикселях).
*/
public function sanitize_tree_int($value) {
$value = (int) family_tree_sanitize_str($value);
if ($value <= 0) {
return 100;
}
if ($value > 800) {
return 800;
}
return $value;
}
/**
* Проверка и санитизация URL заглушки фото (JPG/PNG/SVG, квадратные, не более 300x300 px).
* Возвращает массив: 'url' — допустимый URL (или '' при пустом поле), 'valid' — признак прохождения проверки, 'message' — текст ошибки.
*/
public function sanitize_placeholder_image($value) {
$url = esc_url_raw(family_tree_sanitize_str($value));
if (empty($url)) {
return array('url' => '', 'valid' => true, 'message' => '');
}
$path = (string) parse_url($url, PHP_URL_PATH);
$ext = strtolower(pathinfo($path, PATHINFO_EXTENSION));
$allowed = array('jpg', 'jpeg', 'png', 'svg');
if (!in_array($ext, $allowed, true)) {
return array('url' => '', 'valid' => false, 'message' => esc_html__('Допустимые форматы заглушек: JPG, PNG, SVG.', 'genius-family-tree'));
}
if ('svg' !== $ext) {
$attachment_id = attachment_url_to_postid($url);
if ($attachment_id) {
$meta = wp_get_attachment_metadata($attachment_id);
if (is_array($meta) && !empty($meta['width']) && !empty($meta['height'])) {
$width = (int) $meta['width'];
$height = (int) $meta['height'];
if ($width > 300 || $height > 300) {
return array('url' => '', 'valid' => false, 'message' => esc_html__('Изображение заглушки должно быть не более 300x300 px.', 'genius-family-tree'));
}
if ($width !== $height) {
return array('url' => '', 'valid' => false, 'message' => esc_html__('Изображение заглушки должно быть квадратным (1:1).', 'genius-family-tree'));
}
}
}
}
return array('url' => $url, 'valid' => true, 'message' => '');
}
/**
* Санитизация числовых параметров оформления персоналий (скругление углов, толщина границы).
*/
public function sanitize_tree_dimension($value, $min = 0, $max = 200, $default = 0) {
$value = (int) family_tree_sanitize_str($value);
if ($value < $min) {
return $min;
}
if ($value > $max) {
return $max;
}
return $value;
}
/**
* Санитизация стиля линии границы (solid, dashed, dotted).
*/
public function sanitize_border_style($value) {
$value = family_tree_sanitize_str($value);
$allowed = array('solid', 'dashed', 'dotted', 'double');
return in_array($value, $allowed, true) ? $value : '';
}
