'Montserrat' => array(300, 400, 500, 600, 700),
'Playfair Display' => array(400, 500, 600, 700, 800, 900),
'Lora' => array(400, 500, 600, 700),
'Merriweather' => array(300, 400, 700, 900),
'PT Serif' => array(400, 700),
'Oswald' => array(300, 400, 500, 600, 700),
'Raleway' => array(300, 400, 500, 600, 700),
'Cormorant' => array(300, 400, 500, 600, 700),
'EB Garamond' => array(400, 500, 600, 700, 800),
'Exo 2' => array(300, 400, 500, 600, 700),
'Alegreya' => array(400, 500, 700, 800, 900),
'Noto Serif' => array(400, 500, 600, 700),
'Caveat' => array(400, 600, 700),
'Pacifico' => array(400),
);
if (isset($map[$font])) {
return $map[$font];
}
return array(400, 700);
}
/**
* HTML опций селекта толщины для выбранной гарнитуры.
*/
    public static function render_font_weight_options($font, $selected_weight, $empty_label = '') {
    $weights = self::get_font_weights($font);
    $out = '<option value="0" ' . selected((string) $selected_weight, '0', false) . '>' . esc_html('' !== $empty_label ? $empty_label : __('По умолчанию', 'genius-family-tree')) . '</option>';
foreach ($weights as $w) {
$w = (int) $w;
$out .= '<option value="' . esc_attr($w) . '" ' . selected((string) $selected_weight, (string) $w, false) . '>' . esc_html($w) . '</option>';
}
return $out;
}
public function init() {
// Регистрация типа записи
Family_Tree_Post_Type::register();
// Регистрация метабоксов
Family_Tree_Meta_Boxes::init();
// Регистрация AJAX обработчиков
Family_Tree_Ajax::init();
// Регистрация шорткода
Family_Tree_Shortcode::init();
// Правила перезаписи для семейного архива
$this->register_archive_rewrite_rules();
// Блоки Гутенберга для быстрой вставки шорткодов семейного архива
$this->register_archive_blocks();
// Гарантируем, что heartbeat-проверка лицензии запланирована (в т.ч. после обновления плагина)
if (!wp_next_scheduled('family_tree_license_heartbeat')) {
$this->schedule_license_cron();
}
}
/**
 * Регистрирует правила перезаписи для подразделов семейного архива.
 * Правила строятся для каждого включённого раздела:
 * /{archive-slug}/{section}/
 * /{archive-slug}/{section}/{member-slug}/
 * /{archive-slug}/{section}/{member-slug}/{album-slug}/
 * /{archive-slug}/{section}/{member-slug}/{album-slug}/{photo-slug}/
 * ВАЖНО: маршруты архива не пересекаются с премалинками персон
 * (CTP family-member), поэтому страницы персон не затронуты.
 */
private function register_archive_rewrite_rules() {
    add_rewrite_tag('%ft_section%', '([^/]+)');
    add_rewrite_tag('%ft_member%', '([^/]+)');
    add_rewrite_tag('%ft_album%', '([^/]+)');
    add_rewrite_tag('%ft_photo%', '([^/]+)');
    $sections = array();
    $sections_meta = ft_get_archive_sections();
    if (is_array($sections_meta)) {
        foreach ($sections_meta as $sec_id => $sec_cfg) {
            if (empty($sec_cfg['enabled'])) {
                continue;
            }
            $sections[] = sanitize_key($sec_id);
        }
    }
    $sections = array_unique($sections);
    if (empty($sections)) {
        $sections = array('photoalbums');
    }
    if (!in_array('photoalbums', $sections, true)) {
        $sections[] = 'photoalbums';
    }
    foreach ($sections as $sec) {
        $qsec = preg_quote($sec, '~');
        // Каталог раздела: /{archive-slug}/{section}/
        add_rewrite_rule('^([^/]+)/' . $qsec . '/?$', 'index.php?pagename=$matches[1]&ft_section=' . $sec, 'top');
        // Папки/альбомы конкретной персоны: /{archive-slug}/{section}/{member-slug}/
        add_rewrite_rule('^([^/]+)/' . $qsec . '/([^/]+)/?$', 'index.php?pagename=$matches[1]&ft_section=' . $sec . '&ft_member=$matches[2]', 'top');
        // Отдельная папка/альбом персоны: /{archive-slug}/{section}/{member-slug}/{album-slug}/
        add_rewrite_rule('^([^/]+)/' . $qsec . '/([^/]+)/([^/]+)/?$', 'index.php?pagename=$matches[1]&ft_section=' . $sec . '&ft_member=$matches[2]&ft_album=$matches[3]', 'top');
        // Отдельное фото/файл персоны: /{archive-slug}/{section}/{member-slug}/{album-slug}/{photo-slug}/
        // (top-правило добавляется позже всех — оказывается первым в списке проверки)
        add_rewrite_rule('^([^/]+)/' . $qsec . '/([^/]+)/([^/]+)/([^/]+)/?$', 'index.php?pagename=$matches[1]&ft_section=' . $sec . '&ft_member=$matches[2]&ft_album=$matches[3]&ft_photo=$matches[4]', 'top');
    }
}
/**
 * Разовое обновление правил перезаписи (только в админке, безопасно).
 * Запускается один раз после обновления плагина, чтобы «прошить»
 * новые правила архива в базу и не трогать премалинки персон.
 */
public function maybe_flush_archive_rewrite_rules() {
    if (!get_option('family_tree_rewrite_rules_v6')) {
        $this->register_archive_rewrite_rules();
        flush_rewrite_rules();
        update_option('family_tree_rewrite_rules_v6', 1);
    }
}
/**
 * Добавляет кастомные query-переменные для архивных подразделов.
 */
public function archive_query_vars($vars) {
    $vars[] = 'ft_section';
    $vars[] = 'ft_member';
    $vars[] = 'ft_album';
    $vars[] = 'ft_photo';
    return $vars;
}
/**
 * Подменяет шаблон для подразделов семейного архива.
 */
public function archive_template_include($template) {
    $ft_section = get_query_var('ft_section');
    if (empty($ft_section)) {
        return $template;
    }
    $ft_sec_cfg = ft_get_archive_sections();
    if (!isset($ft_sec_cfg[$ft_section]) || empty($ft_sec_cfg[$ft_section]['enabled'])) {
        return $template;
    }
    $member_slug = get_query_var('ft_member');
    if (!empty($member_slug)) {
        $member = get_page_by_path($member_slug, OBJECT, 'family_member');
        if ($member) {
            $this->current_archive_member = $member;
            // Отдельная страница фото — единый шаблон для ВСЕХ разделов
            if (!empty(get_query_var('ft_photo'))) {
                $custom = FAMILY_TREE_PLUGIN_DIR . 'templates/single-photo.php';
                return file_exists($custom) ? $custom : $template;
            }
            if ('photoalbums' === $ft_section) {
                // Страница альбомов конкретной персоны (фотоальбомы)
                $custom = FAMILY_TREE_PLUGIN_DIR . 'templates/archive-member-albums.php';
                return file_exists($custom) ? $custom : $template;
            }
            // Страница папок/альбомов конкретной персоны в не-фотоальбомном разделе
            $custom = FAMILY_TREE_PLUGIN_DIR . 'templates/archive-member-section.php';
            return file_exists($custom) ? $custom : $template;
        }
    }
    // Каталог персон по алфавиту — единый шаблон для ВСЕХ разделов.
    // Оболочка темы настраивается самим archive-section.php перед header().
    $custom = FAMILY_TREE_PLUGIN_DIR . 'templates/archive-section.php';
    return file_exists($custom) ? $custom : $template;
}
/**
 * Применяет выбранную для алфавитного каталога оболочку темы.
 *
 * Вызывается из archive-section.php непосредственно перед выводом header,
 * чтобы выбор гарантированно влиял на часть темы, которая будет отрисована.
 */
public function prepare_catalog_page_template() {
    $selected = get_option('family_tree_catalog_template', '');
    if (!is_string($selected) || '' === $selected) {
        return;
    }
    $templates = $this->get_person_page_templates();
    if (!isset($templates[$selected])) {
        return;
    }
    $tpl = $templates[$selected];
    if ('block' === $tpl['source']) {
        Family_Tree_Template_Compat::set_template_slug($tpl['slug']);
    } else {
        $this->apply_classic_template_shell($tpl['file']);
    }
}
/**
 * Корректирует хлебные крошки Yoast для страниц семейного архива.
 * Цепочка: Главная » Семейный архив » {Раздел} » {Персона} » {Папка} » {Фото}
 */
public function yoast_archive_breadcrumbs($crumbs) {
    if (is_admin()) return $crumbs;
    $section = get_query_var('ft_section');
    if (empty($section)) {
        return $crumbs;
    }
    $ft_secs = ft_get_archive_sections();
    if (!isset($ft_secs[$section]) || empty($ft_secs[$section]['enabled'])) {
        return $crumbs;
    }
    $archive_id = get_option('family_tree_archive_page_id', 0);
    $archive_url = $archive_id ? untrailingslashit(get_permalink($archive_id)) : '';
    $trail = array();
    $inserted = false;
    foreach ($crumbs as $crumb) {
        $trail[] = $crumb;
        if (!$inserted && $archive_url && !empty($crumb['url']) && untrailingslashit($crumb['url']) === $archive_url) {
            $trail = array_merge($trail, $this->archive_breadcrumb_items());
            $inserted = true;
        }
    }
    if (!$inserted) {
        // Страница архива не найдена в крошках — строим цепочку вручную
        $trail = array();
        if (!empty($crumbs[0]['url'])) {
            $trail[] = $crumbs[0];
        }
        $trail[] = array(
            'text' => $archive_id ? get_the_title($archive_id) : __('Семейный архив', 'genius-family-tree'),
            'url'  => $archive_url,
        );
        $trail = array_merge($trail, $this->archive_breadcrumb_items());
    }
    return $trail;
}
/**
 * Дополнительные звенья цепочки для текущей страницы архива.
 * Работает для любого включённого раздела.
 */
private function archive_breadcrumb_items() {
    if (is_admin()) return array();
    $items = array();
    $section = get_query_var('ft_section');
    if (empty($section)) {
        return $items;
    }
    $ft_secs = ft_get_archive_sections();
    if (!isset($ft_secs[$section]) || empty($ft_secs[$section]['enabled'])) {
        return $items;
    }
    $terms = ft_archive_section_terms($section);
    $items[] = array(
        'text' => !empty($ft_secs[$section]['title']) ? $ft_secs[$section]['title'] : $terms['name'],
        'url'  => $this->get_archive_page_url($section),
    );
    $member_slug = get_query_var('ft_member');
    if ($member_slug) {
        $member = get_page_by_path($member_slug, OBJECT, 'family_member');
        if ($member) {
            $items[] = array(
                'text' => get_the_title($member->ID),
                'url'  => $this->get_member_section_url($member, $section),
            );
            $album_slug = get_query_var('ft_album');
            if ($album_slug) {
                foreach (ft_get_albums($member->ID, $section) as $a) {
                    if (sanitize_title($a['name']) === $album_slug) {
                        $items[] = array(
                            'text' => $a['name'],
                            'url'  => $this->get_member_section_folder_url($member, $section, $a['name']),
                        );
                        // Текущее фото — завершающее звено цепочки
                        $photo_slug = get_query_var('ft_photo');
                        if ($photo_slug && !empty($a['photos'])) {
                            foreach (array_map('intval', $a['photos']) as $pid) {
                                if (!wp_attachment_is_image($pid)) continue;
                                if (get_post_field('post_name', $pid) === $photo_slug || (string) $photo_slug === (string) $pid) {
                                    $caption = get_the_title($pid);
                                    $items[] = array(
                                        'text' => $caption ? $caption : __('Фото', 'genius-family-tree'),
                                        'url'  => '',
                                    );
                                    break;
                                }
                            }
                        }
                        break;
                    }
                }
            }
        }
    }
    return $items;
}
