/**
 * Регистрирует серверную часть блоков Гутенберга «Genius Family Tree».
 * Каждый блок рендерится через соответствующий шорткод архива.
 */
private function register_archive_blocks() {
    foreach ($this->archive_block_defs() as $name => $def) {
        $attr_schema = array();
        foreach ($def['attrs'] as $key => $field) {
            $attr_schema[$key] = array(
                'type'    => 'string',
                'default' => '',
            );
        }
        register_block_type($name, array(
            'api_version'    => 2,
            'title'          => $def['label'],
            'category'       => 'gft-archive',
            'icon'           => 'portfolio',
            'keywords'       => $def['keywords'],
            'editor_script'  => 'gft-archive-helper-editor',
            'render_callback'=> array($this, 'render_archive_block'),
            'attributes'     => $attr_schema,
        ));
    }
}
/**
 * Фронтенд-вывод блока: превращает блок в шорткод семейного архива.
 */
public function render_archive_block($attributes, $content, $block) {
    $defs = $this->archive_block_defs();
    $name = $block->name;
    if (!isset($defs[$name])) {
        return '';
    }
    $def = $defs[$name];
    $attributes = is_array($attributes) ? $attributes : array();
    $parts = array();
    foreach ($def['attrs'] as $key => $field) {
        $val = isset($attributes[$key]) ? (string) $attributes[$key] : '';
        if ('' !== $val) {
            $parts[] = $key . '="' . esc_attr($val) . '"';
        }
    }
    $shortcode = $def['shortcode'] . ( $parts ? ' ' . implode(' ', $parts) : '' );
    if ('family_tree' === $def['shortcode']) {
        $this->enqueue_family_tree_assets();
    }
    return do_shortcode('[' . $shortcode . ']');
}
/**
 * Подключает стили/скрипты семейного древа и локализацию.
 * Вызывается из enqueue_scripts() при детекте блока и прямо из рендера блока —
 * гарантирует, что древо оживает на фронтенде.
 */
private function enqueue_family_tree_assets() {
    wp_enqueue_style('family-tree-style', FAMILY_TREE_PLUGIN_URL . 'assets/css/family-tree.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/family-tree.css'));
    wp_enqueue_script('d3', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/d3.min.js', array(), '1.0.0', true);
    wp_enqueue_script('family-chart', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/family-chart.min.js', array('d3'), '1.0.0', true);
    wp_enqueue_script('family-tree-script', FAMILY_TREE_PLUGIN_URL . 'assets/js/family-tree.js', array('family-chart'), '1.4.4', true);
    wp_localize_script('family-tree-script', 'familyTreeAjax', array(
        'ajaxurl' => admin_url('admin-ajax.php'),
        'nonce' => wp_create_nonce('family_tree_nonce'),
        'plugin_url' => FAMILY_TREE_PLUGIN_URL,
        'silhouette_man' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-man.svg',
        'silhouette_woman' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-woman.svg',
        'logo_url' => FAMILY_TREE_PLUGIN_URL . 'assets/images/logo.svg',
        'site_url' => home_url(),
        'root_member_id' => $this->get_root_member_id(),
        'card_width' => (int) get_option('family_tree_card_width', 220),
        'card_height' => (int) get_option('family_tree_card_height', 100),
        'disable_wheel_zoom' => (int) get_option('family_tree_disable_wheel_zoom', 0),
        'toolbar_position' => get_option('family_tree_toolbar_position', 'bottom-right'),
        'toolbar_icon_color' => get_option('family_tree_toolbar_icon_color', ''),
        'toolbar_icon_color_hover' => get_option('family_tree_toolbar_icon_color_hover', ''),
        'toolbar_btn_bg' => get_option('family_tree_toolbar_btn_bg', ''),
        'toolbar_btn_bg_hover' => get_option('family_tree_toolbar_btn_bg_hover', '')
    ));
}
