/**
 * Скрипт согласия на публикацию данных (ФЗ-152) для редактора персоны.
 * Подключается ВНУТРЬ блочного редактора (в т.ч. в iframe-режиме WP 6.9+/7.x),
 * блокирует сохранение/публикацию через штатный API wp.data, пока согласие
 * не подтверждено в родительском документе.
 */
public function enqueue_family_member_consent_editor_assets() {
    $screen = function_exists('get_current_screen') ? get_current_screen() : null;
    if ($screen && isset($screen->post_type) && $screen->post_type !== 'family_member') {
        return;
    }
    $post = get_post();
    $post_id = (is_object($post) && isset($post->ID)) ? (int) $post->ID : 0;
    $given = $post_id ? (bool) get_post_meta($post_id, '_family_member_consent', true) : false;
    wp_enqueue_script(
        'family-tree-consent-editor',
        FAMILY_TREE_PLUGIN_URL . 'assets/js/editor-consent.js',
        array('wp-data', 'wp-dom-ready'),
        (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/editor-consent.js'),
        true
    );
    wp_localize_script('family-tree-consent-editor', 'familyTreeConsentEditor', array(
        'postId'  => $post_id,
        'given'   => $given,
        'hint'    => __('Подтвердите согласие на публикацию данных, поставив галочку в блоке «Согласие на публикацию данных».', 'genius-family-tree'),
    ));
}

/**
 * Пункты быстрой вставки блоков семейного архива для темизации JS.
 * Каждый пункт: имя блока, название, иконка (SVG, stroke currentColor — красится в зелёный),
 * поля настроек и обязательные атрибуты.
 */
private function archive_helper_items() {
    $items = array();
    foreach ($this->archive_block_defs() as $name => $def) {
        $fields = array();
        foreach ($def['attrs'] as $key => $field) {
            $fields[] = array(
                'key'   => $key,
                'type'  => isset($field['type']) ? $field['type'] : 'text',
                'label' => $field['label'],
                'help'  => isset($field['help']) ? $field['help'] : '',
            );
        }
        $items[] = array(
            'name'      => $name,
            'label'     => $def['label'],
            'shortcode' => '[' . $def['shortcode'] . ']',
            'icon'      => $def['icon'],
            'attrs'     => $fields,
            'required'  => $def['required'],
            'keywords'  => $def['keywords'],
        );
    }
    return $items;
}
/**
 * Список персон для выпадающих списков блоков Гутенберга.
 * У каждой персоны: ID (value), slug и её фотоальбомы (для выбора альбома).
 */
private function archive_picker_members() {
    $members = get_posts(array(
        'post_type'      => 'family_member',
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'nopaging'       => true,
        'no_found_rows'  => true,
        'orderby'        => 'title',
        'order'          => 'ASC',
    ));
    $list = array();
    foreach ($members as $member) {
        $slug = $member->post_name;
        // WP хранит кириллические slugs в URL-кодированном виде (%d0%b3…) —
        // для показа в выпадающем списке декодируем, оставляя человекочитаемым
        $display_slug = ( false !== strpos($slug, '%') ) ? rawurldecode($slug) : $slug;
        $label = trim($member->post_title);
        if ($slug && false === mb_stripos($label, $display_slug, 0, 'UTF-8')) {
            $label .= ' (' . $display_slug . ')';
        }
        $albums = array();
        foreach (ft_get_albums($member->ID) as $album) {
            if (empty($album['photos'])) {
                continue;
            }
            $albums[] = array(
                'value' => sanitize_title($album['name']),
                'label' => $album['name'] . ' (' . count($album['photos']) . ')',
            );
        }
        $list[] = array(
            'value'  => (string) $member->ID,
            'slug'   => $display_slug,
            'label'  => $label,
            'albums' => $albums,
        );
    }
    return $list;
}
/**
 * Список семейных групп для выпадающего списка блока «Древо».
 */
private function archive_picker_groups() {
    $groups = get_posts(array(
        'post_type'      => 'family_group',
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'no_found_rows'  => true,
        'orderby'        => 'title',
        'order'          => 'ASC',
    ));
    $list = array();
    foreach ($groups as $group) {
        $list[] = array(
            'value' => (string) $group->ID,
            'label' => $group->post_title,
        );
    }
    return $list;
}
    public function activate() {
        // Регистрируем тип записи и пересохраняем правила
        Family_Tree_Post_Type::register();
        flush_rewrite_rules();
        // Создаем семейную группу "Без названия" по умолчанию
        $this->create_default_family_group();
        // Добавляем индексы для часто используемых мета-ключей
        $this->add_performance_indexes();
        // Планируем фоновую перевалидацию лицензии
        $this->schedule_license_cron();
        // Создаём страницу «Семейный архив» на фронтенде
        $this->create_archive_page();
        // ФЗ-152: новая «эпоха» согласия — модальное окно с документами
        // появится заново при каждой активации плагина.
        update_option('family_tree_terms_epoch', (string) time());
    }
    /**
     * Добавляет индексы в таблицу postmeta для ускорения часто используемых запросов
     */
    private function add_performance_indexes() {
        global $wpdb;
        $table = $wpdb->postmeta;
        $index_map = array(
            '_family_member_group_id' => 'idx_ft_group_id',
            '_family_member_is_root' => 'idx_ft_is_root',
            '_family_member_father' => 'idx_ft_father',
            '_family_member_mother' => 'idx_ft_mother',
        );
        foreach ($index_map as $meta_key => $index_name) {
            // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching, WordPress.DB.PreparedSQL.InterpolatedNotPrepared
            $exists = $wpdb->get_results($wpdb->prepare("SHOW INDEX FROM `$table` WHERE Key_name = %s", $index_name));
            if (empty($exists)) {
                // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching, WordPress.DB.DirectDatabaseQuery.SchemaChange, WordPress.DB.PreparedSQL.InterpolatedNotPrepared
                $wpdb->query($wpdb->prepare("ALTER TABLE `$table` ADD INDEX `$index_name` (`meta_key`(191), `meta_value`(20))"));
            }
        }
    }
/**
 * Создаёт публичную страницу «Семейный архив» на фронтенде.
 */
private function create_archive_page() {
    $page_id = get_option('family_tree_archive_page_id', 0);
    if ($page_id && get_post_status($page_id) === 'publish') {
        return;
    }
    $page_id = wp_insert_post(array(
        'post_type'     => 'page',
        'post_title'    => __('Семейный архив', 'genius-family-tree'),
        'post_name'     => 'family-archive',
        'post_content'  => '[family_archive]',
        'post_status'   => 'publish',
        'comment_status'=> 'closed',
        'ping_status'   => 'closed',
    ));
    if ($page_id && !is_wp_error($page_id)) {
        update_option('family_tree_archive_page_id', $page_id);
    }
}
/**
 * Проверяет existence страницы «Семейный архив» при загрузке админки.
 */
public function ensure_archive_page_exists() {
    $page_id = (int) get_option('family_tree_archive_page_id', 0);
    if (!$page_id || get_post_status($page_id) !== 'publish') {
        $this->create_archive_page();
        $page_id = (int) get_option('family_tree_archive_page_id', 0);
    }
    if (!$page_id) {
        return;
    }
    // Приводим slug страницы к «family-archive» (если slug свободен)
    $current_slug = get_post_field('post_name', $page_id);
    if ($current_slug && $current_slug !== 'family-archive') {
        $collision = get_posts(array(
            'post_type'      => 'page',
            'name'           => 'family-archive',
            'post_status'    => 'any',
            'posts_per_page' => 1,
            'fields'         => 'ids',
        ));
        if (empty($collision) || (int) $collision[0] === $page_id) {
            wp_update_post(array('ID' => $page_id, 'post_name' => 'family-archive'));
        }
    }
}
/**
* Создает семейную группу по умолчанию и переносит в неё все персоналии без группы
*/
private function create_default_family_group() {
// Проверяем, существует ли уже группа по умолчанию
$default_group_id = get_option('family_tree_default_group_id', 0);
if ($default_group_id && get_post($default_group_id)) {
// Группа существует, проверяем нужно ли перенести персоналии без группы
$this->migrate_ungrouped_members_to_default($default_group_id);
return;
}
// Создаем новую группу
$group_id = wp_insert_post(array(
'post_type' => 'family_group',
'post_title' => __('Без названия', 'genius-family-tree'),
'post_status' => 'publish'
));
if ($group_id && !is_wp_error($group_id)) {
update_option('family_tree_default_group_id', $group_id);
// Переносим все персоналии без группы в новую группу по умолчанию
$this->migrate_ungrouped_members_to_default($group_id);
} else {
// Если создание группы не удалось, всё равно пытаемся мигрировать персоналии
// на случай если группа была создана вручную
$existing_groups = get_posts(array(
'post_type' => 'family_group',
'posts_per_page' => 1,
'post_status' => 'any',
'fields' => 'ids'
));
if (!empty($existing_groups)) {
update_option('family_tree_default_group_id', $existing_groups[0]);
$this->migrate_ungrouped_members_to_default($existing_groups[0]);
}
}
}
/**
* Находит или создает семейную группу по названию
*/
private function get_or_create_family_group_by_name($group_name) {
$group_name = sanitize_text_field($group_name);
if ($group_name === '') {
return 0;
}
$existing_groups = get_posts(array(
'post_type' => 'family_group',
'posts_per_page' => 1,
'post_status' => 'any',
'title' => $group_name
));
if (!empty($existing_groups)) {
return (int) $existing_groups[0]->ID;
}
$group_id = wp_insert_post(array(
'post_type' => 'family_group',
'post_title' => $group_name,
'post_status' => 'publish'
), true);
if (is_wp_error($group_id)) {
return 0;
}
return (int) $group_id;
}
public function deactivate() {
// Очищаем правила пермалинков
flush_rewrite_rules();
// Убираем фоновую перевалидацию лицензии
$this->clear_license_cron();
// При деактивации плагина пытаемся деактивировать лицензию на сервере
$license_key = get_option('family_tree_license_key', '');
if (!empty($license_key)) {
$this->deactivate_license_on_server($license_key);
// Отправляем данные о деактивации
$this->send_activation_data($license_key, false);
}
}
/**
* Отправляет запрос на сервер для деактивации лицензии при деактивации плагина
*/
private function deactivate_license_on_server($license_key) {
$api_url = 'https://xn----8sbbdpda1c7cwf.xn--p1ai/wp-json/family-tree/v1/deactivate-license';
$site_url = home_url();
$timestamp = time();
$response = wp_remote_post($api_url, array(
'timeout' => 15,
'body' => array(
'license_key' => $license_key,
'site_url' => $site_url,
'timestamp' => $timestamp,
'signature' => hash_hmac('sha256', 'deactivate|' . $site_url . '|' . $timestamp, $license_key),
)
));
}
public function enqueue_scripts() {
// Для страниц персон не загружаем скрипты древа вообще
if (is_singular('family_member')) {
// Загружаем только базовые стили
        wp_enqueue_style('family-tree-style', FAMILY_TREE_PLUGIN_URL . 'assets/css/family-tree.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/family-tree.css'));
        // Официальный лайтбокс (GLightbox) для фотоальбомов
        wp_enqueue_style('glightbox', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/glightbox.min.css', array(), '3.3.0');
        wp_enqueue_script('glightbox', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/glightbox.min.js', array(), '3.3.0', true);
        // Инициализация лайтбокса и прокрутки карусели альбома
        wp_enqueue_script('family-tree-album', FAMILY_TREE_PLUGIN_URL . 'assets/js/family-album.js', array('glightbox'), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/family-album.js'), true);
        return;
}
// Не загружаем скрипты в админке
if (is_admin()) {
return;
}
// Страницы с альбомными блоками Гутенберга и подразделы архива /photoalbums/…
// подключают лайтбокс и карусель альбомов
if (is_page() || is_single()) {
global $post;
$is_album_subpage = ('' !== get_query_var('ft_section'));
if ($post && (
    $is_album_subpage ||
    strpos($post->post_content, '<!-- wp:genius-tree/archive-all-albums') !== false ||
    strpos($post->post_content, '<!-- wp:genius-tree/member-albums') !== false ||
    strpos($post->post_content, '<!-- wp:genius-tree/single-album') !== false
)) {
    wp_enqueue_style('glightbox', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/glightbox.min.css', array(), '3.3.0');
    wp_enqueue_script('glightbox', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/glightbox.min.js', array(), '3.3.0', true);
    wp_enqueue_script('family-tree-album', FAMILY_TREE_PLUGIN_URL . 'assets/js/family-album.js', array('glightbox'), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/family-album.js'), true);
}
}
// Проверяем, есть ли шорткод на странице
$should_load_scripts = $this->should_load_family_tree_scripts();
// Загружаем скрипты только если они действительно нужны
if ($should_load_scripts) {
    $this->enqueue_family_tree_assets();
} else {
// Загружаем только стили
wp_enqueue_style('family-tree-style', FAMILY_TREE_PLUGIN_URL . 'assets/css/family-tree.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/family-tree.css'));
}
}
