/**
* Выводит пользовательские стили страниц отдельных персон (фон, текст, шрифт, кнопки, ссылки)
*/
public function output_person_styles() {
if (is_admin() || !is_singular('family_member')) {
return;
}
$bg = get_option('family_tree_person_bg', '');
$bg_type = get_option('family_tree_person_bg_type', 'classic');
$bg_gradient = get_option('family_tree_person_bg_gradient', '');
$bg_image = get_option('family_tree_person_bg_image', '');
$container_margin = get_option('family_tree_person_container_margin', '16px');
$container_padding = get_option('family_tree_person_container_padding', '16px');
if ('' === trim((string) $container_margin)) { $container_margin = '16px'; }
if ('' === trim((string) $container_padding)) { $container_padding = '16px'; }
$container_radius = get_option('family_tree_person_container_radius', '');
$container_border_width = get_option('family_tree_person_container_border_width', '');
$container_border_style = get_option('family_tree_person_container_border_style', 'solid');
$container_border_color = get_option('family_tree_person_container_border_color', '');
$blocks_bg = get_option('family_tree_person_blocks_bg', '');
$blocks_bg_type = get_option('family_tree_person_blocks_bg_type', 'classic');
$blocks_bg_gradient = get_option('family_tree_person_blocks_bg_gradient', '');
$blocks_bg_image = get_option('family_tree_person_blocks_bg_image', '');
$blocks_margin = get_option('family_tree_person_blocks_margin', '16px');
$blocks_padding = get_option('family_tree_person_blocks_padding', '16px');
if ('' === trim((string) $blocks_margin)) { $blocks_margin = '16px'; }
if ('' === trim((string) $blocks_padding)) { $blocks_padding = '16px'; }
$blocks_radius = get_option('family_tree_person_blocks_radius', '');
$blocks_border_width = get_option('family_tree_person_blocks_border_width', '');
$blocks_border_style = get_option('family_tree_person_blocks_border_style', 'solid');
$blocks_border_color = get_option('family_tree_person_blocks_border_color', '');
$tree_button = get_option('family_tree_person_tree_button', '');
$tree_button_text_color = get_option('family_tree_person_tree_button_text_color', '');
$tree_button_font_family = get_option('family_tree_person_tree_button_font_family', '');
$tree_button_font_size = family_tree_font_size_value('family_tree_person_tree_button_font_size', 14);
$link = get_option('family_tree_person_link', '');
$header_font_family = get_option('family_tree_person_header_font_family', '');
$header_font_size = family_tree_font_size_value('family_tree_person_header_font_size', 32);
$header_font_size_tablet = family_tree_font_size_value('family_tree_person_header_font_size_tablet', 28);
$header_font_size_mobile = family_tree_font_size_value('family_tree_person_header_font_size_mobile', 24);
$header_title_color = get_option('family_tree_person_header_title_color', '');
    $header_font_weight = (int) get_option('family_tree_person_header_font_weight', 0);
    $tree_button_font_weight = (int) get_option('family_tree_person_tree_button_font_weight', 0);
    $ft_has_bg_gradient = ('gradient' === $bg_type && !empty($bg_gradient)) || ('gradient' === $blocks_bg_type && !empty($blocks_bg_gradient));
    $ft_has_border = function ($width, $color) {
        return (!empty($width) && !empty($color));
    };
    // Контейнер и блоки персон — с табами устройств: базовые значения для
    // Десктопа и свои для Планшета (≤1024px) и Мобильных (≤767px).
    $ft_person_container_values = $this->ft_get_box_devices(array(
        'margin'       => 'family_tree_person_container_margin',
        'padding'      => 'family_tree_person_container_padding',
        'radius'       => 'family_tree_person_container_radius',
        'border-width' => 'family_tree_person_container_border_width',
        'border-style' => 'family_tree_person_container_border_style',
        'border-color' => 'family_tree_person_container_border_color',
    ));
    $ft_person_blocks_values = $this->ft_get_box_devices(array(
        'margin'       => 'family_tree_person_blocks_margin',
        'padding'      => 'family_tree_person_blocks_padding',
        'radius'       => 'family_tree_person_blocks_radius',
        'border-width' => 'family_tree_person_blocks_border_width',
        'border-style' => 'family_tree_person_blocks_border_style',
        'border-color' => 'family_tree_person_blocks_border_color',
    ));
if (empty($bg) && empty($bg_image) && empty($container_margin) && empty($container_padding) && empty($container_radius) && !$ft_has_border($container_border_width, $container_border_color) && !$ft_has_bg_gradient
    && empty($blocks_bg) && empty($blocks_bg_image) && empty($blocks_margin) && empty($blocks_padding) && '0px' === ft_radius_css($blocks_radius, '0px') && !$ft_has_border($blocks_border_width, $blocks_border_color)
    && empty($tree_button) && empty($tree_button_text_color) && empty($tree_button_font_family) && empty($tree_button_font_size) && empty($tree_button_font_weight) && empty($link)
    && empty($header_font_family) && empty($header_font_size) && empty($header_font_size_tablet) && empty($header_font_size_mobile)
    && empty($header_title_color) && empty($header_font_weight)
    && ft_phs_is_empty(ft_get_person_header_settings())
    && ft_pms_is_empty(ft_get_person_sidebar_settings())
    && !self::ft_has_device_values($ft_person_container_values)
    && !self::ft_has_device_values($ft_person_blocks_values)) {
    return;
}
$css = '';
$ft_border_style = function ($value) {
    return in_array($value, array('solid', 'dashed', 'dotted', 'double'), true) ? $value : 'solid';
};
// Фон и геометрия контейнера страницы персоны.
$ft_person_bg_parts = '';
if (!empty($bg_image)) {
    $ft_person_bg_parts .= ' background-image: url(\'' . esc_url($bg_image) . '\') !important;';
    $ft_person_bg_parts .= ' background-size: cover !important;';
    $ft_person_bg_parts .= ' background-position: center center !important;';
    $ft_person_bg_parts .= ' background-repeat: no-repeat !important;';
}
if ('gradient' === $bg_type && !empty($bg_gradient)) {
    $ft_person_bg_parts .= ' background-image: ' . esc_html($bg_gradient) . ' !important;';
}
if (!empty($bg)) {
    $ft_person_bg_parts .= ' background-color: ' . esc_html($bg) . ' !important;';
}
if ('' !== $ft_person_bg_parts) {
    $css .= '.family-member-single {' . $ft_person_bg_parts . ' }';
}
// Контейнер персоны — с табами устройств: базовые правила для Десктопа и
// @media-правила для Планшета (≤1024px) и Мобильных (≤767px). Пустые значения
// устройства наследуют Десктоп, поэтому правило выводится всегда, когда есть
// хотя бы одно значение; при полном отсутствии значений ft_box_device_css()
// вернёт пустую строку.
$css .= ft_box_device_css('.family-member-single', $ft_person_container_values, function ($v, $dev) use ($ft_border_style, $ft_has_border) {
    $margin  = ft_device_value($v, $dev, 'margin');
    $padding = ft_device_value($v, $dev, 'padding');
    $radius  = ft_device_value($v, $dev, 'radius');
    $bwidth  = ft_device_value($v, $dev, 'border-width');
    $bcolor  = ft_device_value($v, $dev, 'border-color');
    if ('' === $margin && '' === $padding && '' === $radius && !$ft_has_border($bwidth, $bcolor)) {
        return '';
    }
    $rules = (!empty($padding) || !empty($bwidth)) ? ' box-sizing: border-box;' : '';
    if (!empty($margin)) {
        $rules .= ' margin: ' . esc_attr(ft_radius_css($margin, '16px')) . ' !important;';
    }
    if (!empty($padding)) {
        $rules .= ' padding: ' . esc_attr(ft_radius_css($padding, '16px')) . ' !important;';
    }
    if (!empty($radius)) {
        $rules .= ' border-radius: ' . esc_attr(ft_radius_css($radius, '0px')) . ' !important;';
    }
    if ($ft_has_border($bwidth, $bcolor)) {
        $rules .= ' border: ' . esc_attr(ft_border_width_css($bwidth, $ft_border_style(ft_device_value($v, $dev, 'border-style')))) . ' ' . esc_attr($ft_border_style(ft_device_value($v, $dev, 'border-style'))) . ' ' . esc_html($bcolor) . ' !important;';
    }
    return $rules;
});
// Единый набор оформления для шапки, текстовой части и сайдбара.
$ft_blocks_selectors = '.family-member-header, .family-member-content-gutenberg, .family-member-sidebar';
if (!empty($blocks_bg) || !empty($blocks_bg_image) || ('gradient' === $blocks_bg_type && !empty($blocks_bg_gradient))) {
    $ft_blocks_bg_parts = '';
    if (!empty($blocks_bg_image)) {
        $ft_blocks_bg_parts .= ' background-image: url(\'' . esc_url($blocks_bg_image) . '\') !important;';
        $ft_blocks_bg_parts .= ' background-size: cover !important;';
        $ft_blocks_bg_parts .= ' background-position: center center !important;';
        $ft_blocks_bg_parts .= ' background-repeat: no-repeat !important;';
    }
    if ('gradient' === $blocks_bg_type && !empty($blocks_bg_gradient)) {
        $ft_blocks_bg_parts .= ' background-image: ' . esc_html($blocks_bg_gradient) . ' !important;';
    }
    if (!empty($blocks_bg)) {
        $ft_blocks_bg_parts .= ' background-color: ' . esc_html($blocks_bg) . ' !important;';
