    $margin  = ft_device_value($v, $dev, 'margin');
    $padding = ft_device_value($v, $dev, 'padding');
    $radius  = ft_device_value($v, $dev, 'radius');
    $bwidth  = ft_device_value($v, $dev, 'border-width');
    $bcolor  = ft_device_value($v, $dev, 'border-color');
    if ('' === $margin && '' === $padding && '' === $radius && !$ft_has_border($bwidth, $bcolor)) {
        return '';
    }
    $rules = (!empty($padding) || !empty($bwidth)) ? ' box-sizing: border-box;' : '';
    if (!empty($margin)) {
        $rules .= ' margin: ' . esc_attr(ft_radius_css($margin, '16px')) . ' !important;';
    }
    if (!empty($padding)) {
        $rules .= ' padding: ' . esc_attr(ft_radius_css($padding, '16px')) . ' !important;';
    }
    if (!empty($radius)) {
        $rules .= ' border-radius: ' . esc_attr(ft_radius_css($radius, '0px')) . ' !important;';
    }
    if ($ft_has_border($bwidth, $bcolor)) {
        $rules .= ' border: ' . esc_attr(ft_border_width_css($bwidth, $ft_border_style(ft_device_value($v, $dev, 'border-style')))) . ' ' . esc_attr($ft_border_style(ft_device_value($v, $dev, 'border-style'))) . ' ' . esc_html($bcolor) . ' !important;';
    }
    return $rules;
});
// CSS сайдбара целиком выводит ft_person_sidebar_device_css() ниже. Раньше
