    }
    if (!empty($ft_phs_settings[$ft_phs_dev]['title']['font_family'])) {
        $ft_phs_fonts[] = $ft_phs_settings[$ft_phs_dev]['title']['font_family'];
    }
    foreach (array('normal', 'hover') as $ft_phs_state) {
        if (!empty($ft_phs_settings[$ft_phs_dev]['button'][$ft_phs_state]['font_family'])) {
            $ft_phs_fonts[] = $ft_phs_settings[$ft_phs_dev]['button'][$ft_phs_state]['font_family'];
        }
    }
}
if (!empty($link)) {
$css .= '.family-member-parents a, .family-member-siblings a, .family-member-spouses a, .family-member-children a, .family-member-sidebar a { color: ' . esc_html($link) . ' !important; }';
$css .= '.family-member-parents a:hover, .family-member-siblings a:hover, .family-member-spouses a:hover, .family-member-children a:hover, .family-member-sidebar a:hover { text-decoration: none !important; }';
$css .= '.family-member-content-gutenberg a:hover { text-decoration: none !important; }';
}
// Адаптивные настройки сайдбара. Идут после старой опции family_tree_person_link,
// чтобы новые значения перекрывали её: иначе старый общий цвет перебивал бы
// выбранный в разделе «Ссылки».
$ft_pms_settings = ft_get_person_sidebar_settings();
$ft_pms_fonts = array();
// Портрет и подпись — общие для всех устройств, поэтому их CSS идёт один раз
// и без @media, до перечисления табов устройств.
$ft_pms_img_css = ft_person_sidebar_image_css($ft_pms_settings);
if ('' !== $ft_pms_img_css) {
$css .= $ft_pms_img_css;
}
foreach (ft_device_list() as $ft_pms_dev => $ft_pms_meta) {
    $ft_pms_css = ft_wrap_media(ft_device_media($ft_pms_dev), ft_person_sidebar_device_css($ft_pms_settings, $ft_pms_dev));
    if ('' !== $ft_pms_css) {
$css .= $ft_pms_css;
    }
    foreach (array('heading', 'text') as $ft_pms_block) {
        if (!empty($ft_pms_settings[$ft_pms_dev][$ft_pms_block]['font_family'])) {
            $ft_pms_fonts[] = $ft_pms_settings[$ft_pms_dev][$ft_pms_block]['font_family'];
        }
    }
    foreach (array('normal', 'hover') as $ft_pms_state) {
        if (!empty($ft_pms_settings[$ft_pms_dev]['link'][$ft_pms_state]['font_family'])) {
            $ft_pms_fonts[] = $ft_pms_settings[$ft_pms_dev]['link'][$ft_pms_state]['font_family'];
        }
    }
}
$ft_available_google = self::get_google_fonts();
$ft_google_to_load = array();
// Гарнитуры из адаптивных настроек сайдбара (любое устройство, любое состояние).
foreach (array_unique($ft_pms_fonts) as $ft_pms_font) {
    if (isset($ft_available_google[$ft_pms_font])) {
        $ft_google_to_load[] = $ft_pms_font;
    }
}
// Гарнитуры из адаптивных настроек шапки (любое устройство, любое состояние).
foreach (array_unique($ft_phs_fonts) as $ft_phs_font) {
if (isset($ft_available_google[$ft_phs_font])) {
$ft_google_to_load[] = $ft_phs_font;
}
}
if (!empty($header_font_family) && isset($ft_available_google[$header_font_family])) {
$ft_google_to_load[] = $header_font_family;
}
if (!empty($tree_button_font_family) && isset($ft_available_google[$tree_button_font_family])) {
$ft_google_to_load[] = $tree_button_font_family;
}
$ft_google_to_load = array_unique($ft_google_to_load);
foreach ($ft_google_to_load as $ft_google_font) {
$ft_weights = self::get_font_weights($ft_google_font);
$ft_weights_str = implode(';', array_map('intval', $ft_weights));
echo '<link rel="stylesheet" href="' . esc_url('https://fonts.googleapis.com/css2?family=' . rawurlencode($ft_google_font) . ':wght@' . $ft_weights_str . '&display=swap') . '" />' . "\n";
}
?>
<style type="text/css">
<?php echo $css; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
</style>
<?php
}
/**
