/**
 * Собирает весь CSS оформления фотоальбомов/каталога (семейный архив, option family_tree_album_settings).
 * Возвращает строку CSS; параллельно выводит <link> для выбранных Google Fonts.
 */
private function build_album_display_css($s) {
    $style_whitelist = array('solid', 'dashed', 'dotted', 'double');
    $ft_border_style = function ($value) use ($style_whitelist) {
        return in_array($value, $style_whitelist, true) ? $value : 'solid';
    };
    $columns = max(1, min(8, intval($s['columns'])));
    $columns_tablet = max(1, min(8, intval($s['columns_tablet'])));
    $columns_mobile = max(1, min(8, intval($s['columns_mobile'])));
    $gap = max(0, min(60, intval($s['gap'])));
    $image_height = max(0, intval($s['image_height']));
    $has_caption_position_styles = !empty($s['caption_styles']);
    $layout = in_array($s['album_layout'], array('grid', 'tile', 'masonry', 'mosaic', 'carousel', 'carousel-fluid'), true) ? $s['album_layout'] : 'grid';
    $ratio_map = array(
        '4:3' => '4 / 3',
        '3:2' => '3 / 2',
        '16:9' => '16 / 9',
        '2:1' => '2 / 1',
        '3:1' => '3 / 1',
        '4:1' => '4 / 1',
        '3:4' => '3 / 4',
        '2:3' => '2 / 3',
        '1:1' => '1 / 1',
    );

    // CSS-переменные на контейнере
    $vars = '--ft-album-cols: ' . $columns . ';';
    $vars .= ' --ft-album-cols-tablet: ' . $columns_tablet . ';';
    $vars .= ' --ft-album-cols-mobile: ' . $columns_mobile . ';';
    if ($gap > 0) {
        $vars .= ' --ft-album-gap: ' . $gap . 'px;';
    }
    if ($image_height !== 150) {
        $vars .= ' --ft-album-img-height: ' . ($image_height > 0 ? $image_height . 'px' : 'auto') . ';';
    }
    if (!$has_caption_position_styles && intval($s['caption_padding_y']) > 0) {
        $vars .= ' --ft-caption-py: ' . intval($s['caption_padding_y']) . 'px;';
    }
    if (!$has_caption_position_styles && intval($s['caption_padding_x']) > 0) {
        $vars .= ' --ft-caption-px: ' . intval($s['caption_padding_x']) . 'px;';
    }
    if ('carousel-fluid' === $layout && intval($s['carousel_height']) > 0) {
        $vars .= ' --ft-carousel-height: ' . intval($s['carousel_height']) . 'px;';
    }
    if ('#ffffff' !== $s['carousel_btn_bg'] && !empty($s['carousel_btn_bg'])) {
        $vars .= ' --ft-album-btn-bg: ' . esc_html($s['carousel_btn_bg']) . ';';
    }
    if ('#1d2327' !== $s['carousel_btn_color'] && !empty($s['carousel_btn_color'])) {
        $vars .= ' --ft-album-btn-color: ' . esc_html($s['carousel_btn_color']) . ';';
    }
    if (1 !== intval($s['carousel_btn_border_width']) || 'double' === $ft_border_style($s['carousel_btn_border_style'])) {
        $vars .= ' --ft-album-btn-border-width: ' . esc_html(ft_border_width_css(intval($s['carousel_btn_border_width']) . 'px', $ft_border_style($s['carousel_btn_border_style']))) . ';';
    }
    if ('#dcdcde' !== $s['carousel_btn_border_color'] && !empty($s['carousel_btn_border_color'])) {
        $vars .= ' --ft-album-btn-border-color: ' . esc_html($s['carousel_btn_border_color']) . ';';
    }
    if ('solid' !== $s['carousel_btn_border_style']) {
        $vars .= ' --ft-album-btn-border-style: ' . esc_html($ft_border_style($s['carousel_btn_border_style'])) . ';';
    }
    if ('50%' !== ft_radius_css($s['carousel_btn_radius'], '50%')) {
        $vars .= ' --ft-album-btn-radius: ' . ft_radius_css($s['carousel_btn_radius'], '50%') . ';';
    }
    if (intval($s['carousel_btn_shadow'])) {
        $btn_shadow = intval($s['carousel_btn_shadow_x']) . 'px ' . intval($s['carousel_btn_shadow_y']) . 'px '
            . max(0, intval($s['carousel_btn_shadow_blur'])) . 'px ' . intval($s['carousel_btn_shadow_spread']) . 'px '
            . esc_html(!empty($s['carousel_btn_shadow_color']) ? $s['carousel_btn_shadow_color'] : 'rgba(0, 0, 0, 0.2)');
        $vars .= ' --ft-album-btn-shadow: ' . $btn_shadow . ';';
    }
    if ('8px' !== ft_radius_css($s['image_radius'], '8px')) {
        $vars .= ' --ft-album-image-radius: ' . ft_radius_css($s['image_radius'], '8px') . ';';
    }
    if (!empty($s['container_bg_color'])) {
        $vars .= ' --ft-album-bg-color: ' . esc_html($s['container_bg_color']) . ';';
    }
    if ('gradient' === $s['container_bg_type'] && !empty($s['container_bg_gradient'])) {
        $vars .= ' --ft-album-bg-gradient: ' . esc_html($s['container_bg_gradient']) . ';';
    }
    if (!empty($s['container_bg_image'])) {
        // Как «Цвет контейнера» на странице персоны: картинка поверх цвета/градиента.
        $vars .= ' --ft-album-bg-image: url(\'' . esc_url($s['container_bg_image']) . '\');';
        $vars .= ' --ft-album-bg-image-size: cover;';
        $vars .= ' --ft-album-bg-image-position: center center;';
        $vars .= ' --ft-album-bg-image-repeat: no-repeat;';
    }
    // Оформление контейнера — с табами устройств: базовые переменные для
    // Десктопа и @media-переопределения для Планшета (≤1024px) и Мобильных
    // (≤767px). Пустое поле Планшета/Мобильных наследует Десктоп.
    $ft_container_values = array();
    foreach (array('desktop' => '', 'tablet' => '_tablet', 'mobile' => '_mobile') as $ft_dev => $ft_sfx) {
        $ft_row = array();
        foreach (array('radius', 'margin', 'padding', 'border_width', 'border_style', 'border_color') as $ft_key) {
            $ft_opt = 'container_' . $ft_key;
            if ('desktop' === $ft_dev) {
                $ft_row[$ft_key] = isset($s[$ft_opt]) ? $s[$ft_opt] : '';
            } else {
                $ft_row[$ft_key] = isset($s[$ft_opt . $ft_sfx]) ? $s[$ft_opt . $ft_sfx] : '';
            }
        }
        $ft_container_values[$ft_dev] = $ft_row;
    }
    $ft_container_emit = function ($v, $dev) use ($ft_border_style) {
        $radius  = ft_device_value($v, $dev, 'radius');
        $margin  = ft_device_value($v, $dev, 'margin');
        $padding = ft_device_value($v, $dev, 'padding');
        $bwidth  = ft_device_value($v, $dev, 'border_width');
        $bcolor  = ft_device_value($v, $dev, 'border_color');
        $out = '';
        if ('' !== $radius && '0px' !== ft_radius_css($radius, '0px')) {
            $out .= ' --ft-album-radius: ' . ft_radius_css($radius, '0px') . ';';
        }
        if ('' !== $margin) {
            $out .= ' --ft-album-margin: ' . ft_radius_css($margin, '32px') . ';';
        }
        if ('' !== $padding) {
            $out .= ' --ft-album-padding: ' . ft_radius_css($padding, '20px') . ';';
        }
        if ('' !== $bwidth && '' !== $bcolor) {
            $out .= ' --ft-album-border: ' . ft_border_width_css($bwidth, $ft_border_style(ft_device_value($v, $dev, 'border_style'))) . ' ' . esc_html($ft_border_style(ft_device_value($v, $dev, 'border_style'))) . ' ' . esc_html($bcolor) . ';';
        }
        return $out;
    };
    $css = ft_box_device_css('.family-member-photo-album', $ft_container_values, $ft_container_emit);
    if ('' !== $vars) {
        $css .= '.family-member-photo-album { ' . $vars . ' }';
    }

    // Заголовок: табы устройств. Планшет и мобильный наследуют десктоп, поэтому
    // незаданное значение заменяем десктопным, а свои правила выносим в @media.
    $title_rules = array();
    // Ключи всех трёх устройств: правило разделителя появляется в $ft_sep_rules
    // только когда у устройства задано своё значение, а читаем его без isset.
    $ft_sep_rules = array('desktop' => '', 'tablet' => '', 'mobile' => '');
    foreach (array('desktop' => '', 'tablet' => '_tablet', 'mobile' => '_mobile') as $ft_t_dev => $ft_t_sfx) {
        $ft_t_rules = '';
        $ft_t_color = isset($s['title_color' . $ft_t_sfx]) ? trim((string) $s['title_color' . $ft_t_sfx]) : '';
        if ('' === $ft_t_color && 'desktop' !== $ft_t_dev) {
            $ft_t_color = $s['title_color'];
        }
        if ('' !== $ft_t_color) {
            $ft_t_rules .= ' color: ' . esc_html($ft_t_color) . ' !important;';
        }
        $ft_t_family = isset($s['title_font_family' . $ft_t_sfx]) ? trim((string) $s['title_font_family' . $ft_t_sfx]) : '';
        if ('' === $ft_t_family && 'desktop' !== $ft_t_dev) {
            $ft_t_family = $s['title_font_family'];
        }
        if ('' !== $ft_t_family) {
            $ft_t_rules .= ' font-family: \'' . esc_attr($ft_t_family) . '\', serif !important;';
        }
        $ft_t_weight = isset($s['title_font_weight' . $ft_t_sfx]) ? intval($s['title_font_weight' . $ft_t_sfx]) : 0;
        if (0 === $ft_t_weight && 'desktop' !== $ft_t_dev) {
            $ft_t_weight = intval($s['title_font_weight']);
        }
        if ($ft_t_weight > 0) {
            $ft_t_rules .= ' font-weight: ' . intval($ft_t_weight) . ' !important;';
        }
        $ft_t_size = isset($s['title_font_size' . $ft_t_sfx]) ? intval($s['title_font_size' . $ft_t_sfx]) : 0;
        if (0 === $ft_t_size && 'desktop' !== $ft_t_dev) {
            $ft_t_size = intval($s['title_font_size']);
        }
        if ($ft_t_size > 0) {
            $ft_t_rules .= ' font-size: ' . intval($ft_t_size) . 'px !important;';
        }
        $title_rules[$ft_t_dev] = $ft_t_rules;
        // Разделитель под заголовком — длинными свойствами border-bottom: полоса
        // лежит на шапке блока, а у режима без шапки — на самом заголовке,
        // поэтому селекторов два. Пустое значение у Планшета и Мобильных =
        // «не задано», то есть решение Десктопа.
        $ft_t_sep = isset($s['title_separator' . $ft_t_sfx]) ? (string) $s['title_separator' . $ft_t_sfx] : '';
        if ('' === $ft_t_sep && 'desktop' !== $ft_t_dev) {
            $ft_t_sep = isset($s['title_separator']) ? (string) $s['title_separator'] : '';
        }
        if ('' !== $ft_t_sep) {
            if ('1' === $ft_t_sep) {
                $ft_t_sep_w = isset($s['title_separator_width' . $ft_t_sfx]) ? intval($s['title_separator_width' . $ft_t_sfx]) : 0;
                if (0 === $ft_t_sep_w && 'desktop' !== $ft_t_dev) {
                    $ft_t_sep_w = isset($s['title_separator_width']) ? intval($s['title_separator_width']) : 0;
                }
                $ft_t_sep_c = isset($s['title_separator_color' . $ft_t_sfx]) ? trim((string) $s['title_separator_color' . $ft_t_sfx]) : '';
                if ('' === $ft_t_sep_c && 'desktop' !== $ft_t_dev) {
                    $ft_t_sep_c = isset($s['title_separator_color']) ? trim((string) $s['title_separator_color']) : '';
                }
                $ft_sep_rules[$ft_t_dev] = ' border-bottom-style: solid !important;'
                    . ($ft_t_sep_w > 0 ? ' border-bottom-width: ' . $ft_t_sep_w . 'px !important;' : '')
                    . ('' !== $ft_t_sep_c ? ' border-bottom-color: ' . esc_html($ft_t_sep_c) . ' !important;' : '');
            } else {
                $ft_sep_rules[$ft_t_dev] = ' border-bottom-style: none !important;';
            }
        }
    }
    if ('' !== $title_rules['desktop']) {
        $css .= '.family-member-photo-album h2 { ' . $title_rules['desktop'] . ' }';
    }
    if ('' !== $title_rules['tablet']) {
        $css .= '@media (max-width: 1024px) { .family-member-photo-album h2 { ' . $title_rules['tablet'] . ' } }';
    }
    if ('' !== $title_rules['mobile']) {
        $css .= '@media (max-width: 767px) { .family-member-photo-album h2 { ' . $title_rules['mobile'] . ' } }';
    }
    $ft_sep_sel = '.family-member-photo-album__header';
    if ('' !== $ft_sep_rules['desktop']) {
        $css .= $ft_sep_sel . ' { ' . $ft_sep_rules['desktop'] . ' }';
    }
    if ('' !== $ft_sep_rules['tablet']) {
        $css .= '@media (max-width: 1024px) { ' . $ft_sep_sel . ' { ' . $ft_sep_rules['tablet'] . ' } }';
    }
    if ('' !== $ft_sep_rules['mobile']) {
        $css .= '@media (max-width: 767px) { ' . $ft_sep_sel . ' { ' . $ft_sep_rules['mobile'] . ' } }';
    }

    $ft_subheader_box_values = array();
    $ft_subheader_typography_rules = array();
    foreach (array('desktop' => '', 'tablet' => '_tablet', 'mobile' => '_mobile') as $ft_sub_dev => $ft_sub_sfx) {
        $ft_subheader_box_values[$ft_sub_dev] = array(
            'margin'       => isset($s['subheader_box_margin' . $ft_sub_sfx]) ? $s['subheader_box_margin' . $ft_sub_sfx] : '',
            'padding'      => isset($s['subheader_box_padding' . $ft_sub_sfx]) ? $s['subheader_box_padding' . $ft_sub_sfx] : '',
            'radius'       => isset($s['subheader_box_radius' . $ft_sub_sfx]) ? $s['subheader_box_radius' . $ft_sub_sfx] : '',
            'border'       => isset($s['subheader_box_border_width' . $ft_sub_sfx]) ? $s['subheader_box_border_width' . $ft_sub_sfx] : '',
            'border-style' => isset($s['subheader_box_border_style' . $ft_sub_sfx]) ? $s['subheader_box_border_style' . $ft_sub_sfx] : '',
            'border-color' => isset($s['subheader_box_border_color' . $ft_sub_sfx]) ? $s['subheader_box_border_color' . $ft_sub_sfx] : '',
        );
        $ft_subheader_typography_rules[$ft_sub_dev] = '';
        foreach (array('color', 'font_family', 'font_weight', 'font_size') as $ft_prop) {
            $ft_value = isset($s['subheader_' . $ft_prop . $ft_sub_sfx]) ? $s['subheader_' . $ft_prop . $ft_sub_sfx] : '';
            $ft_unset = '' === trim((string) $ft_value)
                || (in_array($ft_prop, array('font_weight', 'font_size'), true) && 0 === intval($ft_value));
            if ($ft_unset) {
                if ('desktop' !== $ft_sub_dev) {
                    $ft_value = isset($s['subheader_' . $ft_prop]) ? $s['subheader_' . $ft_prop] : '';
                }
            }
            if ('' === trim((string) $ft_value)
                || (in_array($ft_prop, array('font_weight', 'font_size'), true) && 0 === intval($ft_value))) {
                continue;
            }
            if ('font_family' === $ft_prop) {
                $ft_subheader_typography_rules[$ft_sub_dev] .= ' font-family: \'' . esc_attr($ft_value) . '\', serif !important;';
            } elseif ('font_size' === $ft_prop) {
                $ft_subheader_typography_rules[$ft_sub_dev] .= ' font-size: ' . max(0, min(96, intval($ft_value))) . 'px !important;';
            } elseif ('font_weight' === $ft_prop) {
                $ft_subheader_typography_rules[$ft_sub_dev] .= ' font-weight: ' . intval($ft_value) . ' !important;';
            } else {
                $ft_subheader_typography_rules[$ft_sub_dev] .= ' color: ' . esc_html($ft_value) . ' !important;';
            }
        }
    }
    $ft_subheader_emit = function ($values, $dev) use ($ft_border_style) {
        $rules = '';
        $margin = ft_device_value($values, $dev, 'margin');
        if ('' !== $margin) {
            $parts = preg_split('/\s+/', trim((string) $margin));
            $valid = array();
            foreach ($parts as $part) {
                if (!preg_match('/^-?\d+(?:\.\d+)?(?:px|%|vh|vw|em|rem|pt|cm|mm|in)?$/', $part)) {
                    $valid = array();
                    break;
                }
                $valid[] = preg_match('/(?:px|%|vh|vw|em|rem|pt|cm|mm|in)$/', $part) ? $part : $part . 'px';
            }
            if (!empty($valid) && count($valid) <= 4) {
                $rules .= ' margin: ' . implode(' ', $valid) . ' !important;';
            }
        }
        $padding = ft_device_value($values, $dev, 'padding');
        if ('' !== $padding && '' !== ($padding_css = ft_radius_css($padding, '0px'))) {
            $rules .= ' padding: ' . esc_html($padding_css) . ' !important;';
        }
        $radius = ft_device_value($values, $dev, 'radius');
        if ('' !== $radius && '' !== ($radius_css = ft_radius_css($radius, '0px'))) {
            $rules .= ' border-radius: ' . esc_html($radius_css) . ' !important;';
        }
        $border_width = ft_device_value($values, $dev, 'border');
        $border_color = ft_device_value($values, $dev, 'border-color');
        if ('' !== $border_width) {
            $border_width_css = ft_radius_css($border_width, '0px');
            if ('' !== $border_width_css) {
                $rules .= ' border: ' . esc_html(ft_border_width_css($border_width_css, $ft_border_style(ft_device_value($values, $dev, 'border-style')))) . ' ' . esc_html($ft_border_style(ft_device_value($values, $dev, 'border-style'))) . ' ' . esc_html('' !== $border_color ? $border_color : '#e8e2d2') . ' !important;';
            }
        }
        return $rules;
    };
    $css .= ft_box_device_css('.family-member-photo-album__subheader', $ft_subheader_box_values, $ft_subheader_emit);
    foreach ($ft_subheader_typography_rules as $ft_sub_dev => $ft_sub_rules) {
        if ('' === trim($ft_sub_rules)) {
            continue;
        }
        $ft_sub_selector = '.family-member-photo-album__subheader-name';
        if ('desktop' === $ft_sub_dev) {
            $css .= $ft_sub_selector . ' { ' . $ft_sub_rules . ' }';
        } else {
            $css .= '@media (' . ft_device_media($ft_sub_dev) . ') { ' . $ft_sub_selector . ' { ' . $ft_sub_rules . ' } }';
        }
    }
    $ft_subheader_bg_rules = '';
    if ('gradient' === $s['subheader_bg_type'] && '' !== $s['subheader_bg_gradient']) {
        $ft_subheader_bg_rules .= ' background-image: ' . esc_html($s['subheader_bg_gradient']) . ' !important;';
        $ft_subheader_bg_rules .= ' background-color: ' . esc_html('' !== $s['subheader_bg'] ? $s['subheader_bg'] : 'transparent') . ' !important;';
    } elseif ('' !== $s['subheader_bg_image']) {
        $ft_subheader_bg_rules .= ' background-image: url("' . esc_url($s['subheader_bg_image']) . '") !important;';
        $ft_subheader_bg_rules .= ' background-size: cover !important; background-position: center center !important; background-repeat: no-repeat !important;';
        if ('' !== $s['subheader_bg']) {
            $ft_subheader_bg_rules .= ' background-color: ' . esc_html($s['subheader_bg']) . ' !important;';
        }
    } elseif ('' !== $s['subheader_bg']) {
        $ft_subheader_bg_rules .= ' background: ' . esc_html($s['subheader_bg']) . ' !important;';
    }
    if ('' !== $ft_subheader_bg_rules) {
        $css .= '.family-member-photo-album__subheader { ' . $ft_subheader_bg_rules . ' }';
    }

    foreach (array('desktop' => '', 'tablet' => '_tablet', 'mobile' => '_mobile') as $ft_desc_dev => $ft_desc_sfx) {
        $ft_desc_rules = '';
        foreach (array('color', 'font_family', 'font_weight', 'font_size', 'text_align') as $ft_desc_prop) {
            $ft_desc_value = isset($s['description_' . $ft_desc_prop . $ft_desc_sfx]) ? trim((string) $s['description_' . $ft_desc_prop . $ft_desc_sfx]) : '';
            $ft_desc_unset = '' === $ft_desc_value || (in_array($ft_desc_prop, array('font_weight', 'font_size'), true) && 0 === intval($ft_desc_value));
            if ($ft_desc_unset && 'desktop' !== $ft_desc_dev) {
                $ft_desc_value = isset($s['description_' . $ft_desc_prop]) ? trim((string) $s['description_' . $ft_desc_prop]) : '';
            }
            if ('' === $ft_desc_value || (in_array($ft_desc_prop, array('font_weight', 'font_size'), true) && 0 === intval($ft_desc_value))) {
                continue;
            }
            if ('font_family' === $ft_desc_prop) {
                $ft_desc_rules .= ' font-family: \'' . esc_attr($ft_desc_value) . '\', serif !important;';
            } elseif ('font_weight' === $ft_desc_prop) {
                $ft_desc_rules .= ' font-weight: ' . intval($ft_desc_value) . ' !important;';
            } elseif ('font_size' === $ft_desc_prop) {
                $ft_desc_rules .= ' font-size: ' . max(0, min(96, intval($ft_desc_value))) . 'px !important;';
            } elseif ('text_align' === $ft_desc_prop && in_array($ft_desc_value, ft_phs_align_values(), true)) {
                $ft_desc_rules .= ' text-align: ' . $ft_desc_value . ' !important;';
            } else {
                $ft_desc_rules .= ' color: ' . esc_html($ft_desc_value) . ' !important;';
            }
        }
        if ('' !== trim($ft_desc_rules)) {
            $ft_desc_selector = '.ft-album-description';
            if ('desktop' === $ft_desc_dev) {
                $css .= $ft_desc_selector . ' { ' . $ft_desc_rules . ' }';
            } else {
                $css .= '@media (' . ft_device_media($ft_desc_dev) . ') { ' . $ft_desc_selector . ' { ' . $ft_desc_rules . ' } }';
            }
        }
    }

    // Кнопки ленты альбомов — ссылки .ft-photo-page__nav-link в шапке блока.
    $ft_navlink_settings = ft_album_navlink_normalized(isset($s['navlink']) ? $s['navlink'] : array());
    foreach (ft_device_list() as $ft_nl_dev => $ft_nl_meta) {
        $ft_nl_css = ft_wrap_media(ft_device_media($ft_nl_dev), ft_album_navlink_device_css($ft_navlink_settings, $ft_nl_dev));
        if ('' !== $ft_nl_css) {
            $css .= $ft_nl_css;
        }
    }

    // Раскладка: сетка и masonry используют CSS-переменные, простая карусель считает ширину слайда по колонкам в PHP
    // (у Fluid ширину слайда определяет высота и естественные пропорции фото — без колонок)
    if ('carousel' === $layout) {
        $item_css = '.family-member-photo-album.ft-layout-carousel .family-member-photo-item { flex: 0 0 calc((100% - ' . intval($gap * ($columns - 1)) . 'px) / ' . $columns . '); }';
        $item_css .= '@media (max-width: 1024px) { .family-member-photo-album.ft-layout-carousel .family-member-photo-item { flex: 0 0 calc((100% - ' . intval($gap * ($columns_tablet - 1)) . 'px) / ' . $columns_tablet . '); } }';
        $item_css .= '@media (max-width: 767px) { .family-member-photo-album.ft-layout-carousel .family-member-photo-item { flex: 0 0 calc((100% - ' . intval($gap * ($columns_mobile - 1)) . 'px) / ' . $columns_mobile . '); } }';
        $css .= $item_css;
    }

    // Соотношение сторон: применяется к сетке и простой карусели, задаёт формат самой фотографии (обрезка до формата)
    if ('inherit' !== $s['image_ratio'] && isset($ratio_map[$s['image_ratio']])) {
        if ('carousel' === $layout) {
            // Простая карусель: ширина слайда = колонка, высота определяется соотношением (без фиксированной высоты)
            $css .= '.family-member-photo-album.ft-layout-carousel:not(.ft-layout-carousel-fluid) .family-member-photo-item img { aspect-ratio: ' . $ratio_map[$s['image_ratio']] . '; width: 100%; max-width: none; height: auto; object-fit: cover; }';
        } elseif ($image_height > 0) {
            $ratio_css = 'aspect-ratio: ' . $ratio_map[$s['image_ratio']] . '; width: 100%; height: auto; object-fit: cover;';
            $css .= '.family-member-photo-album.ft-layout-grid .family-member-photo-item img { ' . $ratio_css . ' }';
        } else {
            $ratio_css = 'aspect-ratio: ' . $ratio_map[$s['image_ratio']] . '; width: 100%; height: auto; object-fit: cover;';
            $css .= '.family-member-photo-album.ft-layout-grid .family-member-photo-item img { ' . $ratio_css . ' }';
        }
    }

    // Подписи
    $cap_rules = '';
    if (!$has_caption_position_styles) {
        if (!empty($s['caption_color'])) {
            $cap_rules .= ' color: ' . esc_html($s['caption_color']) . ' !important;';
        }
        if (!empty($s['caption_bg'])) {
            $cap_rules .= ' background: ' . esc_html($s['caption_bg']) . ' !important;';
        }
        if (!empty($s['caption_font_family'])) {
            $cap_rules .= ' font-family: \'' . esc_attr($s['caption_font_family']) . '\', serif !important;';
        }
        if ($s['caption_font_weight'] > 0) {
            $cap_rules .= ' font-weight: ' . intval($s['caption_font_weight']) . ' !important;';
        }
        if ($s['caption_font_size'] > 0) {
            $cap_rules .= ' font-size: ' . intval($s['caption_font_size']) . 'px !important;';
        }
        if (!empty($cap_rules)) {
            $css .= '.family-member-photo-album figcaption { ' . $cap_rules . ' }';
        }
    }
    foreach (array('below', 'above', 'overlay') as $caption_position) {
        foreach (array('desktop' => '', 'tablet' => 'max-width:1024px', 'mobile' => 'max-width:767px') as $caption_device => $media) {
            $row = isset($s['caption_styles'][$caption_position][$caption_device]) && is_array($s['caption_styles'][$caption_position][$caption_device])
                ? $s['caption_styles'][$caption_position][$caption_device] : array();
            $rules = '';
            if (!empty($row['align'])) {
                $rules .= ' text-align: ' . esc_html($row['align']) . ' !important;';
            }
            if (!empty($row['color'])) {
                $rules .= ' color: ' . esc_html($row['color']) . ' !important;';
            }
            $bg = isset($row['bg']) && is_array($row['bg']) ? $row['bg'] : array();
            if (isset($bg['type'], $bg['gradient']) && 'gradient' === $bg['type'] && '' !== $bg['gradient']) {
                $rules .= ' background-image: ' . esc_html($bg['gradient']) . ' !important;';
                $rules .= ' background-color: ' . esc_html(!empty($bg['color']) ? $bg['color'] : 'transparent') . ' !important;';
            } elseif (!empty($bg['image'])) {
                $rules .= ' background-image: url("' . esc_url($bg['image']) . '") !important;';
                $rules .= ' background-size: cover !important; background-position: center center !important; background-repeat: no-repeat !important;';
                if (!empty($bg['color'])) {
                    $rules .= ' background-color: ' . esc_html($bg['color']) . ' !important;';
                }
            } elseif (!empty($bg['color'])) {
                $rules .= ' background: ' . esc_html($bg['color']) . ' !important;';
            }
            if (!empty($row['padding'])) {
                $rules .= ' padding: ' . esc_html($row['padding']) . ' !important;';
            }
            if (!empty($row['radius'])) {
                $rules .= ' border-radius: ' . esc_html($row['radius']) . ' !important;';
            }
            if (!empty($row['font_family'])) {
                $rules .= ' font-family: \'' . esc_attr($row['font_family']) . '\', serif !important;';
            }
            if (!empty($row['font_size'])) {
                $rules .= ' font-size: ' . max(0, min(96, intval($row['font_size']))) . 'px !important;';
            }
            if (!empty($row['font_weight'])) {
                $rules .= ' font-weight: ' . intval($row['font_weight']) . ' !important;';
            }
            if ('' !== $rules) {
                $caption_selector = '.family-member-photo-album.ft-captions-' . $caption_position . ' figcaption';
                $caption_rule = $caption_selector . ' { ' . $rules . ' }';
                $css .= '' !== $media ? '@media (' . $media . ') { ' . $caption_rule . ' }' : $caption_rule;
            }
        }
    }

    // Фотография: рамка и тень
    $img_rule = '';
    if (!empty($s['image_border_width']) || !empty($s['image_border_color'])) {
        $img_rule .= 'border: ' . esc_html(ft_border_width_css(max(1, intval($s['image_border_width'])) . 'px', $ft_border_style($s['image_border_style']))) . ' ' . esc_html($ft_border_style($s['image_border_style'])) . ' ' . esc_html(!empty($s['image_border_color']) ? $s['image_border_color'] : '#dcdcde') . ';';
    }
    if ($s['image_shadow']) {
        $shadow_color = !empty($s['shadow_color']) ? $s['shadow_color'] : 'rgba(0, 0, 0, 0.18)';
        $img_rule .= 'box-shadow: ' . intval($s['shadow_offset_x']) . 'px ' . intval($s['shadow_offset_y']) . 'px ' . intval($s['shadow_blur']) . 'px ' . intval($s['shadow_spread']) . 'px ' . esc_html($shadow_color) . ';';
    }
    if (!empty($img_rule)) {
        $css .= '.family-member-photo-album .family-member-photo-item { ' . $img_rule . ' }';
    }

    // Hover-правила для кнопок карусели
    $ft_btn_hover_rules = '';
    if (!empty($s['carousel_btn_bg_hover'])) {
        $ft_btn_hover_rules .= 'background: ' . esc_html($s['carousel_btn_bg_hover']) . ' !important;';
    }
    if (!empty($s['carousel_btn_color_hover'])) {
        $ft_btn_hover_rules .= 'color: ' . esc_html($s['carousel_btn_color_hover']) . ' !important;';
    }
    if (!empty($s['carousel_btn_border_color_hover'])) {
        $ft_btn_hover_rules .= 'border-color: ' . esc_html($s['carousel_btn_border_color_hover']) . ' !important;';
    }
    $ft_btn_hover_style = !empty($s['carousel_btn_border_style_hover'])
            ? $ft_border_style($s['carousel_btn_border_style_hover'])
            : $ft_border_style($s['carousel_btn_border_style']);
    if ('' !== (string) $s['carousel_btn_border_width_hover'] || ('double' === $ft_btn_hover_style && 'double' !== $ft_border_style($s['carousel_btn_border_style']))) {
        $ft_btn_hover_width = '' !== (string) $s['carousel_btn_border_width_hover']
            ? max(0, min(10, intval($s['carousel_btn_border_width_hover'])))
            : max(0, min(10, intval($s['carousel_btn_border_width'])));
        $ft_btn_hover_rules .= 'border-width: ' . esc_html(ft_border_width_css($ft_btn_hover_width . 'px', $ft_btn_hover_style)) . ' !important;';
    }
    if (!empty($s['carousel_btn_border_style_hover'])) {
        $ft_btn_hover_rules .= 'border-style: ' . esc_html($ft_border_style($s['carousel_btn_border_style_hover'])) . ' !important;';
    }
    if (intval($s['carousel_btn_shadow_hover'])) {
        $ft_btn_hover_shadow = intval($s['carousel_btn_shadow_hover_x']) . 'px ' . intval($s['carousel_btn_shadow_hover_y']) . 'px '
            . max(0, intval($s['carousel_btn_shadow_hover_blur'])) . 'px ' . intval($s['carousel_btn_shadow_hover_spread']) . 'px '
            . esc_html(!empty($s['carousel_btn_shadow_hover_color']) ? $s['carousel_btn_shadow_hover_color'] : 'rgba(0, 0, 0, 0.2)');
        $ft_btn_hover_rules .= 'box-shadow: ' . $ft_btn_hover_shadow . ' !important;';
    }
    if (!empty($ft_btn_hover_rules)) {
        $css .= '.ft-album-btn:hover { ' . $ft_btn_hover_rules . ' }';
    }

    // Hover-правила для фотографий (граница / тень)
    $ft_img_hover_rules = '';
    $ft_img_hover_style = !empty($s['image_border_style_hover'])
            ? $ft_border_style($s['image_border_style_hover'])
            : $ft_border_style($s['image_border_style']);
    if ('' !== (string) $s['image_border_width_hover'] || ('double' === $ft_img_hover_style && 'double' !== $ft_border_style($s['image_border_style']))) {
        $ft_img_hover_width = '' !== (string) $s['image_border_width_hover']
            ? max(0, min(50, intval($s['image_border_width_hover'])))
            : max(0, min(50, intval($s['image_border_width'])));
        $ft_img_hover_rules .= 'border-width: ' . esc_html(ft_border_width_css($ft_img_hover_width . 'px', $ft_img_hover_style)) . ' !important;';
    }
    if (!empty($s['image_border_style_hover'])) {
        $ft_img_hover_rules .= 'border-style: ' . esc_html($ft_border_style($s['image_border_style_hover'])) . ' !important;';
    }
    if (!empty($s['image_border_color_hover'])) {
        $ft_img_hover_rules .= 'border-color: ' . esc_html($s['image_border_color_hover']) . ' !important;';
    }
    if (intval($s['image_shadow_hover'])) {
        $sh_h_color = !empty($s['image_shadow_hover_color']) ? $s['image_shadow_hover_color'] : 'rgba(0, 0, 0, 0.18)';
        $ft_img_hover_rules .= 'box-shadow: ' . intval($s['image_shadow_hover_x']) . 'px ' . intval($s['image_shadow_hover_y']) . 'px ' . max(0, intval($s['image_shadow_hover_blur'])) . 'px ' . intval($s['image_shadow_hover_spread']) . 'px ' . esc_html($sh_h_color) . ' !important;';
    }
    if (!empty($ft_img_hover_rules)) {
        $css .= '.family-member-photo-album .family-member-photo-item:hover { ' . $ft_img_hover_rules . ' }';
    }

    // === Отображение карточек альбомов на странице персоны (обложки в режимах «Обложки альбомов»/«Выбранные альбомы») ===
    $ft_card_sel = '.family-member-photo-album .ft-albums-cover-card';
    $display_card_rule = '';
    $ft_background_declarations = function ($color, $type, $gradient, $gradient_type, $angle, $image) {
        $rules = '';
        if ('gradient' === $type && '' !== (string) $gradient) {
            $rules .= ' background-image: ' . esc_html($gradient) . ' !important;';
            $rules .= ' background-color: ' . ('' !== (string) $color ? esc_html($color) : 'transparent') . ' !important;';
        } elseif ('' !== (string) $image) {
            $rules .= ' background-image: url("' . esc_url($image) . '") !important;';
            if ('' !== (string) $color) {
                $rules .= ' background-color: ' . esc_html($color) . ' !important;';
            }
        } elseif ('' !== (string) $color) {
            $rules .= ' background: ' . esc_html($color) . ' !important;';
        }
        return $rules;
    };
    $display_card_rule .= $ft_background_declarations(
        $s['display_bg_color'],
        $s['display_bg_type'],
        $s['display_bg_gradient'],
        $s['display_bg_gradient_type'],
        $s['display_bg_angle'],
        $s['display_bg_image']
    );
    if ('10px' !== ft_radius_css($s['display_radius'], '10px')) {
        $display_card_rule .= ' border-radius: ' . ft_radius_css($s['display_radius'], '10px') . ' !important;';
    }
    $ft_card_border_color = '';
    if (intval($s['display_border_width']) > 0 || !empty($s['display_border_color'])) {
        $ft_card_border_color = !empty($s['display_border_color']) ? $s['display_border_color'] : '#e5e5e5';
        $display_card_rule .= ' border: ' . esc_html(ft_border_width_css(max(1, intval($s['display_border_width'])) . 'px', $ft_border_style($s['display_border_style']))) . ' ' . esc_html($ft_border_style($s['display_border_style'])) . ' ' . esc_html($ft_card_border_color) . ' !important;';
    }
    if (!empty($display_card_rule)) {
        $css .= $ft_card_sel . ' { ' . $display_card_rule . ' }';
    }
    if (20 !== intval($s['display_padding'])) {
        $css .= '.family-member-photo-album .ft-albums-cover-card > span:last-child { padding: ' . intval($s['display_padding']) . 'px !important; }';
    }
    $ft_card_device_values = array();
    foreach (array('desktop' => '', 'tablet' => '_tablet', 'mobile' => '_mobile') as $ft_dev => $ft_sfx) {
        $ft_card_device_values[$ft_dev] = array(
            'gap' => isset($s['display_card_gap' . $ft_sfx]) ? $s['display_card_gap' . $ft_sfx] : '',
            'padding' => isset($s['display_card_padding' . $ft_sfx]) ? $s['display_card_padding' . $ft_sfx] : '',
            'radius' => isset($s['display_card_radius' . $ft_sfx]) ? $s['display_card_radius' . $ft_sfx] : '',
            'border' => isset($s['display_card_border_width' . $ft_sfx]) ? $s['display_card_border_width' . $ft_sfx] : '',
            'border-style' => isset($s['display_card_border_style' . $ft_sfx]) ? $s['display_card_border_style' . $ft_sfx] : '',
            'border-color' => isset($s['display_card_border_color' . $ft_sfx]) ? $s['display_card_border_color' . $ft_sfx] : '',
        );
    }
    $ft_card_device_values['desktop']['padding'] = $ft_card_device_values['desktop']['padding'] ?: intval($s['display_padding']) . 'px';
    $ft_card_device_values['desktop']['radius'] = $ft_card_device_values['desktop']['radius'] ?: intval($s['display_radius']) . 'px';
    $ft_card_device_values['desktop']['border'] = $ft_card_device_values['desktop']['border'] ?: intval($s['display_border_width']) . 'px';
    $ft_card_device_values['desktop']['border-style'] = $ft_card_device_values['desktop']['border-style'] ?: $s['display_border_style'];
    $ft_card_device_values['desktop']['border-color'] = $ft_card_device_values['desktop']['border-color'] ?: $s['display_border_color'];
    $css .= ft_box_device_css('.ft-albums-covers', $ft_card_device_values, function ($values, $dev) {
        $gap = trim(ft_device_value($values, $dev, 'gap'));
        return '' !== $gap ? ' gap: ' . esc_html($gap) . ' !important;' : '';
    });
    $css .= ft_box_device_css($ft_card_sel, $ft_card_device_values, function ($values, $dev) {
        $rule = '';
        $radius = ft_radius_css(ft_device_value($values, $dev, 'radius'), '10px');
        if ('' !== $radius) {
            $rule .= ' border-radius: ' . esc_html($radius) . ' !important;';
        }
        $border_width = ft_radius_css(ft_device_value($values, $dev, 'border'), '0px');
        $border_style = ft_device_value($values, $dev, 'border-style');
        $border_color = ft_device_value($values, $dev, 'border-color');
        if ('' !== $border_width && '0px' !== $border_width) {
            $border_style = in_array($border_style, array('solid', 'dashed', 'dotted', 'double'), true) ? $border_style : 'solid';
            $rule .= ' border-width: ' . esc_html(ft_border_width_css($border_width, $border_style)) . ' !important;';
            $rule .= ' border-style: ' . esc_html($border_style) . ' !important;';
        } elseif ('0px' === $border_width) {
            $rule .= ' border: none !important;';
        }
        if ('' !== trim($border_color)) {
            $rule .= ' border-color: ' . esc_html($border_color) . ' !important;';
        }
        return $rule;
    });
    $css .= ft_box_device_css('.family-member-photo-album .ft-albums-cover-card > span:last-child', $ft_card_device_values, function ($values, $dev) {
        $padding = trim(ft_device_value($values, $dev, 'padding'));
        return '' !== $padding ? ' padding: ' . esc_html($padding) . ' !important;' : '';
    });
    if (!empty($s['display_shadow'])) {
        $sh_x = max(-200, min(200, intval($s['display_shadow_x'])));
        $sh_y = max(-200, min(200, intval($s['display_shadow_y'])));
        $sh_blur = max(0, min(200, intval($s['display_shadow_blur'])));
        $sh_spread = max(-100, min(100, intval($s['display_shadow_spread'])));
        $sh_color = !empty($s['display_shadow_color']) ? esc_html($s['display_shadow_color']) : 'rgba(0, 0, 0, 0.12)';
        $css .= $ft_card_sel . ' { box-shadow: ' . $sh_x . 'px ' . $sh_y . 'px ' . $sh_blur . 'px ' . $sh_spread . 'px ' . $sh_color . '; }';
    }
    if (!empty($s['display_hover_shadow'])) {
        $hsh_x = max(-200, min(200, intval($s['display_hover_shadow_x'])));
        $hsh_y = max(-200, min(200, intval($s['display_hover_shadow_y'])));
        $hsh_blur = max(0, min(200, intval($s['display_hover_shadow_blur'])));
        $hsh_spread = max(-100, min(100, intval($s['display_hover_shadow_spread'])));
        $hsh_color = !empty($s['display_hover_shadow_color']) ? esc_html($s['display_hover_shadow_color']) : 'rgba(0, 0, 0, 0.12)';
        $css .= $ft_card_sel . ':hover { box-shadow: ' . $hsh_x . 'px ' . $hsh_y . 'px ' . $hsh_blur . 'px ' . $hsh_spread . 'px ' . $hsh_color . ' !important; }';
    }
    foreach (array('tablet' => '_tablet', 'mobile' => '_mobile') as $ft_shadow_dev => $ft_shadow_sfx) {
        foreach (array('display_shadow' => '', 'display_hover_shadow' => ':hover') as $ft_shadow_key => $ft_state_selector) {
            if (!array_key_exists($ft_shadow_key . $ft_shadow_sfx, $s)) {
                continue;
            }
            $shadow_on = !empty($s[$ft_shadow_key . $ft_shadow_sfx]);
            if (!$shadow_on) {
                $shadow_rule = 'box-shadow: none !important;';
            } else {
                $x = max(-200, min(200, intval($s[$ft_shadow_key . '_x' . $ft_shadow_sfx] ?? $s[$ft_shadow_key . '_x'])));
                $y = max(-200, min(200, intval($s[$ft_shadow_key . '_y' . $ft_shadow_sfx] ?? $s[$ft_shadow_key . '_y'])));
                $blur = max(0, min(200, intval($s[$ft_shadow_key . '_blur' . $ft_shadow_sfx] ?? $s[$ft_shadow_key . '_blur'])));
                $spread = max(-100, min(100, intval($s[$ft_shadow_key . '_spread' . $ft_shadow_sfx] ?? $s[$ft_shadow_key . '_spread'])));
                $color = !empty($s[$ft_shadow_key . '_color' . $ft_shadow_sfx]) ? esc_html($s[$ft_shadow_key . '_color' . $ft_shadow_sfx]) : esc_html($s[$ft_shadow_key . '_color']);
                $shadow_rule = 'box-shadow: ' . $x . 'px ' . $y . 'px ' . $blur . 'px ' . $spread . 'px ' . $color . ' !important;';
            }
            $media = ft_device_media($ft_shadow_dev);
            $selector = $ft_card_sel . $ft_state_selector;
            $css .= '' !== $media
                ? '@media (' . $media . ') { ' . $selector . ' { ' . $shadow_rule . ' } }'
                : $selector . ' { ' . $shadow_rule . ' }';
        }
    }

    foreach (array(
        'title' => array('selector' => '.ft-albums-cover-name', 'legacy_hover_color' => 'display_hover_title_color'),
        'count' => array('selector' => '.ft-albums-cover-count', 'legacy_hover_color' => ''),
    ) as $ft_text_part => $ft_text_spec) {
        $ft_normal_desktop = array();
        foreach (array('color', 'font_family', 'font_weight', 'font_size') as $ft_prop) {
            $ft_normal_desktop[$ft_prop] = isset($s['display_' . $ft_text_part . '_' . $ft_prop])
                ? $s['display_' . $ft_text_part . '_' . $ft_prop]
                : '';
        }
        foreach (array('desktop' => '', 'tablet' => '_tablet', 'mobile' => '_mobile') as $ft_display_dev => $ft_display_sfx) {
            $ft_normal = array();
            $ft_hover = array();
            foreach (array('color', 'font_family', 'font_weight', 'font_size') as $ft_prop) {
                $ft_normal_key = 'display_' . $ft_text_part . '_' . $ft_prop . $ft_display_sfx;
                $ft_normal[$ft_prop] = isset($s[$ft_normal_key]) ? $s[$ft_normal_key] : '';
                if ('desktop' !== $ft_display_dev && ('' === (string) $ft_normal[$ft_prop] || 0 === (int) $ft_normal[$ft_prop])) {
                    $ft_normal[$ft_prop] = $ft_normal_desktop[$ft_prop];
                }
                $ft_hover_key = 'display_' . $ft_text_part . '_hover_' . $ft_prop . $ft_display_sfx;
                $ft_hover[$ft_prop] = isset($s[$ft_hover_key]) ? $s[$ft_hover_key] : '';
                if ('' === (string) $ft_hover[$ft_prop] || ('font_weight' === $ft_prop && 0 === (int) $ft_hover[$ft_prop]) || ('font_size' === $ft_prop && 0 === (int) $ft_hover[$ft_prop])) {
                    $ft_hover[$ft_prop] = $ft_normal[$ft_prop];
                }
            }
            if ('title' === $ft_text_part && 'desktop' === $ft_display_dev
                && '' === (string) $s['display_title_hover_color']
                && !empty($s[$ft_text_spec['legacy_hover_color']])) {
                $ft_hover['color'] = $s[$ft_text_spec['legacy_hover_color']];
            }
            $ft_align_key = 'display_' . $ft_text_part . '_text_align' . $ft_display_sfx;
            $ft_text_align = isset($s[$ft_align_key]) ? $s[$ft_align_key] : '';
            if ('' === $ft_text_align && 'desktop' !== $ft_display_dev) {
                $ft_text_align = isset($s['display_' . $ft_text_part . '_text_align'])
                    ? $s['display_' . $ft_text_part . '_text_align']
                    : '';
            }
            if (!in_array($ft_text_align, ft_phs_align_values(), true)) {
                $ft_text_align = '';
            }
            foreach (array('normal' => $ft_normal, 'hover' => $ft_hover) as $ft_state => $ft_values) {
                $ft_rule = '' !== $ft_text_align ? ' text-align: ' . $ft_text_align . ' !important;' : '';
                if ('' !== trim((string) $ft_values['color'])) {
                    $ft_rule .= ' color: ' . esc_html($ft_values['color']) . ' !important;';
                }
                if ('' !== trim((string) $ft_values['font_family'])) {
                    $ft_rule .= ' font-family: \'' . esc_attr($ft_values['font_family']) . '\', serif !important;';
                }
                if ((int) $ft_values['font_weight'] > 0) {
                    $ft_rule .= ' font-weight: ' . (int) $ft_values['font_weight'] . ' !important;';
                }
                if ((int) $ft_values['font_size'] > 0) {
                    $ft_rule .= ' font-size: ' . (int) $ft_values['font_size'] . 'px !important;';
                }
                if ('' === $ft_rule) {
                    continue;
                }
                $ft_selector = '.family-member-photo-album .ft-albums-cover-card';
                if ('hover' === $ft_state) {
                    $ft_selector .= ':hover';
                }
                $ft_selector .= ' ' . $ft_text_spec['selector'];
                $ft_rule_css = $ft_selector . ' { ' . $ft_rule . ' }';
                $css .= ft_wrap_media(ft_device_media($ft_display_dev), $ft_rule_css);
            }
        }
    }

    // Ховер: фон и граница кастомизируются только если заданы не по умолчанию.
    // Заданный свой цвет границы карточки сохраняем и при наведении,
    // чтобы базовое правило .ft-albums-cover-card:hover не подменяло его синим.
    $hover_rule = '';
    $ft_hover_border_color = '';
    $hover_rule .= $ft_background_declarations(
        $s['display_hover_bg'],
        $s['display_bg_type_hover'],
        $s['display_bg_gradient_hover'],
        $s['display_bg_gradient_type_hover'],
        $s['display_bg_angle_hover'],
        $s['display_bg_image_hover']
    );
    if (!empty($s['display_hover_border']) && '#2271b1' !== $s['display_hover_border']) {
        $ft_hover_border_color = esc_html($s['display_hover_border']);
        $hover_rule .= ' border-color: ' . $ft_hover_border_color . ' !important;';
    } elseif ('' !== $ft_card_border_color) {
        $hover_rule .= ' border-color: ' . esc_html($ft_card_border_color) . ' !important;';
    }
    if (!empty($hover_rule)) {
        $css .= $ft_card_sel . ':hover { ' . $hover_rule . ' }';
        if ('' !== $ft_hover_border_color) {
            $css .= 'a.family-member-photo-album .ft-albums-cover-card:focus-visible { outline-color: ' . $ft_hover_border_color . '; }';
        }
    }
    // Главная страница семейного архива (контейнер каталога)
    $home_container_css = 'margin-top:' . intval($s['home_container_margin_top']) . 'px;margin-bottom:' . intval($s['home_container_margin_bottom']) . 'px;';
    if (!empty($s['home_container_bg']) || ('gradient' === $s['home_container_bg_type'] && !empty($s['home_container_bg_gradient']))) {
        if ('gradient' === $s['home_container_bg_type'] && !empty($s['home_container_bg_gradient'])) {
            $home_container_css .= 'background-image:' . esc_html($s['home_container_bg_gradient']) . '!important;background-color:' . ('' !== $s['home_container_bg'] ? esc_html($s['home_container_bg']) : 'transparent') . '!important;';
        } else {
            $home_container_css .= 'background:' . esc_html($s['home_container_bg']) . '!important;';
        }
    } else {
        $home_container_css .= 'background:transparent!important;';
    }
    $home_container_css .= 'border-radius:' . ft_radius_css($s['home_container_radius'], '0px') . '!important;';
    if (!empty($s['home_container_border_width']) || !empty($s['home_container_border_color'])) {
        $home_container_css .= 'border:' . ft_border_width_css(max(1, intval($s['home_container_border_width'])) . 'px', $ft_border_style($s['home_container_border_style'])) . ' ' . $ft_border_style($s['home_container_border_style']) . ' ' . esc_html(!empty($s['home_container_border_color']) ? $s['home_container_border_color'] : '#dcdcde') . '!important;';
    } else {
        $home_container_css .= 'border:none!important;';
    }
    if ('' !== $s['home_container_padding'] && intval($s['home_container_padding']) >= 0) {
        $home_container_css .= 'padding:' . intval($s['home_container_padding']) . 'px!important;';
    } else {
        $home_container_css .= 'padding:0!important;';
    }
    $css .= '.ft-archive-catalog{' . $home_container_css . '}';

    // Главная страница семейного архива (блоки подразделов)
    $home_card_css = '';
    if ('' !== $s['home_block_bg']) {
        $home_card_css .= ' background: ' . esc_html($s['home_block_bg']) . ' !important;';
    }
    if ('8px' !== ft_radius_css($s['home_block_radius'], '8px')) {
        $home_card_css .= ' border-radius: ' . ft_radius_css($s['home_block_radius'], '8px') . ' !important;';
    }
    if (1 !== intval($s['home_block_border_width']) || 'solid' !== $s['home_block_border_style'] || '#ddd' !== $s['home_block_border_color']) {
        if (0 === intval($s['home_block_border_width'])) {
            $home_card_css .= ' border: none !important;';
        } else {
            $home_card_css .= ' border: ' . esc_html(ft_border_width_css(intval($s['home_block_border_width']) . 'px', $ft_border_style($s['home_block_border_style']))) . ' ' . esc_html($ft_border_style($s['home_block_border_style'])) . ' ' . esc_html(!empty($s['home_block_border_color']) ? $s['home_block_border_color'] : '#ddd') . ' !important;';
        }
    }
    if (20 !== intval($s['home_block_padding'])) {
