    }
    $home_count_css = '';
    if ('#888' !== $s['home_count_color']) {
        $home_count_css .= ' color: ' . esc_html($s['home_count_color']) . ' !important;';
    }
    if ('' !== $s['home_count_font_family']) {
        $home_count_css .= ' font-family: \'' . esc_attr($s['home_count_font_family']) . '\', serif !important;';
