        $css .= '.ft-archive-card:hover .ft-archive-card__count { color: ' . esc_html($s['home_count_color_hover']) . ' !important; }';
    }
    $home_badge_css = '';
    if ('' !== $s['home_badge_bg'] && '#f0f0f1' !== $s['home_badge_bg']) {
        $home_badge_css .= ' background: ' . esc_html($s['home_badge_bg']) . ' !important;';
    }
    if ('#999' !== $s['home_badge_color']) {
        $home_badge_css .= ' color: ' . esc_html($s['home_badge_color']) . ' !important;';
    }
    if (3 !== intval($s['home_badge_padding_y']) || 10 !== intval($s['home_badge_padding_x'])) {
        $home_badge_css .= ' padding: ' . intval($s['home_badge_padding_y']) . 'px ' . intval($s['home_badge_padding_x']) . 'px !important;';
    }
    if ('4px' !== ft_radius_css($s['home_badge_radius'], '4px')) {
        $home_badge_css .= ' border-radius: ' . ft_radius_css($s['home_badge_radius'], '4px') . ' !important;';
    }
    if (0 !== intval($s['home_badge_border_width']) || 'solid' !== $s['home_badge_border_style'] || '' !== $s['home_badge_border_color']) {
        if (0 === intval($s['home_badge_border_width'])) {
            $home_badge_css .= ' border: none !important;';
        } else {
            $home_badge_css .= ' border: ' . esc_html(ft_border_width_css(intval($s['home_badge_border_width']) . 'px', $ft_border_style($s['home_badge_border_style']))) . ' ' . esc_html($ft_border_style($s['home_badge_border_style'])) . ' ' . esc_html(!empty($s['home_badge_border_color']) ? $s['home_badge_border_color'] : '#ddd') . ' !important;';
        }
    }
    if ('' !== $s['home_badge_font_family']) {
        $home_badge_css .= ' font-family: \'' . esc_attr($s['home_badge_font_family']) . '\', serif !important;';
    }
    if (0 !== intval($s['home_badge_font_weight'])) {
        $home_badge_css .= ' font-weight: ' . intval($s['home_badge_font_weight']) . ' !important;';
    }
    if (12 !== intval($s['home_badge_font_size'])) {
        $home_badge_css .= ' font-size: ' . intval($s['home_badge_font_size']) . 'px !important;';
    }
    if ('' !== $home_badge_css) {
        $css .= '.ft-archive-card__badge {' . $home_badge_css . ' }';
    }
    if ('' !== $s['home_badge_bg_hover'] || '' !== $s['home_badge_color_hover']) {
        $home_badge_hover_css = '';
        if ('' !== $s['home_badge_bg_hover']) {
            $home_badge_hover_css .= ' background: ' . esc_html($s['home_badge_bg_hover']) . ' !important;';
        }
        if ('' !== $s['home_badge_color_hover']) {
            $home_badge_hover_css .= ' color: ' . esc_html($s['home_badge_color_hover']) . ' !important;';
        }
        $css .= '.ft-archive-card:hover .ft-archive-card__badge {' . $home_badge_hover_css . ' }';
    }

    // Загрузка Google Fonts, если выбраны
    $ft_available_google = self::get_google_fonts();
    $ft_google_to_load = array();
    // Заголовок ленты: гарнитуры всех вкладок устройств.
    foreach (array('', '_tablet', '_mobile') as $ft_t_google_sfx) {
        if (!empty($s['title_font_family' . $ft_t_google_sfx]) && isset($ft_available_google[$s['title_font_family' . $ft_t_google_sfx]])) {
            $ft_google_to_load[] = $s['title_font_family' . $ft_t_google_sfx];
        }
    }
    // Кнопки ленты: гарнитуры всех вкладок устройств и состояний.
    $ft_navlink = ft_album_navlink_normalized(isset($s['navlink']) ? $s['navlink'] : array());
    foreach ($ft_navlink as $ft_nl_dev) {
        foreach (array('normal', 'hover') as $ft_nl_state) {
            if (!empty($ft_nl_dev['button'][$ft_nl_state]['font_family']) && isset($ft_available_google[$ft_nl_dev['button'][$ft_nl_state]['font_family']])) {
                $ft_google_to_load[] = $ft_nl_dev['button'][$ft_nl_state]['font_family'];
            }
        }
    }
    if (!empty($s['caption_font_family']) && isset($ft_available_google[$s['caption_font_family']])) {
        $ft_google_to_load[] = $s['caption_font_family'];
    }
    foreach (array('below', 'above', 'overlay') as $ft_caption_position) {
        foreach (array('desktop', 'tablet', 'mobile') as $ft_caption_device) {
            $ft_caption_font = isset($s['caption_styles'][$ft_caption_position][$ft_caption_device]['font_family'])
                ? $s['caption_styles'][$ft_caption_position][$ft_caption_device]['font_family'] : '';
            if (!empty($ft_caption_font) && isset($ft_available_google[$ft_caption_font])) {
                $ft_google_to_load[] = $ft_caption_font;
            }
        }
    }
    foreach (array('title', 'count') as $ft_display_part) {
        foreach (array('', '_tablet', '_mobile') as $ft_display_sfx) {
            foreach (array(
                'display_' . $ft_display_part . '_font_family' . $ft_display_sfx,
                'display_' . $ft_display_part . '_hover_font_family' . $ft_display_sfx,
            ) as $ft_font_key) {
                if (!empty($s[$ft_font_key]) && isset($ft_available_google[$s[$ft_font_key]])) {
                    $ft_google_to_load[] = $s[$ft_font_key];
                }
            }
        }
    }
    foreach (array('', '_tablet', '_mobile') as $ft_subheader_sfx) {
        $ft_subheader_font = isset($s['subheader_font_family' . $ft_subheader_sfx]) ? $s['subheader_font_family' . $ft_subheader_sfx] : '';
        if (!empty($ft_subheader_font) && isset($ft_available_google[$ft_subheader_font])) {
            $ft_google_to_load[] = $ft_subheader_font;
        }
    }
    foreach (array('', '_tablet', '_mobile') as $ft_description_sfx) {
        $ft_description_font = isset($s['description_font_family' . $ft_description_sfx]) ? $s['description_font_family' . $ft_description_sfx] : '';
        if (!empty($ft_description_font) && isset($ft_available_google[$ft_description_font])) {
            $ft_google_to_load[] = $ft_description_font;
        }
    }
    if (!empty($s['home_title_font_family']) && isset($ft_available_google[$s['home_title_font_family']])) {
        $ft_google_to_load[] = $s['home_title_font_family'];
    }
    if (!empty($s['home_desc_font_family']) && isset($ft_available_google[$s['home_desc_font_family']])) {
        $ft_google_to_load[] = $s['home_desc_font_family'];
    }
    if (!empty($s['home_count_font_family']) && isset($ft_available_google[$s['home_count_font_family']])) {
        $ft_google_to_load[] = $s['home_count_font_family'];
    }
    if (!empty($s['home_badge_font_family']) && isset($ft_available_google[$s['home_badge_font_family']])) {
        $ft_google_to_load[] = $s['home_badge_font_family'];
    }
    $ft_google_to_load = array_unique($ft_google_to_load);
    foreach ($ft_google_to_load as $ft_google_font) {
        $ft_weights = self::get_font_weights($ft_google_font);
        $ft_weights_str = implode(';', array_map('intval', $ft_weights));
        echo '<link rel="stylesheet" href="' . esc_url('https://fonts.googleapis.com/css2?family=' . rawurlencode($ft_google_font) . ':wght@' . $ft_weights_str . '&display=swap') . '" />' . "\n";
    }
    return $css;
}
private function should_load_family_tree_scripts() {
// Проверяем только на страницах, где может быть древо
if (is_page() || is_single() || is_home() || is_archive()) {
global $post;
if ($post) {
// Проверяем наличие шорткода
if (has_shortcode($post->post_content, 'family_tree')) {
return true;
}
// Проверяем по содержанию
if (strpos($post->post_content, '[family_tree') !== false) {
return true;
}
// Проверяем Gutenberg-блок плагина (сохраняется как <!-- wp:genius-tree/family-tree ... -->)
if (strpos($post->post_content, '<!-- wp:genius-tree/family-tree') !== false) {
return true;
}
}
}
return false;
}
private function should_load_catalog_scripts() {
// Архив "Члены семьи" автоматически показывает каталог фамилий
if (is_post_type_archive('family_member')) {
return true;
}
// Проверяем только на страницах, где может быть каталог фамилий
if (is_page() || is_single() || is_home() || is_archive()) {
global $post;
if ($post) {
// Проверяем наличие шорткода
if (has_shortcode($post->post_content, 'family_surname_catalog')) {
return true;
}
// Проверяем по содержанию
if (strpos($post->post_content, '[family_surname_catalog') !== false) {
return true;
}
// Проверяем Gutenberg-блок плагина
if (strpos($post->post_content, '<!-- wp:genius-tree/persons-catalog') !== false) {
return true;
}
}
}
return false;
}
public function admin_enqueue_scripts($hook) {
global $post_type, $pagenow;
// Вендорный лайтбокс GLightbox (тот же, что и во фронтенде) — для админки фотоальбомов
wp_register_script('family-tree-glightbox', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/glightbox.min.js', array(), '3.2.0', true);
wp_register_style('family-tree-glightbox', FAMILY_TREE_PLUGIN_URL . 'assets/vendor/glightbox.min.css', array(), '3.2.0');
// Флаг страницы настроек плагина (хук сабменю может различаться в зависимости от WP/темы)
$is_ft_settings = (false !== strpos((string) $hook, 'family-tree-settings'));
$is_ft_archive = (false !== strpos((string) $hook, 'family-tree-archive')) || (false !== strpos((string) $hook, 'family-tree-photoalbums'));
// Отключаем heartbeat на странице настроек плагина
if ($is_ft_settings) {
wp_deregister_script('heartbeat');
}
// Стили для страницы «Семейный архив»
if ($is_ft_archive) {
// Медиабиблиотека — для выбора обложки альбома
wp_enqueue_media();
wp_enqueue_style('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/css/admin.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/admin.css'));
// Палитра цветов для настроек фотоальбомов (inline-скрипт на странице «Семейный архив»)
wp_enqueue_style('wp-color-picker');
wp_enqueue_script('wp-color-picker');
// Лайтбокс GLightbox для просмотра фото в полном размере (страницы фотоальбомов)
wp_enqueue_script('family-tree-glightbox');
wp_enqueue_style('family-tree-glightbox');
// Скрипты перестановки фотографий, AJAX и лайтбокса на страницах фотоальбомов
wp_enqueue_script('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/js/admin.js', array('jquery', 'family-tree-glightbox'), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/admin.js'), true);
wp_localize_script('family-tree-admin', 'familyTreeAdmin', array(
'ajaxurl' => admin_url('admin-ajax.php'),
'nonce' => wp_create_nonce('family_tree_admin_nonce'),
'silhouette_man' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-man.svg',
'silhouette_woman' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-woman.svg',
'root_member_id' => $this->get_root_member_id()
));
}
if (($hook == 'post-new.php' || $hook == 'post.php') && ($post_type == 'family_member' || $post_type == 'family_group')) {
wp_enqueue_style('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/css/admin.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/admin.css'));
wp_enqueue_media();
wp_enqueue_script('family-tree-glightbox');
wp_enqueue_style('family-tree-glightbox');
wp_enqueue_script('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/js/admin.js', array('jquery', 'family-tree-glightbox'), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/admin.js'), true);
// Скрипт согласия на публикацию (ФЗ-152) — только для редактора персоналии
if ($post_type == 'family_member') {
wp_enqueue_script('family-tree-admin-consent', FAMILY_TREE_PLUGIN_URL . 'assets/js/admin-consent.js', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/admin-consent.js'), true);
}
// Передача данных в скрипт
wp_localize_script('family-tree-admin', 'familyTreeAdmin', array(
'ajaxurl' => admin_url('admin-ajax.php'),
'nonce' => wp_create_nonce('family_tree_admin_nonce'),
'silhouette_man' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-man.svg',
'silhouette_woman' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-woman.svg',
'root_member_id' => $this->get_root_member_id()
));
}
// Загружаем скрипты и медиабиблиотеку для списка членов семьи (колонка «Фотоальбом»)
if ($hook == 'edit.php' && $post_type == 'family_member') {
wp_enqueue_style('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/css/admin.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/admin.css'));
wp_enqueue_media();
wp_enqueue_script('family-tree-glightbox');
wp_enqueue_style('family-tree-glightbox');
wp_enqueue_script('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/js/admin.js', array('jquery', 'family-tree-glightbox'), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/admin.js'), true);
wp_localize_script('family-tree-admin', 'familyTreeAdmin', array(
'ajaxurl' => admin_url('admin-ajax.php'),
'nonce' => wp_create_nonce('family_tree_admin_nonce'),
'silhouette_man' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-man.svg',
'silhouette_woman' => FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-woman.svg',
'root_member_id' => $this->get_root_member_id()
));
}
// Загружаем стили и скрипты для страницы настроек
if ($is_ft_settings) {
wp_enqueue_style('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/css/admin.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/admin.css'));
wp_enqueue_style('wp-color-picker');
wp_enqueue_media();
wp_enqueue_script('family-tree-glightbox');
wp_enqueue_style('family-tree-glightbox');
wp_enqueue_script('family-tree-settings', FAMILY_TREE_PLUGIN_URL . 'assets/js/admin.js', array('jquery', 'wp-color-picker', 'family-tree-glightbox'), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/admin.js'), true);
wp_localize_script('family-tree-settings', 'familyTreeAdmin', array(
    'ajaxurl' => admin_url('admin-ajax.php'),
    'nonce' => wp_create_nonce('family_tree_license_nonce')
));
}
// ВАЖНО: подключаем CSS и JS модального окна согласия (ФЗ-152)
// На всех админ-страницах плагина, пока пользователь не принял документы
if ($this->should_show_terms_modal() && $this->is_plugin_admin_screen($hook, $post_type, $pagenow)) {
    wp_enqueue_style('family-tree-admin', FAMILY_TREE_PLUGIN_URL . 'assets/css/admin.css', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/css/admin.css'));
    wp_enqueue_script('family-tree-terms-modal', FAMILY_TREE_PLUGIN_URL . 'assets/js/admin-terms-modal.js', array(), (string) filemtime(FAMILY_TREE_PLUGIN_DIR . 'assets/js/admin-terms-modal.js'), true);
    wp_localize_script('family-tree-terms-modal', 'familyTreeTerms', array(
        'ajaxurl' => admin_url('admin-ajax.php'),
        'nonce' => wp_create_nonce('family_tree_terms_nonce')
    ));
}
}
public function add_thumbnail_support() {
add_theme_support('post-thumbnails');
}
/**
 * ФЗ-152: редирект на главную страницу плагина сразу после активации,
 * чтобы пользователь увидел модальное окно с документами.
 */
public function redirect_after_activation($plugin) {
    $needle = plugin_basename(__FILE__);
    if ($plugin !== $needle) {
        return;
    }
    if (isset($_SERVER['REQUEST_URI']) && false !== strpos((string) wp_unslash($_SERVER['REQUEST_URI']), 'activate-multi')) {
        // При массовой активации редирект пропускаем (страница уже перезагружается).
        return;
    }
    if (!headers_sent()) {
        wp_safe_redirect(admin_url('admin.php?page=family-tree-main'));
        exit;
    }
}
/**
 * ФЗ-152: нужно ли показывать модальное окно с документами.
 * Согласие хранится пер-юзер (user_meta) в виде эпохи последней активации.
 * При каждой активации `family_tree_terms_epoch` меняется => окно появляется заново.
 */
public function should_show_terms_modal() {
    $epoch = (string) get_option('family_tree_terms_epoch', '');
    if ('' === $epoch) {
        // Флаг «эпохи» ещё не выставлен (например, устанавливалось до этой версии).
        // Не показываем окно, чтобы не заблокировать существующие установки.
        return false;
    }
    if (!current_user_can('manage_options')) {
        return false;
    }
    $user_id = get_current_user_id();
    $accepted = (string) get_user_meta($user_id, 'family_tree_terms_accepted_epoch', true);
    return $accepted !== $epoch;
}
/**
 * ФЗ-152: AJAX-сохранение согласия пользователя с документами плагина.
 */
public function ajax_accept_terms() {
    check_ajax_referer('family_tree_terms_nonce', 'nonce');
    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Недостаточно прав'), 403);
    }
    $epoch = (string) get_option('family_tree_terms_epoch', '');
    if ('' === $epoch) {
        $epoch = (string) time();
        update_option('family_tree_terms_epoch', $epoch);
    }
    update_user_meta(get_current_user_id(), 'family_tree_terms_accepted_epoch', $epoch);
    wp_send_json_success();
}
/**
 * ФЗ-152: отказ пользователя от принятия документов.
 * Плагин автоматически деактивируется, чтобы не работать без согласия.
 */
public function ajax_decline_terms() {
    check_ajax_referer('family_tree_terms_nonce', 'nonce');
    if (!current_user_can('deactivate_plugin') && !current_user_can('deactivate_plugins')) {
        wp_send_json_error(array('message' => 'Недостаточно прав'), 403);
    }
    if (!function_exists('deactivate_plugins')) {
        require_once ABSPATH . 'wp-admin/includes/plugin.php';
    }
    $basename = plugin_basename(__FILE__);
    // Проверяем, что плагин ещё активен, и деактивируем.
    if (is_plugin_active($basename)) {
        deactivate_plugins($basename);
    }
    wp_send_json_success(array(
        'redirect' => admin_url('plugins.php'),
    ));
}
/**
 * ФЗ-152: проверяет, находится ли пользователь на админ-странице плагина.
 * Оверлей с модальным окном закрывает весь функционал плагина, пока не принято
 * согласие с документами: страницы меню «Семейное древо», «Семейный архив»,
 * а также редакторы/списки записей family_member и family_group.
 */
private function is_plugin_admin_screen($screen_id, $pagenow = '', $post_type = '') {
    if (is_string($screen_id) && false !== strpos($screen_id, 'family-tree')) {
        return true;
    }
    if ('post.php' === $pagenow || 'post-new.php' === $pagenow || 'edit.php' === $pagenow) {
        if (in_array($post_type, array('family_member', 'family_group'), true)) {
            return true;
        }
    }
    return false;
}
