/**
 * Возвращает HTML документов плагина с разбивкой на секции (для окна просмотра в настройках).
 * Каждая секция помечена атрибутом data-ft-doc-id для навигации по ссылкам.
 * @return string
 */
private function get_terms_documents_sections_html() {
    $docs_html = $this->get_terms_documents_html();
    $sections = array(
        '1' => '',
        '2' => '',
    );
    // Разбиваем общий HTML по заголовкам третьего уровня (каждый документ начинается с <h3>).
    $parts = preg_split('/(?=<h3>)/', $docs_html);
    $index = 1;
    foreach ($parts as $part) {
        $trimmed = trim($part);
        if ($trimmed === '') {
            continue;
        }
        if (!isset($sections[(string) $index])) {
            break;
        }
        $sections[(string) $index] = '<div class="ft-terms-doc-section" data-ft-doc-id="' . $index . '">' . $trimmed . '</div>';
        $index++;
    }
    return $sections['1'] . $sections['2'];
}
