/**
 * Шорткод [family_archive] — WooCommerce-стиль каталог подразделов семейного архива.
 * Показывает: Фотоальбомы, Документы, Видео, Дерево (карточки-ссылки).
 */
public function render_family_archive($atts) {
    if (is_admin()) return '';
    $ft_sections = ft_get_archive_sections();
    // Доступные подразделы (из настроек таба «Разделы»)
    $sections = array();
    foreach ($ft_sections as $ft_section_id => $ft_section_cfg) {
        if (empty($ft_section_cfg['enabled'])) {
            continue;
        }
        $is_photoalbums = ('photoalbums' === $ft_section_id);
        $section = array(
            'title'       => $ft_section_cfg['title'],
            'description' => $ft_section_cfg['description'],
            'icon'        => ft_archive_section_icon_html($ft_section_id, intval($ft_section_cfg['image'])),
            'url'         => '#',
            'count'       => 0,
            'count_html'  => '',
            'coming_soon' => !empty($ft_section_cfg['coming_soon']),
        );
        if ($is_photoalbums) {
            $section['url']     = $this->get_archive_page_url('photoalbums');
            $section['count']   = $this->count_all_album_photos();
            $section['albums']  = $this->count_all_albums();
            $section['count_html'] = ft_album_count_label($section['albums']) . ', ' . $this->album_photo_count_label($section['count']);
        } else {
            $stats = ft_archive_section_stats($ft_section_id);
            $has_content = intval($stats['files']) > 0;
            if ($has_content) {
                $section['url']         = $this->get_archive_page_url($ft_section_id);
                $section['count']       = $stats['files'];
                $section['count_html']  = ft_archive_section_counts_label($ft_section_id, $stats['albums'], $stats['files']);
                $section['coming_soon'] = false;
            }
        }
        $sections[] = $section;
    }
    $archive_id = get_option('family_tree_archive_page_id', 0);
    $base_url = $archive_id ? get_permalink($archive_id) : '#';
    $ft_home_s = $this->get_album_display_settings();
    $ft_home_cols = max(1, min(8, intval($ft_home_s['home_columns'])));
    $ft_home_gap = max(0, intval($ft_home_s['home_gap']));
    $ft_home_maxw = max(0, intval($ft_home_s['home_catalog_max_width']));
    $ft_home_maxw_unit = ('px' === $ft_home_s['home_catalog_max_width_unit']) ? 'px' : '%';
    $ft_home_align = in_array($ft_home_s['home_catalog_align'], array('center', 'left', 'right'), true) ? $ft_home_s['home_catalog_align'] : 'center';
    $pa_settings = ft_get_person_albums_settings();
    $ft_home_catalog_style = 'padding:20px 0;';
    if (100 !== $ft_home_maxw || '%' !== $ft_home_maxw_unit) {
        $ft_home_catalog_style .= 'max-width:' . $ft_home_maxw . $ft_home_maxw_unit . ';';
    }
    if ('left' === $ft_home_align) {
        $ft_home_catalog_style .= 'margin-right:auto;';
    } elseif ('right' === $ft_home_align) {
        $ft_home_catalog_style .= 'margin-left:auto;';
    } else {
        $ft_home_catalog_style .= 'margin:0 auto;';
    }
    ob_start();
    ?>
    <div class="ft-archive-catalog" style="<?php echo esc_attr($ft_home_catalog_style); ?>">
        <style type="text/css"><?php echo ft_person_albums_css($pa_settings); ?></style>
        <style type="text/css"><?php echo $this->build_album_display_css($ft_home_s); ?></style>
        <div class="ft-archive-catalog__grid" style="display:grid;grid-template-columns:repeat(<?php echo esc_attr($ft_home_cols); ?>,minmax(0,1fr));gap:<?php echo esc_attr($ft_home_gap); ?>px;">
            <style type="text/css">@media (max-width:767px){.ft-archive-catalog__grid{grid-template-columns:repeat(1,minmax(0,1fr)) !important;}}</style>
            <?php foreach ($sections as $s) : ?>
            <a href="<?php echo esc_url($s['url']); ?>"
               class="ft-archive-card<?php echo !empty($s['coming_soon']) ? ' ft-archive-card--coming-soon' : ''; ?>"
               style="display:flex;flex-direction:column;align-items:center;text-align:center;padding:32px 20px;background:#fff;border:1px solid #ddd;border-radius:8px;text-decoration:none;color:inherit;transition:box-shadow .2s,border-color .2s;<?php if (empty($s['coming_soon'])) : ?>cursor:pointer;<?php endif; ?>"
               <?php if (!empty($s['coming_soon'])) : ?>onclick="return false;"<?php endif; ?>>
                <div class="ft-archive-card__icon" style="color:#2271b1;margin-bottom:16px;">
                    <?php echo $s['icon']; ?>
                </div>
                <h3 class="ft-archive-card__title" style="margin:0 0 8px;font-size:18px;font-weight:600;color:#1d2327;">
                    <?php echo esc_html($s['title']); ?>
                </h3>
                <p class="ft-archive-card__desc" style="margin:0 0 12px;font-size:14px;color:#646970;line-height:1.4;">
                    <?php echo esc_html($s['description']); ?>
                </p>
                <?php if (intval($s['count']) > 0 && '' !== $s['count_html']) : ?>
                <span class="ft-archive-card__count" style="font-size:13px;color:#888;">
                    <?php echo esc_html($s['count_html']); ?>
                </span>
                <?php endif; ?>
                <?php if (!empty($s['coming_soon'])) : ?>
                <span class="ft-archive-card__badge" style="margin-top:10px;padding:3px 10px;background:#f0f0f1;border-radius:4px;font-size:12px;color:#999;">
                    <?php echo esc_html__('Скоро', 'genius-family-tree'); ?>
                </span>
                <?php endif; ?>
            </a>
            <?php endforeach; ?>
        </div>
    </div>
    <?php
    return ob_get_clean();
}
/**
 * Возвращает URL подраздела архива на фронтенде.
 */
public function get_archive_page_url($section) {
    $page_id = get_option('family_tree_archive_page_id', 0);
    if (!$page_id) return '#';
    $base = get_permalink($page_id);
    return $base . $section . '/';
}
/**
 * Возвращает URL раздела «Фотоальбомы персоны» в семейном архиве:
 * /{archive-slug}/photoalbums/{member-slug}/
 *
 * @param int|WP_Post $member
 */
public function get_member_albums_url($member) {
    $id = is_object($member) ? $member->ID : (int) $member;
    $slug = $id ? get_post_field('post_name', $id) : '';
    return trailingslashit($this->get_archive_page_url('photoalbums')) . ($slug ? $slug : $id) . '/';
}
/**
 * Возвращает URL отдельного альбома персоны:
 * /{archive-slug}/photoalbums/{member-slug}/{album-slug}/
 *
 * @param int|WP_Post $member
 * @param string      $album_name
 */
public function get_member_album_url($member, $album_name) {
    return $this->get_member_albums_url($member) . sanitize_title($album_name) . '/';
}
/**
 * Возвращает URL отдельной фотографии персоны:
 * /{archive-slug}/photoalbums/{member-slug}/{album-slug}/{photo-slug}/
 *
 * @param int|WP_Post $member
 * @param string      $album_name
 * @param int|WP_Post $photo вложение (attachment) фотографии
 */
public function get_member_photo_url($member, $album_name, $photo) {
    $id = is_object($photo) ? $photo->ID : (int) $photo;
    $slug = $id ? get_post_field('post_name', $id) : '';
    return $this->get_member_album_url($member, $album_name) . ($slug ? $slug : $id) . '/';
}
/**
 * Возвращает URL раздела персоны в семейном архиве:
 * /{archive-slug}/{section}/{member-slug}/
 *
 * @param int|WP_Post $member
 * @param string      $section ID раздела.
 */
public function get_member_section_url($member, $section) {
    $id = is_object($member) ? $member->ID : (int) $member;
    $slug = $id ? get_post_field('post_name', $id) : '';
    return trailingslashit($this->get_archive_page_url($section)) . ($slug ? $slug : $id) . '/';
}
/**
 * Возвращает URL папки/альбома персоны в разделе:
 * /{archive-slug}/{section}/{member-slug}/{folder-slug}/
 *
 * @param int|WP_Post $member
 * @param string      $section     ID раздела.
 * @param string      $folder_name название папки/альбома.
 */
public function get_member_section_folder_url($member, $section, $folder_name) {
    return $this->get_member_section_url($member, $section) . sanitize_title($folder_name) . '/';
}
/**
 * Возвращает URL отдельного фото персоны в разделе:
 * /{archive-slug}/{section}/{member-slug}/{folder-slug}/{item-slug}/
 *
 * @param int|WP_Post $member
 * @param string      $section     ID раздела.
 * @param string      $folder_name название папки/альбома.
 * @param int|WP_Post $item        вложение (attachment).
 */
public function get_member_section_item_url($member, $section, $folder_name, $item) {
    $id = is_object($item) ? $item->ID : (int) $item;
    $slug = $id ? get_post_field('post_name', $id) : '';
    return $this->get_member_section_folder_url($member, $section, $folder_name) . ($slug ? $slug : $id) . '/';
}
/**
 * Резолвит контекст отдельной страницы фотографии по query-переменным.
 * Возвращает null, если страница не является страницей фото или контекст не найден.
 *
 * @return array|null ['member' => WP_Post, 'album_name' => string, 'photo' => WP_Post, 'photos' => int[]]|null
 */
private function archive_photo_context() {
    if (is_admin()) {
        return null;
    }
    $section = get_query_var('ft_section');
    if (empty($section)) {
        return null;
    }
    $sec_cfg = ft_get_archive_sections();
    if (!isset($sec_cfg[$section]) || empty($sec_cfg[$section]['enabled'])) {
        return null;
    }
    $member_slug = get_query_var('ft_member');
    $album_slug = get_query_var('ft_album');
    $photo_slug = get_query_var('ft_photo');
    if (!$member_slug || !$album_slug || !$photo_slug) {
        return null;
    }
    $member = get_page_by_path($member_slug, OBJECT, 'family_member');
    if (!$member || $member->post_status !== 'publish') {
        return null;
    }
    foreach (ft_get_albums($member->ID, $section) as $a) {
        if (sanitize_title($a['name']) !== $album_slug) {
            continue;
        }
        $photos = array_values(array_filter(array_map('intval', (array) $a['photos']), 'wp_attachment_is_image'));
        if (empty($photos)) {
            return null;
        }
        $photo = null;
        foreach ($photos as $pid) {
            if (get_post_field('post_name', $pid) === $photo_slug || (string) $photo_slug === (string) $pid) {
                $photo = get_post($pid);
                break;
            }
        }
        if (!$photo) {
            return null;
        }
        return array(
            'member'     => $member,
            'album_name' => $a['name'],
            'photo'      => $photo,
            'photos'     => $photos,
            'section'    => $section,
        );
    }
    return null;
}
/**
 * Заголовок вкладки/страницы для отдельной фотографии (WP 4.4+ title-tag).
 */
public function archive_document_title($parts) {
    $ctx = $this->archive_photo_context();
    if (!$ctx) return $parts;
    $caption = get_the_title($ctx['photo']->ID);
    if ($caption !== '') {
        $parts['title'] = $caption;
    }
    return $parts;
}
/**
 * SEO-заголовок Yoast для отдельной фотографии.
 */
public function archive_yoast_title($title) {
    $ctx = $this->archive_photo_context();
    if (!$ctx) return $title;
    $caption = get_the_title($ctx['photo']->ID);
    return ($caption !== '') ? $caption : $title;
}
/**
 * Заголовок для классических тем (wp_title).
 */
public function archive_wp_title($title, $sep = '', $seplocation = '') {
    $ctx = $this->archive_photo_context();
    if (!$ctx || $sep === '') return $title;
    $caption = get_the_title($ctx['photo']->ID);
    if ($caption === '') return $title;
    $t = trim($caption);
    if ('right' === $seplocation) {
        $t .= " $sep ";
    } else {
        $t = " $sep " . $t;
    }
    return $t;
}
/**
 * Находит запись персоны по ID или slug для шорткодов архива.
 */
private function resolve_archive_member($person) {
    if (empty($person)) return null;
    if (is_numeric($person)) {
        $post = get_post((int) $person);
        return ($post && $post->post_type === 'family_member' && $post->post_status === 'publish') ? $post : null;
    }
    $post = get_page_by_path(sanitize_title($person), OBJECT, 'family_member');
    return ($post && $post->post_status === 'publish') ? $post : null;
}
/**
 * Отрисовывает сетку фотографий альбома.
 * При mode = page ссылки ведут на отдельные страницы фотографий,
 * иначе — на полное изображение (лайтбокс).
 */
public function render_album_photos_grid($photos, $gallery_id, $member = null, $album_name = '', $photo_open = 'lightbox') {
    if (ft_hide_field('photo')) {
        return '';
    }
    $html = '<div class="ft-album-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;">';
    foreach ($photos as $photo_id) {
        $full = wp_get_attachment_image_src($photo_id, 'large');
        $thumb = wp_get_attachment_image_src($photo_id, 'medium');
        $caption = wp_get_attachment_caption($photo_id);
        if (!$thumb) continue;
        if (!$full) $full = $thumb;
        if ($photo_open === 'page' && $member) {
            $url = $this->get_member_photo_url($member, $album_name, $photo_id);
            $html .= '<a href="' . esc_url($url) . '" class="ft-album-photo ft-photo-page-link" title="' . esc_attr($caption) . '" style="display:block;border-radius:6px;overflow:hidden;border:1px solid #ddd;">';
        } else {
            $html .= '<a href="' . esc_url($full[0]) . '" class="ft-album-photo glightbox" data-ft-album-photo="1" data-gallery="' . esc_attr($gallery_id) . '" data-caption="' . esc_attr($caption) . '" title="' . esc_attr($caption) . '" style="display:block;border-radius:6px;overflow:hidden;border:1px solid #ddd;">';
        }
        $html .= '<img src="' . esc_url($thumb[0]) . '" alt="' . esc_attr($caption) . '" loading="lazy" style="display:block;width:100%;height:180px;object-fit:cover;" />';
        $html .= '</a>';
    }
    $html .= '</div>';
    return $html;
}
/**
 * Карточка обложки альбома/папки: фотография, название, количество материалов.
 *
 * @param int|WP_Post $member
 * @param array       $album
 * @param string      $section ключ раздела (по умолчанию photoalbums).
 */
public function render_album_cover_card($member, $album, $section = 'photoalbums') {
    $cover_id = !empty($album['cover']) ? (int) $album['cover'] : (!empty($album['photos']) ? (int) reset($album['photos']) : 0);
    $img = ($cover_id && !ft_hide_field('photo')) ? wp_get_attachment_image_src($cover_id, 'medium') : false;
    $src = $img ? $img[0] : '';
    $count = count(array_filter(array_map('intval', (array) $album['photos']), 'wp_attachment_is_image'));
    if ('photoalbums' === $section) {
        $url = $this->get_member_album_url($member, $album['name']);
        $count_label = $this->person_section_item_count_label($section, $count);
    } else {
        $url = $this->get_member_section_folder_url($member, $section, $album['name']);
        $count_label = $this->person_section_item_count_label($section, $count);
    }
    $html = '<a href="' . esc_url($url) . '" class="ft-albums-cover-card" style="display:block;border:1px solid #ddd;border-radius:8px;overflow:hidden;text-decoration:none;color:inherit;background:#fff;transition:box-shadow .2s,border-color .2s;">';
    if ($src) {
        $html .= '<span style="display:block;overflow:hidden;"><img src="' . esc_url($src) . '" alt="' . esc_attr($album['name']) . '" loading="lazy" style="display:block;width:100%;height:140px;object-fit:cover;"></span>';
    } else {
        $html .= '<span style="display:block;height:140px;background:#f0f0f1;"></span>';
    }
    $html .= '<span style="display:block;padding:10px 12px;">';
    $html .= '<span class="ft-albums-cover-name" style="display:block;font-weight:600;color:#1d2327;font-size:15px;">' . esc_html($album['name']) . '</span>';
    $html .= '<span class="ft-albums-cover-count" style="display:block;font-size:12px;color:#646970;margin-top:2px;">' . esc_html($count_label) . '</span>';
    $html .= '</span></a>';
    return $html;
}
/**
 * Секция «Фотоальбомы» (или другого раздела семейного архива) персоны по режиму отображения:
 *  - all          — все фотографии единой сеткой;
 *  - album_photos — фотографии выбранного альбома/папки;
 *  - album_covers — обложки всех альбомов (название + количество фото);
 *  - select_albums — обложки выбранных альбомов (один или несколько).
 * Режим хранится в мете персоны (ft_get_album_display) или передаётся через $force.
 *
 * @param int|WP_Post $member
 * @param array       $force            ['mode' => ..., 'album' => slug] — принудительный режим.
 * @param bool        $show_archive_link ссылка «Все фотоальбомы»/на раздел.
 * @param string      $section          ключ раздела (по умолчанию photoalbums).
 */
public function render_person_albums_section($member, $force = array(), $show_archive_link = true, $section = 'photoalbums') {
    $id = is_object($member) ? $member->ID : (int) $member;
    if (!$id) {
        return '';
    }
    // Скрытые персоны не отдают свои фотоальбомы, а при закрытом древе секция не выводится
    if (ft_person_is_private($id)) {
        return '';
    }
    if (ft_privacy_visibility() === 'blocked') {
        return '';
    }
    $section = sanitize_key($section);
    if ('' === $section) {
        $section = 'photoalbums';
    }
    // Фотоальбомы не показываем, если фото скрыты администратором
    if ('photoalbums' === $section && ft_hide_field('photo')) {
        return '';
    }
    if (in_array($section, ft_get_person_disabled_sections($id), true)) {
        return '';
    }
    $terms = ft_archive_section_terms($section);
    $sec_cfg = ft_get_archive_sections();
    if ('photoalbums' === $section) {
        $sec_title = __('Фотоальбомы', 'genius-family-tree');
    } else {
        $sec_title = (!empty($sec_cfg[$section]['title'])) ? $sec_cfg[$section]['title'] : $terms['name'];
    }
    if ('photoalbums' === $section) {
        $block_title = __('Фотоальбомы', 'genius-family-tree');
        $msg_empty_folder = __('В этом альбоме нет фотографий.', 'genius-family-tree');
        $msg_empty_all = __('Фотографии ещё не добавлены.', 'genius-family-tree');
    } else {
        $block_title = $sec_title;
        $msg_empty_folder = __('В этой папке пока нет материалов.', 'genius-family-tree');
        $msg_empty_all = sprintf(__('Материалы раздела «%1$s» ещё не добавлены.', 'genius-family-tree'), $sec_title);
    }
    $all_label = $this->person_section_all_label($section);
    $all_url = $this->person_section_all_url($id, $section);
    $albums = ft_get_albums($id, $section);
    $albums = array_values(array_filter($albums, function($a) { return !empty($a['photos']); }));
    if (empty($albums)) {
        return '';
    }
    if (!empty($force) && is_array($force)) {
        $cfg = array(
            'mode'   => isset($force['mode']) ? $force['mode'] : 'all',
            'album'  => isset($force['album']) ? sanitize_title($force['album']) : '',
            'albums' => isset($force['albums']) && is_array($force['albums']) ? array_values(array_unique(array_filter(array_map('sanitize_title', $force['albums'])))) : array(),
        );
    } else {
        $cfg = ft_get_album_display($id, $section);
    }
    if ($cfg['mode'] === 'one_album') {
        $cfg['mode'] = 'select_albums';
    }
    if (!in_array($cfg['mode'], array('all', 'album_photos', 'album_covers', 'select_albums'), true)) {
        $cfg['mode'] = 'all';
    }
    $s = $this->get_album_display_settings();
    $photo_open = isset($s['photo_open']) ? $s['photo_open'] : 'lightbox';
    if (!in_array($photo_open, array('lightbox', 'page'), true)) {
        $photo_open = 'lightbox';
    }
    $target = null;
    if ($cfg['album']) {
        foreach ($albums as $a) {
            if (sanitize_title($a['name']) === $cfg['album']) {
                $target = $a;
                break;
            }
        }
    }
    if ($cfg['mode'] === 'album_photos' && !$target) {
        // Выбранный альбом не найден — показываем обложки всех альбомов.
        $cfg['mode'] = 'album_covers';
    }
    ob_start();
    if ($cfg['mode'] === 'album_photos') {
        $photos_full = array_values(array_filter(array_map('intval', (array) $target['photos']), 'wp_attachment_is_image'));
        $photos = $photos_full;
        if (intval($s['photos_count']) > 0) {
            $photos = array_slice($photos, 0, max(1, min(500, intval($s['photos_count']))));
        }
        if (empty($photos)) {
            echo '<div class="family-member-photo-album ft-album-view"><p>' . esc_html($msg_empty_folder) . '</p></div>';
        } else {
            $album_names = array();
            foreach ($photos as $pid) {
                $album_names[$pid] = $target['name'];
            }
            echo $this->render_person_album_block($photos, (int) $id, $block_title, !empty($target['description']) ? $target['description'] : '', $photo_open, $album_names, $target['name'], count($photos_full), $section);
        }
    } elseif ($cfg['mode'] === 'album_covers') {
        echo '<div class="family-member-photo-album">';
        echo '<div class="family-member-photo-album__header">';
        echo '<h2 class="family-member-photo-album__title">' . esc_html($block_title) . '</h2>';
        if ($show_archive_link) {
            echo '<a href="' . esc_url($all_url) . '" class="ft-photo-page__nav-link">' . esc_html($all_label) . ' &rarr;</a>';
        }
        echo '</div>';
        echo '<div class="ft-albums-covers" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));">';
        foreach ($albums as $a) {
            echo $this->render_album_cover_card($id, $a, $section);
        }
        echo '</div>';
        echo '</div>';
    } elseif ($cfg['mode'] === 'select_albums') {
        $selected = array();
        foreach ($albums as $a) {
            if (in_array(sanitize_title($a['name']), $cfg['albums'], true)) {
                $selected[] = $a;
            }
        }
        if (empty($selected)) {
            // Ничего не выбрано — показываем обложки всех альбомов.
            $selected = $albums;
        }
        echo '<div class="family-member-photo-album">';
        echo '<div class="family-member-photo-album__header">';
        echo '<h2 class="family-member-photo-album__title">' . esc_html($block_title) . '</h2>';
        if ($show_archive_link) {
            echo '<a href="' . esc_url($all_url) . '" class="ft-photo-page__nav-link">' . esc_html($all_label) . ' &rarr;</a>';
        }
        echo '</div>';
        echo '<div class="ft-albums-covers" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));">';
        foreach ($selected as $a) {
            echo $this->render_album_cover_card($id, $a, $section);
        }
        echo '</div>';
        echo '</div>';
    } else {
        $photos = array();
        $album_names = array();
        $ft_single_name = '';
        $ft_single_desc = '';
        $ft_single_total = 0;
        if (1 === count($albums)) {
            $ft_single_album = $albums[0];
            $ft_single_name = isset($ft_single_album['name']) ? $ft_single_album['name'] : '';
            $ft_single_desc = !empty($ft_single_album['description']) ? $ft_single_album['description'] : '';
            $ft_single_total = count(array_values(array_filter(array_map('intval', (array) $ft_single_album['photos']), 'wp_attachment_is_image')));
        }
        foreach ($albums as $a) {
            $p = array_values(array_filter(array_map('intval', (array) $a['photos']), 'wp_attachment_is_image'));
            if (intval($s['photos_count']) > 0) {
                $p = array_slice($p, 0, max(1, min(500, intval($s['photos_count']))));
            }
            $photos = array_merge($photos, $p);
            foreach ($p as $pid) {
                if (!isset($album_names[$pid])) {
                    $album_names[$pid] = $a['name'];
                }
            }
        }
        if (empty($photos)) {
            echo '<div class="family-member-photo-album ft-album-view"><p>' . esc_html($msg_empty_all) . '</p></div>';
        } else {
            echo $this->render_person_album_block($photos, (int) $id, $block_title, $ft_single_desc, $photo_open, $album_names, $ft_single_name, $ft_single_total, $section);
        }
    }
    return ob_get_clean();
}
/**
 * Склонение «фотография/фотографии/фотографий» для количества.
 *
 * @param int $count
 * @return string например «20 фотографий».
 */
private function album_photo_count_label($count) {
    $count = absint($count);
    $mod10 = $count % 10;
    $mod100 = $count % 100;
    if (1 === $mod10 && 11 !== $mod100) {
        $word = __('фотография', 'genius-family-tree');
    } elseif ($mod10 >= 2 && $mod10 <= 4 && ($mod100 < 12 || $mod100 > 14)) {
        $word = __('фотографии', 'genius-family-tree');
    } else {
        $word = __('фотографий', 'genius-family-tree');
    }
    return $count . ' ' . $word;
}
/**
 * Счётная подпись материалов альбома с учётом раздела архива.
 *
 * @param string $section ключ раздела.
 * @param int    $count   количество материалов.
 * @return string
 */
private function person_section_item_count_label($section, $count) {
    return ('photoalbums' === $section)
        ? $this->album_photo_count_label($count)
        : ft_archive_item_name($section, $count);
}
/**
 * Название ссылки перехода к конкретному альбому/папке раздела.
 *
 * @param string $section ключ раздела.
 * @return string
 */
private function person_section_folder_link_label($section) {
    $labels = array(
        'photoalbums' => __('Перейти в фотоальбом', 'genius-family-tree'),
        'documents'   => __('Перейти в альбом', 'genius-family-tree'),
        'video'       => __('Перейти к источнику', 'genius-family-tree'),
        'tree'        => __('Перейти к адресату', 'genius-family-tree'),
    );
    if (isset($labels[$section])) {
        return $labels[$section];
    }
    return __('Перейти в альбом', 'genius-family-tree');
}
/**
 * Текст кнопки «Все …» раздела в шапке альбомного блока персоны.
 *
 * @param string $section ключ раздела.
 * @return string
 */
private function person_section_all_label($section) {
    $map = array(
        'photoalbums' => __('Все фотоальбомы', 'genius-family-tree'),
        'documents'   => __('Все документы', 'genius-family-tree'),
        'video'       => __('Вся пресса', 'genius-family-tree'),
        'tree'        => __('Все письма', 'genius-family-tree'),
    );
    if (isset($map[$section])) {
        return $map[$section];
    }
    $sec_cfg = ft_get_archive_sections();
    $title = (!empty($sec_cfg[$section]['title'])) ? $sec_cfg[$section]['title'] : '';
    if ('' !== $title) {
        return sprintf(__('Все %1$s', 'genius-family-tree'), mb_strtolower($title, 'UTF-8'));
    }
    return __('Все материалы раздела', 'genius-family-tree');
}
/**
 * URL кнопки «Все …» раздела в шапке альбомного блока персоны.
 *
 * @param int    $member_id ID персоны.
 * @param string $section   ключ раздела.
 * @return string
 */
private function person_section_all_url($member_id, $section) {
    return ('photoalbums' === $section) ? $this->get_member_albums_url($member_id) : $this->get_member_section_url($member_id, $section);
}
/**
 * Блок «фотографии персоны» в стандартной разметке .family-member-photo-album.
 * Раскладка, подписи, карусель, оформление обложек/заголовков и открытие фото
 * берутся из настроек «Семейный архив → Настройки».
 *
 * @param array  $photos      массив ID вложений-фотографий.
 * @param int    $member_id   ID персоны (для ссылок на страницы фотографий).
 * @param string $title       заголовок блока (h2).
 * @param string $description описание альбома ('' — без описания).
 * @param string $photo_open  lightbox|page.
 * @param array  $album_names карта photo_id => имя альбома (для ссылок на страницы фото).
 * @param string $album_name  имя альбома для подзаголовка «Альбом …» ('' — не выводить).
 * @param int    $album_photos_total всего фотографий в альбоме (для подзаголовка).
 * @param string $section     ключ раздела (по умолчанию photoalbums).
 */
private function render_person_album_block($photos, $member_id, $title, $description, $photo_open, $album_names = array(), $album_name = '', $album_photos_total = 0, $section = 'photoalbums') {
    $s = $this->get_album_display_settings();
    $layout = in_array($s['album_layout'], array('grid', 'tile', 'masonry', 'mosaic', 'carousel', 'carousel-fluid'), true) ? $s['album_layout'] : 'grid';
    $captions = !empty($s['captions']);
    $caption_position = in_array($s['caption_position'], array('below', 'above', 'overlay'), true) ? $s['caption_position'] : 'below';
    $speed = isset($s['carousel_speed']) ? max(200, min(5000, intval($s['carousel_speed']))) : 400;
    $scroll = in_array(isset($s['carousel_scroll']) ? $s['carousel_scroll'] : 'one', array('one', 'all'), true) ? $s['carousel_scroll'] : 'one';
    $ratio = ('carousel' === $layout && !empty($s['image_ratio']) && 'inherit' !== $s['image_ratio']) ? '1' : '0';
    $lazy = !empty($s['carousel_lazyload']) ? 'lazy' : 'eager';
    $gallery_id = 'family-member-photo-album-' . (int) $member_id;
    $html = '<div class="family-member-photo-album ft-layout-' . esc_attr($layout) . (('carousel-fluid' === $layout) ? ' ft-layout-carousel' : '') . ' ft-captions-' . esc_attr($caption_position) . '"';
    $html .= ' data-album-autoplay="' . (!empty($s['carousel_autoplay']) ? '1' : '0') . '"';
    $html .= ' data-album-hover-pause="' . (!empty($s['carousel_hover_pause']) ? '1' : '0') . '"';
    $html .= ' data-album-speed="' . esc_attr($speed) . '"';
    $html .= ' data-album-scroll="' . esc_attr($scroll) . '"';
    $html .= ' data-album-loop="' . (!empty($s['carousel_loop']) ? '1' : '0') . '"';
    $html .= ' data-album-ratio="' . esc_attr($ratio) . '">';
    if ('' !== $title) {
        $html .= '<div class="family-member-photo-album__header">';
        $html .= '<h2 class="family-member-photo-album__title">' . esc_html($title) . '</h2>';
        $html .= '<a href="' . esc_url($this->person_section_all_url($member_id, $section)) . '" class="ft-photo-page__nav-link">' . esc_html($this->person_section_all_label($section)) . ' &rarr;</a>';
        $html .= '</div>';
    }
    if ('' !== $album_name) {
        if (!empty($s['show_album_subheader'])) {
            $html .= '<div class="family-member-photo-album__subheader">';
            $html .= '<span class="family-member-photo-album__subheader-name">' . esc_html(sprintf(__('Альбом «%s», %s', 'genius-family-tree'), $album_name, $this->person_section_item_count_label($section, $album_photos_total))) . '</span>';
            $folder_url = ('photoalbums' === $section)
                ? $this->get_member_album_url($member_id, $album_name)
                : $this->get_member_section_folder_url($member_id, $section, $album_name);
            $html .= '<a href="' . esc_url($folder_url) . '" class="ft-photo-page__nav-link">' . esc_html($this->person_section_folder_link_label($section)) . ' &rarr;</a>';
            $html .= '</div>';
        }
    }
    if ('' !== $description && !empty($s['show_album_description'])) {
        $desc_color = !empty($s['description_color']) ? $s['description_color'] : '#50575e';
        $desc_size = intval($s['description_font_size']) > 0 ? intval($s['description_font_size']) : 14;
        $desc_rule = '';
        if (!empty($s['description_font_family'])) {
            $desc_rule .= 'font-family:\'' . esc_attr($s['description_font_family']) . '\', serif;';
        }
        if (intval($s['description_font_weight']) > 0) {
            $desc_rule .= 'font-weight:' . intval($s['description_font_weight']) . ';';
        }
        $html .= '<div class="ft-album-description" style="color:' . esc_attr($desc_color) . ';font-size:' . $desc_size . 'px;' . $desc_rule . 'line-height:1.6;margin:0 0 30px;">' . nl2br(esc_html($description)) . '</div>';
    }
    $html .= '<div class="ft-album-carousel-wrap">';
    if ('carousel' === $layout || 'carousel-fluid' === $layout) {
        $html .= '<div class="ft-album-carousel-controls">';
        $html .= '<button type="button" class="ft-album-prev" aria-label="' . esc_attr__('Предыдущие фотографии', 'genius-family-tree') . '">&lsaquo;</button>';
        $html .= '<button type="button" class="ft-album-next" aria-label="' . esc_attr__('Следующие фотографии', 'genius-family-tree') . '">&rsaquo;</button>';
        $html .= '</div>';
    }
    $html .= '<div class="family-member-photo-grid family-member-photo-track">';
    foreach ($photos as $photo_id) {
        $thumb = wp_get_attachment_image_src($photo_id, 'thumbnail');
        if (!$thumb) {
            continue;
        }
        $medium = wp_get_attachment_image_src($photo_id, 'medium');
        $full = wp_get_attachment_image_src($photo_id, 'full');
        $src = $medium ? $medium[0] : $thumb[0];
        $full_url = $full ? $full[0] : $src;
        $photo_title = get_the_title($photo_id);
        $html .= '<figure class="family-member-photo-item">';
        if ('page' === $photo_open) {
            $photo_album = isset($album_names[$photo_id]) ? $album_names[$photo_id] : $album_name;
            if ('photoalbums' === $section) {
                $html .= '<a href="' . esc_url($this->get_member_photo_url($member_id, $photo_album, $photo_id)) . '">';
            } else {
                $html .= '<a href="' . esc_url($this->get_member_section_item_url($member_id, $section, $photo_album, $photo_id)) . '">';
            }
        } else {
            $html .= '<a href="' . esc_url($full_url) . '" data-gallery="' . esc_attr($gallery_id) . '" data-title="' . esc_attr($photo_title) . '">';
        }
        $html .= '<img src="' . esc_url($src) . '" alt="' . esc_attr($photo_title) . '" loading="' . esc_attr($lazy) . '" />';
        $html .= '</a>';
        if ($captions && '' !== $photo_title) {
            $html .= '<figcaption>' . esc_html($photo_title) . '</figcaption>';
        }
        $html .= '</figure>';
    }
    $html .= '</div></div></div>';
    return $html;
}
/**
 * Общая вёрстка «фотоальбомы персоны»: шапка, переключатель альбомов,
 * выбранный альбом, навигация пред/след. Используется шорткодами
 * [family_member_albums] и [family_album].
 *
 * @param WP_Post $member
 * @param string  $requested_slug slug выбранного альбома ('' — первый).
 */
private function render_member_albums_view($member, $requested_slug = '') {
    // При полностью закрытом древе — заглушка вместо страницы альбомов
    if (ft_privacy_visibility() === 'blocked') {
        return ft_privacy_render_blocked();
    }
    // Скрытая администратором персона — только заглушка
    if (ft_person_is_private($member->ID)) {
        return ft_privacy_render_person_hidden();
    }
    $album_slug = sanitize_title((string) $requested_slug);
    $albums = ft_get_albums($member->ID);
    $albums = array_values(array_filter($albums, function($a) { return !empty($a['photos']); }));
    $member_albums_url = $this->get_member_albums_url($member);
    $catalog_url = $this->get_archive_page_url('photoalbums');
    $thumb_id = get_post_thumbnail_id($member->ID);
    $thumb_src = '';
    if ($thumb_id && !ft_hide_field('photo')) {
        $arr = wp_get_attachment_image_src($thumb_id, 'medium');
        $thumb_src = $arr ? $arr[0] : '';
    }
    $birth_year = get_post_meta($member->ID, '_family_member_birth_year', true);
    $death_year = get_post_meta($member->ID, '_family_member_death_year', true);
    $years = '';
    if ((!ft_hide_field('dates') && !ft_hide_field('years')) && $birth_year) { $years = $birth_year . ($death_year ? ' — ' . $death_year : ''); }
    ob_start();
    ?>
    <?php $pa_settings = ft_get_person_albums_settings(); ?>
    <div class="ft-member-albums-shortcode" style="margin:20px 0;">
        <style type="text/css"><?php echo ft_person_albums_css($pa_settings); ?></style>
        <div class="ft-albums-header">
            <div class="ft-albums-header__inner">
            <?php if ($thumb_src) : ?>
                <img src="<?php echo esc_url($thumb_src); ?>" width="84" height="84" class="ft-albums-header__avatar" alt="<?php echo esc_attr(ft_person_display_name($member->ID, get_the_title($member->ID))); ?>" />
            <?php else : ?>
                <div class="ft-albums-header__avatar ft-albums-header__avatar--empty"><?php echo esc_html(mb_strtoupper(mb_substr(ft_person_display_name($member->ID, get_the_title($member->ID)), 0, 1, 'UTF-8'), 'UTF-8')); ?></div>
            <?php endif; ?>
            <div>
                <h1 class="ft-albums-header-title"><?php echo esc_html(ft_person_display_name($member->ID, get_the_title($member->ID))); ?></h1>
                <?php if ($years) : ?><div class="ft-albums-years"><?php echo esc_html($years); ?></div><?php endif; ?>
                <div class="ft-albums-header__links">
                    <a href="<?php echo esc_url(get_permalink($member->ID)); ?>" class="ft-pa-header-btn"><?php echo esc_html__('Открыть страницу персоны', 'genius-family-tree'); ?></a>
                    <a href="<?php echo esc_url($catalog_url); ?>" class="ft-pa-header-btn"><?php echo esc_html__('Каталог фотоальбомов', 'genius-family-tree'); ?></a>
                </div>
            </div>
            </div>
        </div>
        <?php if (empty($albums)) : ?>
            <p><?php echo esc_html__('Фотоальбомы ещё не добавлены.', 'genius-family-tree'); ?></p>
        <?php else : ?>
            <nav class="ft-album-switcher">
                <?php foreach ($albums as $idx => $a) :
                    $a_slug = sanitize_title($a['name']);
                    $is_active = empty($album_slug) ? ($idx === 0) : ($a_slug === $album_slug);
                    $tab_cover_id = !empty($a['cover']) ? (int) $a['cover'] : (!empty($a['photos']) ? (int) reset($a['photos']) : 0);
                    $tab_cover_src = (!$tab_cover_id || ft_hide_field('photo')) ? false : wp_get_attachment_image_src($tab_cover_id, 'thumbnail');
                    ?>
                    <a href="<?php echo esc_url($member_albums_url . $a_slug . '/'); ?>" class="ft-album-tab<?php echo $is_active ? ' is-active' : ''; ?>">
                        <?php if ($tab_cover_src) : ?>
                            <span class="ft-album-tab-cover"><img src="<?php echo esc_url($tab_cover_src[0]); ?>" alt="" /></span>
                        <?php endif; ?>
                        <span class="ft-album-tab-name"><?php echo esc_html($a['name']); ?> (<?php echo count($a['photos']); ?>)</span>
                    </a>
                <?php endforeach; ?>
            </nav>
            <?php
            $display_album = $albums[0];
            $album_index = 0;
            foreach ($albums as $idx => $a) {
                if (!empty($album_slug) && sanitize_title($a['name']) === $album_slug) {
                    $display_album = $a;
                    $album_index = $idx;
                    break;
                }
            }
            $photos = array_values(array_filter(array_map('intval', $display_album['photos']), function($pid) { return wp_attachment_is_image($pid); }));
            // Классы блока фотографий (раскладка/подписи), переиспользуем инфраструктуру family-member-photo-*
            $ft_pa_layout_class = 'ft-layout-' . $pa_settings['layout'];
            $ft_pa_caption_class = intval($pa_settings['captions']) ? 'ft-captions-' . $pa_settings['caption_position'] : '';
            $ft_pa_style_vars = '--ft-album-cols:' . intval($pa_settings['columns']) . ';--ft-album-cols-tablet:' . intval($pa_settings['columns_tablet']) . ';--ft-album-cols-mobile:' . intval($pa_settings['columns_mobile']) . ';--ft-album-gap:' . intval($pa_settings['gap']) . 'px;--ft-album-img-height:' . intval($pa_settings['image_height']) . 'px;--ft-album-image-radius:' . ft_radius_css($pa_settings['image_radius'], '8px') . ';--ft-caption-py:' . intval($pa_settings['caption_padding_y']) . 'px;--ft-caption-px:' . intval($pa_settings['caption_padding_x']) . 'px;';
            ?>
            <div class="family-member-photo-album ft-album-view <?php echo esc_attr(trim($ft_pa_layout_class . ' ' . $ft_pa_caption_class)); ?>" style="<?php echo esc_attr($ft_pa_style_vars); ?>">
                <h2 class="ft-albums-album-title"><?php echo esc_html($display_album['name']); ?></h2>
                <?php if (!empty($display_album['description'])) : ?>
                    <div class="ft-album-description"><?php echo nl2br(esc_html($display_album['description'])); ?></div>
                <?php endif; ?>
                <?php if (ft_hide_field('photo')) : ?>
                    <p><?php echo esc_html__('Фото скрыто администратором.', 'genius-family-tree'); ?></p>
                <?php elseif (empty($photos)) : ?>
                    <p><?php echo esc_html__('В этом альбоме нет фотографий.', 'genius-family-tree'); ?></p>
                <?php else : ?>
                    <div class="family-member-photo-grid">
                            <?php foreach ($photos as $photo_id) :
                                $thumb = wp_get_attachment_image_src($photo_id, 'medium');
                                $caption = (string) get_the_title($photo_id);
                                if ('' === $caption) { $caption = (string) wp_get_attachment_caption($photo_id); }
                                if (!$thumb) continue;
                                $ft_photo_page_url = $this->get_member_photo_url($member, $display_album['name'], $photo_id);
                            ?>
                                <figure class="family-member-photo-item">
                                    <a href="<?php echo esc_url($ft_photo_page_url); ?>" title="<?php echo esc_attr($caption); ?>">
                                        <img src="<?php echo esc_url($thumb[0]); ?>" alt="<?php echo esc_attr($caption); ?>" loading="lazy" />
                                    </a>
                                    <?php if (intval($pa_settings['captions']) && $caption) : ?>
                                        <figcaption><?php echo esc_html($caption); ?></figcaption>
                                    <?php endif; ?>
                                </figure>
                            <?php endforeach; ?>
                        </div>
                <?php endif; ?>
                <?php
                $prev_idx = $album_index - 1;
                $next_idx = $album_index + 1;
                ?>
                <?php if (count($albums) > 1) : ?>
                <nav class="ft-photo-page__nav">
                    <?php if ($prev_idx >= 0) : ?>
                        <a class="ft-photo-page__nav-link" href="<?php echo esc_url($member_albums_url . sanitize_title($albums[$prev_idx]['name']) . '/'); ?>">&larr; <?php echo esc_html($albums[$prev_idx]['name']); ?></a>
                    <?php else : ?><span></span><?php endif; ?>
                    <span class="ft-photo-page__counter"><?php echo esc_html(($album_index + 1) . ' / ' . count($albums)); ?></span>
                    <?php if ($next_idx < count($albums)) : ?>
                        <a class="ft-photo-page__nav-link" href="<?php echo esc_url($member_albums_url . sanitize_title($albums[$next_idx]['name']) . '/'); ?>"><?php echo esc_html($albums[$next_idx]['name']); ?> &rarr;</a>
                    <?php else : ?><span></span><?php endif; ?>
                </nav>
                <?php endif; ?>
            </div>
        <?php endif; ?>
    </div>
    <?php
    return ob_get_clean();
}
/**
 * Шорткод [family_archive_albums] — каталог всех фотоальбомов
 * (все персоны с альбомами, алфавитная навигация).
 */
public function render_album_catalog($atts) {
    if (is_admin()) return '';
    // При полностью закрытом древе — заглушка вместо каталога
    if (ft_privacy_visibility() === 'blocked') {
        return ft_privacy_render_blocked();
    }
    $atts = shortcode_atts(array('letter' => ''), $atts, 'family_archive_albums');
    $members = get_posts(array(
        'post_type'      => 'family_member',
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'nopaging'       => true,
        'no_found_rows'  => true,
        'orderby'        => 'title',
        'order'          => 'ASC',
    ));
    $grouped = array();
    foreach ($members as $member) {
        // Скрытая администратором персона не попадает в публичный каталог
        if (ft_person_is_private($member->ID)) {
            continue;
        }
        $albums = ft_get_albums($member->ID);
        $albums = array_values(array_filter($albums, function($a) { return !empty($a['photos']); }));
        if (empty($albums)) continue;
        $last_name = get_post_meta($member->ID, '_family_member_last_name', true);
        $maiden_name = get_post_meta($member->ID, '_family_member_maiden_name', true);
        $first_name = get_post_meta($member->ID, '_family_member_first_name', true);
        $surname = !empty($last_name) ? $last_name : (!empty($maiden_name) ? $maiden_name : '');
        $letter = mb_strtoupper(mb_substr(mb_strtolower(trim($surname ?: $first_name)), 0, 1, 'UTF-8'), 'UTF-8');
        if (!$letter || !preg_match('/^[A-ZА-ЯЁ]$/u', $letter)) {
            $letter = '#';
        }
        $total_photos = 0;
        foreach ($albums as $a) { $total_photos += count($a['photos']); }
        $grouped[$letter][] = array(
            'id'           => $member->ID,
            'title'        => $member->post_title,
            'url'          => $this->get_member_albums_url($member),
            'albums'       => $albums,
            'album_count'  => count($albums),
            'total_photos' => $total_photos,
        );
    }
    if (empty($grouped)) {
        return '<p>' . esc_html__('Фотоальбомы ещё не созданы.', 'genius-family-tree') . '</p>';
    }
    ksort($grouped);
    $filter = !empty($atts['letter']) ? mb_strtoupper(sanitize_text_field($atts['letter']), 'UTF-8') : '';
    $current_url = is_singular() ? get_permalink() : home_url(add_query_arg(array()));
    $pa_settings = ft_get_person_albums_settings();
    $ac_settings = ft_get_archive_catalog_settings();
    $ac_base_css = '.ft-archive-catalog-shortcode .ft-archive-letters{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:24px;padding:16px;background:var(--ft-surface,#fff);border:1px solid var(--ft-border,#ddd);border-radius:8px;}'
        . '.ft-archive-catalog-shortcode .ft-archive-letters .ft-letter{display:inline-flex;align-items:center;justify-content:center;min-width:36px;height:36px;padding:0 10px;text-align:center;text-decoration:none;font-weight:600;font-size:14px;line-height:1;background:var(--ft-accent,#2271b1);color:#fff;border-radius:6px;transition:all .2s ease;}'
        . '.ft-archive-catalog-shortcode .ft-archive-letters .ft-letter:hover{transform:translateY(-1px);box-shadow:0 2px 6px rgba(0,0,0,.12);}'
        . '.ft-archive-catalog-shortcode .ft-archive-letter-block h2{margin:0 0 16px;font-size:20px;font-weight:600;color:#1d2327;}'
        . '.ft-archive-catalog-shortcode .ft-archive-person-card{transition:box-shadow .2s,border-color .2s;}'
        . '.ft-archive-catalog-shortcode .ft-archive-person-card .ft-avatar{flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;overflow:hidden;}'
        . '.ft-archive-catalog-shortcode .ft-archive-person-card .ft-avatar img{width:100%;height:100%;object-fit:cover;display:block;}'
        . '.ft-archive-catalog-shortcode .ft-archive-person-card .ft-avatar .ft-avatar-fallback{width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:#999;font-size:18px;background:#f0f0f1;}'
        . '.ft-archive-catalog-shortcode .ft-card-body{min-width:0;}'
        . '.ft-archive-catalog-shortcode .ft-card-name{font-weight:600;}'
        . '.ft-archive-catalog-shortcode .ft-archive-persons{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px;}';
    $ac_css = str_replace('.family-archive-catalog', '.ft-archive-catalog-shortcode', ft_archive_catalog_css($ac_settings));
    $ac_css .= str_replace('.family-archive-catalog', '.ft-archive-catalog-shortcode', ft_archive_catalog_layout_css());
    ob_start();
    ?>
    <div class="ft-archive-catalog-shortcode" style="margin:20px 0;">
        <style type="text/css"><?php echo ft_person_albums_css($pa_settings); ?></style>
        <style type="text/css"><?php echo $ac_base_css; ?><?php echo $ac_css; ?></style>
        <style type="text/css">@media (max-width:767px){.ft-archive-catalog-shortcode .ft-archive-persons{grid-template-columns:repeat(1,minmax(0,1fr)) !important;}}</style>
        <div class="ft-archive-letters">
            <a href="<?php echo esc_url($current_url); ?>" class="ft-letter<?php echo empty($filter) ? ' active' : ''; ?>"><?php echo esc_html__('Все', 'genius-family-tree'); ?></a>
            <?php foreach ($grouped as $ltr => $m) : ?>
                <a href="<?php echo esc_url(add_query_arg('letter', $ltr, $current_url)); ?>" class="ft-letter<?php echo $filter === $ltr ? ' active' : ''; ?>"><?php echo esc_html($ltr); ?></a>
            <?php endforeach; ?>
        </div>
        <?php foreach ($grouped as $letter => $members_list) : ?>
            <?php if (!empty($filter) && $filter !== $letter) continue; ?>
            <div class="ft-archive-letter-block" style="margin-top:24px;">
                <h2><?php echo esc_html($letter); ?></h2>
                <div class="ft-archive-persons">
                    <?php foreach ($members_list as $pm) : ?>
                        <?php $pm_name = ft_person_display_name($pm['id'], $pm['title']); ?>
                        <a href="<?php echo esc_url($pm['url']); ?>" class="ft-archive-person-card" style="display:flex;align-items:center;gap:12px;padding:14px;background:#fff;border:1px solid #ddd;border-radius:8px;text-decoration:none;color:inherit;transition:box-shadow .2s,border-color .2s;">
                            <?php
                            $thumb_id = get_post_thumbnail_id($pm['id']);
                            $thumb = ($thumb_id && !ft_hide_field('photo')) ? wp_get_attachment_image_src($thumb_id, 'thumbnail') : false;
                            ?>
                            <span class="ft-avatar">
                                <?php if (!empty($thumb) && $thumb) : ?>
                                    <img src="<?php echo esc_url($thumb[0]); ?>" alt="<?php echo esc_attr($pm_name); ?>" loading="lazy" />
                                <?php else : ?>
                                    <div class="ft-avatar-fallback"><span><?php echo esc_html(mb_strtoupper(mb_substr($pm_name, 0, 1, 'UTF-8'), 'UTF-8')); ?></span></div>
                                <?php endif; ?>
                            </span>
                            <div class="ft-card-body">
                                <div class="ft-card-name" style="font-weight:600;color:#1d2327;font-size:15px;"><?php echo esc_html($pm_name); ?></div>
                                <div class="ft-card-count" style="font-size:12px;color:#646970;margin-top:2px;">
                                    <?php echo esc_html(ft_album_count_label($pm['album_count'])); ?> &middot; <?php echo intval($pm['total_photos']); ?> <?php echo esc_html__('фото', 'genius-family-tree'); ?>
                                </div>
                            </div>
                        </a>
                    <?php endforeach; ?>
                </div>
            </div>
        <?php endforeach; ?>
    </div>
    <?php
    return ob_get_clean();
}
/**
 * Шорткод [family_member_albums] — фотоальбомы отдельной персоны.
 * Атрибуты: person="ID или slug"
 */
public function render_member_albums($atts) {
    if (is_admin()) return '';
    $atts = shortcode_atts(array('person' => ''), $atts, 'family_member_albums');
    $member = $this->resolve_archive_member($atts['person']);
    if (!$member) return '<p>' . esc_html__('Персоналия не найдена.', 'genius-family-tree') . '</p>';
    return $this->render_member_albums_view($member);
}
/**
 * Шорткод [family_album] — отдельный фотоальбом персоны.
 * Атрибуты: person="ID или slug", album="название или slug альбома"
 */
public function render_single_album($atts) {
    if (is_admin()) return '';
    $atts = shortcode_atts(array('person' => '', 'album' => ''), $atts, 'family_album');
    $member = $this->resolve_archive_member($atts['person']);
    if (!$member) return '<p>' . esc_html__('Персоналия не найдена.', 'genius-family-tree') . '</p>';
    return $this->render_member_albums_view($member, $atts['album']);
}
/**
 * Считает общее количество альбомов всех персон.
 */
private function count_all_albums() {
    $members = get_posts(array(
        'post_type'      => 'family_member',
        'posts_per_page' => -1,
        'post_status'    => 'publish',
        'fields'         => 'ids',
        'no_found_rows'  => true,
    ));
    $total = 0;
    foreach ($members as $mid) {
        $total += count(ft_get_albums($mid));
    }
    return $total;
}
/**
 * Считает общее количество фото во всех альбомах всех персон.
 */
private function count_all_album_photos() {
    $members = get_posts(array(
        'post_type'      => 'family_member',
        'posts_per_page' => -1,
        'post_status'    => 'publish',
        'fields'         => 'ids',
        'no_found_rows'  => true,
    ));
    $total = 0;
    foreach ($members as $mid) {
        $albums = ft_get_albums($mid);
        foreach ($albums as $a) {
            $total += count($a['photos']);
        }
    }
    return $total;
}
/**
 * DEBUG callback-функция для шорткода [family_surname_catalog_debug]
 * Просто выводит список всех записей и их фамилий.
 */
public function render_surname_catalog_debug($atts) {
if (is_admin()) return '';
// При полностью закрытом древе показываем заглушку вместо отладочного каталога
if (ft_privacy_visibility() === 'blocked') {
    return ft_privacy_render_blocked();
}
// Скрытые персоны не попадают в публичный отладочный каталог
$skip_private = function_exists('ft_privacy_visibility') && ft_privacy_visibility() !== 'full';
// Получаем ВСЕ записи типа family_member
$args = array(
'post_type'      => 'family_member',
'post_status'    => 'publish',
'posts_per_page' => 500,
'nopaging'       => true,
'no_found_rows'  => true,
'orderby'        => 'title',
'order'          => 'ASC',
);
$members_query = new WP_Query($args);
if (!$members_query->have_posts()) {
return '<p>' . esc_html__('Нет записей типа family_member.', 'genius-family-tree') . '</p>';
}
$total_count = 0;
$with_surname_count = 0;
$surname_list = array();
while ($members_query->have_posts()) {
$members_query->the_post();
$post_id = get_the_ID();
if ($skip_private && ft_person_is_private($post_id)) {
continue;
}
$total_count++;
$raw_last_name_meta = get_post_meta($post_id, '_family_member_last_name', true);
$last_name = trim($raw_last_name_meta);
if (!empty($last_name)) {
$with_surname_count++;
if (!isset($surname_list[$last_name])) {
$surname_list[$last_name] = array(
'count' => 0,
'members' => array()
);
}
$surname_list[$last_name]['count']++;
$surname_list[$last_name]['members'][] = array(
'id' => $post_id,
'title' => get_the_title(),
'url' => get_permalink()
);
}
}
wp_reset_postdata();
uksort($surname_list, 'strnatcasecmp');
ob_start();
?>
<div style="padding: 20px; font-family: monospace;">
<h2><?php echo esc_html__('DEBUG: Каталог Фамилий (Простой список)', 'genius-family-tree'); ?></h2>
<p><strong><?php echo esc_html__('Всего записей:', 'genius-family-tree'); ?></strong> <?php echo esc_html($total_count); ?></p>
<p><strong><?php echo esc_html__('Записей с фамилией:', 'genius-family-tree'); ?></strong> <?php echo esc_html($with_surname_count); ?></p>
<p><strong><?php echo esc_html__('Записей без фамилии:', 'genius-family-tree'); ?></strong> <?php echo esc_html($total_count - $with_surname_count); ?></p>
<hr>
<h3><?php echo esc_html__('Список фамилий:', 'genius-family-tree'); ?></h3>
<table border="1" cellpadding="5" cellspacing="0" style="width: 100%; border-collapse: collapse;">
<thead>
<tr>
<th><?php echo esc_html__('Фамилия', 'genius-family-tree'); ?></th>
<th><?php echo esc_html__('Количество', 'genius-family-tree'); ?></th>
<th><?php echo esc_html__('Персоны', 'genius-family-tree'); ?></th>
</tr>
</thead>
<tbody>
<?php foreach($surname_list as $surname => $data): ?>
<tr>
<td><strong><?php echo esc_html(ft_hide_field('name_parts') ? ft_privacy_hidden_label() : $surname); ?></strong></td>
<td><?php echo esc_html($data['count']); ?></td>
<td>
<ul style="margin: 0; padding-left: 20px;">
<?php foreach($data['members'] as $member): ?>
<li>
<a href="<?php echo esc_url($member['url']); ?>" target="_blank"><?php echo esc_html(ft_person_display_name($member['id'], $member['title'])); ?></a>
<?php if (!ft_hide_field('name_parts')): ?>
(ID: <?php echo esc_html($member['id']); ?>)
<?php endif; ?>
</li>
<?php endforeach; ?>
</ul>
</td>
</tr>
<?php endforeach; ?>
</tbody>
</table>
</div>
<?php
return ob_get_clean();
}
