        'home_badge_font_weight' => 0,
        'home_badge_font_size' => 12,
        'home_badge_radius' => 4,
        'home_badge_border_width' => 0,
        'home_badge_border_style' => 'solid',
        'home_badge_border_color' => '',
        'home_badge_padding_y' => 3,
        'home_badge_padding_x' => 10,
    );
    $saved = get_option('family_tree_album_settings', array());
    if (!is_array($saved)) {
        $saved = array();
    }
    $legacy_sides = array('top', 'right', 'bottom', 'left');
    $legacy_box = array(
        'subheader_box_margin' => 'subheader_margin',
        'subheader_box_padding' => 'subheader_padding',
    );
    foreach ($legacy_box as $ft_box_key => $ft_legacy_prefix) {
        if (!array_key_exists($ft_box_key, $saved)) {
            $ft_values = array();
            foreach ($legacy_sides as $ft_side) {
                $ft_values[] = isset($saved[$ft_legacy_prefix . '_' . $ft_side]) ? intval($saved[$ft_legacy_prefix . '_' . $ft_side]) : 0;
            }
            $ft_has_box_value = ('subheader_box_margin' === $ft_box_key)
                ? 0 !== array_sum($ft_values)
                : max($ft_values) > 0;
            $saved[$ft_box_key] = $ft_has_box_value
                ? implode(' ', array_map(function ($value) {
                    return $value . 'px';
                }, $ft_values))
                : '';
        }
    }
    foreach (array(
        'subheader_box_radius' => 'subheader_radius',
        'subheader_box_border_width' => 'subheader_border_width',
        'subheader_box_border_style' => 'subheader_border_style',
        'subheader_box_border_color' => 'subheader_border_color',
    ) as $ft_box_key => $ft_legacy_key) {
        if (!array_key_exists($ft_box_key, $saved)) {
            $ft_legacy_value = isset($saved[$ft_legacy_key]) ? $saved[$ft_legacy_key] : '';
            if ('subheader_box_border_width' === $ft_box_key) {
                $saved[$ft_box_key] = intval($ft_legacy_value) > 0 ? intval($ft_legacy_value) . 'px' : '';
            } elseif ('subheader_box_radius' === $ft_box_key) {
                $saved[$ft_box_key] = $this->sanitize_css_radius($ft_legacy_value);
            } else {
                $saved[$ft_box_key] = $ft_legacy_value;
            }
        }
    }
    if (!array_key_exists('image_style_state', $saved)) {
        $legacy_image_state = isset($saved['image_border_state']) ? $saved['image_border_state'] : 'normal';
        $saved['image_style_state'] = in_array($legacy_image_state, array('normal', 'hover'), true) ? $legacy_image_state : 'normal';
    }
    foreach (array('color' => 'shadow_color', 'x' => 'shadow_offset_x', 'y' => 'shadow_offset_y', 'blur' => 'shadow_blur', 'spread' => 'shadow_spread') as $ft_hover_shadow_part => $ft_legacy_shadow_key) {
        $ft_hover_shadow_key = 'image_shadow_hover_' . $ft_hover_shadow_part;
        if (!array_key_exists($ft_hover_shadow_key, $saved)) {
            $saved[$ft_hover_shadow_key] = isset($saved[$ft_legacy_shadow_key]) ? $saved[$ft_legacy_shadow_key] : $defaults[$ft_legacy_shadow_key];
        }
    }
    return array_merge($defaults, $saved);
}
/**
 * Страница «Семейный архив» — настройки внешнего вида фотоальбомов персоналий.
 * Настройки хранятся в опции family_tree_album_settings (массив).
 */
public function archive_settings_page() {
    // Список допустимых гарнитур (системные + Google Fonts)
    $ft_fonts = array(
        'Open Sans' => 'Open Sans',
        'Roboto Slab' => 'Roboto Slab',
        'Georgia' => 'Georgia',
        'Times New Roman' => 'Times New Roman',
        'Arial' => 'Arial',
        'Verdana' => 'Verdana',
        'Tahoma' => 'Tahoma',
        'Trebuchet MS' => 'Trebuchet MS',
        'Courier New' => 'Courier New',
    );
    $ft_google_fonts = self::get_google_fonts();
    $allowed_fonts = array_merge(array_keys($ft_fonts), array_keys($ft_google_fonts));
    $ft_font_weights = array();
    foreach (array_merge($ft_fonts, $ft_google_fonts) as $ft_font_name => $ft_font_label) {
        $ft_font_weights[$ft_font_name] = self::get_font_weights($ft_font_name);
    }

    // Актуальные настройки (текущие + значения по умолчанию)
    $settings = $this->get_album_display_settings();

    // Обработка сохранения форм
    $message = '';
    $message_type = '';
    // Сохранение названия раздела (таб «Разделы»)
    if (isset($_POST['family_tree_save_archive_section_title'])
        && isset($_POST['ft_archive_section_title_nonce'])
        && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ft_archive_section_title_nonce'])), 'ft_save_archive_section_title')
        && current_user_can('manage_options')) {
        $section_id = isset($_POST['archive_section_id']) ? sanitize_key($_POST['archive_section_id']) : '';
        $ft_sections_tmp = ft_get_archive_sections();
        if ('' !== $section_id && isset($ft_sections_tmp[$section_id])) {
            $section_title_tmp = isset($_POST['archive_section_title']) ? sanitize_text_field(wp_unslash($_POST['archive_section_title'])) : '';
            if ('' !== $section_title_tmp) {
                $ft_sections_tmp[$section_id]['title'] = $section_title_tmp;
                ft_save_archive_sections($ft_sections_tmp);
                $message = esc_html__('Название раздела сохранено', 'genius-family-tree');
                $message_type = 'updated';
            }
        }
    }
    if (isset($_POST['family_tree_album_settings_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['family_tree_album_settings_nonce'])), 'family_tree_save_album_settings')) {
        if (isset($_POST['family_tree_save_album_home_settings'])) {
            $settings['home_container_margin_top'] = isset($_POST['family_tree_album_home_container_margin_top']) ? max(0, min(100, intval($_POST['family_tree_album_home_container_margin_top']))) : $settings['home_container_margin_top'];
            $settings['home_container_margin_bottom'] = isset($_POST['family_tree_album_home_container_margin_bottom']) ? max(0, min(100, intval($_POST['family_tree_album_home_container_margin_bottom']))) : $settings['home_container_margin_bottom'];
            $settings['home_container_bg'] = isset($_POST['family_tree_album_home_container_bg']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_home_container_bg'])) : $settings['home_container_bg'];
            $settings['home_container_bg_type'] = isset($_POST['family_tree_album_home_container_bg_type']) && 'gradient' === $_POST['family_tree_album_home_container_bg_type'] ? 'gradient' : 'classic';
            $settings['home_container_bg_gradient'] = isset($_POST['family_tree_album_home_container_bg_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_album_home_container_bg_gradient'])) : $settings['home_container_bg_gradient'];
