    <script type="text/javascript">
jQuery(document).ready(function($) {
    function ftSetColorAndSwatch($input, color) {
        color = typeof color === 'string' ? color : '';
        var $wrap = $input.closest('.wp-picker-container');
        var def = '';
        try { def = $input.data('default-color') || ''; } catch (err) {}
        if (color === '' && def === '' && $wrap.length && $wrap.find('.wp-picker-clear').length) {
            try { $wrap.find('.wp-picker-clear').trigger('click'); } catch (err) {}
        }
        if (color === '') $input.data('ft-clear', Date.now());
        $input.val(color);
        if ($wrap.length) {
            $wrap.find('.wp-color-result').css('background-color', color ? color : 'transparent');
        }
        if ($input.hasClass('wp-color-picker')) {
            try {
                $input.wpColorPicker('color', color);
            } catch (err) {}
        }
    }
    function ftInitAlphaColor(inputSel, sliderSel, labelSel) {
        var $input = $(inputSel);
        var $slider = $(sliderSel);
        var $label = $(labelSel);
        if (!$input.length || !$slider.length) return null;
        function ftToHex(r, g, b) {
            return '#' + [r, g, b].map(function(v) {
                var h = (+v).toString(16);
                return h.length === 1 ? '0' + h : h;
            }).join('');
        }
        function ftRgbString(r, g, b, a) {
            if (a >= 1) return ftToHex(r, g, b);
            a = Math.round(a * 100) / 100;
            return 'rgba(' + r + ', ' + g + ', ' + b + ', ' + a + ')';
        }
        function ftParseRgb(val) {
            var m = val.match(/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})(?:\s*,\s*([0-9.]+))?\s*\)$/i);
            if (m) return { r: +m[1], g: +m[2], b: +m[3] };
            var hex = (val || '').replace('#', '');
            if (hex.length === 3) hex = hex.split('').map(function(c) { return c + c; }).join('');
            if (hex.length === 6) return { r: parseInt(hex.substr(0, 2), 16), g: parseInt(hex.substr(2, 2), 16), b: parseInt(hex.substr(4, 2), 16) };
            return { r: 255, g: 255, b: 255 };
        }
        function ftAlphaPct() {
            return parseInt($slider.val(), 10);
        }
        function ftPaintChip() {
            var $chip = $input.closest('.wp-picker-container').find('.wp-color-result');
            if ($chip.length) $chip.css('background-color', $input.val() ? $input.val() : 'transparent');
        }
        function ftApply() {
            var rgb = ftParseRgb($input.val());
            var a = ftAlphaPct() / 100;
            $input.val(ftRgbString(rgb.r, rgb.g, rgb.b, a));
            $label.text(ftAlphaPct() + '%');
            ftPaintChip();
        }
        function ftInit() {
            var v = $input.val();
            var m = v.match(/^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*([0-9.]+)\)$/i);
            if (m) {
                $slider.val(Math.round(parseFloat(m[4]) * 100));
            } else if (v === '') {
                $slider.val(0);
            }
            $label.text($slider.val() + '%');
        }
        ftInit();
        $slider.on('input change', ftApply);
        $input.wpColorPicker({
            defaultColor: $input.data('default-color'),
            clear: function() { $(this).data('ft-clear', Date.now()); },
            change: function(event, ui) {
                if (ui.color) {
                    $input.data('ft-clear', 0);
                    var a = ftAlphaPct() / 100;
                    $input.val(ftRgbString(ui.color.r, ui.color.g, ui.color.b, a));
                    $label.text(ftAlphaPct() + '%');
                    ftPaintChip();
                } else {
                    $input.val($input.val());
                }
            }
        });
        return {
            setSolid: function() {
                $slider.val(100);
                $label.text('100%');
            },
            setTransparent: function() {
                $slider.val(0);
                $label.text('0%');
            },
            apply: ftApply,
            setValue: function(color) {
                if (!color) {
                    ftSetColorAndSwatch($input, '');
                    $slider.val(0);
                    $label.text('0%');
                    return;
                }
                ftSetColorAndSwatch($input, color);
                if (color === '') {
                    $slider.val(0);
                } else {
                    var m = color.match(/^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*([0-9.]+)\)$/i);
                    $slider.val(m ? Math.round(parseFloat(m[4]) * 100) : 100);
                }
                $label.text($slider.val() + '%');
            }
        };
    }
    $('.ft-alpha-color-group').each(function() {
        var $group = $(this);
        var api = ftInitAlphaColor($group.data('input'), $group.data('slider'), $group.data('label'));
        if (!api) return;
        $group.find('.ft-color-preset').on('click', function(e) {
            e.preventDefault();
            api.setValue($(this).data('color'));
        });
        $group.find('.ft-color-transparent').on('click', function(e) {
            e.preventDefault();
            api.setValue('');
        });
        $group.find('.ft-color-reset').on('click', function(e) {
            e.preventDefault();
            api.setValue($group.find('.ft-alpha-input').data('default-color') || '');
        });
        var $form = $group.closest('form');
        if ($form.length) {
            $form.on('submit', function() {
                var $fInp = $($group.data('input'));
                var $fSld = $($group.data('slider'));
                if (!$fInp.length || !$fSld.length) return;
                var fVal = ($fInp.val() || '').trim();
                var fPct = parseInt($fSld.val(), 10) || 0;
                if (fVal === '') {
                    var fWc = '';
                    try { fWc = $fInp.wpColorPicker('color'); } catch (err) {}
                    var fDef = '';
                    try { fDef = $fInp.data('default-color') || ''; } catch (err) {}
                    if (!$fInp.data('ft-clear') && typeof fWc === 'string' && fWc !== '' &&
                        /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(fWc) &&
                        fWc.toLowerCase() !== fDef.toLowerCase()) {
                        fVal = fWc;
                    }
                }
                if (fVal === '' && (fPct === 0 || fPct === 100)) return;
                $fInp.val(fVal);
                api.apply();
            });
        }
    });

    // Переключение устройства и состояния живёт в assets/js/admin.js,
    // он подключается и на «Странице персоны», и в архиве.

    // === Границы: сброс толщины/стиля/цвета ===
    // В legacy-блоках кнопки сброса заменены на .ft-measure__reset
    // (единый контрол ft_render_border_control), отдельных обработчиков не нужно.

    // === Цвета без прозрачности ===
    $('#ft-album-caption-color-input, #ft-album-image-border-color-input, #ft-album-carousel-btn-bg-input, #ft-album-carousel-btn-color-input, #ft-album-carousel-btn-border-color-input, #ft-album-subheader-bg-input, #ft-album-subheader-color-input, #ft-album-subheader-border-color-input, #ft-album-description-color-input, #ft-album-display-title-color-input, #ft-album-display-border-color-input, #ft-album-display-count-color-input, #ft-album-display-hover-border-input, #ft-album-display-hover-title-input, #ft-album-home-icon-color-input, #ft-album-home-title-color-input, #ft-album-home-desc-color-input, #ft-album-home-count-color-input, #ft-album-home-badge-color-input, #ft-album-home-block-border-color-input, #ft-album-home-image-border-color-input, #ft-album-home-badge-border-color-input, #ft-album-home-block-border-color-hover-input, #ft-album-home-title-color-hover-input, #ft-album-home-desc-color-hover-input, #ft-album-home-count-color-hover-input, #ft-album-home-badge-color-hover-input, #ft-album-carousel-btn-bg-hover-input, #ft-album-carousel-btn-color-hover-input, #ft-album-carousel-btn-border-color-hover-input, #ft-album-image-border-color-hover-input, #ft-ac-letter-text-input, #ft-ac-letter-text-active-input, #ft-ac-litera-color-input, #ft-ac-name-color-input, #ft-ac-name-color-hover-input, #ft-ac-count-color-input, #ft-ac-count-color-hover-input, #ft-ac-card-border-color-input, #ft-ac-card-border-color-hover-input, #ft-ac-catalog-border-color-input, #ft-ac-catalog-border-color-hover-input, #ft-ac-block-border-color-input, #ft-ac-block-border-color-hover-input, #ft-pa-header-title-color-input, #ft-pa-header-years-color-input, #ft-pa-container-border-color-input, #ft-pa-header-btn-color-input, #ft-pa-header-btn-color-hover-input, #ft-pa-header-btn-bg-input, #ft-pa-header-btn-bg-hover-input, #ft-pa-header-btn-border-color-input, #ft-pa-header-btn-border-color-hover-input, #ft-pa-tab-border-color-input, #ft-pa-tab-border-color-hover-input, #ft-pa-tab-active-bg-input, #ft-pa-tab-active-color-input, #ft-pa-tab-active-border-color-input, #ft-pa-tab-cover-border-color-input, #ft-pa-tab-cover-border-active-input, #ft-pa-tab-title-color-input, #ft-pa-tab-title-color-hover-input, #ft-pa-album-title-color-input, #ft-pa-album-desc-color-input, #ft-pa-caption-color-input, #ft-pa-image-border-color-input, #ft-pa-image-border-color-hover-input, #ft-album-home-container-border-color-input, #ft-album-pp-container-border-color-input, #ft-album-pp-media-border-color-input, #ft-album-pp-back-border-color-input, #ft-album-pp-thumbs-border-color-input, #ft-album-pp-thumbs-active-border-color-input, #ft-pp-text-color-input, #ft-pp-person-color-input, #ft-album-pp-person-border-color-input, #ft-pp-person-hover-color-input, #ft-pp-person-num-bg-input, #ft-pp-person-num-color-input, #ft-pp-tag-bg-input, #ft-pp-tag-color-input, #ft-album-pp-tag-border-color-input, #ft-pp-back-color-input, #ft-pp-back-hover-color-input, #ft-album-pp-back-hover-border-color-input, #ft-pp-thumb-title-color-input').each(function() {
        var $input = $(this);
        if ($input.hasClass('ft-bg-color-input')) {
            return;
        }
        $input.wpColorPicker({
            defaultColor: $input.data('default-color'),
            clear: function() { $(this).data('ft-clear', Date.now()); },
            change: function(event, ui) {
                $(this).val(ui.color ? ui.color.toString() : $(this).val());
                $(this).data('ft-clear', 0);
            }
        });
    });
    // Палитра цвета заголовка и «Сбросить» — в assets/js/admin.js.
    // Гарантия сохранения: при отправке формы подтягиваем в поле цвет из виджета палитры,
    // даже если виджет не успел записать его в поле.
    function ftSyncPlainColor($inp) {
        var v = ($inp.val() || '').trim();
        if (v !== '') return;
        var wc = '';
        try { wc = $inp.wpColorPicker('color'); } catch (err) {}
        var def = '';
        try { def = $inp.data('default-color') || ''; } catch (err) {}
        if (!$inp.data('ft-clear') && typeof wc === 'string' && wc !== '' && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(wc) && wc.toLowerCase() !== def.toLowerCase()) {
            $inp.val(wc);
        }
    }
