    // === Толщина шрифтов: зависит от выбранной гарнитуры ===
    var ftAlbumFontWeights = <?php echo wp_json_encode($ft_font_weights); ?>;
    function ftAlbumPopulateWeightOptions(font, $weightSelect) {
        var weights = ftAlbumFontWeights[font] || [400, 700];
        var current = $weightSelect.val();
        $weightSelect.empty();
        $weightSelect.append($('<option>', { value: '0' }).text('<?php echo esc_js(__('По умолчанию', 'genius-family-tree')); ?>'));
        $.each(weights, function(i, w) {
            $weightSelect.append($('<option>', { value: String(w) }).text(String(w)));
        });
        if (current && current !== '0') {
            var found = false;
            $.each(weights, function(i, w) {
                if (Number(current) === Number(w)) {
                    found = true;
                    return false;
                }
            });
            if (found) {
                $weightSelect.val(current);
            }
        }
    }
    $('.ft-font-weight-select').each(function() {
        var $weightSelect = $(this);
        var $fontSelect = $($weightSelect.data('font-select'));
        if (!$fontSelect.length) {
            return;
        }
        ftAlbumPopulateWeightOptions($fontSelect.val() || '', $weightSelect);
        $fontSelect.on('change', function() {
            ftAlbumPopulateWeightOptions($(this).val() || '', $weightSelect);
        });
    });

    // === Разделы семейного архива: перетаскивание строк и модалка ===
    var ftSecSort = { dragEl: null, tbodyEl: null, dropRef: null, placeholder: null };
    var ftSecModal = { sectionId: '', imageId: 0, imageUrls: {} };

    function ftSecGetPlaceholder() {
        if (!ftSecSort.placeholder) {
            var ph = document.createElement('tr');
            ph.className = 'ft-section-row-placeholder';
            ph.innerHTML = '<td colspan="10"></td>';
            ph.draggable = false;
            ftSecSort.placeholder = ph;
        }
        return ftSecSort.placeholder;
    }

    function ftSecEnsurePlaceholder(tbody) {
        var ph = ftSecGetPlaceholder();
        if (ph.parentNode !== tbody) { tbody.appendChild(ph); }
        return ph;
    }

    function ftSecMovePlaceholder(tr, before) {
        var ph = ftSecGetPlaceholder();
        if (!ph.parentNode) { return; }
        tr.parentNode.insertBefore(ph, before ? tr : tr.nextSibling);
    }

    function ftSecClearState() {
        var ph = ftSecSort.placeholder;
        if (ph && ph.parentNode) { ph.parentNode.removeChild(ph); }
        if (ftSecSort.dragEl) { $(ftSecSort.dragEl).removeClass('ft-row-dragging'); }
        ftSecSort.dragEl = null;
        ftSecSort.tbodyEl = null;
        ftSecSort.dropRef = null;
        ftSecSort.placeholder = null;
    }

    function ftSecSaveOrder($tbody) {
        var order = [];
        $tbody.find('tr.ft-section-edit-row').each(function () {
            order.push(String($(this).data('section-id')));
        });
        if (!order.length) { return; }
        $.post(familyTreeAdmin.ajaxurl, {
            action: 'family_tree_reorder_archive_sections',
            section_order: order,
            nonce: familyTreeAdmin.nonce
        }, function (response) {
            if (response && response.success) {
                location.reload();
            } else {
                alert((response && response.data && response.data.message) ? response.data.message : 'Не удалось сохранить порядок разделов');
                location.reload();
            }
        });
    }

    $('.ft-reorder-sections tr.ft-section-edit-row').find('input, button, select, textarea, a').attr('draggable', 'false');

    $(document)
        .on('dragstart', '.ft-reorder-sections tr.ft-section-edit-row', function (e) {
            if ($(e.target).closest('input, button, select, textarea, a').length) { return; }
            var $tr = $(this);
            var $tbody = $tr.closest('tbody.ft-reorder-sections');
            if (!$tbody.length) { return; }
            ftSecSort.dragEl = this;
            ftSecSort.tbodyEl = $tbody[0];
            ftSecSort.dropRef = null;
            $tr.addClass('ft-row-dragging');
            e.originalEvent.dataTransfer.effectAllowed = 'move';
            e.originalEvent.dataTransfer.setData('text/plain', String($tr.data('section-id')));
        })
        .on('dragover', '.ft-reorder-sections', function (e) {
            if (!ftSecSort.dragEl) { return; }
            e.preventDefault();
            var $tbody = $(ftSecSort.tbodyEl);
            var $tr = $(e.target).closest('tr.ft-section-edit-row');
            if (!$tr.length || $tr[0] === ftSecSort.dragEl) { return; }
            var rows = $tbody.find('tr.ft-section-edit-row');
            var isFirst = (rows[0] === $tr[0]);
            var isLast = (rows.length > 1 && rows[rows.length - 1] === $tr[0]);
            var before = isFirst ? true : (isLast ? false : (e.originalEvent.clientY < $tr[0].getBoundingClientRect().top + $tr[0].getBoundingClientRect().height / 2));
            var ref = ftSecSort.dropRef;
            if (ref && ref.tr === $tr[0] && ref.before === before) { return; }
            ftSecSort.dropRef = { tr: $tr[0], before: before };
            ftSecEnsurePlaceholder($tbody[0]);
            ftSecMovePlaceholder($tr[0], before);
        })
        .on('drop', '.ft-reorder-sections', function (e) {
            if (!ftSecSort.dragEl) { return; }
            e.preventDefault();
            var $tbody = $(ftSecSort.tbodyEl);
            var dragEl = ftSecSort.dragEl;
            var ph = ftSecGetPlaceholder();
            var saved = ftSecSort.dropRef;
            if (saved && ph && ph.parentNode) {
                ph.parentNode.insertBefore(dragEl, ph);
                ph.parentNode.removeChild(ph);
                ftSecClearState();
                ftSecSaveOrder($tbody);
            } else {
                ftSecClearState();
            }
        });

    $(document)
        .on('dragover.ftsecrowdrop', function (e) { if (ftSecSort.dragEl) { e.preventDefault(); } })
        .on('drop.ftsecrowdrop', function (e) { if (ftSecSort.dragEl) { e.preventDefault(); ftSecClearState(); } })
        .on('dragend', function () { if (ftSecSort.dragEl) { ftSecClearState(); } });

    // Модалка «Изображение и описание раздела»
    function ftSecRenderModalCover() {
        var $preview = $('#ft-section-cover-preview');
        if (ftSecModal.imageId && ftSecModal.imageUrls[ftSecModal.imageId]) {
            $preview.html('<img src="' + ftSecModal.imageUrls[ftSecModal.imageId] + '" alt="">');
        } else {
            $preview.html('<span class="dashicons dashicons-format-image"></span>');
        }
    }

    function ftSecOpenMetaModal($btn) {
        ftSecModal.sectionId = String($btn.data('section-id') || '');
        ftSecModal.imageId = parseInt($btn.data('image') || '0', 10) || 0;
        var imageUrl = $btn.data('image-url') || '';
        ftSecModal.imageUrls = {};
        if (ftSecModal.imageId && imageUrl) { ftSecModal.imageUrls[ftSecModal.imageId] = imageUrl; }
        $('#ft-section-description').val($btn.data('description') || '');
        ftSecRenderModalCover();
        $('#ft-section-meta-modal').addClass('ft-modal-open').attr('aria-hidden', 'false');
    }

    function ftSecCloseMetaModal() {
        $('#ft-section-meta-modal').removeClass('ft-modal-open').attr('aria-hidden', 'true');
    }

    function ftSecOpenMediaPicker() {
        if (typeof wp === 'undefined' || !wp.media) {
            alert('Медиабиблиотека не загружена. Обновите страницу.');
            return;
        }
        var frame = wp.media({
            title: 'Выберите изображение раздела',
            button: { text: 'Выбрать изображение' },
            library: { type: 'image' },
            multiple: false
        });
        frame.on('select', function () {
            var att = frame.state().get('selection').first().toJSON();
            if (att && att.id) {
                var url = (att.sizes && att.sizes.thumbnail && att.sizes.thumbnail.url) ? att.sizes.thumbnail.url : att.url;
                ftSecModal.imageId = parseInt(att.id, 10) || 0;
                if (ftSecModal.imageId) { ftSecModal.imageUrls[ftSecModal.imageId] = url; }
                ftSecRenderModalCover();
            }
        });
        frame.open();
    }

    $(document)
        .on('click', '.ft-section-meta-btn', function (e) {
            e.preventDefault();
            ftSecOpenMetaModal($(this));
        })
        .on('click', '#ft-section-cover-pick', function () {
            ftSecOpenMediaPicker();
        })
        .on('click', '#ft-section-cover-clear', function () {
            ftSecModal.imageId = 0;
            ftSecRenderModalCover();
        })
        .on('click', '#ft-section-meta-save', function () {
            if (!ftSecModal.sectionId) { return; }
            $.post(familyTreeAdmin.ajaxurl, {
                action: 'family_tree_update_archive_section_meta',
                section_id: ftSecModal.sectionId,
                image: ftSecModal.imageId,
                description: $('#ft-section-description').val(),
                nonce: familyTreeAdmin.nonce
            }, function (response) {
