                    alert((response && response.data && response.data.message) ? response.data.message : 'Не удалось сохранить раздел');
                }
            });
        })
        .on('click', '[data-ft-modal-close]', function () { ftSecCloseMetaModal(); })
        .on('keydown', function (e) {
            if (e.key === 'Escape' && $('#ft-section-meta-modal').hasClass('ft-modal-open')) {
                ftSecCloseMetaModal();
            }
        });

    // === Тумблеры включения/выключения разделов ===
    $(document).on('click', '.ft-section-toggle', function () {
        var $btn = $(this);
        var sectionId = $btn.data('section-id');
        if (!sectionId) { return; }
        $btn.prop('disabled', true);
        $.post(familyTreeAdmin.ajaxurl, {
            action: 'family_tree_toggle_archive_section',
            section_id: sectionId,
            nonce: familyTreeAdmin.nonce
        }, function (response) {
            $btn.prop('disabled', false);
            if (response && response.success && response.data && response.data.sections) {
                var enabled = !!(response.data.sections[sectionId] && response.data.sections[sectionId].enabled);
                $btn.toggleClass('ft-section-toggle--on', enabled);
                $btn.attr('aria-pressed', enabled ? 'true' : 'false');
                $btn.attr('title', enabled ? 'Выключить раздел' : 'Включить раздел');
                $btn.data('enabled', enabled ? '1' : '0');
                $btn.find('.ft-section-toggle-label').text(enabled ? 'Включено' : 'Выключено');
            } else {
                alert((response && response.data && response.data.message) ? response.data.message : 'Не удалось изменить состояние раздела');
            }
        });
    });

    // === Добавление нового раздела ===
    var ftNewSection = { imageId: 0, imageUrls: {} };
    function ftNewRenderCover() {
        var $cell = $('#ft-section-add-wrap .ft-section-thumb-cell');
