    // === Переключение табов (с запоминанием активного таба) ===
    var ftCurrentTab = sessionStorage.getItem('ft_settings_active_tab') || 'ft-tab-home';

    function ftActivateTab(id) {
        $('.ft-tab-btn').removeClass('active');
        $('.ft-tab-btn[data-tab="' + id + '"]').addClass('active');
        $('.ft-tab-panel').removeClass('active');
        $('#' + id).addClass('active');
        $('.ft-settings-aside .ft-hint').removeClass('active');
        $('.ft-settings-aside .ft-hint[data-hint="' + id + '"]').addClass('active');
