/**
 * AJAX: сохранение порядка разделов семейного архива.
 */
public function ajax_reorder_archive_sections() {
    if (!check_ajax_referer('family_tree_admin_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Security check failed'));
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Access denied'));
    }
    $order = isset($_POST['section_order']) ? wp_unslash($_POST['section_order']) : array();
    $order = is_array($order) ? $order : array();
    $sections = ft_get_archive_sections();
    $reordered = array();
    foreach ($order as $id) {
        $id = sanitize_key($id);
        if (isset($sections[$id]) && !isset($reordered[$id])) {
            $reordered[$id] = $sections[$id];
        }
    }
    foreach ($sections as $id => $item) {
        if (!isset($reordered[$id])) {
            $reordered[$id] = $item;
        }
    }
    ft_save_archive_sections($reordered);
    wp_send_json_success(array('sections' => $reordered));
}
/**
 * AJAX: сохранение изображения и описания раздела семейного архива.
 */
public function ajax_update_archive_section_meta() {
    if (!check_ajax_referer('family_tree_admin_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Security check failed'));
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Access denied'));
    }
    $section_id = isset($_POST['section_id']) ? sanitize_key($_POST['section_id']) : '';
    $image = isset($_POST['image']) ? max(0, intval($_POST['image'])) : 0;
    $description = isset($_POST['description']) ? sanitize_textarea_field(wp_unslash($_POST['description'])) : '';
    $sections = ft_get_archive_sections();
    if (empty($section_id) || !isset($sections[$section_id])) {
        wp_send_json_error(array('message' => 'Раздел не найден'));
    }
    if ($image > 0 && !wp_attachment_is_image($image)) {
        $image = 0;
    }
    $sections[$section_id]['image'] = $image;
    $sections[$section_id]['description'] = $description;
    ft_save_archive_sections($sections);
    wp_send_json_success(array('sections' => $sections));
}
/**
 * AJAX: включение/выключение раздела семейного архива.
 */
public function ajax_toggle_archive_section() {
    if (!check_ajax_referer('family_tree_admin_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Security check failed'));
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Access denied'));
    }
    $section_id = isset($_POST['section_id']) ? sanitize_key($_POST['section_id']) : '';
    $sections = ft_get_archive_sections();
    if (empty($section_id) || !isset($sections[$section_id])) {
        wp_send_json_error(array('message' => 'Раздел не найден'));
    }
    $sections[$section_id]['enabled'] = empty($sections[$section_id]['enabled']) ? true : false;
    ft_save_archive_sections($sections);
    $this->register_archive_rewrite_rules();
    flush_rewrite_rules();
    wp_send_json_success(array('sections' => $sections));
}
/**
 * AJAX: добавление нового раздела семейного архива.
 */
public function ajax_add_archive_section() {
    if (!check_ajax_referer('family_tree_admin_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Security check failed'));
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Access denied'));
    }
    $title = isset($_POST['title']) ? sanitize_text_field(wp_unslash($_POST['title'])) : '';
    $description = isset($_POST['description']) ? sanitize_textarea_field(wp_unslash($_POST['description'])) : '';
    $image = isset($_POST['image']) ? max(0, intval($_POST['image'])) : 0;
    if ('' === trim($title)) {
        wp_send_json_error(array('message' => 'Укажите название раздела'));
    }
    if ($image > 0 && !wp_attachment_is_image($image)) {
        $image = 0;
    }
    $sections = ft_get_archive_sections();
    $base = sanitize_title($title);
    if ('' === $base) {
        $base = 'section';
    }
    $id = $base;
    $n = 2;
    while (isset($sections[$id])) {
        $id = $base . '-' . $n;
        $n++;
    }
    $sections[$id] = array(
        'title'       => $title,
        'description' => $description,
        'image'       => $image,
        'enabled'     => true,
        'coming_soon' => true,
    );
    ft_save_archive_sections($sections);
    $this->register_archive_rewrite_rules();
    flush_rewrite_rules();
    wp_send_json_success(array('sections' => $sections, 'id' => $id));
}
/**
 * AJAX: удаление раздела семейного архива (нельзя удалить основные 4).
 */
public function ajax_delete_archive_section() {
    if (!check_ajax_referer('family_tree_admin_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Security check failed'));
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Access denied'));
    }
    $section_id = isset($_POST['section_id']) ? sanitize_key($_POST['section_id']) : '';
    $sections = ft_get_archive_sections();
    if (empty($section_id) || !isset($sections[$section_id])) {
        wp_send_json_error(array('message' => 'Раздел не найден'));
    }
    $core = ft_get_archive_section_defaults();
    if (isset($core[$section_id])) {
        wp_send_json_error(array('message' => 'Основные разделы удалить нельзя'));
    }
    unset($sections[$section_id]);
    ft_save_archive_sections($sections);
    $this->register_archive_rewrite_rules();
    flush_rewrite_rules();
    wp_send_json_success(array('sections' => $sections));
}
// === Страница «Фотоальбомы» — алфавитный каталог персон ===
/**
 * URL страницы раздела семейного архива в админке.
 *
 * @param string $section ключ раздела.
 * @return string
 */
public function archive_section_url($section) {
    $section = sanitize_key($section);
    $page = ('photoalbums' === $section) ? 'family-tree-photoalbums' : 'family-tree-archive-section-' . $section;
    return admin_url('admin.php?page=' . $page);
}

/**
 * URL страницы альбомов персоны внутри раздела семейного архива.
 *
 * @param string $section   ключ раздела.
 * @param int    $person_id ID персоналии.
 * @return string
 */
public function archive_person_url($section, $person_id) {
    return add_query_arg('person_id', (int) $person_id, $this->archive_section_url($section));
}

/**
 * Безопасная переадресация после POST/GET-обработки на страницах разделов архива.
 * В админке заголовки могут быть уже отправлены (admin-header.php выводится до
 * колбэка страницы) — тогда wp_redirect() не срабатывает и страница была бы пустой.
 * Здесь используется HTML-фолбэк (meta refresh + JS), работающий в любом случае.
 *
 * @param string $url целевой URL.
 * @return never
 */
public function safe_redirect($url) {
    $url = esc_url_raw($url);
    if (!headers_sent()) {
        wp_redirect($url);
        exit;
    }
    echo '<meta http-equiv="refresh" content="0; url=' . esc_url($url) . '">' . "\n";
    echo '<script type="text/javascript">window.location.href = ' . wp_json_encode($url) . ';</script>' . "\n";
    exit;
}

/**
 * Каталог разделов семейного архива (алфавитный список персоналий с фапка).
 */
public function archive_section_page() {
    $page = isset($_REQUEST['page']) ? sanitize_key(wp_unslash($_REQUEST['page'])) : '';
    $section = isset($_GET['section']) ? sanitize_key(wp_unslash($_GET['section'])) : '';
    if ('' === $section) {
        if ('family-tree-photoalbums' === $page || 'family-tree-archive' === $page || '' === $page) {
            $section = 'photoalbums';
        } elseif ($page && strpos($page, 'family-tree-archive-section-') === 0) {
            $section = substr($page, strlen('family-tree-archive-section-'));
        }
    }
    $available = ft_get_archive_sections();
    if ('' === $section || !isset($available[$section])) {
        wp_die(esc_html__('Раздел семейного архива не найден.', 'genius-family-tree'));
    }
    $terms = ft_archive_section_terms($section);
    $section_title = $available[$section]['title'];
    // Обработка: клик по персоне → показ альбомов
    $person_id = isset($_GET['person_id']) ? intval($_GET['person_id']) : 0;
    if ($person_id && get_post_type($person_id) === 'family_member') {
        $this->person_albums_page($person_id, $section);
        return;
    }
    ?>
    <div class="wrap">
        <h1><?php echo esc_html($section_title); ?></h1>
        <?php if (!empty($_GET['updated'])) : ?>
            <div class="updated"><p><?php echo esc_html__('Изменения сохранены.', 'genius-family-tree'); ?></p></div>
        <?php endif; ?>
        <?php
        // Загружаем всех персон, сортируем по фамилии
        $all_members = get_posts(array(
            'post_type'      => 'family_member',
            'posts_per_page' => -1,
            'post_status'    => 'publish',
            'orderby'        => 'title',
            'order'          => 'ASC',
        ));
        if (empty($all_members)) {
            echo '<p>' . esc_html__('Пока нет ни одной персоналии.', 'genius-family-tree') . '</p>';
            return;
        }
        // Группировка по первой букве фамилии (нормализованной)
        $grouped = array();
        foreach ($all_members as $member) {
            $last = get_post_meta($member->ID, '_family_member_last_name', true);
            $maiden = get_post_meta($member->ID, '_family_member_maiden_name', true);
            $surname = !empty($last) ? $last : (!empty($maiden) ? $maiden : '');
            $first = get_post_meta($member->ID, '_family_member_first_name', true);
            $letter = mb_strtoupper(mb_substr(mb_strtolower(trim($surname ?: $first)), 0, 1), 'UTF-8');
            if (!$letter || !preg_match('/^[A-ZА-ЯЁ]$/u', $letter)) {
                $letter = '#';
            }
            $albums = ft_get_albums($member->ID, $section);
            $total_items = 0;
            foreach ($albums as $a) {
                $total_items += count($a['photos']);
            }
            $grouped[$letter][] = array(
                'id'           => $member->ID,
                'title'        => $member->post_title,
                'surname'      => $surname,
                'first_name'   => $first,
                'albums'       => $albums,
                'album_count'  => count($albums),
                'total_photos' => $total_items,
                'permalink'    => get_permalink($member->ID),
            );
        }
        ksort($grouped);
        // Алфавитный указатель
        $letters = array_keys($grouped);
        ?>
        <div class="ft-archive-letters" style="display:flex;flex-wrap:wrap;gap:4px;margin:15px 0;">
            <?php foreach ($letters as $ltr) : ?>
                <a href="#ft-letter-<?php echo esc_attr($ltr); ?>" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:4px;background:#fff;border:1px solid #ccc;text-decoration:none;font-weight:600;color:#333;font-size:14px;"><?php echo esc_html($ltr); ?></a>
            <?php endforeach; ?>
        </div>
        <?php foreach ($grouped as $letter => $members) : ?>
            <div id="ft-letter-<?php echo esc_attr($letter); ?>" style="margin-top:20px;">
                <h2 style="margin-bottom:10px;font-size:20px;color:#2271b1;"><?php echo esc_html($letter); ?></h2>
<table class="wp-list-table widefat fixed striped" style="width:100%;table-layout:auto;">
                    <thead>
                        <tr>
                            <th style="width:250px;"><?php echo esc_html__('Персона', 'genius-family-tree'); ?></th>
                            <th style="width:100px;"><?php echo esc_html($terms['folder']); ?></th>
                            <th style="width:100px;"><?php echo esc_html($terms['item']); ?></th>
                            <th><?php echo esc_html($terms['folder']); ?></th>
                        </tr>
                    </thead>
                    <tbody>
                        <?php foreach ($members as $m) : ?>
                        <tr>
                            <td>
                                <a href="<?php echo esc_url($this->archive_person_url($section, $m['id'])); ?>" style="font-weight:600;text-decoration:none;color:#2271b1;">
                                    <?php echo esc_html($m['title']); ?>
                                </a>
                            </td>
                            <td><?php echo intval($m['album_count']); ?></td>
                            <td><?php echo intval($m['total_photos']); ?></td>
                            <td>
                                <?php if (!empty($m['albums'])) : ?>
                                    <?php foreach ($m['albums'] as $a) : ?>
                                        <span style="display:inline-block;background:#f0f0f1;padding:2px 8px;border-radius:3px;margin:1px 4px 1px 0;font-size:12px;">
                                            <?php echo esc_html($a['name']); ?> (<?php echo count($a['photos']); ?>)
                                        </span>
                                    <?php endforeach; ?>
                                <?php else : ?>
                                    <span style="color:#999;font-size:12px;"><?php echo esc_html($terms['no_folders']); ?></span>
                                <?php endif; ?>
                            </td>
                        </tr>
                        <?php endforeach; ?>
                    </tbody>
                </table>
            </div>
        <?php endforeach; ?>
    </div>
    <?php
}
// === Страница альбомов конкретной персоны в разделе архива ===
private function person_albums_page($person_id, $section = 'photoalbums') {
    $person = get_post($person_id);
    if (!$person) {
        echo '<div class="wrap"><p>' . esc_html__('Персоналия не найдена.', 'genius-family-tree') . '</p></div>';
        return;
    }
    $terms = ft_archive_section_terms($section);
    $catalog_url = $this->archive_section_url($section);
    // Обработка: переименование альбома
    if (isset($_POST['ft_rename_album_nonce'], $_POST['album_name'], $_POST['album_index'])
        && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ft_rename_album_nonce'])), 'ft_rename_album_' . $person_id)) {
ft_rename_album($person_id, intval($_POST['album_index']), sanitize_text_field(wp_unslash($_POST['album_name'])), $section);
        $this->safe_redirect(add_query_arg('updated', '1', $this->archive_person_url($section, $person_id)));
            exit;
    }
    // Обработка: добавление альбома
    if (isset($_POST['ft_new_album_nonce'])
        && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ft_new_album_nonce'])), 'ft_new_album')) {
if (current_user_can('edit_post', $person_id)) {
            $album_name = sanitize_text_field(wp_unslash($_POST['new_album_name']));
            ft_add_album($person_id, $album_name, $section);
        }
        $this->safe_redirect(add_query_arg('updated', '1', $this->archive_person_url($section, $person_id)));
            exit;
    }
    $albums = ft_get_albums($person_id, $section);
    // Обработка: удаление альбома
    if (isset($_GET['delete_album']) && isset($_GET['album_nonce'])) {
        if (wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['album_nonce'])), 'ft_delete_album_' . $person_id)) {
ft_delete_album($person_id, intval($_GET['delete_album']), $section);
            $this->safe_redirect(add_query_arg('updated', '1', $this->archive_person_url($section, $person_id)));
                exit;
        }
    }
    ?>
    <div class="wrap">
        <p><a href="<?php echo esc_url($catalog_url); ?>">&larr; <?php echo esc_html__('Назад к каталогу', 'genius-family-tree'); ?></a></p>
        <h1><?php echo esc_html($person->post_title); ?> — <?php echo esc_html($terms['name']); ?></h1>
        <?php if (!empty($_GET['updated'])) : ?>
            <div class="updated"><p><?php echo esc_html__('Изменения сохранены.', 'genius-family-tree'); ?></p></div>
        <?php endif; ?>
        <input type="hidden" id="ft-admin-section" value="<?php echo esc_attr($section); ?>" />
        <?php if (empty($albums)) : ?>
            <p><?php echo esc_html($terms['no_folders_h2']); ?></p>
        <?php else : ?>
            <p class="components-base-control__help"><?php echo esc_html(sprintf(__('Перетащите строку за номер, чтобы изменить порядок %s (он обновится и на сайте).', 'genius-family-tree'), mb_strtolower($terms['folder']))); ?></p>
            <table class="wp-list-table widefat fixed striped" style="max-width:960px;">
                <thead>
                    <tr>
                        <th style="width:50px;">#</th>
                        <th style="width:90px;"><?php echo esc_html__('Обложка', 'genius-family-tree'); ?></th>
                        <th><?php echo esc_html__('Название', 'genius-family-tree'); ?></th>
