                        <?php endif; ?>
                        <?php if ($full) : ?>
                            <a href="<?php echo esc_url($full[0]); ?>" class="ft-album-editor-view ft-admin-lightbox" data-gallery="ft-admin-album-photos" title="<?php echo esc_attr(get_the_title($photo_id)); ?>" draggable="false">
                                <span class="dashicons dashicons-external"></span>
                            </a>
                        <?php endif; ?>
                    </div>
                    <?php endforeach; ?>
                <?php endif; ?>
            </div>
        </div>
        <?php endforeach; ?>
        <?php endif; ?>
        <?php if (!empty($albums)) : ?>
        <script>
        jQuery(function($){
            if (typeof window.GLightbox === 'undefined') { return; }
            if (window.__ftAdminLightbox) { window.__ftAdminLightbox.destroy(); }
            window.__ftAdminLightbox = window.GLightbox({
                selector: '.ft-admin-lightbox',
                touchNavigation: true,
                loop: true,
                keyboardNavigation: true,
                closeButton: true,
                openEffect: 'fade',
                closeEffect: 'fade',
                slideEffect: 'slide'
            });
        });
        </script>
        <?php endif; ?>
    </div>
    <?php
}
// Добавляем страницу настроек
public function settings_page() {
// Обработка формы
$message = '';
$message_type = '';
if (isset($_POST['family_tree_save_settings']) && isset($_POST['family_tree_settings_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['family_tree_settings_nonce'])), 'family_tree_save_settings')) {
    if (isset($_POST['family_tree_license_key'])) {
        $new_license_key = sanitize_text_field(wp_unslash($_POST['family_tree_license_key']));
$old_license_key = get_option('family_tree_license_key', '');
if (empty($new_license_key)) {
// Деактивация
delete_option('family_tree_license_key');
$this->force_free();
if (!empty($old_license_key)) {
$this->send_activation_data($old_license_key, false);
}
$message = esc_html__('Лицензия деактивирована', 'genius-family-tree');
$message_type = 'updated';
} else {
// Активация/проверка лицензии
$result = $this->validate_license($new_license_key);
if ($result['success']) {
update_option('family_tree_license_key', $new_license_key);
$message = esc_html($result['message']);
$message_type = 'updated';
$this->send_activation_data($new_license_key, true);
} else {
$message = esc_html($result['message']);
$message_type = 'error';
$this->send_activation_data($new_license_key, false);
}
}
}
}
// Список допустимых гарнитур (системные + Google Fonts) — используется при сохранении шрифтов персоналий и каталога
$allowed_fonts = array_merge(array('Open Sans', 'Roboto Slab', 'Georgia', 'Times New Roman', 'Arial', 'Verdana', 'Tahoma', 'Trebuchet MS', 'Courier New'), array_keys(self::get_google_fonts()));
// Обработка сохранения общих настроек (таб «Общие настройки») — приватность и доступ
if (isset($_POST['family_tree_save_general_settings']) && isset($_POST['family_tree_settings_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['family_tree_settings_nonce'])), 'family_tree_save_settings')) {
    $ft_access_mode_raw = isset($_POST['family_tree_access_mode']) ? sanitize_key(wp_unslash($_POST['family_tree_access_mode'])) : '';
    if (!in_array($ft_access_mode_raw, array('private', 'registered', 'visitors'), true)) {
        $ft_access_mode_raw = 'visitors';
    }
    update_option('family_tree_private_tree', $ft_access_mode_raw === 'private' ? 1 : 0);
    update_option('family_tree_hide_from_unregistered', $ft_access_mode_raw === 'registered' ? 1 : 0);
    $stub_text = isset($_POST['family_tree_private_stub_text']) ? sanitize_textarea_field(wp_unslash($_POST['family_tree_private_stub_text'])) : '';
    update_option('family_tree_private_stub_text', $stub_text);
    $allowed_viewers = array();
    if (isset($_POST['family_tree_allowed_viewers']) && is_array($_POST['family_tree_allowed_viewers'])) {
        foreach ($_POST['family_tree_allowed_viewers'] as $ft_uid) {
            $ft_uid = intval($ft_uid);
            if ($ft_uid > 0 && get_user_by('id', $ft_uid)) {
                $allowed_viewers[] = $ft_uid;
            }
        }
    }
    update_option('family_tree_allowed_viewers', array_values(array_unique($allowed_viewers)));
    $ft_allowed_hide_fields = array('dates', 'years', 'name_parts', 'photo', 'places');
    $hide_fields = array();
    if (isset($_POST['family_tree_hide_fields']) && is_array($_POST['family_tree_hide_fields'])) {
        foreach ($_POST['family_tree_hide_fields'] as $ft_field_key) {
            $ft_field_key = sanitize_key($ft_field_key);
            if (in_array($ft_field_key, $ft_allowed_hide_fields, true) && !in_array($ft_field_key, $hide_fields, true)) {
                $hide_fields[] = $ft_field_key;
            }
        }
    }
    update_option('family_tree_hide_fields', $hide_fields);
    $message = esc_html__('Общие настройки сохранены', 'genius-family-tree');
    $message_type = 'updated';
}
// Обработка сохранения настроек отображения (таб «Отображение древа»)
if (isset($_POST['family_tree_save_display_settings']) && isset($_POST['family_tree_settings_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['family_tree_settings_nonce'])), 'family_tree_save_settings')) {
    $bg_color = isset($_POST['family_tree_bg_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_bg_color'])) : '';
    $bg_image = isset($_POST['family_tree_bg_image']) ? esc_url_raw(family_tree_sanitize_str($_POST['family_tree_bg_image'])) : '';
    $bg_type = isset($_POST['family_tree_bg_type']) && 'gradient' === $_POST['family_tree_bg_type'] ? 'gradient' : 'classic';
    $bg_gradient = isset($_POST['family_tree_bg_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_bg_gradient'])) : '';
    $bg_gradient_type = isset($_POST['family_tree_bg_gradient_type']) && 'radial' === $_POST['family_tree_bg_gradient_type'] ? 'radial' : 'linear';
    $bg_angle = isset($_POST['family_tree_bg_angle']) ? max(-360, min(360, intval($_POST['family_tree_bg_angle']))) : 180;
    // Ширина/высота, отступы, скругление и граница — с табами устройств:
    // базовое имя для Десктопа, суффиксы _tablet и _mobile — для Планшета и
    // Мобильных. Пустое поле Планшета/Мобильных наследует Десктоп.
    $border_radius = $this->ft_post_box_device('family_tree_border_radius');
    $tree_width = $this->ft_post_box_device('family_tree_width', 'size');
    $tree_height = $this->ft_post_box_device('family_tree_height', 'size');
    $container_margin = $this->ft_post_box_device('family_tree_container_margin');
    $container_padding = $this->ft_post_box_device('family_tree_container_padding');
    $container_border_width = $this->ft_post_box_device('family_tree_container_border_width');
    $container_border_color = $this->ft_post_box_device('family_tree_container_border_color', 'color');
    // Стиль границы: неизвестное значение у Десктопа заменяем на «сплошная»,
    // у Планшета и Мобильных — пустое поле, то есть наследование с Десктопа.
    $container_border_style = $this->ft_box_device_style($this->ft_post_box_device('family_tree_container_border_style', 'style'));
    $card_color = isset($_POST['family_tree_card_color']) ? $this->sanitize_tree_color($_POST['family_tree_card_color']) : '';
    $male_color = isset($_POST['family_tree_male_color']) ? $this->sanitize_tree_color($_POST['family_tree_male_color']) : '';
    $female_color = isset($_POST['family_tree_female_color']) ? $this->sanitize_tree_color($_POST['family_tree_female_color']) : '';
    $text_color = isset($_POST['family_tree_text_color']) ? $this->sanitize_tree_color($_POST['family_tree_text_color']) : '';
    $text_color_hover = isset($_POST['family_tree_text_color_hover']) ? $this->sanitize_tree_color($_POST['family_tree_text_color_hover']) : '';
    $text_color_state_raw = isset($_POST['family_tree_text_color_state']) ? family_tree_sanitize_str($_POST['family_tree_text_color_state']) : 'normal';
    $text_color_state = in_array($text_color_state_raw, array('normal', 'hover'), true) ? $text_color_state_raw : 'normal';
    $card_width = isset($_POST['family_tree_card_width']) ? $this->sanitize_tree_int($_POST['family_tree_card_width']) : 220;
    $card_height = isset($_POST['family_tree_card_height']) ? $this->sanitize_tree_int($_POST['family_tree_card_height']) : 100;
    // Текст карточек: свой цвет для «Имён» и «Дат», своя типографика при наведении.
    // Обычное состояние пишется в те же опции family_tree_*_font_*, что и раньше,
    // поэтому отдельный разбор family_tree_name_font_* / family_tree_date_font_* не нужен.
    $card_text = array();
    foreach (array('name', 'date') as $ft_ct_block) {
        $ft_ct_base = 'family_tree_' . $ft_ct_block . '_';
        foreach (array('' => 'normal', '_hover' => 'hover') as $ft_ct_sfx => $ft_ct_state) {
            $ft_ct_font_raw = isset($_POST[$ft_ct_base . 'font_family' . $ft_ct_sfx])
                ? family_tree_sanitize_str($_POST[$ft_ct_base . 'font_family' . $ft_ct_sfx])
                : '';
            $ft_ct_font = in_array($ft_ct_font_raw, $allowed_fonts, true) ? $ft_ct_font_raw : '';
            $ft_ct_size = isset($_POST[$ft_ct_base . 'font_size' . $ft_ct_sfx])
                ? intval($_POST[$ft_ct_base . 'font_size' . $ft_ct_sfx])
                : 0;
            $ft_ct_weight = isset($_POST[$ft_ct_base . 'font_weight' . $ft_ct_sfx])
                ? intval($_POST[$ft_ct_base . 'font_weight' . $ft_ct_sfx])
                : 0;
            $card_text[$ft_ct_block][$ft_ct_state] = array(
                'color' => isset($_POST[$ft_ct_base . 'text_color' . $ft_ct_sfx])
                    ? $this->sanitize_tree_color($_POST[$ft_ct_base . 'text_color' . $ft_ct_sfx])
                    : '',
                'font_family' => $ft_ct_font,
                'font_size'   => max(0, min(96, $ft_ct_size)),
                'font_weight' => in_array($ft_ct_weight, self::get_font_weights($ft_ct_font), true) ? $ft_ct_weight : 0,
            );
        }
    }
    $male_placeholder_data = isset($_POST['family_tree_male_placeholder']) ? $this->sanitize_placeholder_image($_POST['family_tree_male_placeholder']) : array('url' => '', 'valid' => true, 'message' => '');
    $female_placeholder_data = isset($_POST['family_tree_female_placeholder']) ? $this->sanitize_placeholder_image($_POST['family_tree_female_placeholder']) : array('url' => '', 'valid' => true, 'message' => '');
$disable_wheel_zoom = isset($_POST['family_tree_disable_wheel_zoom']) ? 1 : 0;
$toolbar_btn_bg = isset($_POST['family_tree_toolbar_btn_bg']) ? $this->sanitize_tree_color($_POST['family_tree_toolbar_btn_bg']) : '';
$toolbar_btn_bg_hover = isset($_POST['family_tree_toolbar_btn_bg_hover']) ? $this->sanitize_tree_color($_POST['family_tree_toolbar_btn_bg_hover']) : '';
$toolbar_btn_bg_type = isset($_POST['family_tree_toolbar_btn_bg_type']) && 'gradient' === $_POST['family_tree_toolbar_btn_bg_type'] ? 'gradient' : 'classic';
$toolbar_btn_bg_gradient = isset($_POST['family_tree_toolbar_btn_bg_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_toolbar_btn_bg_gradient'])) : '';
$toolbar_btn_bg_gradient_type = isset($_POST['family_tree_toolbar_btn_bg_gradient_type']) && 'radial' === $_POST['family_tree_toolbar_btn_bg_gradient_type'] ? 'radial' : 'linear';
$toolbar_btn_bg_angle = isset($_POST['family_tree_toolbar_btn_bg_angle']) ? max(-360, min(360, intval($_POST['family_tree_toolbar_btn_bg_angle']))) : 180;
$toolbar_btn_bg_hover_type = isset($_POST['family_tree_toolbar_btn_bg_hover_type']) && 'gradient' === $_POST['family_tree_toolbar_btn_bg_hover_type'] ? 'gradient' : 'classic';
$toolbar_btn_bg_hover_gradient = isset($_POST['family_tree_toolbar_btn_bg_hover_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_toolbar_btn_bg_hover_gradient'])) : '';
$toolbar_btn_bg_hover_gradient_type = isset($_POST['family_tree_toolbar_btn_bg_hover_gradient_type']) && 'radial' === $_POST['family_tree_toolbar_btn_bg_hover_gradient_type'] ? 'radial' : 'linear';
$toolbar_btn_bg_hover_angle = isset($_POST['family_tree_toolbar_btn_bg_hover_angle']) ? max(-360, min(360, intval($_POST['family_tree_toolbar_btn_bg_hover_angle']))) : 180;
$toolbar_btn_bg_state_raw = isset($_POST['family_tree_toolbar_btn_bg_state']) ? family_tree_sanitize_str($_POST['family_tree_toolbar_btn_bg_state']) : 'normal';
$toolbar_btn_bg_state = in_array($toolbar_btn_bg_state_raw, array('normal', 'hover'), true) ? $toolbar_btn_bg_state_raw : 'normal';
$toolbar_icon_color = isset($_POST['family_tree_toolbar_icon_color']) ? $this->sanitize_tree_color($_POST['family_tree_toolbar_icon_color']) : '';
$toolbar_icon_color_hover = isset($_POST['family_tree_toolbar_icon_color_hover']) ? $this->sanitize_tree_color($_POST['family_tree_toolbar_icon_color_hover']) : '';
$toolbar_icon_color_state_raw = isset($_POST['family_tree_toolbar_icon_color_state']) ? family_tree_sanitize_str($_POST['family_tree_toolbar_icon_color_state']) : 'normal';
$toolbar_icon_color_state = in_array($toolbar_icon_color_state_raw, array('normal', 'hover'), true) ? $toolbar_icon_color_state_raw : 'normal';
$toolbar_position_raw = isset($_POST['family_tree_toolbar_position']) ? family_tree_sanitize_str($_POST['family_tree_toolbar_position']) : 'bottom-right';
$allowed_positions = array('top-left', 'top-right', 'bottom-right', 'bottom-left');
$toolbar_position = in_array($toolbar_position_raw, $allowed_positions, true) ? $toolbar_position_raw : 'bottom-right';
$toolbar_border_width = isset($_POST['family_tree_toolbar_border_width']) ? $this->sanitize_css_radius($_POST['family_tree_toolbar_border_width']) : '1px';
$toolbar_border_style_raw = isset($_POST['family_tree_toolbar_border_style']) ? family_tree_sanitize_str($_POST['family_tree_toolbar_border_style']) : 'solid';
$toolbar_border_style = in_array($toolbar_border_style_raw, array('solid', 'dashed', 'dotted', 'double'), true) ? $toolbar_border_style_raw : 'solid';
$toolbar_border_color = isset($_POST['family_tree_toolbar_border_color']) ? $this->sanitize_tree_color($_POST['family_tree_toolbar_border_color']) : '';
$toolbar_border_radius = isset($_POST['family_tree_toolbar_border_radius']) ? $this->sanitize_css_radius($_POST['family_tree_toolbar_border_radius']) : '8px';
    update_option('family_tree_bg_color', $bg_color);
    update_option('family_tree_bg_image', $bg_image);
    update_option('family_tree_bg_type', $bg_type);
    update_option('family_tree_bg_gradient', $bg_gradient);
    update_option('family_tree_bg_gradient_type', $bg_gradient_type);
    update_option('family_tree_bg_angle', $bg_angle);
    // Табы устройств: базовые имена — Десктоп, суффиксы _tablet/_mobile.
    $this->ft_save_box_device('family_tree_border_radius');
    $this->ft_save_box_device('family_tree_width', 'size');
    $this->ft_save_box_device('family_tree_height', 'size');
    $this->ft_save_box_device('family_tree_container_margin');
    $this->ft_save_box_device('family_tree_container_padding');
    $this->ft_save_box_device('family_tree_container_border_width');
    $this->ft_save_box_device('family_tree_container_border_color', 'color');
    foreach (self::ft_box_device_suffixes() as $ft_cs_sfx => $ft_cs_dev) {
        update_option('family_tree_container_border_style' . $ft_cs_sfx, $container_border_style[$ft_cs_dev]);
    }
    update_option('family_tree_card_color', $card_color);
    update_option('family_tree_male_color', $male_color);
    update_option('family_tree_female_color', $female_color);
    // Старые общие цвета текста больше не выводятся в форме, поэтому не затираем
    // их: на них завязаны сторонние места, а для миграции их читает ft_card_text_opt().
    if (isset($_POST['family_tree_text_color'])) {
        update_option('family_tree_text_color', $text_color);
    }
    if (isset($_POST['family_tree_text_color_hover'])) {
        update_option('family_tree_text_color_hover', $text_color_hover);
    }
    update_option('family_tree_text_color_state', $text_color_state);
    update_option('family_tree_card_width', $card_width);
    update_option('family_tree_card_height', $card_height);
    // Текст карточек: «Имена» и «Даты», обычное состояние и при наведении.
    // Этот же цикл пишет и опции обычного состояния family_tree_*_font_*,
    // поэтому отдельной записи для них здесь нет.
    foreach ($card_text as $ft_ct_block => $ft_ct_states) {
        foreach ($ft_ct_states as $ft_ct_state => $ft_ct_row) {
            $ft_ct_sfx = ('hover' === $ft_ct_state) ? '_hover' : '';
            update_option('family_tree_' . $ft_ct_block . '_text_color' . $ft_ct_sfx, $ft_ct_row['color']);
            update_option('family_tree_' . $ft_ct_block . '_font_family' . $ft_ct_sfx, $ft_ct_row['font_family']);
            update_option('family_tree_' . $ft_ct_block . '_font_size' . $ft_ct_sfx, $ft_ct_row['font_size']);
            update_option('family_tree_' . $ft_ct_block . '_font_weight' . $ft_ct_sfx, $ft_ct_row['font_weight']);
        }
    }
    if ($male_placeholder_data['valid']) {
        update_option('family_tree_male_placeholder', $male_placeholder_data['url']);
    }
    if ($female_placeholder_data['valid']) {
        update_option('family_tree_female_placeholder', $female_placeholder_data['url']);
    }
    update_option('family_tree_disable_wheel_zoom', $disable_wheel_zoom);
    update_option('family_tree_toolbar_btn_bg', $toolbar_btn_bg);
    update_option('family_tree_toolbar_btn_bg_hover', $toolbar_btn_bg_hover);
    update_option('family_tree_toolbar_btn_bg_type', $toolbar_btn_bg_type);
    update_option('family_tree_toolbar_btn_bg_gradient', $toolbar_btn_bg_gradient);
    update_option('family_tree_toolbar_btn_bg_gradient_type', $toolbar_btn_bg_gradient_type);
    update_option('family_tree_toolbar_btn_bg_angle', $toolbar_btn_bg_angle);
    update_option('family_tree_toolbar_btn_bg_hover_type', $toolbar_btn_bg_hover_type);
    update_option('family_tree_toolbar_btn_bg_hover_gradient', $toolbar_btn_bg_hover_gradient);
    update_option('family_tree_toolbar_btn_bg_hover_gradient_type', $toolbar_btn_bg_hover_gradient_type);
    update_option('family_tree_toolbar_btn_bg_hover_angle', $toolbar_btn_bg_hover_angle);
    update_option('family_tree_toolbar_btn_bg_state', $toolbar_btn_bg_state);
    update_option('family_tree_toolbar_icon_color', $toolbar_icon_color);
    update_option('family_tree_toolbar_icon_color_hover', $toolbar_icon_color_hover);
    update_option('family_tree_toolbar_icon_color_state', $toolbar_icon_color_state);
    update_option('family_tree_toolbar_position', $toolbar_position);
    update_option('family_tree_toolbar_border_width', $toolbar_border_width);
    update_option('family_tree_toolbar_border_style', $toolbar_border_style);
    update_option('family_tree_toolbar_border_color', $toolbar_border_color);
    update_option('family_tree_toolbar_border_radius', $toolbar_border_radius);
    if (!$male_placeholder_data['valid'] || !$female_placeholder_data['valid']) {
        $placeholder_errors = array();
        if (!$male_placeholder_data['valid']) {
            $placeholder_errors[] = esc_html__('мужская', 'genius-family-tree') . ': ' . $male_placeholder_data['message'];
        }
        if (!$female_placeholder_data['valid']) {
            $placeholder_errors[] = esc_html__('женская', 'genius-family-tree') . ': ' . $female_placeholder_data['message'];
        }
        $message = esc_html__('Заглушки фото не сохранены: ', 'genius-family-tree') . implode('; ', $placeholder_errors);
        $message_type = 'error';
    } else {
        $message = esc_html__('Настройки отображения сохранены', 'genius-family-tree');
        $message_type = 'updated';
    }
}
// Обработка сохранения оформления страницы персоны (таб «Страница персоны»)
if (isset($_POST['family_tree_save_person_styles']) && isset($_POST['family_tree_settings_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['family_tree_settings_nonce'])), 'family_tree_save_settings')) {
    $person_bg = isset($_POST['family_tree_person_bg']) ? $this->sanitize_tree_color($_POST['family_tree_person_bg']) : '';
    $person_bg_type = isset($_POST['family_tree_person_bg_type']) && 'gradient' === $_POST['family_tree_person_bg_type'] ? 'gradient' : 'classic';
    $person_bg_gradient = isset($_POST['family_tree_person_bg_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_person_bg_gradient'])) : '';
    $person_bg_gradient_type = isset($_POST['family_tree_person_bg_gradient_type']) && 'radial' === $_POST['family_tree_person_bg_gradient_type'] ? 'radial' : 'linear';
    $person_bg_angle = isset($_POST['family_tree_person_bg_angle']) ? max(-360, min(360, intval($_POST['family_tree_person_bg_angle']))) : 180;
    $person_bg_image = isset($_POST['family_tree_person_bg_image']) ? esc_url_raw(family_tree_sanitize_str($_POST['family_tree_person_bg_image'])) : '';
    update_option('family_tree_person_bg_type', $person_bg_type);
    update_option('family_tree_person_bg_gradient', $person_bg_gradient);
    update_option('family_tree_person_bg_gradient_type', $person_bg_gradient_type);
    update_option('family_tree_person_bg_angle', $person_bg_angle);
    update_option('family_tree_person_bg_image', $person_bg_image);
    $person_template = isset($_POST['family_tree_person_template']) ? $this->sanitize_person_template($_POST['family_tree_person_template']) : '';
    // Контейнер и блоки персон — с табами устройств (пустое поле наследует
    // Десктоп), как у параметров древа.
    $person_container_margin = $this->ft_post_box_device('family_tree_person_container_margin');
    $person_container_padding = $this->ft_post_box_device('family_tree_person_container_padding');
    $person_container_radius = $this->ft_post_box_device('family_tree_person_container_radius');
    $person_container_border_width = $this->ft_post_box_device('family_tree_person_container_border_width');
    $person_container_border_color = $this->ft_post_box_device('family_tree_person_container_border_color', 'color');
    $person_container_border_style = $this->ft_box_device_style($this->ft_post_box_device('family_tree_person_container_border_style', 'style'));
