}
$settings = $this->get_album_display_settings();

// ===== Feed: preservation of album feed settings (container / layout / display) =====
if (isset($_POST['family_tree_album_settings_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['family_tree_album_settings_nonce'])), 'family_tree_save_album_settings')) {
        // Вкладка «Лента альбомов» — одна карточка, одна форма и одна кнопка сохранения,
        // поэтому все три блока (контейнер / раскладка / отображение) сохраняются вместе.
        // Старые имена кнопок принимаются для совместимости с закэшированными страницами.
        $ft_album_feed_save = isset($_POST['family_tree_save_album_feed_settings'])
            || isset($_POST['family_tree_save_album_container_settings'])
            || isset($_POST['family_tree_save_album_layout_settings'])
            || isset($_POST['family_tree_save_album_display_settings']);
        if ($ft_album_feed_save) {
            $settings['container_bg_color'] = isset($_POST['family_tree_album_container_bg']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_container_bg'])) : $settings['container_bg_color'];
$settings['container_bg_image'] = isset($_POST['family_tree_album_container_bg_image']) ? esc_url_raw(family_tree_sanitize_str($_POST['family_tree_album_container_bg_image'])) : $settings['container_bg_image'];
            $settings['container_bg_type'] = isset($_POST['family_tree_album_container_bg_type']) && 'gradient' === $_POST['family_tree_album_container_bg_type'] ? 'gradient' : 'classic';
            $settings['container_bg_gradient'] = isset($_POST['family_tree_album_container_bg_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_album_container_bg_gradient'])) : $settings['container_bg_gradient'];
            $settings['container_bg_gradient_type'] = isset($_POST['family_tree_album_container_bg_gradient_type']) && 'radial' === $_POST['family_tree_album_container_bg_gradient_type'] ? 'radial' : 'linear';
            $settings['container_bg_angle'] = isset($_POST['family_tree_album_container_bg_angle']) ? max(-360, min(360, intval($_POST['family_tree_album_container_bg_angle']))) : $settings['container_bg_angle'];
            // Оформление контейнера ленты — с табами устройств: базовые ключи — Десктоп,
            // суффиксы _tablet и _mobile — Планшет и Мобильные. Пустое поле
            // Планшета/Мобильных наследует Десктоп.
            foreach (self::ft_box_device_suffixes() as $ft_sfx => $ft_dev) {
                foreach (array('container_radius', 'container_margin', 'container_padding', 'container_border_width') as $ft_key) {
                    $ft_post = 'family_tree_album_' . $ft_key . $ft_sfx;
                    $settings[$ft_key . $ft_sfx] = isset($_POST[$ft_post])
                        ? $this->sanitize_css_radius(family_tree_sanitize_str($_POST[$ft_post]))
                        : (isset($settings[$ft_key . $ft_sfx]) ? $settings[$ft_key . $ft_sfx] : '');
                }
                $ft_post = 'family_tree_album_container_border_color' . $ft_sfx;
                $settings['container_border_color' . $ft_sfx] = isset($_POST[$ft_post])
                    ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST[$ft_post]))
                    : (isset($settings['container_border_color' . $ft_sfx]) ? $settings['container_border_color' . $ft_sfx] : '');
                $ft_post = 'family_tree_album_container_border_style' . $ft_sfx;
                $ft_style = isset($_POST[$ft_post]) ? family_tree_sanitize_str($_POST[$ft_post]) : '';
                if (!in_array($ft_style, array('solid', 'dashed', 'dotted', 'double'), true)) {
                    // У Десктопа неизвестное значение заменяем на «сплошная»,
                    // у Планшета и Мобильных — пустое поле (наследование).
                    $ft_style = ('desktop' === $ft_dev)
                        ? 'solid'
                        : (isset($settings['container_border_style' . $ft_sfx]) ? $settings['container_border_style' . $ft_sfx] : '');
                    if (!in_array($ft_style, array('solid', 'dashed', 'dotted', 'double'), true)) {
                        $ft_style = '';
                    }
                }
                $settings['container_border_style' . $ft_sfx] = $ft_style;
            }
            $settings['show_album_subheader'] = isset($_POST['family_tree_album_show_album_subheader']) ? 1 : 0;
            $settings['show_album_description'] = isset($_POST['family_tree_album_show_album_description']) ? 1 : 0;
            $settings['subheader_bg'] = isset($_POST['family_tree_album_subheader_bg']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_subheader_bg'])) : $settings['subheader_bg'];
            $settings['subheader_bg_type'] = isset($_POST['family_tree_album_subheader_bg_type'])
                ? ('gradient' === $_POST['family_tree_album_subheader_bg_type'] ? 'gradient' : 'classic')
                : $settings['subheader_bg_type'];
            $settings['subheader_bg_gradient'] = isset($_POST['family_tree_album_subheader_bg_gradient']) ? sanitize_text_field(wp_unslash($_POST['family_tree_album_subheader_bg_gradient'])) : $settings['subheader_bg_gradient'];
            $settings['subheader_bg_gradient_type'] = isset($_POST['family_tree_album_subheader_bg_gradient_type'])
                ? ('radial' === $_POST['family_tree_album_subheader_bg_gradient_type'] ? 'radial' : 'linear')
                : $settings['subheader_bg_gradient_type'];
            $settings['subheader_bg_angle'] = isset($_POST['family_tree_album_subheader_bg_angle']) ? max(-360, min(360, intval($_POST['family_tree_album_subheader_bg_angle']))) : $settings['subheader_bg_angle'];
            $settings['subheader_bg_image'] = isset($_POST['family_tree_album_subheader_bg_image']) ? esc_url_raw(family_tree_sanitize_str($_POST['family_tree_album_subheader_bg_image'])) : $settings['subheader_bg_image'];
            $settings['subheader_color'] = isset($_POST['family_tree_album_subheader_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_subheader_color'])) : $settings['subheader_color'];
            $sub_font_raw = isset($_POST['family_tree_album_subheader_font_family']) ? family_tree_sanitize_str($_POST['family_tree_album_subheader_font_family']) : '';
            $settings['subheader_font_family'] = in_array($sub_font_raw, $allowed_fonts, true) ? $sub_font_raw : '';
            $sub_font_weight = isset($_POST['family_tree_album_subheader_font_weight']) ? intval($_POST['family_tree_album_subheader_font_weight']) : 0;
            $settings['subheader_font_weight'] = in_array($sub_font_weight, self::get_font_weights($settings['subheader_font_family']), true) ? $sub_font_weight : 0;
            $settings['subheader_font_size'] = isset($_POST['family_tree_album_subheader_font_size']) ? max(0, min(96, intval($_POST['family_tree_album_subheader_font_size']))) : $settings['subheader_font_size'];
            $settings['subheader_border_width'] = isset($_POST['family_tree_album_subheader_border_width']) ? max(0, min(50, intval($_POST['family_tree_album_subheader_border_width']))) : $settings['subheader_border_width'];
            $sh_border_style = isset($_POST['family_tree_album_subheader_border_style']) ? family_tree_sanitize_str($_POST['family_tree_album_subheader_border_style']) : 'solid';
            $settings['subheader_border_style'] = in_array($sh_border_style, array('solid', 'dashed', 'dotted', 'double'), true) ? $sh_border_style : 'solid';
            $settings['subheader_border_color'] = isset($_POST['family_tree_album_subheader_border_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_subheader_border_color'])) : $settings['subheader_border_color'];
            $settings['subheader_radius'] = isset($_POST['family_tree_album_subheader_radius']) ? $this->sanitize_css_radius($_POST['family_tree_album_subheader_radius']) : $settings['subheader_radius'];
            foreach (array('top' => 200, 'right' => 200, 'bottom' => 200, 'left' => 200) as $sh_side => $sh_max) {
                $settings['subheader_padding_' . $sh_side] = isset($_POST['family_tree_album_subheader_padding_' . $sh_side]) ? max(0, min($sh_max, intval($_POST['family_tree_album_subheader_padding_' . $sh_side]))) : $settings['subheader_padding_' . $sh_side];
                $settings['subheader_margin_' . $sh_side] = isset($_POST['family_tree_album_subheader_margin_' . $sh_side]) ? max(-200, min(200, intval($_POST['family_tree_album_subheader_margin_' . $sh_side]))) : $settings['subheader_margin_' . $sh_side];
            }
            foreach (self::ft_box_device_suffixes() as $ft_sfx => $ft_dev) {
                foreach (array('margin', 'padding', 'radius', 'border_width') as $ft_box_prop) {
                    $ft_box_name = 'family_tree_album_subheader_box_' . $ft_box_prop . $ft_sfx;
                    if (!isset($_POST[$ft_box_name])) {
                        continue;
                    }
                    $ft_raw = wp_unslash($_POST[$ft_box_name]);
                    $ft_box_value = family_tree_sanitize_str($ft_raw);
                    if ('margin' === $ft_box_prop) {
                        $ft_parts = preg_split('/\s+/', trim($ft_box_value));
                        $ft_clean_parts = array();
                        foreach ($ft_parts as $ft_part) {
                            if (!preg_match('/^-?\d+(?:\.\d+)?(?:px|%|vh|vw|em|rem|pt|cm|mm|in)?$/', $ft_part)) {
                                $ft_clean_parts = array();
                                break;
                            }
                            $ft_clean_parts[] = preg_match('/(?:px|%|vh|vw|em|rem|pt|cm|mm|in)$/', $ft_part) ? $ft_part : $ft_part . 'px';
                        }
                        $settings['subheader_box_' . $ft_box_prop . $ft_sfx] = count($ft_clean_parts) > 0 && count($ft_clean_parts) <= 4
                            ? implode(' ', $ft_clean_parts)
                            : '';
                    } else {
                        $settings['subheader_box_' . $ft_box_prop . $ft_sfx] = $this->sanitize_css_radius($ft_box_value);
                    }
                }
                $ft_style_name = 'family_tree_album_subheader_box_border_style' . $ft_sfx;
                if (isset($_POST[$ft_style_name])) {
                    $ft_style = family_tree_sanitize_str(wp_unslash($_POST[$ft_style_name]));
                    $settings['subheader_box_border_style' . $ft_sfx] = in_array($ft_style, array('solid', 'dashed', 'dotted', 'double'), true)
                        ? $ft_style
                        : ('desktop' === $ft_dev ? 'solid' : '');
                }
                $ft_color_name = 'family_tree_album_subheader_box_border_color' . $ft_sfx;
                if (isset($_POST[$ft_color_name])) {
                    $settings['subheader_box_border_color' . $ft_sfx] = $this->sanitize_tree_color(family_tree_sanitize_str(wp_unslash($_POST[$ft_color_name])));
                }
            }
            foreach (array('tablet', 'mobile') as $ft_subheader_dev) {
                $ft_sfx = '_' . $ft_subheader_dev;
                $ft_color_post = 'family_tree_album_subheader_color' . $ft_sfx;
                if (isset($_POST[$ft_color_post])) {
                    $settings['subheader_color' . $ft_sfx] = $this->sanitize_tree_color(family_tree_sanitize_str(wp_unslash($_POST[$ft_color_post])));
                }
                $ft_font_post = 'family_tree_album_subheader_font_family' . $ft_sfx;
                if (isset($_POST[$ft_font_post])) {
                    $ft_font = family_tree_sanitize_str(wp_unslash($_POST[$ft_font_post]));
                    $settings['subheader_font_family' . $ft_sfx] = in_array($ft_font, $allowed_fonts, true) ? $ft_font : '';
                }
                $ft_weight_post = 'family_tree_album_subheader_font_weight' . $ft_sfx;
                $ft_weight = isset($_POST[$ft_weight_post]) ? intval($_POST[$ft_weight_post]) : intval($settings['subheader_font_weight' . $ft_sfx]);
                $ft_weight_font = '' !== $settings['subheader_font_family' . $ft_sfx]
                    ? $settings['subheader_font_family' . $ft_sfx] : $settings['subheader_font_family'];
                $settings['subheader_font_weight' . $ft_sfx] = in_array($ft_weight, self::get_font_weights($ft_weight_font), true) ? $ft_weight : 0;
                $ft_size_post = 'family_tree_album_subheader_font_size' . $ft_sfx;
                if (isset($_POST[$ft_size_post])) {
                    $settings['subheader_font_size' . $ft_sfx] = max(0, min(96, intval($_POST[$ft_size_post])));
                }
            }
            $settings['description_color'] = isset($_POST['family_tree_album_description_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_description_color'])) : $settings['description_color'];
            $desc_font_raw = isset($_POST['family_tree_album_description_font_family']) ? family_tree_sanitize_str($_POST['family_tree_album_description_font_family']) : '';
            $settings['description_font_family'] = in_array($desc_font_raw, $allowed_fonts, true) ? $desc_font_raw : '';
            $desc_font_weight = isset($_POST['family_tree_album_description_font_weight']) ? intval($_POST['family_tree_album_description_font_weight']) : 0;
            $settings['description_font_weight'] = in_array($desc_font_weight, self::get_font_weights($settings['description_font_family']), true) ? $desc_font_weight : 0;
            $settings['description_font_size'] = isset($_POST['family_tree_album_description_font_size']) ? max(0, min(96, intval($_POST['family_tree_album_description_font_size']))) : $settings['description_font_size'];
            if (isset($_POST['family_tree_album_description_text_align'])) {
                $ft_description_align = family_tree_sanitize_str(wp_unslash($_POST['family_tree_album_description_text_align']));
                $settings['description_text_align'] = in_array($ft_description_align, ft_phs_align_values(), true) ? $ft_description_align : '';
            }
            foreach (array('tablet', 'mobile') as $ft_description_dev) {
                $ft_description_sfx = '_' . $ft_description_dev;
                $ft_description_color_post = 'family_tree_album_description_color' . $ft_description_sfx;
                if (isset($_POST[$ft_description_color_post])) {
                    $settings['description_color' . $ft_description_sfx] = $this->sanitize_tree_color(family_tree_sanitize_str(wp_unslash($_POST[$ft_description_color_post])));
                }
                $ft_description_font_post = 'family_tree_album_description_font_family' . $ft_description_sfx;
                if (isset($_POST[$ft_description_font_post])) {
                    $ft_description_font = family_tree_sanitize_str(wp_unslash($_POST[$ft_description_font_post]));
                    $settings['description_font_family' . $ft_description_sfx] = in_array($ft_description_font, $allowed_fonts, true) ? $ft_description_font : '';
                }
                $ft_description_font_for_weight = '' !== $settings['description_font_family' . $ft_description_sfx]
                    ? $settings['description_font_family' . $ft_description_sfx] : $settings['description_font_family'];
                $ft_description_weight_post = 'family_tree_album_description_font_weight' . $ft_description_sfx;
                if (isset($_POST[$ft_description_weight_post])) {
                    $ft_description_weight = intval($_POST[$ft_description_weight_post]);
                    $settings['description_font_weight' . $ft_description_sfx] = in_array($ft_description_weight, self::get_font_weights($ft_description_font_for_weight), true)
                        ? $ft_description_weight
                        : 0;
                }
                $ft_description_size_post = 'family_tree_album_description_font_size' . $ft_description_sfx;
                if (isset($_POST[$ft_description_size_post])) {
                    $settings['description_font_size' . $ft_description_sfx] = max(0, min(96, intval($_POST[$ft_description_size_post])));
                }
                $ft_description_align_post = 'family_tree_album_description_text_align' . $ft_description_sfx;
                if (isset($_POST[$ft_description_align_post])) {
                    $ft_description_align = family_tree_sanitize_str(wp_unslash($_POST[$ft_description_align_post]));
                    $settings['description_text_align' . $ft_description_sfx] = in_array($ft_description_align, ft_phs_align_values(), true) ? $ft_description_align : '';
                }
            }
            $settings['title_color'] = isset($_POST['family_tree_album_title_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_title_color'])) : $settings['title_color'];
            $title_font_raw = isset($_POST['family_tree_album_title_font_family']) ? family_tree_sanitize_str($_POST['family_tree_album_title_font_family']) : '';
            $settings['title_font_family'] = in_array($title_font_raw, $allowed_fonts, true) ? $title_font_raw : '';
            $title_font_weight = isset($_POST['family_tree_album_title_font_weight']) ? intval($_POST['family_tree_album_title_font_weight']) : 0;
            $settings['title_font_weight'] = in_array($title_font_weight, self::get_font_weights($settings['title_font_family']), true) ? $title_font_weight : 0;
            $settings['title_font_size'] = isset($_POST['family_tree_album_title_font_size']) ? max(0, min(96, intval($_POST['family_tree_album_title_font_size']))) : $settings['title_font_size'];
            // Заголовок ленты — табы устройств: планшет и мобильный наследуют
            // десктоп, поэтому пустое поле сохраняем как '' (не как default),
            // иначе переопределение перестало бы работать.
            $settings['title_font_size_tablet'] = isset($_POST['family_tree_album_title_font_size_tablet']) ? max(0, min(96, intval($_POST['family_tree_album_title_font_size_tablet']))) : $settings['title_font_size_tablet'];
            $settings['title_font_size_mobile'] = isset($_POST['family_tree_album_title_font_size_mobile']) ? max(0, min(96, intval($_POST['family_tree_album_title_font_size_mobile']))) : $settings['title_font_size_mobile'];
            foreach (array('tablet', 'mobile') as $ft_title_dev) {
                $ft_title_sfx = '_' . $ft_title_dev;
                $ft_title_color = isset($_POST['family_tree_album_title_color' . $ft_title_sfx])
                    ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_title_color' . $ft_title_sfx])) : '';
                $settings['title_color' . $ft_title_sfx] = $ft_title_color;
                $ft_title_font = isset($_POST['family_tree_album_title_font_family' . $ft_title_sfx])
                    ? family_tree_sanitize_str($_POST['family_tree_album_title_font_family' . $ft_title_sfx]) : '';
                $settings['title_font_family' . $ft_title_sfx] = in_array($ft_title_font, $allowed_fonts, true) ? $ft_title_font : '';
                // Толщину сверяем с набором самой гарнитуры; при наследовании
                // гарнитуры пусто, поэтому варианты берём у десктопной.
                $ft_title_weight_font = '' !== $settings['title_font_family' . $ft_title_sfx]
                    ? $settings['title_font_family' . $ft_title_sfx] : $settings['title_font_family'];
                $ft_title_weight = isset($_POST['family_tree_album_title_font_weight' . $ft_title_sfx])
                    ? intval($_POST['family_tree_album_title_font_weight' . $ft_title_sfx]) : 0;
                $settings['title_font_weight' . $ft_title_sfx] = in_array($ft_title_weight, self::get_font_weights($ft_title_weight_font), true) ? $ft_title_weight : 0;
            }
            // Разделитель под заголовком ленты. Чекбокс без третьего состояния:
            // у Десктопа снятая галочка = «выключено», у Планшета и Мобильных —
            // «не задано», то есть решение Десктопа.
            $settings['title_separator'] = !empty($_POST['family_tree_album_title_separator']) ? '1' : '0';
            $settings['title_separator_color'] = $this->sanitize_tree_color(isset($_POST['family_tree_album_title_separator_color']) ? family_tree_sanitize_str($_POST['family_tree_album_title_separator_color']) : '');
            $settings['title_separator_width'] = isset($_POST['family_tree_album_title_separator_width']) ? max(0, min(96, intval($_POST['family_tree_album_title_separator_width']))) : 2;
            foreach (array('tablet', 'mobile') as $ft_sep_dev) {
                $ft_sep_sfx = '_' . $ft_sep_dev;
                $ft_sep_on  = !empty($_POST['family_tree_album_title_separator' . $ft_sep_sfx]);
                $settings['title_separator' . $ft_sep_sfx] = $ft_sep_on ? '1' : '';
                $settings['title_separator_color' . $ft_sep_sfx] = ($ft_sep_on && isset($_POST['family_tree_album_title_separator_color' . $ft_sep_sfx]))
                    ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_title_separator_color' . $ft_sep_sfx])) : '';
                $settings['title_separator_width' . $ft_sep_sfx] = ($ft_sep_on && isset($_POST['family_tree_album_title_separator_width' . $ft_sep_sfx]))
                    ? max(0, min(96, intval($_POST['family_tree_album_title_separator_width' . $ft_sep_sfx]))) : 0;
            }
            // Кнопки ленты альбомов — отдельная вложенная структура: свои
            // состояния и габариты по каждому устройству.
            $ft_navlink_raw = isset($_POST['family_tree_album_navlink']) && is_array($_POST['family_tree_album_navlink'])
                ? wp_unslash($_POST['family_tree_album_navlink']) : array();
            $settings['navlink'] = $this->sanitize_album_navlink_settings($ft_navlink_raw, $allowed_fonts);
            update_option('family_tree_album_settings', $settings);
        }
        if ($ft_album_feed_save) {
            $layout_raw = isset($_POST['family_tree_album_layout']) ? family_tree_sanitize_str($_POST['family_tree_album_layout']) : 'grid';
            $settings['album_layout'] = in_array($layout_raw, array('grid', 'tile', 'masonry', 'mosaic', 'carousel', 'carousel-fluid'), true) ? $layout_raw : 'grid';
            $settings['columns'] = isset($_POST['family_tree_album_columns']) ? max(1, min(8, intval($_POST['family_tree_album_columns']))) : $settings['columns'];
            $settings['columns_tablet'] = isset($_POST['family_tree_album_columns_tablet']) ? max(1, min(8, intval($_POST['family_tree_album_columns_tablet']))) : $settings['columns_tablet'];
            $settings['columns_mobile'] = isset($_POST['family_tree_album_columns_mobile']) ? max(1, min(8, intval($_POST['family_tree_album_columns_mobile']))) : $settings['columns_mobile'];
            $settings['gap'] = isset($_POST['family_tree_album_gap']) ? max(0, min(60, intval($_POST['family_tree_album_gap']))) : $settings['gap'];
            $settings['captions'] = isset($_POST['family_tree_album_captions']) ? 1 : 0;
            $caption_position_raw = isset($_POST['family_tree_album_caption_position']) ? family_tree_sanitize_str($_POST['family_tree_album_caption_position']) : 'below';
            $settings['caption_position'] = in_array($caption_position_raw, array('below', 'above', 'overlay'), true) ? $caption_position_raw : 'below';
            if (!isset($settings['caption_styles']) || !is_array($settings['caption_styles'])) {
                $settings['caption_styles'] = array();
            }
            $caption_styles_raw = isset($_POST['family_tree_album_caption_style']) && is_array($_POST['family_tree_album_caption_style'])
                ? wp_unslash($_POST['family_tree_album_caption_style']) : array();
            foreach (array('below', 'above', 'overlay') as $caption_position) {
                foreach (array('desktop', 'tablet', 'mobile') as $caption_device) {
                    $row = isset($caption_styles_raw[$caption_position][$caption_device]) && is_array($caption_styles_raw[$caption_position][$caption_device])
                        ? $caption_styles_raw[$caption_position][$caption_device] : array();
                    $scalar = function ($source, $key, $fallback = '') {
                        return isset($source[$key]) && is_scalar($source[$key]) ? (string) $source[$key] : $fallback;
                    };
                    $style = array();
                    $align = family_tree_sanitize_str($scalar($row, 'align'));
                    $style['align'] = in_array($align, ft_phs_align_values(), true) ? $align : '';
                    $style['color'] = $this->sanitize_tree_color(family_tree_sanitize_str($scalar($row, 'color')));
                    $font = family_tree_sanitize_str($scalar($row, 'font_family'));
                    $style['font_family'] = in_array($font, $allowed_fonts, true) ? $font : '';
                    $font_size = $scalar($row, 'font_size');
                    $style['font_size'] = '' !== $font_size ? max(0, min(96, intval($font_size))) : '';
                    $weight = intval($scalar($row, 'font_weight'));
                    $style['font_weight'] = in_array($weight, self::get_font_weights($style['font_family']), true) ? $weight : '';
                    $bg = isset($row['bg']) && is_array($row['bg']) ? $row['bg'] : array();
                    $bg_type = family_tree_sanitize_str($scalar($bg, 'type', 'classic'));
                    $style['bg'] = array(
                        'color' => $this->sanitize_tree_color(family_tree_sanitize_str($scalar($bg, 'color'))),
                        'type' => in_array($bg_type, array('classic', 'gradient'), true) ? $bg_type : 'classic',
                        'gradient' => sanitize_text_field($scalar($bg, 'gradient')),
                        'gradient_type' => 'radial' === family_tree_sanitize_str($scalar($bg, 'gradient_type')) ? 'radial' : 'linear',
                        'angle' => max(-360, min(360, intval($scalar($bg, 'angle', '180')))),
                        'image' => esc_url_raw($scalar($bg, 'image')),
                    );
                    $style['padding'] = $this->sanitize_css_radius($scalar($row, 'padding'));
                    $style['radius'] = $this->sanitize_css_radius($scalar($row, 'radius'));
                    $settings['caption_styles'][$caption_position][$caption_device] = $style;
                }
            }
            $settings['caption_color'] = isset($_POST['family_tree_album_caption_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_caption_color'])) : $settings['caption_color'];
            $settings['caption_bg'] = isset($_POST['family_tree_album_caption_bg']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_caption_bg'])) : $settings['caption_bg'];
            $caption_font_raw = isset($_POST['family_tree_album_caption_font_family']) ? family_tree_sanitize_str($_POST['family_tree_album_caption_font_family']) : '';
            $settings['caption_font_family'] = in_array($caption_font_raw, $allowed_fonts, true) ? $caption_font_raw : '';
            $caption_font_weight = isset($_POST['family_tree_album_caption_font_weight']) ? intval($_POST['family_tree_album_caption_font_weight']) : 0;
            $settings['caption_font_weight'] = in_array($caption_font_weight, self::get_font_weights($settings['caption_font_family']), true) ? $caption_font_weight : 0;
            $settings['caption_font_size'] = isset($_POST['family_tree_album_caption_font_size']) ? max(0, min(96, intval($_POST['family_tree_album_caption_font_size']))) : $settings['caption_font_size'];
            $settings['image_radius'] = isset($_POST['family_tree_album_image_radius']) ? $this->sanitize_css_radius($_POST['family_tree_album_image_radius']) : $settings['image_radius'];
            $settings['image_height'] = isset($_POST['family_tree_album_image_height']) ? max(0, min(800, intval($_POST['family_tree_album_image_height']))) : $settings['image_height'];
            $image_ratio_raw = isset($_POST['family_tree_album_image_ratio']) ? family_tree_sanitize_str($_POST['family_tree_album_image_ratio']) : 'inherit';
            $ratio_values = array('inherit', '4:3', '3:2', '16:9', '2:1', '3:1', '4:1', '3:4', '2:3', '1:1');
            $settings['image_ratio'] = in_array($image_ratio_raw, $ratio_values, true) ? $image_ratio_raw : 'inherit';
            $settings['photos_count'] = isset($_POST['family_tree_album_photos_count']) ? max(0, min(500, intval($_POST['family_tree_album_photos_count']))) : $settings['photos_count'];
            $settings['image_border_width'] = isset($_POST['family_tree_album_image_border_width']) ? max(0, min(50, intval($_POST['family_tree_album_image_border_width']))) : $settings['image_border_width'];
            $image_border_style = isset($_POST['family_tree_album_image_border_style']) ? family_tree_sanitize_str($_POST['family_tree_album_image_border_style']) : 'solid';
            $settings['image_border_style'] = in_array($image_border_style, array('solid', 'dashed', 'dotted', 'double'), true) ? $image_border_style : 'solid';
            $settings['image_border_color'] = isset($_POST['family_tree_album_image_border_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_image_border_color'])) : $settings['image_border_color'];
            $image_border_width_hover_raw = isset($_POST['family_tree_album_image_border_width_hover']) ? trim(family_tree_sanitize_str($_POST['family_tree_album_image_border_width_hover'])) : $settings['image_border_width_hover'];
            $settings['image_border_width_hover'] = '' === $image_border_width_hover_raw
                ? ''
                : (preg_match('/^\d+(?:px)?$/', $image_border_width_hover_raw) ? max(0, min(50, intval($image_border_width_hover_raw))) : $settings['image_border_width_hover']);
            $image_border_style_hover = isset($_POST['family_tree_album_image_border_style_hover']) ? family_tree_sanitize_str($_POST['family_tree_album_image_border_style_hover']) : $settings['image_border_style_hover'];
            $settings['image_border_style_hover'] = in_array($image_border_style_hover, array('', 'solid', 'dashed', 'dotted', 'double'), true) ? $image_border_style_hover : $settings['image_border_style_hover'];
            $settings['image_border_color_hover'] = isset($_POST['family_tree_album_image_border_color_hover']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_image_border_color_hover'])) : $settings['image_border_color_hover'];
            $settings['image_shadow'] = isset($_POST['family_tree_album_image_shadow']) ? 1 : 0;
            $image_style_state = isset($_POST['family_tree_album_image_style_state']) ? family_tree_sanitize_str($_POST['family_tree_album_image_style_state']) : 'normal';
            $settings['image_style_state'] = in_array($image_style_state, array('normal', 'hover'), true) ? $image_style_state : 'normal';
            $settings['image_border_state'] = $settings['image_style_state'];
            $settings['image_shadow_state'] = $settings['image_style_state'];
            $settings['image_shadow_hover'] = isset($_POST['family_tree_album_image_shadow_hover']) ? 1 : 0;
            $settings['shadow_color'] = isset($_POST['family_tree_album_shadow_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_shadow_color'])) : $settings['shadow_color'];
            $settings['shadow_offset_x'] = isset($_POST['family_tree_album_shadow_x']) ? max(-200, min(200, intval($_POST['family_tree_album_shadow_x']))) : $settings['shadow_offset_x'];
            $settings['shadow_offset_y'] = isset($_POST['family_tree_album_shadow_y']) ? max(-200, min(200, intval($_POST['family_tree_album_shadow_y']))) : $settings['shadow_offset_y'];
            $settings['shadow_blur'] = isset($_POST['family_tree_album_shadow_blur']) ? max(0, min(200, intval($_POST['family_tree_album_shadow_blur']))) : $settings['shadow_blur'];
            $settings['shadow_spread'] = isset($_POST['family_tree_album_shadow_spread']) ? max(-100, min(100, intval($_POST['family_tree_album_shadow_spread']))) : $settings['shadow_spread'];
            $settings['image_shadow_hover_color'] = isset($_POST['family_tree_album_image_shadow_hover_color'])
                ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_image_shadow_hover_color']))
                : $settings['image_shadow_hover_color'];
            foreach (array('x' => array(-200, 200), 'y' => array(-200, 200), 'blur' => array(0, 200), 'spread' => array(-100, 100)) as $ft_image_shadow_dimension => $ft_image_shadow_bounds) {
                $ft_image_shadow_post = 'family_tree_album_image_shadow_hover_' . $ft_image_shadow_dimension;
