                    $settings[$ft_hover_font_key] = in_array($ft_hover_font, $allowed_fonts, true) ? $ft_hover_font : '';
                    $ft_hover_weight_key = 'display_' . $ft_part . '_hover_font_weight' . $ft_sfx;
                    $ft_hover_weight_post = 'family_tree_album_' . $ft_hover_weight_key;
                    $ft_hover_weight = isset($_POST[$ft_hover_weight_post]) ? intval($_POST[$ft_hover_weight_post]) : 0;
                    $settings[$ft_hover_weight_key] = in_array($ft_hover_weight, self::get_font_weights($settings[$ft_hover_font_key]), true)
                        ? $ft_hover_weight
                        : 0;
                    $ft_hover_size_key = 'display_' . $ft_part . '_hover_font_size' . $ft_sfx;
                    $ft_hover_size_post = 'family_tree_album_' . $ft_hover_size_key;
                    $settings[$ft_hover_size_key] = isset($_POST[$ft_hover_size_post])
                        ? max(0, min(96, intval($_POST[$ft_hover_size_post])))
                        : $settings[$ft_hover_size_key];
                }
            }
            $settings['display_hover_bg'] = isset($_POST['family_tree_album_display_hover_bg']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_display_hover_bg'])) : $settings['display_hover_bg'];
            $settings['display_hover_border'] = isset($_POST['family_tree_album_display_hover_border']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_display_hover_border'])) : $settings['display_hover_border'];
            $settings['display_hover_title_color'] = isset($_POST['family_tree_album_display_hover_title_color']) ? $this->sanitize_tree_color(family_tree_sanitize_str($_POST['family_tree_album_display_hover_title_color'])) : $settings['display_hover_title_color'];
            update_option('family_tree_album_settings', $settings);
            $message = esc_html__('Настройки ленты альбомов сохранены', 'genius-family-tree');
            $message_type = 'updated';
        }
    }
?>
