    <script type="text/javascript">
jQuery(document).ready(function($) {
    $('#deactivate-license-button').click(function() {
        if (!confirm('<?php echo esc_js(__('Вы уверены, что хотите деактивировать лицензию?', 'genius-family-tree')); ?>')) {
            return;
        }
        $.post(ajaxurl, {
            action: 'family_tree_deactivate_license',
            nonce: '<?php echo esc_js(wp_create_nonce('family_tree_license_nonce')); ?>'
        }, function(response) {
            if (response.success) {
                alert('<?php echo esc_js(__('Лицензия успешно деактивирована!', 'genius-family-tree')); ?>');
                location.reload();
            } else {
                alert('<?php echo esc_js(__('Ошибка деактивации: ', 'genius-family-tree')); ?>' + response.data);
            }
        });
    });

    // === Фоны с прозрачностью (HEX + RGBA): древо, персоналии, каталог ===
    function ftInitAlphaColor(inputSel, sliderSel, labelSel) {
        var $input = $(inputSel);
        var $slider = $(sliderSel);
        var $label = $(labelSel);
        if (!$input.length || !$slider.length) return null;
        function ftToHex(r, g, b) {
            return '#' + [r, g, b].map(function(v) {
                var h = (+v).toString(16);
                return h.length === 1 ? '0' + h : h;
            }).join('');
        }
        function ftRgbString(r, g, b, a) {
            if (a >= 1) return ftToHex(r, g, b);
            a = Math.round(a * 100) / 100;
            return 'rgba(' + r + ', ' + g + ', ' + b + ', ' + a + ')';
        }
        function ftParseRgb(val) {
            var m = val.match(/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})(?:\s*,\s*([0-9.]+))?\s*\)$/i);
            if (m) return { r: +m[1], g: +m[2], b: +m[3] };
            var hex = (val || '').replace('#', '');
            if (hex.length === 3) hex = hex.split('').map(function(c) { return c + c; }).join('');
            if (hex.length === 6) return { r: parseInt(hex.substr(0, 2), 16), g: parseInt(hex.substr(2, 2), 16), b: parseInt(hex.substr(4, 2), 16) };
            return { r: 255, g: 255, b: 255 };
        }
        function ftAlphaPct() {
            return parseInt($slider.val(), 10);
        }
        function ftPaintChip() {
            var $chip = $input.closest('.wp-picker-container').find('.wp-color-result');
            if ($chip.length) $chip.css('background-color', $input.val() ? $input.val() : 'transparent');
        }
        function ftApply() {
            var rgb = ftParseRgb($input.val());
            var a = ftAlphaPct() / 100;
            $input.val(ftRgbString(rgb.r, rgb.g, rgb.b, a));
            $label.text(ftAlphaPct() + '%');
            ftPaintChip();
        }
        function ftInit() {
            var v = $input.val();
            var m = v.match(/^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*([0-9.]+)\)$/i);
            if (m) {
                $slider.val(Math.round(parseFloat(m[4]) * 100));
            } else if (v === '') {
                $slider.val(0);
            }
            $label.text($slider.val() + '%');
        }
        ftInit();
        $slider.on('input change', ftApply);
        $input.wpColorPicker({
            defaultColor: $input.data('default-color'),
            clear: function() { $(this).data('ft-clear', Date.now()); },
            change: function(event, ui) {
                if (ui.color) {
                    $input.data('ft-clear', 0);
                    var a = ftAlphaPct() / 100;
                    $input.val(ftRgbString(ui.color.r, ui.color.g, ui.color.b, a));
                    $label.text(ftAlphaPct() + '%');
                    ftPaintChip();
                } else {
                    $input.val($input.val());
                }
            }
        });
        return {
            setSolid: function() {
                $slider.val(100);
                $label.text('100%');
            },
            setTransparent: function() {
                $slider.val(0);
                $label.text('0%');
            }
        };
    }
    $('.ft-alpha-color-group').each(function() {
        var $group = $(this);
        var api = ftInitAlphaColor($group.data('input'), $group.data('slider'), $group.data('label'));
        if (!api) return;
        $group.find('.ft-color-preset').on('click', function(e) {
            e.preventDefault();
            api.setSolid();
            var color = $(this).data('color');
            $group.find('.ft-alpha-input').val(color);
            $group.find('.ft-alpha-input').data('ft-clear', 0);
            try { $group.find('.ft-alpha-input').wpColorPicker('color', color); } catch (err) {}
        });
        $group.find('.ft-color-transparent').on('click', function(e) {
            e.preventDefault();
            api.setTransparent();
            $group.find('.ft-alpha-input').val('rgba(0, 0, 0, 0)');
            try { $group.find('.ft-alpha-input').wpColorPicker('color', 'rgba(0, 0, 0, 0)'); } catch (err) {}
        });
        $group.find('.ft-color-reset').on('click', function(e) {
            e.preventDefault();
            var color = $group.find('.ft-alpha-input').data('default-color');
            api.setSolid();
            $group.find('.ft-alpha-input').val(color);
            $group.find('.ft-alpha-input').data('ft-clear', color ? 0 : Date.now());
            try { $group.find('.ft-alpha-input').wpColorPicker('color', color); } catch (err) {}
        });
        var $sForm = $group.closest('form');
        if ($sForm.length) {
            $sForm.on('submit', function() {
                var $sInp = $($group.data('input'));
                var $sSld = $($group.data('slider'));
                if (!$sInp.length || !$sSld.length) return;
                var sVal = ($sInp.val() || '').trim();
                var sPct = parseInt($sSld.val(), 10) || 0;
                if (sVal === '') {
                    var sWc = '';
                    try { sWc = $sInp.wpColorPicker('color'); } catch (err) {}
                    var sDef = '';
                    try { sDef = $sInp.data('default-color') || ''; } catch (err) {}
                    if (!$sInp.data('ft-clear') && typeof sWc === 'string' && sWc !== '' && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(sWc) && sWc.toLowerCase() !== sDef.toLowerCase()) {
                        sVal = sWc;
                    }
                }
                if (sVal === '' && (sPct === 0 || sPct === 100)) return;
                if (!/^(#([0-9a-f]{3}|[0-9a-f]{6})|rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(?:\s*,\s*[0-9.]+)?\s*\))$/i.test(sVal)) return;
                if (sPct === 100) {
                    $sInp.val(sVal);
                    return;
                }
                var sM = sVal.match(/^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*([0-9.]+)\)$/i);
                var sr, sg, cb;
                if (sM) {
                    sr = +sM[1]; sg = +sM[2]; cb = +sM[3];
                } else {
                    var sh = sVal.replace('#', '');
                    if (sh.length === 3) sh = sh.split('').map(function(c) { return c + c; }).join('');
                    sr = parseInt(sh.substr(0, 2), 16);
                    sg = parseInt(sh.substr(2, 2), 16);
                    cb = parseInt(sh.substr(4, 2), 16);
                }
                if (isNaN(sr) || isNaN(sg) || isNaN(cb)) return;
                $sInp.val('rgba(' + sr + ', ' + sg + ', ' + cb + ', ' + (Math.round(sPct) / 100) + ')');
            });
        }
    });
    // Гарантия сохранения: цвета без прозрачности подтягиваем из виджета при отправке формы
    function ftSyncPlainColor($inp) {
        var pv = ($inp.val() || '').trim();
        if (pv !== '') return;
        var pw = '';
        try { pw = $inp.wpColorPicker('color'); } catch (err) {}
        var pd = '';
        try { pd = $inp.data('default-color') || ''; } catch (err) {}
        if (typeof pw === 'string' && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(pw) && pw.toLowerCase() !== pd.toLowerCase()) {
            $inp.val(pw);
        }
    }
    $('form').on('submit', function() {
        $(this).find('input.ft-color-hex').not('.ft-alpha-input').each(function() {
            ftSyncPlainColor($(this));
        });
    });

    // === Настройки отображения: цвета карточек и текста ===
    // Цвета карточек/текста теперь используют единый контрол .ft-bg-control (assets/js/admin.js).

    // === Настройки отображения: фоновое изображение ===
    if ($('#ft-bg-image-upload').length) {
        var ftMediaFrame;
        $('#ft-bg-image-upload').on('click', function(e) {
            e.preventDefault();
            if (typeof wp === 'undefined' || !wp.media) {
                alert('Медиабиблиотека не загружена. Обновите страницу.');
                return;
            }
            if (ftMediaFrame) {
                ftMediaFrame.open();
                return;
            }
            ftMediaFrame = wp.media({
                title: '<?php echo esc_js(__('Выберите фоновое изображение', 'genius-family-tree')); ?>',
                button: { text: '<?php echo esc_js(__('Использовать это изображение', 'genius-family-tree')); ?>' },
                multiple: false,
                library: { type: 'image' }
            });
            ftMediaFrame.on('select', function() {
                var attachment = ftMediaFrame.state().get('selection').first().toJSON();
                var url = attachment.sizes && attachment.sizes.medium ? attachment.sizes.medium.url : attachment.url;
                $('#ft-bg-image-url').val(attachment.url);
                $('#ft-bg-image-preview img').attr('src', url);
                $('#ft-bg-image-preview').show();
                $('#ft-bg-image-remove').show();
            });
            ftMediaFrame.open();
        });

        $('#ft-bg-image-remove').on('click', function(e) {
            e.preventDefault();
            $('#ft-bg-image-url').val('');
            $('#ft-bg-image-preview').hide();
            $(this).hide();
        });
    }

    // === Настройки отображения: заглушки фото для карточек ===
    function ftInitPlaceholder(uploadId, removeId, urlId, previewImgId, defaultUrl) {
        if (!$(uploadId).length) {
            return;
        }
        var frame;
        $(uploadId).on('click', function(e) {
            e.preventDefault();
            if (typeof wp === 'undefined' || !wp.media) {
                alert('Медиабиблиотека не загружена. Обновите страницу.');
                return;
            }
            if (frame) {
                frame.open();
                return;
            }
            frame = wp.media({
                title: '<?php echo esc_js(__('Выберите изображение-заглушку', 'genius-family-tree')); ?>',
                button: { text: '<?php echo esc_js(__('Использовать это изображение', 'genius-family-tree')); ?>' },
                multiple: false,
                library: { type: 'image' }
            });
            frame.on('select', function() {
                var attachment = frame.state().get('selection').first().toJSON();
                var filename = (attachment.url || '').toLowerCase();
                var isSvg = filename.indexOf('.svg') !== -1;
                if (!isSvg && attachment.width && attachment.height) {
                    if (attachment.width > 300 || attachment.height > 300) {
                        alert('<?php echo esc_js(__('Изображение должно быть не более 300x300 px.', 'genius-family-tree')); ?>');
                        return;
                    }
                    if (attachment.width !== attachment.height) {
                        alert('<?php echo esc_js(__('Изображение должно быть квадратным (1:1).', 'genius-family-tree')); ?>');
                        return;
                    }
                }
                $(urlId).val(attachment.url);
                $(previewImgId).attr('src', attachment.url);
                $(removeId).show();
            });
            frame.open();
        });
        $(removeId).on('click', function(e) {
            e.preventDefault();
            $(urlId).val('');
            $(previewImgId).attr('src', defaultUrl);
            $(this).hide();
        });
    }
    ftInitPlaceholder('#ft-male-placeholder-upload', '#ft-male-placeholder-remove', '#ft-male-placeholder-url', '#ft-male-placeholder-preview img', '<?php echo esc_url(FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-man.svg'); ?>');
    ftInitPlaceholder('#ft-female-placeholder-upload', '#ft-female-placeholder-remove', '#ft-female-placeholder-url', '#ft-female-placeholder-preview img', '<?php echo esc_url(FAMILY_TREE_PLUGIN_URL . 'assets/images/silhouette-woman.svg'); ?>');

    // === Переключение табов настроек (с запоминанием активного таба) ===
    var ftCurrentTab = sessionStorage.getItem('ft_tree_settings_active_tab') || 'ft-tab-tree';

    function ftActivateTreeTab(id) {
        $('.ft-tab-btn').removeClass('active');
        $('.ft-tab-btn[data-tab="' + id + '"]').addClass('active');
        $('.ft-tab-panel').removeClass('active');
