    // === Album feed: fields depending on layout ===
    var $albumLayoutPanels = $('#ft-album-layout-settings-panels');
    function ftWrapAlbumLayoutField(selector, rowClass) {
        var $control = $(selector).closest('.components-base-control');
        if (!$control.length) {
            return $();
        }
        var $label = $control.prev('.components-base-control__label');
        var $separator = $label.prev('.ft-genius_plugin-separator');
        var $group = $('<div class="ft-album-layout-settings-group"></div>').addClass(rowClass);
        if ($separator.length) {
            $separator.before($group);
            $group.append($separator);
        } else {
            $label.before($group);
        }
        $group.append($label, $control);
        return $group;
    }

    if ($albumLayoutPanels.length && !$albumLayoutPanels.data('initialized')) {
        $albumLayoutPanels.data('initialized', true);

