        function ftMoveAlbumLayoutGroup($group, $panel, allowedLayouts, layout) {
            if ($group.length && $.inArray(layout, allowedLayouts) !== -1) {
                $panel.append($group);
            }
        }

        function ftUpdateAlbumLayoutPanels() {
            var layout = $('input[name="family_tree_album_layout"]:checked').val();
            if (!layout) {
                return;
            }
            var $panel = $albumLayoutPanels.find('[data-layout-panel="' + layout + '"]');
            if (!$panel.length) {
                return;
            }
            $albumLayoutPanels.children('.ft-album-layout-settings-panel').prop('hidden', true);
            $panel.prop('hidden', false);

            if ($gapGroup.length) {
                $panel.append($gapGroup);
            }
            if ($photosCountGroup.length) {
                $panel.append($photosCountGroup);
            }
            ftMoveAlbumLayoutGroup($columnsGroup, $panel, ['grid', 'masonry', 'mosaic', 'carousel'], layout);
            ftMoveAlbumLayoutGroup($imageHeightGroup, $panel, ['grid', 'tile'], layout);
            ftMoveAlbumLayoutGroup($imageRatioGroup, $panel, ['grid', 'carousel'], layout);
            ftMoveAlbumLayoutGroup($carouselGroup, $panel, ['carousel', 'carousel-fluid'], layout);
            $carouselHeightGroup.toggle(layout === 'carousel-fluid');
        }

        $('input[name="family_tree_album_layout"]').on('change', ftUpdateAlbumLayoutPanels);
        ftUpdateAlbumLayoutPanels();
    }

